-- Migration: add_2024_winter_substantive_angles
--
-- ANGLES-ONLY backfill for the 2024 winter substantive batch. The original
-- ingestion (migration 20260526000002) dropped every nested
-- `angle_questions` array because `generate_migration.py` used the wrong
-- dict key (`q.get("angles")` instead of `q.get("angle_questions")`).
-- Sources + source_choices already landed; this migration adds only the
-- missing angle rows.
--
-- Idempotency: each angle is guarded by a SELECT-then-INSERT against the
-- (source_question_id, angle_letter) unique key. Choices fire only when
-- the parent angle is newly inserted. Re-running is a no-op (each block
-- RAISE NOTICEs that the angle already exists).

-- ============================================================
-- Q01 — angles backfill for 2024-W-S-Q01 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q01';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q01';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'שינוי תקנון ללא פגיעה ישירה בזכויות סוג', 1,
      'בחברת "הלל" יש שני סוגי מניות. בעלי המניות שמחזיקים במניות מסוג A מעוניינים לבצע שינוי בתקנון החברה שאינו משנה ישירות את זכויותיהם של בעלי המניות מסוג B, אך עלול להשפיע לרעה על שווי מניותיהם. מה הדין?', 'שאלה זו בוחנת את ההבחנה בין פגיעה ישירה ב''זכויות'' סוג מניות, המחייבת אישור אסיפת סוג לפי סעיף 20(ג) לחוק החברות, לבין פגיעה עקיפה או כלכלית בשווי המניות, שאינה מפעילה בהכרח את מנגנון אסיפת הסוג, אך עשויה להקים עילה לטענת קיפוח מיעוט לפי סעיף 191 לחוק החברות.', 'סעיף 20(ג) לחוק החברות דורש אישור אסיפת סוג כאשר שינוי בתקנון ''פוגע בזכויותיו של סוג מניות''. הפסיקה מפרשת ''פגיעה בזכויות'' כשינוי ישיר בזכויות המעוגנות בתקנון, ולא בהכרח כל השפעה כלכלית עקיפה. עם זאת, גם אם שינוי אינו פוגע ישירות בזכויות סוג המניות באופן שמפעיל את סעיף 20(ג), הוא עדיין כפוף לחובות תום הלב וההגינות של בעלי המניות (סעיף 192 לחוק החברות) ולמניעת קיפוח מיעוט (סעיף 191 לחוק החברות). אם השינוי, אף שאינו משנה את הזכויות הפורמליות, גורם לפגיעה מהותית בציפיות הלגיטימיות או באינטרסים הכלכליים של סוג המניות, הוא עשוי להיחשב כקיפוח מיעוט, ובית המשפט יהיה מוסמך להעניק סעד מתאים. ע"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.04.2020)ת"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז"ל (02.03.2017)ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (18.08.2022)', 'הטעות הנפוצה היא להניח שכל פגיעה כלכלית או עקיפה בזכויות סוג מניות מפעילה אוטומטית את דרישת אסיפת הסוג, מבלי להבחין בין פגיעה ישירה בזכויות לבין קיפוח מיעוט.',
      '["פגיעה בזכויות סוג", "קיפוח מיעוט", "סעיף 20(ג) לחוק החברות", "סעיף 191 לחוק החברות", "ציפיות לגיטימיות", "השפעה עקיפה"]'::jsonb, '**וריאציה 1 — פגיעה ישירה מול עקיפה:** האם שינוי המשפיע לרעה על שווי מניות אך לא משנה את זכויותיהן הפורמליות דורש אסיפת סוגלא בהכרח, סעיף 20(ג) מתייחס לפגיעה בזכויות עצמן (סעיף 20(ג) לחוק החברות).
**וריאציה 2 — עילת קיפוח:** האם פגיעה עקיפה בשווי מניות יכולה להקים עילת קיפוחכן, אם היא פוגעת בציפיות לגיטימיות של בעלי המניות (ת"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז"ל).
**וריאציה 3 — סעד במקרה קיפוח:** מהו הסעד העיקרי במקרה של קיפוח מיעוטבית המשפט יכול להורות על הפרדות לפי סעיף 191 לחוק החברות (ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ).', 'פגיעה עקיפה בשווי מניותלא בהכרח אסיפת סוגאך עשויה להקים עילת קיפוח מיעוט (סעיף 191).', '["חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "חוק החברות, תשנ\"ט-1999, סעיף 191", "ע\"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.04.2020)", "ת\"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז\"ל (02.03.2017)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'השינוי אינו אפשרי כלל, שכן הוא פוגע בעקיפין בבעלי המניות מסוג B.', false, 'תשובה זו שגויה. פגיעה עקיפה בשווי המניות אינה מונעת את השינוי באופן מוחלט, אך עשויה להקים עילה לטענת קיפוח מיעוט.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'נדרש אישור של אסיפת בעלי המניות מסוג B, שכן כל פגיעה, גם עקיפה, מחייבת את אישורם.', false, 'תשובה זו שגויה. סעיף 20(ג) מתייחס לפגיעה ב''זכויותיו'' של סוג המניות, ולא בהכרח לכל השפעה כלכלית עקיפה. פגיעה עקיפה בשווי אינה מחייבת בהכרח אישור אסיפת סוג.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'השינוי יכול להתבצע ברוב רגיל באסיפה הכללית, אך בעלי המניות מסוג B עשויים לטעון לקיפוח מיעוט לפי סעיף 191 לחוק החברות.', true, 'זו התשובה הנכונה. כאשר אין פגיעה ישירה בזכויות המעוגנות בתקנון, השינוי יכול להתבצע ברוב רגיל (אלא אם נקבע אחרת בתקנון). עם זאת, השפעה לרעה על שווי המניות עשויה להוות עילה לטענת קיפוח מיעוט, המאפשרת לבית המשפט להתערב.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'השינוי יכול להתבצע ברוב רגיל באסיפה הכללית, ואין לבעלי המניות מסוג B כל עילה להתנגד.', false, 'תשובה זו שגויה. גם אם השינוי אינו פוגע ישירות בזכויות, השפעה מהותית לרעה על שווי המניות עשויה להקים עילה לקיפוח מיעוט, המאפשרת התערבות שיפוטית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q01';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחן הפגיעה בזכויות סוג מניות', 2,
      'מהו המבחן לקביעה האם שינוי בתקנון ''פוגע בזכויותיו של סוג מניות'' לצורך הפעלת סעיף 20(ג) לחוק החברות?', 'שאלה זו מתמקדת במבחן המשפטי לקביעת ''פגיעה בזכויותיו של סוג מניות'' לפי סעיף 20(ג) לחוק החברות. היא מבקשת להבהיר את ההיקף והמהות של פגיעה כזו, המפעילה את דרישת אישור אסיפת הסוג, ומבחינה בינה לבין השפעות כלכליות עקיפות או דרישות אחרות בחוק.', 'המבחן לקביעה האם שינוי בתקנון ''פוגע בזכויותיו של סוג מניות'' לצורך סעיף 20(ג) לחוק החברות מתמקד בפגיעה ישירה בזכויות המהותיות הצמודות לסוג המניות, כגון זכויות הצבעה, זכויות לדיבידנד, זכויות ניהול או זכויות אחרות המעוגנות בתקנון. הפסיקה מבחינה בין פגיעה ישירה בזכויות אלו לבין פגיעה עקיפה או כלכלית בשווי המניות. בעוד שפגיעה ישירה בזכויות מחייבת את אישור אסיפת הסוג (אלא אם נקבע אחרת בתקנון), פגיעה עקיפה בשווי המניות, כשלעצמה, אינה מפעילה את סעיף 20(ג), אך עשויה להקים עילה לטענת קיפוח מיעוט לפי סעיף 191 לחוק החברות. ע"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.04.2020)ת"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז"ל (02.03.2017)ה"פ (כלכלית ) 48227-05-17 שלמה לב נ'' ברוך טולדנו (14.04.2021)', 'הטעות הנפוצה היא לבלבל בין פגיעה ב''זכויות'' סוג מניות, המפעילה את סעיף 20(ג), לבין פגיעה כלכלית או עקיפה, שאינה מפעילה סעיף זה אך עשויה להקים עילת קיפוח מיעוט.',
      '["פגיעה בזכויות סוג", "סעיף 20(ג) לחוק החברות", "זכויות הצבעה", "זכויות דיבידנד", "זכויות ניהול", "קיפוח מיעוט", "מבחן אובייקטיבי"]'::jsonb, '**וריאציה 1 — מהות הפגיעה:** האם פגיעה בשווי מניות היא ''פגיעה בזכויות'' לפי סעיף 20(גלא, סעיף 20(ג) מתייחס לפגיעה ישירה בזכויות המהותיות הצמודות למניות (ע"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט).
**וריאציה 2 — דוגמאות לזכויות:** אילו זכויות נחשבות ל''זכויות'' לצורך סעיף 20(גזכויות הצבעה, דיבידנד, ניהול, או זכויות אחרות המעוגנות בתקנון (ה"פ (כלכלית ) 48227-05-17 שלמה לב נ'' ברוך טולדנו).
**וריאציה 3 — יחס לקיפוח:** מה היחס בין פגיעה בזכויות לקיפוח מיעוטפגיעה בזכויות מפעילה את סעיף 20(ג), בעוד שפגיעה עקיפה או כלכלית עשויה להקים עילת קיפוח לפי סעיף 191 (ת"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז"ל).', 'מבחן פגיעה בזכויות סוגפגיעה ישירה בזכויות מהותיות (הצבעה, דיבידנדלא כולל פגיעה עקיפה בשווי.', '["חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "ע\"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.04.2020)", "ת\"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז\"ל (02.03.2017)", "ה\"פ (כלכלית ) 48227-05-17 שלמה לב נ'' ברוך טולדנו (14.04.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כל שינוי בתקנון שבעלי המניות מסוג זה רואים בו פגיעה, ללא קשר למהות השינוי.', false, 'תשובה זו שגויה. המבחן אינו סובייקטיבי לחלוטין, אלא נדרשת פגיעה אובייקטיבית בזכויות המעוגנות בתקנון.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פגיעה ישירה בזכויות המעוגנות בתקנון, כגון זכויות הצבעה, דיבידנד או זכויות ניהול, ולא רק פגיעה עקיפה בשווי הכלכלי.', true, 'זו התשובה הנכונה. הפסיקה מפרשת ''פגיעה בזכויות'' כשינוי ישיר בזכויות המהותיות של סוג המניות, כפי שהן מוגדרות בתקנון או בחוק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כל שינוי שעלול להפחית את שווי השוק של מניות הסוג, גם אם אינו משנה את זכויותיהן הפורמליות.', false, 'תשובה זו שגויה. פגיעה בשווי השוק, כשלעצמה, אינה נחשבת לפגיעה ב''זכויות'' לצורך סעיף 20(ג), אלא עשויה להיות עילה לקיפוח מיעוט.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק שינוי שמחייב את בעלי המניות לרכוש מניות נוספות או להגדיל את היקף אחריותם.', false, 'תשובה זו שגויה. שינוי כזה אכן דורש הסכמה פרטנית של בעל המניות לפי סעיף 20(ד), אך אינו המבחן הכללי לפגיעה בזכויות סוג מניות לפי סעיף 20(ג).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q01';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'שריון הוראה בתקנון המונעת שינוי', 3,
      'בתקנון חברת "הלל" נקבעה הוראה מפורשת לפיה זכויותיהם של בעלי המניות מסוג B לא ניתנות לשינוי לעולם. כעת, בעלי המניות מסוג A מעוניינים לשנות הוראה זו. מה הדין?', 'שאלה זו עוסקת בעקרון היסוד בדיני חברות לפיו לא ניתן לחסום לחלוטין את היכולת לשנות את תקנון החברה. היא בוחנת את הגבולות של ''שריון'' הוראות בתקנון ואת האיזון בין חופש ההתאגדות לבין הצורך בגמישות תאגידית ושלטון הרוב.', 'הלכה פסוקה היא כי לא ניתן לחסום את דרכם של בעלי מניות לשנות את תקנון החברה מדעיקרא. חברה אינה יכולה, ולו בהוראה מפורשת בתקנון עצמו, להתנות על יכולת שינויו של התקנון. התניה שכזו נוגדת את הדין (כיום, סעיף 20 לחוק החברות). ניתן לשריין הוראה מהוראות התקנון באופן שיקשה על שינויה, למשל באמצעות קביעת רוב מיוחס הדרוש לצורך שינוי תקנה מסוימת, אך לא ניתן להתנות או לבטל את עצם קיומה של היכולת לשנות הוראה מהוראות התקנון. גם אם ההוראה המונעת שינוי לחלוטין אינה תקפה, עדיין חלים הכללים הרגילים לשינוי תקנון, ובמקרה של פגיעה בזכויות סוג, נדרש אישור אסיפת הסוג (אלא אם נקבע אחרת בתקנון). ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (25.09.2016)בג"ץ 6460/02 משה אליאב נ'' בית הדין הארצי לעבודה, ס(4) 411 (08.02.2006)ה"פ (מחוזי תל אביב-יפו) 986/07 עו"ד אליהוד יערי נ'' חב'' מעוז הכרך (27.05.2009)', 'הטעות הנפוצה היא לחשוב שניתן לשריין הוראה בתקנון באופן מוחלט, כך שלא ניתן יהיה לשנותה לעולם, מבלי להכיר בעקרון הגמישות התאגידית ובכוחו של הרוב לשנות את התקנון, בכפוף למגבלות החוק.',
      '["שריון תקנון", "שינוי תקנון", "חופש ההתאגדות", "גמישות תאגידית", "רוב מיוחס", "סעיף 20 לחוק החברות", "הלכה פסוקה"]'::jsonb, '**וריאציה 1 — חסימת שינוי:** האם ניתן לחסום לחלוטין שינוי של הוראה בתקנוןלא, לא ניתן לחסום את דרכם של בעלי המניות לשנות את התקנון מדעיקרא (ע"א 6041/15 האמה בע"מ נ'' אורנה מולר).
**וריאציה 2 — שריון מול חסימה:** מה ההבדל בין שריון הוראה לחסימתהשריון מאפשר להקשות על השינוי (למשל ברוב מיוחס), אך חסימה מוחלטת אינה אפשרית (ע"א 6041/15 האמה בע"מ נ'' אורנה מולר).
**וריאציה 3 — תכלית העיקרון:** מדוע לא ניתן לחסום שינוי תקנוןכדי לשמור על יתרון הדינמיות של התאגיד ועל מנגנון קבלת ההחלטות של שלטון הרוב (בג"ץ 6460/02 משה אליאב נ'' בית הדין הארצי לעבודה).', 'שריון הוראה בתקנוןניתן להקשות על שינוי (רוב מיוחסאך לא לחסום לחלוטין (סעיף 20 לחוק החברות).', '["חוק החברות, תשנ\"ט-1999, סעיף 20", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.09.2016)", "בג\"ץ 6460/02 משה אליאב נ'' בית הדין הארצי לעבודה, ס(4) 411 (08.02.2006)", "ה\"פ (מחוזי תל אביב-יפו) 986/07 עו\"ד אליהוד יערי נ'' חב'' מעוז הכרך (27.05.2009)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'ההוראה בתקנון מחייבת, ולא ניתן לשנות את זכויות בעלי המניות מסוג B לעולם.', false, 'תשובה זו שגויה. הפסיקה קובעת כי לא ניתן לחסום לחלוטין את היכולת לשנות תקנון חברה, גם אם ההוראה משוריינת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'ניתן לשנות את ההוראה רק בהסכמה פה אחד של כל בעלי המניות בחברה.', false, 'תשובה זו שגויה. אף שניתן לשריין הוראות ברוב מיוחס, לא ניתן לדרוש הסכמה פה אחד של כל בעלי המניות כדי למנוע שינוי עתידי לחלוטין.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא ניתן לחסום את דרכם של בעלי המניות לשנות את התקנון מדעיקרא, ולכן ניתן לשנות את ההוראה ברוב הנדרש לשינוי תקנון (לרוב רוב רגיל או רוב מיוחס אם נקבע).', true, 'זו התשובה הנכונה. הפסיקה קובעת כי חברה אינה יכולה לוותר על זכותם של חבריה לשנות את תקנונה, וכי סעיף בתקנון המונע את אפשרות שינויו לא יהא תקף. ניתן לשריין הוראות ברוב מיוחס, אך לא לחסום את השינוי לחלוטין.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'ההוראה בטלה מעיקרה, ולכן ניתן לשנות את זכויות בעלי המניות מסוג B ברוב רגיל באסיפה הכללית, ללא צורך באישור אסיפת סוג.', false, 'תשובה זו שגויה. אף שההוראה המונעת שינוי לחלוטין אינה תקפה, עדיין חלים הכללים הרגילים לשינוי תקנון, ובמקרה של פגיעה בזכויות סוג, נדרש אישור אסיפת הסוג (אלא אם נקבע אחרת בתקנון).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q01';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סעד במקרה של קיפוח מיעוט', 4,
      'בעלי המניות מסוג A בחברת "הלל" ביצעו שינוי בתקנון הפוגע בזכויותיהם של בעלי המניות מסוג B, מבלי לקבל את אישור אסיפת הסוג שלהם, בניגוד להוראות החוק. בעלי המניות מסוג B מעוניינים לתבוע סעד בגין קיפוח מיעוט. איזה סעד יכול בית המשפט להעניק במקרה כזה?', 'שאלה זו עוסקת בסעדים הניתנים לבעלי מניות מיעוט במקרה של קיפוח, כפי שמעוגן בסעיף 191 לחוק החברות. היא מדגישה את סמכותו הרחבה של בית המשפט להעניק מגוון סעדים, החל מביטול החלטות ועד להוראה על היפרדות, במטרה להשיב את המצב לקדמותו או להגן על זכויות המיעוט.', 'סעיף 191 לחוק החברות, התשנ"ט-1999, מעניק לבית המשפט סמכות רחבה להעניק סעדים במקרה של קיפוח מיעוט. הסעיף קובע כי ''התנהל עניין מחברה בדרך שיש בה משום קיפוח של בעלי מניותיה, רשאי בית המשפט, לבקשת בעל מניה, לתת הוראות הנראות לו מתאימות, לרבות הוראות בדבר רכישת מניותיו של בעל המניה בידי החברה או בידי בעלי מניות אחרים, או בדבר מכירת המניות, וכן הוראות בדבר שינוי התקנון או ביטולו, או בדבר שינוי תנאי ההתקשרות שבין החברה לבין בעל המניה המקופח או בעלי מניות אחרים''. כלומר, בית המשפט אינו מוגבל לסעד מסוים, אלא יכול להתאים את הסעד לנסיבות המקרה, החל מביטול השינוי בתקנון, דרך תיקון התקנון, ועד להוראה על היפרדות (רכישת מניות המקופח). ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (18.08.2022)ת"א (מחוזי חיפה) 4806-06-22 שמואל גוטמן נ'' מאור להב (08.12.2024)ת"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז"ל (02.03.2017)', 'הטעות הנפוצה היא לחשוב שסעד הקיפוח מוגבל לסעד מסוים (כגון ביטול או פיצוי), מבלי להכיר בסמכותו הרחבה של בית המשפט להעניק מגוון סעדים יצירתיים ומתאימים לנסיבות המקרה.',
      '["קיפוח מיעוט", "סעיף 191 לחוק החברות", "סעדים", "ביטול החלטה", "תיקון תקנון", "היפרדות", "סמכות בית המשפט"]'::jsonb, '**וריאציה 1 — סמכות בית המשפט:** מהי סמכות בית המשפט במקרה של קיפוח מיעוטסמכות רחבה להעניק הוראות הנראות לו מתאימות, לרבות רכישת מניות, מכירת מניות, שינוי או ביטול תקנון (סעיף 191 לחוק החברות).
**וריאציה 2 — סעד של היפרדות:** האם בית המשפט יכול להורות על היפרדותכן, סעד של היפרדות (רכישת מניות המקופח) הוא סעד אפשרי במקרה של קיפוח (ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ).
**וריאציה 3 — תיקון תקנון:** האם בית המשפט יכול לתקן את התקנוןכן, בית המשפט יכול לתת סעד של תיקון התקנון בגדרי סעיף 191 לחוק החברות (ת"א (מחוזי חיפה) 4806-06-22 שמואל גוטמן נ'' מאור להב).', 'קיפוח מיעוט (סעיףסמכות רחבה לבית המשפטביטול, תיקון תקנון, רכישת מניות, סעדים אחרים.', '["חוק החברות, תשנ\"ט-1999, סעיף 191", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)", "ת\"א (מחוזי חיפה) 4806-06-22 שמואל גוטמן נ'' מאור להב (08.12.2024)", "ת\"א (כלכלית ) 21416-08-14 שי טופז (יוכט) נ'' עזבון המנוח פישר יששכר ז\"ל (02.03.2017)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט יכול להורות על ביטול השינוי בתקנון, או על תיקון התקנון, או על רכישת מניותיהם של בעלי המניות המקופחים, או כל סעד אחר שימצא לנכון.', true, 'זו התשובה הנכונה. סעיף 191 לחוק החברות מעניק לבית המשפט סמכות רחבה להעניק מגוון סעדים במקרה של קיפוח מיעוט, לרבות ביטול החלטות, תיקון תקנון או הוראה על היפרדות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט יכול להורות רק על ביטול השינוי בתקנון, שכן זוהי התוצאה הישירה של אי-קיום דרישות החוק.', false, 'תשובה זו שגויה. סעיף 191 לחוק החברות מעניק לבית המשפט סמכות רחבה יותר מסעד של ביטול בלבד, ומאפשר לו להתאים את הסעד לנסיבות המקרה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט יכול להורות רק על פיצוי כספי לבעלי המניות המקופחים, שכן זכויותיהם נפגעו כלכלית.', false, 'תשובה זו שגויה. פיצוי כספי הוא אחד הסעדים האפשריים, אך לא היחיד, ובית המשפט יכול להעניק סעדים מהותיים יותר כמו ביטול השינוי או היפרדות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט אינו יכול להתערב, שכן שינוי תקנון הוא עניין פנימי של החברה.', false, 'תשובה זו שגויה. בית המשפט מוסמך להתערב בעניינים פנימיים של החברה במקרים של קיפוח מיעוט, כדי להגן על זכויות בעלי המניות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q01';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 1, '2024-W-S-Q01';
END
$$;

-- ============================================================
-- Q02 — angles backfill for 2024-W-S-Q02 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q02';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q02';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'משכון נוסף עם תניית הגבלה מפורשת', 1,
      'יצחק לקח הלוואה מחברו יעקב ורשם משכון לטובתו על הרכב. בהסכם המשכון עם יעקב נקבע במפורש כי יצחק אינו רשאי למשכן את הרכב במשכון נוסף ללא הסכמת יעקב. יצחק פנה לחברת ביטוח לקבלת הלוואה נוספת, והיא התנתה את מתן ההלוואה במישכון הרכב. יצחק הסכים ורשם משכון נוסף לטובת חברת הביטוח, ללא קבלת הסכמת יעקב. מה הדין?', 'שאלה זו בוחנת את ההלכה שנקבעה בפסיקת בית המשפט העליון (רע"א 8574/13 לוי) לפיה משכון שני שנעשה בניגוד לתניה מגבילה בהסכם המשכון הראשון אינו בטל באופן מוחלט, אלא בטלותו יחסית. היא מדגישה את ההבחנה בין תוקף המשכון כלפי החייב לבין תוקפו כלפי הנושה הראשון.', 'סעיף 6(א) לחוק המשכון קובע כי חייב רשאי לשעבד נכס ממושכן במשכון נוסף, אלא אם נקבע אחרת בהסכם המשכון הקודם. הפסיקה, ובראשה רע"א 8574/13 לוי, קבעה כי כאשר קיימת תניה מגבילה כזו, המשכון השני אינו בטל מעיקרו. בטלותו היא יחסית: הוא אינו תקף במערכת היחסים שבין בעל המשכון הראשון לבעל המשכון השני (כלומר, הנושה הראשון יכול להתעלם ממנו), אך הוא תקף במערכת היחסים שבין החייב לבעל המשכון השני. החייב עצמו מנוע מלטעון לבטלות המשכון השני. רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל (28.01.2014). ה"פ (מחוזי ת"א) 41927-12-13 כדורי שיווק ביצים בע"מ ה נ'' בנק מזרחי טפחות בע"מ (15.04.2015)', 'הטעות היא לחשוב שתניה מגבילה בהסכם המשכון הראשון מבטלת לחלוטין את המשכון השני, במקום להבין את עקרון הבטלות היחסית.',
      '["משכון נוסף", "תניה מגבילה", "בטלות יחסית", "רע\"א 8574/13 לוי", "חוק המשכון"]'::jsonb, '**וריאציה 1 — תוקף משכון שני עם הגבלה:** האם משכון שני שנעשה בניגוד לתניה מגבילה בטללא בטל באופן מוחלט, אלא בטלותו יחסית (רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל).
**וריאציה 2 — מי יכול לטעון לבטלות:** מי רשאי לטעון לבטלות משכון שני שנעשה בניגוד לתניה מגבילהרק בעל המשכון הראשון, לא החייב עצמו (רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל).
**וריאציה 3 — השלכות על הנושה הראשון:** מה המשמעות של בטלות יחסית כלפי הנושה הראשוןהנושה הראשון יכול להתעלם מהמשכון השני ולממש את זכויותיו ללא הפרעה (רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל).', 'תניה מגבילה בהסכם משכון ראשוןמשכון שני אינו בטל מוחלטתבטלות יחסית (תקף כלפי החייב, לא כלפי הנושה הראשון).', '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.01.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.04.2015)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'המשכון השני בטל מעיקרו, ולא ניתן לתת לו כל תוקף משפטי.', false, 'תשובה זו שגויה. הפסיקה קבעה כי משכון שני שנעשה בניגוד לתניה מגבילה אינו בטל באופן מוחלט, אלא בטלותו יחסית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'המשכון השני תקף, אך יעקב רשאי לתבוע את יצחק בגין הפרת הסכם המשכון הראשון.', false, 'תשובה זו שגויה חלקית. המשכון השני תקף ביחסים שבין החייב לנושה השני, אך יעקב יכול לטעון לאי-תוקפו כלפיו, ולא רק לתבוע בגין הפרה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המשכון השני תקף ביחסים שבין יצחק לחברת הביטוח, אך אינו תקף כלפי יעקב, אלא אם יעקב יסכים לו.', true, 'זו התשובה הנכונה. הלכת לוי קובעת בטלות יחסית למשכון שני שנעשה בניגוד לתניה מגבילה: הוא תקף כלפי החייב, אך אינו תקף כלפי הנושה הראשון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'המשכון השני תקף כלפי כולי עלמא, אך זכותו של יעקב קודמת לזו של חברת הביטוח.', false, 'תשובה זו שגויה. המשכון השני אינו תקף כלפי כולי עלמא במקרה של תניה מגבילה, אלא רק ביחסים מסוימים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q02';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תכלית סעיף 6(א) לחוק המשכון', 2,
      'מהי התכלית העיקרית של סעיף 6(א) לחוק המשכון, המאפשר לחייב לשעבד נכס ממושכן במשכון נוסף, בכפוף לסייג של ''קביעה אחרת בהסכם המישכון הקודם''?', 'שאלה זו מתמקדת בתכלית החקיקתית של סעיף 6(א) לחוק המשכון, כפי שפורשה בפסיקה. היא בוחנת את האיזון בין חופש הקניין של החייב לבין הצורך להגן על זכויות הנושה הראשון, במיוחד כאשר קיימת תניה מגבילה בהסכם המשכון הקודם.', 'בית המשפט העליון, ברע"א 8574/13 לוי, עמד על תכליתו של סעיף 6(א) לחוק המשכון. נקבע כי מטרתו העיקרית של הסעיף היא לפתוח בפני החייב את הדרך לשעבד נכס ממושכן במשכון נוסף בלי נטילת רשות מאת הנושה הראשון, בכפוף לכך שהנושה השני ייפרע רק לאחר סילוק החוב של הנושה הראשון. יחד עם זאת, הסיפא בסעיף 6(א) המגבילה אפשרות זו במקרה של ''קביעה אחרת בהסכם המישכון הקודם'', נועדה להגן על ההסכמה שניתנה מאת החייב לבעל המשכון הראשון ועל זכויותיו של זה. הסייג לא נועד לתת הגנה לחייב עצמו מפני בעל המשכון השני. רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל (28.01.2014). ה"פ (מחוזי ת"א) 41927-12-13 כדורי שיווק ביצים בע"מ ה נ'' בנק מזרחי טפחות בע"מ (15.04.2015)', 'הטעות הנפוצה היא לייחס לסעיף 6(א) תכליות שאינן קשורות ישירות להגנה על הנושה הראשון, או לבלבל בין תכלית הסעיף כולו לתכלית הסייג שבו.',
      '["תכלית חקיקה", "סעיף 6(א) לחוק המשכון", "הגנת הנושה הראשון", "חופש הקניין", "בטלות יחסית"]'::jsonb, '**וריאציה 1 — תכלית הסעיף הכללית:** מהי המטרה הכללית של סעיף 6(א) לחוק המשכוןלפתוח בפני החייב את הדרך לשעבד נכס ממושכן נוסף, תוך שמירה על קדימות הנושה הראשון (סעיף 6(א) לחוק המשכון).
**וריאציה 2 — תכלית הסייג:** מהי תכלית הסייג ''באין קביעה אחרת בהסכם המישכון הקודםלהגן על ההסכמה שניתנה לבעל המשכון הראשון ועל זכויותיו (רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל).
**וריאציה 3 — הגנה על החייב:** האם הסייג נועד להגן על החייבלא, הסייג לא נועד לתת הגנה לחייב עצמו מפני בעל המשכון השני (רע"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז"ל).', 'תכלית סעיף 6(אלאפשר משכון נוסף תוך הגנה על הנושה הראשוןהסייג מגן על זכויות הנושה הראשון.', '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.01.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.04.2015)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'להגן על הנושה השני בזמן מפני בטלות מוחלטת של המשכון.', false, 'תשובה זו שגויה. אף שהסעיף מגן על הנושה השני מפני בטלות מוחלטת, זו אינה תכליתו העיקרית של הסייג.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לאפשר לחייב למשכן נכס נוסף ללא הגבלה, כדי להגביר את נזילותו הכלכלית.', false, 'תשובה זו שגויה. הסעיף מאפשר משכון נוסף, אך הוא אינו ללא הגבלה, והסייג נועד להגן על הנושה הראשון.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'להגן על ההסכמה שניתנה מאת החייב לבעל המשכון הראשון בזמן, ועל זכויותיו של הנושה הראשון.', true, 'זו התשובה הנכונה. תכלית הסייג בסעיף 6(א) היא להגן על הנושה הראשון מפני פגיעה בזכויותיו כתוצאה ממשכון נוסף.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'למנוע מהחייב להתחמק מתשלום חובותיו לנושה השני בזמן.', false, 'תשובה זו שגויה. אף שהסעיף מונע מהחייב להתחמק, זו אינה תכליתו העיקרית של הסייג, אלא תוצאה עקיפה של תוקף המשכון כלפי החייב.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q02';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'טענת בטלות משכון שני על ידי נושה רגיל', 3,
      'יצחק לקח הלוואה מיעקב ורשם משכון על הרכב. בהסכם המשכון נקבע כי יצחק אינו רשאי למשכן את הרכב במשכון נוסף ללא הסכמת יעקב. יצחק רשם משכון נוסף לטובת חברת ביטוח ללא הסכמת יעקב. כעת, נושה רגיל של יצחק (שאינו יעקב או חברת הביטוח) טוען לבטלות המשכון השני. האם טענתו תתקבל?', 'שאלה זו בוחנת את היקף תחולת הלכת לוי (רע"א 8574/13) בדבר בטלות יחסית של משכון שני שנעשה בניגוד לתניה מגבילה. היא מתמקדת בשאלה האם גם נושים רגילים של החייב מנועים מלטעון לבטלות המשכון השני, או שמא טענה זו שמורה רק לנושה הראשון.', 'בית המשפט העליון ברע"א 8574/13 לוי הותיר בצריך עיון את השאלה האם נושיו של החייב, להבדיל מהחייב עצמו, רשאים לטעון לבטלותו של המשכון השני. בתי המשפט המחוזיים, בהתבסס על תכלית סעיף 6(א) לחוק המשכון (הגנה על הנושה הראשון בלבד), קבעו כי גם נושים רגילים של החייב מנועים מלטעון לבטלות המשכון השני. זאת, מהטעם שהכרה בתוקפו של משכון שני כלפי נושיו של החייב אינה פוגעת באינטרס ההסתמכות שלהם, שכן עסקינן במשכון רשום, ועל כן, דבר קיומו ידוע להם או לפחות צריך היה להיות ידוע להם. ה"פ (מחוזי ת"א) 41927-12-13 כדורי שיווק ביצים בע"מ ה נ'' בנק מזרחי טפחות בע"מ (15.04.2015). פש"ר (מחוזי ת"א) 10344-02-16 עו"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה (01.06.2017)', 'הטעות היא להניח שנושה רגיל יכול ליהנות מהגנה שנועדה לנושה המובטח הראשון, או לבלבל בין מעמדו של הנושה הראשון למעמדם של נושים אחרים.',
      '["בטלות יחסית", "נושה רגיל", "נושה מובטח", "סעיף 6(א) לחוק המשכון", "הלכת לוי", "אינטרס הסתמכות"]'::jsonb, '**וריאציה 1 — טענת נושה רגיל:** האם נושה רגיל יכול לטעון לבטלות משכון שני שנעשה בניגוד לתניה מגבילהלא, תכלית סעיף 6(א) היא הגנה על הנושה הראשון בלבד (פש"ר (מחוזי ת"א) 10344-02-16 עו"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה).
**וריאציה 2 — אינטרס הסתמכות:** האם הכרה בתוקף המשכון השני פוגעת באינטרס ההסתמכות של נושים רגיליםלא, שכן מדובר במשכון רשום, ודבר קיומו ידוע להם (פש"ר (מחוזי ת"א) 10344-02-16 עו"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה).
**וריאציה 3 — הרחבת הלכת לוי:** האם הלכת לוי חלה גם על נושים רגיליםכן, בתי המשפט המחוזיים הרחיבו את הלכת לוי וקבעו כי גם נושים רגילים מנועים מלטעון לבטלות (ה"פ (מחוזי ת"א) 41927-12-13 כדורי שיווק ביצים בע"מ ה נ'' בנק מזרחי טפחות בע"מ).', 'נושה רגילאינו יכול לטעון לבטלות משכון שני (גם אם בניגוד להגבלההגנה רק לנושה הראשון.', '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.01.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.04.2015)", "פש\"ר (מחוזי ת\"א) 10344-02-16 עו\"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה (01.06.2017)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהמשכון השני נרשם בניגוד לתניה מגבילה, הוא בטל כלפי כולי עלמא.', false, 'תשובה זו שגויה. הלכת לוי קבעה כי הבטלות היא יחסית, ולא מוחלטת כלפי כולי עלמא.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, מכיוון שהמשכון השני פוגע באינטרס ההסתמכות של הנושים הרגילים.', false, 'תשובה זו שגויה. הפסיקה קבעה כי הכרה בתוקפו של משכון שני כלפי נושים רגילים אינה פוגעת באינטרס ההסתמכות שלהם, שכן מדובר במשכון רשום.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, מכיוון שהוראת סעיף 6(א) לחוק המשכון נועדה להגן על הנושה הראשון בלבד, ולא על נושים רגילים של החייב.', true, 'זו התשובה הנכונה. הפסיקה הרחיבה את הלכת לוי וקבעה כי גם נושים רגילים של החייב מנועים מלטעון לבטלות המשכון השני, שכן תכלית סעיף 6(א) היא הגנה על הנושה הראשון בלבד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן יוכיח הנושה הרגיל כי המשכון השני נרשם בחוסר תום לב.', false, 'תשובה זו שגויה. אף שתום לב הוא עקרון חשוב, המניעות של נושה רגיל לטעון לבטלות אינה תלויה בהוכחת חוסר תום לב, אלא בתכלית הסעיף.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q02';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'מעמד הערת אזהרה כבטוחה בחדלות פירעון', 4,
      'יצחק התחייב לרשום משכנתא לטובת חברת הביטוח על דירתו, ונרשמה הערת אזהרה לטובת חברת הביטוח. יצחק נקלע לחדלות פירעון. האם הערת האזהרה מקנה לחברת הביטוח מעמד של נושה מובטח?', 'שאלה זו עוסקת במעמדה של הערת אזהרה במקרקעין, ובפרט בהשפעתה על מעמד הנושה במצב של חדלות פירעון של החייב. היא בוחנת את הוראת סעיף 127(ב) לחוק המקרקעין, המעניקה לבעל הערת אזהרה הגנה מיוחדת מפני הליכי חדלות פירעון.', 'סעיף 127(ב) לחוק המקרקעין, תשכ"ט-1969, קובע כי ''נרשמה הערת אזהרה ולאחר מכן הוטל עיקול על המקרקעין או על הזכות במקרקעין נשוא ההערה, או שניתן צו לקבלת נכסים בפשיטת רגל או צו פירוק נגד בעל המקרקעין או בעל הזכות במקרקעין, או שנתמנה כונס נכסים על רכושו, הרי כל עוד לא נמחקה ההערה, לא יהיה בכל אלה כדי לפגוע בזכויות הזכאי הנובעות מההתחייבות נשוא ההערה''. הוראה זו מקנה לבעל הערת אזהרה מעמד של נושה מובטח, המוגן מפני הליכי חדלות פירעון של החייב, וזאת גם אם טרם נרשמה משכנתא בפועל. פש"ר (מחוזי ת"א) 58026-10-13 דוד גולבלט לוי, עו"ד (מנהל מיוחד) נ'' לוי גוטמן (22.06.2016). פש"ר (מחוזי ת"א) 11482-08-14 אודי חסון נ'' אברהם חי מכלוף (21.03.2021)', 'הטעות הנפוצה היא לחשוב שהערת אזהרה היא זכות אובליגטורית בלבד שאינה מעניקה הגנה קניינית במצב של חדלות פירעון, מבלי להכיר בהוראה הספציפית של סעיף 127(ב) לחוק המקרקעין.',
      '["הערת אזהרה", "נושה מובטח", "חדלות פירעון", "חוק המקרקעין", "סעיף 127(ב)", "זכות קניינית"]'::jsonb, '**וריאציה 1 — מעמד הערת אזהרה בחדלות פירעון:** האם הערת אזהרה מקנה מעמד של נושה מובטח בחדלות פירעוןכן, מכוח סעיף 127(ב) לחוק המקרקעין (סעיף 127(ב) לחוק המקרקעין).
**וריאציה 2 — הגנה מפני עיקול:** האם הערת אזהרה מגינה מפני עיקול מאוחרכן, סעיף 127(ב) מגן על זכויות הזכאי מפני עיקולים מאוחרים (סעיף 127(ב) לחוק המקרקעין).
**וריאציה 3 — תוקף הערת אזהרה לאחר מימוש:** האם מחיקת הערת אזהרה במימוש משכנתא שוללת את זכויות בעליהלא, מחיקה זו אינה גורעת מזכויות בעל הערת האזהרה, אלא הזכויות יתייחסו ליתרת התמורה מהמימוש (עחדל"פ (שלום תל אביב-יפו) 1582-02-23 קוואלטי קרדיט פאנד נ'' עו"ד חנן חדד).', 'הערת אזהרהמקנה מעמד נושה מובטח בחדלות פירעון (סעיף 127(ב) לחוק המקרקעיןמגינה מפני עיקולים וצווי כינוס מאוחרים.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 127(ב)", "פש\"ר (מחוזי ת\"א) 58026-10-13 דוד גולבלט לוי, עו\"ד (מנהל מיוחד) נ'' לוי גוטמן (22.06.2016)", "פש\"ר (מחוזי ת\"א) 11482-08-14 אודי חסון נ'' אברהם חי מכלוף (21.03.2021)", "עחדל\"פ (שלום תל אביב-יפו) 1582-02-23 קוואלטי קרדיט פאנד נ'' עו\"ד חנן חדד (11.06.2023)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, הערת אזהרה היא זכות אובליגטורית בלבד ואינה מקנה מעמד של נושה מובטח.', false, 'תשובה זו שגויה. הערת אזהרה, במקרים מסוימים, יכולה להקנות מעמד של נושה מובטח, במיוחד במצב של חדלות פירעון.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, הערת אזהרה מקנה מעמד של נושה מובטח, וזאת מכוח סעיף 127(ב) לחוק המקרקעין.', true, 'זו התשובה הנכונה. סעיף 127(ב) לחוק המקרקעין קובע כי הערת אזהרה מגינה על זכויות הזכאי גם במקרה של חדלות פירעון, ומקנה לו מעמד של נושה מובטח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הערת האזהרה נרשמה לפני הטלת עיקול או מתן צו כינוס נכסים.', false, 'תשובה זו שגויה חלקית. הערת אזהרה אכן מגינה מפני עיקולים וצווי כינוס מאוחרים, אך מעמדה כנושה מובטח אינו תלוי רק בכך, אלא בעיקר בסעיף 127(ב).', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן נרשמה משכנתא בפועל ולא רק הערת אזהרה.', false, 'תשובה זו שגויה. סעיף 127(ב) לחוק המקרקעין מעניק הגנה לבעל הערת אזהרה גם ללא רישום משכנתא בפועל, במקרים של חדלות פירעון.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q02';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 2, '2024-W-S-Q02';
END
$$;

-- ============================================================
-- Q03 — angles backfill for 2024-W-S-Q03 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q03';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q03';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'איחור קל במימוש אופציה', 1,
      'מירית שכרה מאלונה דירת מגורים לשנה אחת, עם אופציה לשנה נוספת, בכפוף למתן הודעה בכתב 60 יום מראש. מירית השקיעה סכום ניכר בשיפוץ הדירה, בידיעת אלונה. מירית איחרה ב-5 ימים במתן ההודעה בכתב על מימוש האופציה. אלונה, שקיבלה הצעה גבוהה יותר על הדירה, מסרבת להאריך את השכירות בטענה לאיחור. מה הדין?', 'שאלה זו בוחנת את האיזון בין דרישת הדווקנות במימוש אופציה לבין עקרון תום הלב בחוזים, במיוחד במקרים של איחור קל ושינוי מצב לרעה של השוכר. היא מדגישה את סמכות בית המשפט להתערב כאשר עמידה על זכות חוזית נעשית בחוסר תום לב.', 'הלכה פסוקה היא כי יש למלא בדייקנות ובקפדנות אחר הדרישות ההסכמיות למימוש אופציה. עם זאת, הפסיקה הכירה בכך שעמידה דווקנית על תנאי חוזי, ובפרט על איחור קל במימוש אופציה, עשויה להיחשב כחוסר תום לב, במיוחד כאשר הדבר גורם נזק ניכר לצד השני שהסתמך על מימוש האופציה. בית המשפט יבחן את נסיבות המקרה, לרבות היקף האיחור, מידת ההסתמכות של הצד השני, והאם המשכיר ידע על השקעות השוכר. במקרה של איחור קל, והשקעות משמעותיות של השוכר בידיעת המשכיר, סירוב המשכיר להאריך את השכירות עשוי להיחשב כחוסר תום לב. תא"מ (שלום ת"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע"מ (25.03.2020). תפ"מ (שלום י-ם) 5688-01-23 אמי נציגות ואחזקות בע"מ נ'' אברמוביץ עזר קקאו ושות בע"מ (05.03.2023). רע"א 2243/12 די אייץ'' אל (ישראל) בע"מ נ'' יוסי עטר (10.04.2012)', 'הטעות הנפוצה היא להתעלם מעקרון תום הלב בחוזים, ולחשוב שניתן לעמוד באופן מוחלט על כל תנאי חוזי, גם אם הדבר גורם עוול לצד השני.',
      '["אופציה", "תום לב", "עמידה דווקנית", "הפרת חוזה", "שינוי מצב לרעה", "סעיף 39 לחוק החוזים"]'::jsonb, '**וריאציה 1 — איחור קל והשקעות:** שוכר איחר קלות במימוש אופציה והשקיע רבות במושכר. האם המשכיר יכול לסרבלא, עמידה דווקנית על איחור קל בנסיבות אלו עשויה להיחשב כחוסר תום לב (תפ"מ (שלום י-ם) 5688-01-23 אמי נציגות ואחזקות בע"מ נ'' אברמוביץ עזר קקאו ושות בע"מ).
**וריאציה 2 — דרישת דווקנות:** מהי הגישה הכללית למימוש אופציהיש למלא בדייקנות ובקפדנות אחר הדרישות ההסכמיות למימושה (תא"מ (שלום ת"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע"מ).
**וריאציה 3 — התערבות בית המשפט:** מתי יתערב בית המשפט בעמידה דווקניתכאשר עמידה על זכות חוזית גורמת עוול או נעשית בחוסר תום לב (רע"א 2243/12 די אייץ'' אל (ישראל) בע"מ נ'' יוסי עטר).', 'איחור קל במימוש אופציה + השקעותעשוי להיחשב חוסר תום לבבית המשפט יאכוף את האופציה.', '["תא\"מ (שלום ת\"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע\"מ (25.03.2020)", "תפ\"מ (שלום י-ם) 5688-01-23 אמי נציגות ואחזקות בע\"מ נ'' אברמוביץ עזר קקאו ושות בע\"מ (05.03.2023)", "רע\"א 2243/12 די אייץ'' אל (ישראל) בע\"מ נ'' יוסי עטר (10.04.2012)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'אלונה רשאית לסרב, שכן מימוש אופציה דורש עמידה דווקנית בתנאים שנקבעו בחוזה.', false, 'תשובה זו שגויה. אף שקיימת דרישה לעמידה דווקנית, הפסיקה מכירה בחריגים המבוססים על עקרון תום הלב, במיוחד במקרים של איחור קל ושינוי מצב לרעה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'אלונה אינה רשאית לסרב, שכן איחור קל בנסיבות אלו מהווה עמידה בחוסר תום לב על זכות חוזית, במיוחד לאור השקעותיה של מירית.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי עמידה דווקנית על איחור קל במימוש אופציה, במיוחד כאשר הדבר גורם נזק ניכר לצד השני שהסתמך על מימוש האופציה (כמו השקעות במושכר), עשויה להיחשב כחוסר תום לב.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'האופציה פקעה עקב האיחור, אך מירית זכאית לפיצוי מאלונה בגין השקעותיה בדירה.', false, 'תשובה זו שגויה. במקרים של חוסר תום לב בעמידה על זכות, בית המשפט עשוי לאכוף את מימוש האופציה ולא רק לפסוק פיצויים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'האיחור אינו רלוונטי, שכן סעיף 25יב(ג) לחוק השכירות והשאילה קובע מועד קוגנטי של 60 יום, וכל הודעה בתוך מועד זה תקפה.', false, 'תשובה זו שגויה. סעיף 25יב(ג) קובע מועד מקסימלי, אך אינו מבטל את דרישת החוזה לעמידה במועד ספציפי בתוך תקופה זו. בנוסף, האיחור היה לאחר המועד הקבוע בחוזה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q03';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'דרישת הכתב למימוש אופציה', 2,
      'מירית שכרה מאלונה דירת מגורים לשנה אחת. החוזה קובע אופציה לשנה נוספת, ודורש כי הודעה על מימוש האופציה תינתן בכתב 60 יום מראש. מירית הודיעה לאלונה בעל פה, בשיחת טלפון, על רצונה לממש את האופציה, 70 יום לפני תום תקופת השכירות. אלונה לא התנגדה באותה שיחה. האם האופציה מומשה כדין?', 'שאלה זו עוסקת בדרישת הכתב למימוש אופציה בחוזה שכירות, ובאפשרות לסטות מדרישה זו באמצעות הסכמה בעל פה או התנהגות הצדדים. היא בוחנת את עקרון חופש החוזים ואת גמישותו של הדין לאור אומד דעת הצדדים בפועל.', 'הפסיקה קבעה כי אף שחוזה עשוי לדרוש כתב למימוש אופציה, הצדדים רשאים לשנות תנאי זה בהסכמה בעל פה או באמצעות התנהגותם. סעיף 23 לחוק החוזים (חלק כללי) קובע כי חוזה יכול להיעשות בכל צורה, אלא אם צורה מסוימת היא תנאי לתוקפו על פי חוק או הסכם. גם כאשר החוזה קובע דרישת כתב לשינויים, ניתן לסטות מכך בהסכמה מאוחרת, מפורשת או משתמעת, ובלבד שאומד דעת הצדדים לשינוי ברור. במקרה זה, אי התנגדותה של אלונה למימוש בעל פה עשויה להתפרש כהסכמה לשינוי דרישת הכתב. תא"מ (שלום ת"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע"מ (25.03.2020). תא"ק (שלום ת"א) 11154-01-15 דקור - סטאר בע"מ נ'' דוד ראשיד (06.12.2016). ע"א (מחוזי י-ם) 63031-12-25 יצחק משה ערנפלד נ'' חיה ליבא סגל (04.03.2026)', 'הטעות הנפוצה היא לחשוב שדרישת כתב בחוזה היא מוחלטת ואינה ניתנת לשינוי, גם כאשר הצדדים בפועל מסכימים לסטות ממנה.',
      '["דרישת כתב", "שינוי חוזה בהתנהגות", "אומד דעת הצדדים", "חופש החוזים", "מימוש אופציה", "הסכמה בעל פה"]'::jsonb, '**וריאציה 1 — שינוי דרישת כתב:** האם ניתן לשנות דרישת כתב למימוש אופציה בהסכמה בעל פהכן, הפסיקה הכירה באפשרות לשינוי תנאי חוזה בהתנהגות או בעל פה (תא"מ (שלום ת"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע"מ).
**וריאציה 2 — אומד דעת:** מהו המבחן לשינוי דרישת כתבאומד דעת הצדדים לשינוי צריך להיות ברור, גם אם לא מפורש בכתב (תא"ק (שלום ת"א) 11154-01-15 דקור - סטאר בע"מ נ'' דוד ראשיד).
**וריאציה 3 — חשיבות הכתב:** מדוע חשובה דרישת הכתב מלכתחילהלמנוע מחלוקות עתידיות ולהבטיח ודאות משפטית (תא"מ (שלום ת"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע"מ).', 'דרישת כתב למימוש אופציהניתנת לשינוי בהסכמה בעל פה או התנהגותאומד דעת הצדדים קובע.', '["תא\"מ (שלום ת\"א) 18355-08-18 הייתם קדומי נ'' קבוצת ר. מזרחי אחזקות (2009) בע\"מ (25.03.2020)", "תא\"ק (שלום ת\"א) 11154-01-15 דקור - סטאר בע\"מ נ'' דוד ראשיד (06.12.2016)", "ע\"א (מחוזי י-ם) 63031-12-25 יצחק משה ערנפלד נ'' חיה ליבא סגל (04.03.2026)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, שכן החוזה דורש הודעה בכתב, ודרישה זו קוגנטית ואינה ניתנת לשינוי בעל פה.', false, 'תשובה זו שגויה. דרישת הכתב למימוש אופציה אינה קוגנטית וניתנת לשינוי בהסכמה או בהתנהגות הצדדים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, שכן הצדדים רשאים לשנות את תנאי החוזה בהתנהגות או בעל פה, ואי התנגדותה של אלונה מהווה הסכמה לשינוי דרישת הכתב.', true, 'זו התשובה הנכונה. הפסיקה הכירה באפשרות לשינוי תנאי חוזה, לרבות דרישת כתב, באמצעות התנהגות הצדדים או הסכמה בעל פה, גם אם החוזה קובע אחרת.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, שכן סעיף 25יב(ג) לחוק השכירות והשאילה דורש הודעה בכתב למימוש אופציה על ידי שוכר.', false, 'תשובה זו שגויה. סעיף 25יב(ג) קובע את מועד ההודעה, אך אינו דורש כתב באופן מפורש, אלא אם החוזה קובע זאת. גם אם החוזה דורש כתב, ניתן לשנות זאת בהסכמה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם מירית תוכיח שאלונה פעלה בחוסר תום לב בכך שלא התנגדה למימוש בעל פה.', false, 'תשובה זו שגויה. תום לב הוא עקרון חשוב, אך עצם ההסכמה לשינוי דרישת הכתב היא העיקר, ולאו דווקא חוסר תום לב של הצד השני.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q03';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'אופציה ללא תנאים מפורטים', 3,
      'מירית שכרה מאלונה דירת מגורים לשנה אחת. החוזה קובע כי ''לשוכרת אופציה להארכת תקופת השכירות לשנה נוספת'', אך אינו מפרט את דמי השכירות לתקופת האופציה או תנאים מהותיים אחרים. מירית הודיעה במועד על רצונה לממש את האופציה. האם האופציה תקפה?', 'שאלה זו עוסקת בדרישת המסוימות בחוזים, ובפרט באופציות להארכת שכירות. היא בוחנת את הצורך בפירוט תנאים מהותיים בחוזה, כגון דמי שכירות, כדי שהאופציה תהיה תקפה וניתנת לאכיפה, בהתאם לחוק השכירות והשאילה ולחוק החוזים.', 'סעיף 25ג לחוק השכירות והשאילה, בצירוף התוספת השנייה, קובע כי חוזה שכירות למגורים יכלול, בין השאר, את ''קיומה של ברירה להארכת התקופה ותנאי הברירה כאמור''. דרישה זו משקפת את עקרון המסוימות הכללי בדיני חוזים. כאשר אופציה להארכת שכירות אינה מפרטת תנאים מהותיים כמו דמי השכירות לתקופת האופציה, היא עלולה להיחשב כחסרת מסוימות ולכן אינה תקפה. בית המשפט לא ישלים תנאים מהותיים אלו אם הדבר יפגע בחופש החוזים של הצדדים. סעיף 25ג לחוק השכירות והשאילה, התשל"א-1971. ע"א (מחוזי ירושלים) 53116-03-26 מדינה גוליאמוב נ'' רועי נהרי (14.04.2026). תפ"מ (שלום י-ם) 26069-09-25 רועי נהרי נ'' מדינה גוליאמוב (18.01.2026)', 'הטעות הנפוצה היא להניח שדי באזכור כללי של ''אופציה'' כדי להקנות זכות תקפה, מבלי להבין את דרישת המסוימות והצורך בפירוט תנאים מהותיים.',
      '["מסוימות", "אופציה", "חוק השכירות והשאילה", "השלמת חוזה", "דמי שכירות", "תנאים מהותיים"]'::jsonb, '**וריאציה 1 — חוסר מסוימות באופציה:** האם אופציה ללא פירוט דמי שכירות תקפהלא, היא עלולה להיחשב כחסרת מסוימות ואינה תקפה (ע"א (מחוזי ירושלים) 53116-03-26 מדינה גוליאמוב נ'' רועי נהרי).
**וריאציה 2 — דרישת החוק:** מה דורש חוק השכירות והשאילה לגבי תנאי אופציהחוזה שכירות למגורים יכלול ''קיומה של ברירה להארכת התקופה ותנאי הברירה כאמור'' (סעיף 25ג לחוק השכירות והשאילה).
**וריאציה 3 — השלמת תנאים:** האם בית המשפט יכול להשלים תנאים חסרים באופציהלא תמיד, במיוחד אם מדובר בתנאים מהותיים כמו דמי שכירות, שכן הדבר עלול לפגוע בחופש החוזים (תפ"מ (שלום י-ם) 26069-09-25 רועי נהרי נ'' מדינה גוליאמוב).', 'אופציה ללא תנאים מהותיים (דמי שכירותחסרת מסוימותאינה תקפה.', '["חוק השכירות והשאילה, תשכ\"א-1971, סעיף 25ג", "ע\"א (מחוזי ירושלים) 53116-03-26 מדינה גוליאמוב נ'' רועי נהרי (14.04.2026)", "תפ\"מ (שלום י-ם) 26069-09-25 רועי נהרי נ'' מדינה גוליאמוב (18.01.2026)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, האופציה אינה תקפה בשל חוסר מסוימות, שכן תנאיה המהותיים לא פורטו בחוזה.', true, 'זו התשובה הנכונה. בהיעדר פירוט של תנאים מהותיים כמו דמי שכירות לתקופת האופציה, האופציה עלולה להיחשב כחסרת מסוימות ולכן אינה תקפה, אלא אם ניתן להשלים את התנאים באופן אובייקטיבי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, האופציה תקפה, ודמי השכירות לתקופת האופציה יהיו זהים לדמי השכירות בתקופה הראשונה.', false, 'תשובה זו שגויה. בהיעדר קביעה מפורשת, לא ניתן להניח שדמי השכירות יישארו זהים, וזהו תנאי מהותי שיש לפרטו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, האופציה תקפה, ודמי השכירות לתקופת האופציה ייקבעו על פי המקובל בשוק באותה עת.', false, 'תשובה זו שגויה. אף שניתן להשלים תנאים חסרים במקרים מסוימים, דמי שכירות הם תנאי מהותי שחובה לפרטו באופציה, ובהיעדר הסכמה מראש, קשה להשלים זאת ללא פגיעה בחופש החוזים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הצדדים יגיעו להסכמה חדשה לגבי תנאי האופציה.', false, 'תשובה זו שגויה. אם האופציה אינה תקפה בשל חוסר מסוימות, הרי שאין אופציה לממש, וכל הסכמה חדשה תהווה חוזה חדש ולא מימוש אופציה קיימת.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q03';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'ביטול חוזה שכירות למגורים', 4,
      'מירית שכרה מאלונה דירת מגורים לשנה. חודשיים לאחר תחילת השכירות, התגלו בדירה ליקויים חמורים (רטיבות קשה, בעיות חשמל) שהופכים את הדירה לבלתי ראויה למגורים. מירית הודיעה לאלונה על הליקויים ודרשה תיקונם, אך אלונה לא תיקנה אותם בתוך זמן סביר. מירית מעוניינת לבטל את החוזה ולפנות את הדירה. מה הדין?', 'שאלה זו עוסקת בזכותו של שוכר לבטל חוזה שכירות למגורים עקב ליקויים חמורים במושכר, בהתאם להוראות חוק השכירות והשאילה ודיני החוזים הכלליים. היא מדגישה את חובת המשכיר למסור דירה ראויה למגורים ואת הסעדים העומדים לשוכר במקרה של הפרה.', 'חוק השכירות והשאילה, ובפרט סעיפים 25ו ו-25ח, מטילים על המשכיר חובה למסור דירה ראויה למגורים ולתקן ליקויים שאינם באחריות השוכר. אי מסירת דירה ראויה למגורים או אי תיקון ליקויים חמורים המונעים מגורים סבירים, מהווה הפרה יסודית של החוזה. במקרה של הפרה יסודית, השוכר זכאי לבטל את החוזה באופן מיידי, ללא צורך במתן ארכה לתיקון ההפרה, וזאת בהתאם לדיני החוזים הכלליים (חוק החוזים (תרופות בשל הפרת חוזה)). סעיף 25יג לחוק השכירות והשאילה עוסק בביטול חוזה שלא בשל הפרה, ואינו רלוונטי למקרה של הפרה יסודית. סעיף 25ח(ב) לחוק השכירות והשאילה, התשל"א-1971. סעיף 25ו(ב) לחוק השכירות והשאילה, התשל"א-1971. ת"א (שלום ת"א) 40486-11-24 מאיה נורי שקד נ'' בנימין הפנר (17.11.2024)', 'הטעות הנפוצה היא לבלבל בין ביטול חוזה בשל הפרה לבין ביטול חוזה שלא בשל הפרה, ולהחיל את מועדי ההודעה של ביטול ללא עילה גם על מקרים של הפרה יסודית.',
      '["ביטול חוזה", "הפרה יסודית", "ליקויים במושכר", "דירה ראויה למגורים", "חוק השכירות והשאילה", "סעדים"]'::jsonb, '**וריאציה 1 — ליקויים חמורים:** האם ליקויים חמורים המונעים מגורים סבירים מקנים זכות ביטולכן, אי תיקון פגם דחוף מהווה הפרה יסודית המקנה זכות ביטול מיידית (סעיף 25ח(ב) לחוק השכירות והשאילה).
**וריאציה 2 — מועד תיקון:** כמה זמן יש למשכיר לתקן פגם דחוףבתוך זמן סביר ולא יאוחר משלושה ימים מיום קבלת הדרישה (סעיף 25ח(ב) לחוק השכירות והשאילה).
**וריאציה 3 — ביטול ללא עילה:** מה ההבדל בין ביטול בשל הפרה לביטול ללא עילהביטול בשל הפרה יסודית הוא מיידי, בעוד שביטול ללא עילה דורש הודעה מראש (90 יום למשכיר, 60 יום לשוכר) (סעיף 25יג(ב) לחוק השכירות והשאילה).', 'ליקויים חמורים בדירההפרה יסודיתזכות ביטול מיידית לשוכר (סעיף 25ו, 25ח).', '["חוק השכירות והשאילה, תשכ\"א-1971, סעיף 25ו", "חוק השכירות והשאילה, תשכ\"א-1971, סעיף 25ח", "חוק השכירות והשאילה, תשכ\"א-1971, סעיף 25יג", "ת\"א (שלום ת\"א) 40486-11-24 מאיה נורי שקד נ'' בנימין הפנר (17.11.2024)", "תא\"ח (שלום ת\"א) 17694-12-20 מאמוס קלימו בלחסן נ'' רהיטי דורון עיצובים בע\"מ (18.05.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'מירית רשאית לבטל את החוזה באופן מיידי ולפנות את הדירה, שכן אי תיקון ליקויים חמורים מהווה הפרה יסודית של החוזה.', true, 'זו התשובה הנכונה. אי מסירת דירה ראויה למגורים או אי תיקון ליקויים חמורים המונעים מגורים סבירים, מהווה הפרה יסודית של החוזה, המקנה לשוכר זכות ביטול מיידית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'מירית אינה רשאית לבטל את החוזה, אלא רק לדרוש מאלונה להפחית את דמי השכירות עד לתיקון הליקויים.', false, 'תשובה זו שגויה. אף שזכות להפחתת דמי שכירות קיימת, במקרה של ליקויים חמורים המהווים הפרה יסודית, השוכר זכאי גם לבטל את החוזה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'מירית רשאית לבטל את החוזה, אך עליה להודיע לאלונה 60 יום מראש על כוונתה לבטל.', false, 'תשובה זו שגויה. דרישת הודעה מראש של 60 יום חלה על ביטול חוזה שלא בשל הפרה (סעיף 25יג(ב)), אך במקרה של הפרה יסודית, הביטול יכול להיות מיידי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'מירית אינה רשאית לבטל את החוזה, שכן חוק השכירות והשאילה אינו מאפשר ביטול חוזה שכירות למגורים לפני תום התקופה.', false, 'תשובה זו שגויה. חוק השכירות והשאילה, כמו דיני חוזים כלליים, מאפשר ביטול חוזה במקרה של הפרה יסודית, ובמיוחד כאשר הדירה אינה ראויה למגורים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q03';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 3, '2024-W-S-Q03';
END
$$;

-- ============================================================
-- Q04 — angles backfill for 2024-W-S-Q04 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q04';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q04';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'פגיעה עקיפה ודרישת הוכחה קונקרטית', 1,
      'ראובן הגיש תביעת פיצויים לפי סעיף 197 לחוק התכנון והבניה בטענה לפגיעה עקיפה במקרקעיו (חסימת נוף ופגיעה בפרטיות) כתוצאה מתוכנית חדשה שאושרה במגרש גובל. ראובן צירף לטענותיו חוות דעת שמאית המבוססת על מחקרים כלליים ומקרי מבחן מערים אחרות וממועדים קודמים. האם חוות דעת זו מספיקה להרמת נטל ההוכחה הראשוני המוטל על ראובן?', 'שאלה זו עוסקת בנטל ההוכחה המוטל על תובע פיצויים לפי סעיף 197 לחוק התכנון והבניה, ובדרישות מחוות דעת שמאית, במיוחד כאשר מדובר בפגיעה עקיפה. היא מדגישה את הצורך בראיות קונקרטיות ומנומקות, ולא רק כלליות, להוכחת ירידת ערך המקרקעין.', 'נטל השכנוע להוכחת התקיימות יסודותיו של סעיף 197 לחוק מוטל על תובע הפיצויים, ובכלל זאת להוכיח את עצם הפגיעה שנגרמה מהתוכנית ואת שיעור הפגיעה. הפסיקה קבעה כי אין די בחוות דעת סתמית, אלא שחוות הדעת חייבת להיות משכנעת ומנומקת, ולכלול את מלוא הנתונים החיוניים לתביעת הפיצויים. במקרה של פגיעה עקיפה, יש להראות יישום קונקרטי של מסקנות ומחקרים על המקרה הספציפי, ולא להסתמך על מחקרים כלליים או מקרי מבחן שאינם דומים למקרקעין הנדונים. ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון (04.03.2025). ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה (14.09.2017). ערר (ועדות ערר - תכנון ובנייה צפון) 930/13 אריזות מבח"ר (1973) בע"מ נ'' ועדה מקומית לתכנון ובניה גליל עליון (23.08.2015)', 'הטעות הנפוצה היא להסתפק בחוות דעת שמאית כללית או לא מפורטת מספיק, מבלי להבין את הדרישה להוכחה קונקרטית של הפגיעה במקרקעין הספציפיים.',
      '["סעיף 197 לחוק התכנון והבניה", "נטל הוכחה", "חוות דעת שמאית", "פגיעה עקיפה", "ירידת ערך", "קשר סיבתי"]'::jsonb, '**וריאציה 1 — דרישות מחוות דעת:** האם חוות דעת שמאית המבוססת על מחקרים כלליים מספיקה להוכחת פגיעה עקיפהלא, נדרש יישום קונקרטי של המסקנות למקרה הספציפי (ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון).
**וריאציה 2 — נטל ההוכחה הראשוני:** מי נושא בנטל ההוכחה הראשוני לפגיעההתובע (ראובן) צריך להוכיח את עצם הפגיעה ושיעורה (ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה).
**וריאציה 3 — פגיעה סובייקטיבית מול אובייקטיבית:** האם נדרשת הוכחת פגיעה סובייקטיביתלא, הפגיעה נבדקת באופן אובייקטיבי ביחס למקרקעין, אך יש להראות פגיעה סובייקטיבית בנסיבות המקרה הספציפיות (ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון).', 'הוכחת פגיעה עקיפהדורשת חוות דעת שמאית קונקרטית ומנומקתלא די במחקרים כלליים.', '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון (04.03.2025)", "ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה (14.09.2017)", "ערר (ועדות ערר - תכנון ובנייה צפון) 930/13 אריזות מבח\"ר (1973) בע\"מ נ'' ועדה מקומית לתכנון ובניה גליל עליון (23.08.2015)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, די בחוות דעת שמאית המצביעה על ירידת ערך כללית, שכן פגיעה עקיפה קשה להוכחה באופן קונקרטי.', false, 'תשובה זו שגויה. הפסיקה דורשת חוות דעת משכנעת ומנומקת, המיישמת את המסקנות באופן קונקרטי למקרה הנדון, ולא מסתפקת במחקרים כלליים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חוות הדעת חייבת להיות משכנעת ומנומקת, ולכלול נתונים חיוניים המצביעים על פגיעה סובייקטיבית וקונקרטית במקרקעין של ראובן.', true, 'זו התשובה הנכונה. נטל ההוכחה על התובע דורש חוות דעת שמאית קונקרטית, המבססת את הפגיעה במקרקעין הספציפיים, ולא רק על מחקרים כלליים או מקרי מבחן שאינם דומים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם הוועדה המקומית לא הגישה חוות דעת נגדית, הרי שחוות דעתו של ראובן תתקבל.', false, 'תשובה זו שגויה. גם בהיעדר חוות דעת נגדית, על התובע להרים את נטל ההוכחה הראשוני באמצעות חוות דעת העומדת באמות המידה שנקבעו בפסיקה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, שכן פגיעה עקיפה אינה מזכה בפיצויים לפי סעיף 197 לחוק התכנון והבניה.', false, 'תשובה זו שגויה. סעיף 197 חל גם על פגיעה עקיפה, אך נדרש קשר סיבתי ברור והוכחה קונקרטית של הפגיעה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q04';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחני הסבירות והצדק בסעיף 200', 2,
      'הוועדה המקומית טוענת לפטור מפיצויים לפי סעיף 200 לחוק התכנון והבניה. אילו שיקולים יבחן בית המשפט בקביעת התקיימות תנאי ''הסבירות'' ו''הצדק''?', 'שאלה זו מתמקדת בתנאים המצטברים לפטור מפיצויים לפי סעיף 200 לחוק התכנון והבניה, ובפרט במבחנים שנקבעו בפסיקה לבחינת ''הפגיעה אינה עוברת את תחום הסביר'' ו''אין זה מן הצדק לשלם לנפגע פיצויים''. היא מדגישה את האיזון בין זכות הקניין לאינטרס הציבורי ואת נטל ההוכחה המוטל על הוועדה המקומית.', 'סעיף 200 לחוק התכנון והבניה קובע שלושה תנאים מצטברים לפטור מתשלום פיצויים: (א) הפגיעה נמנית עם אחת ההוראות המפורטות בסעיף; (ב) הפגיעה אינה עוברת את תחום הסביר בנסיבות העניין; (ג) אין זה מן הצדק לשלם לנפגע פיצויים. נטל ההוכחה לקיומם של תנאים אלה מוטל על הוועדה המקומית. לבחינת תנאי הסבירות, הפסיקה (בעניין הורוויץ) קבעה שיש לערוך איזון בין זכות הקניין לאינטרס הציבורי, תוך התחשבות בשלושה שיקולים מרכזיים: גודל ירידת הערך, מידת פיזור הנזק, וקיומו של אינטרס ציבורי חיוני בתכנית. שיקולים אלה אינם רשימה סגורה. תנאי הצדק הוא מבחן פתוח וגמיש, הנבחן לפי נסיבות המקרה הקונקרטיות, ונועד להבטיח פטור רק במקרים יוצאי דופן. סעיף 200 לחוק התכנון והבניה, תשכ"ה-1965. עע"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'' (03.09.2015). עת"מ (מנהלי תל אביב-יפו) 253-09 הוועדה המקומית לתכנון ובנייה הוד השרון נ'' תומר וינשטיין (06.11.2011). עמ"נ (מינהליים י-ם) 305/06 הוועדה המקומית לתכנון ולבניה ירושלים נ'' יששכר מ. חברה לבנין ופיתוח בע"מ (26.08.2010)', 'הטעות הנפוצה היא לחשוב שקיימים אחוזים קבועים המגדירים פגיעה סבירה, או לבלבל בין נטל ההוכחה של התובע לבין נטל ההוכחה של הוועדה המקומית לעניין הפטור.',
      '["סעיף 200 לחוק התכנון והבניה", "תנאים מצטברים", "תנאי הסבירות", "תנאי הצדק", "נטל הוכחה", "איזון אינטרסים", "הלכת הורוויץ"]'::jsonb, '**וריאציה 1 — שיקולי סבירות:** אילו שיקולים נבחנים בקביעת סבירות הפגיעהשיעור ירידת הערך, מידת פיזור הנזק, ואינטרס ציבורי חיוני הגלום בתכנית (עת"מ (מנהלי תל אביב-יפו) 253-09 הוועדה המקומית לתכנון ובנייה הוד השרון נ'' תומר וינשטיין).
**וריאציה 2 — נטל הוכחת הפטור:** מי נושא בנטל ההוכחה להתקיימות תנאי הפטור בסעיףהוועדה המקומית (עמ"נ (מינהליים י-ם) 305/06 הוועדה המקומית לתכנון ולבניה ירושלים נ'' יששכר מ. חברה לבנין ופיתוח בע"מ).
**וריאציה 3 — פרשנות סעיף 200:** כיצד יש לפרש את סעיףבצמצום, שכן הוא חריג לכלל הפיצוי הקבוע בסעיף 197 (עע"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'').', 'סעיףפטור מפיצויים (חריגתנאים מצטברים (סוג פגיעה, סבירות, צדקנטל הוכחה על הוועדה המקומית.', '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 200", "עע\"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'' (03.09.2015)", "עת\"מ (מנהלי תל אביב-יפו) 253-09 הוועדה המקומית לתכנון ובנייה הוד השרון נ'' תומר וינשטיין (06.11.2011)", "עמ\"נ (מינהליים י-ם) 305/06 הוועדה המקומית לתכנון ולבניה ירושלים נ'' יששכר מ. חברה לבנין ופיתוח בע\"מ (26.08.2010)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'תנאי הסבירות ייקבע על פי שיעור ירידת הערך בלבד, ותנאי הצדק ייקבע על פי מידת תום הלב של התובע.', false, 'תשובה זו שגויה. שיעור ירידת הערך הוא שיקול מרכזי אך לא יחיד, ותנאי הצדק אינו מוגבל לתום לב התובע.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'תנאי הסבירות ייקבע על פי שיעור ירידת הערך, מידת פיזור הנזק והאינטרס הציבורי החיוני הגלום בתכנית. תנאי הצדק הוא מבחן פתוח וגמיש הנבחן לפי נסיבות המקרה הקונקרטיות.', true, 'זו התשובה הנכונה. הפסיקה קבעה שלושה שיקולים מרכזיים לבחינת הסבירות, ותנאי הצדק נבחן באופן גמיש וקונקרטי, תוך נטל הוכחה על הוועדה המקומית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'תנאי הסבירות ייקבע על פי קיומו של אינטרס ציבורי חיוני בלבד, ותנאי הצדק ייקבע על פי יכולת התובע לשאת בנזק.', false, 'תשובה זו שגויה. אינטרס ציבורי הוא שיקול אחד מני רבים, ויכולת התובע לשאת בנזק אינה המבחן הבלעדי לצדק.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'תנאי הסבירות ייקבע על פי קביעת שמאי מכריע, ותנאי הצדק ייקבע על פי החלטת הוועדה המקומית.', false, 'תשובה זו שגויה. השמאי המכריע קובע את שיעור הפגיעה, אך בית המשפט או ועדת הערר הם אלה שקובעים את הסבירות והצדק, תוך הפעלת שיקול דעת משפטי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q04';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'שיעור פגיעה זניח וסעיף 200', 3,
      'ראובן הגיש תביעת פיצויים לפי סעיף 197 לחוק התכנון והבניה. השמאי המכריע קבע כי שיעור הפגיעה במקרקעין של ראובן עומד על 2% מערכם. הוועדה המקומית טוענת כי פגיעה בשיעור כזה היא ''זניחה'' ואינה עוברת את תחום הסביר, ולכן יש לפטור אותה מפיצויים לפי סעיף 200 לחוק. האם טענתה תתקבל?', 'שאלה זו עוסקת במבחן ''הסבירות'' שבסעיף 200 לחוק התכנון והבניה, ובפרט בשאלה האם קיים רף אחיד באחוזים לקביעת פגיעה סבירה. היא מדגישה את עמדת הפסיקה לפיה אין לקבוע שיעור קבוע, אלא יש לבחון את מכלול הנסיבות והשיקולים בכל מקרה לגופו.', 'הפסיקה, ובפרט הדיון הנוסף בעניין הורוויץ, דחתה את הגישה לפיה ניתן לקבוע רף אחיד באחוזים (כגון 3% או 12%) לפגיעה הנחשבת סבירה לצורך סעיף 200 לחוק התכנון והבניה. נקבע כי שאלת הסבירות של הפגיעה תיקבע בכל מקרה ומקרה על פי נסיבותיו, תוך איזון בין זכות הקניין לאינטרס הציבורי. שיעור ירידת הערך הוא שיקול מרכזי, אך יש להתחשב גם במידת פיזור הנזק ובחיוניות האינטרס הציבורי הגלום בתכנית. גם אם שיעור הפגיעה נמוך, אין בכך כדי לפטור אוטומטית מפיצוי, אלא יש לבחון את מכלול השיקולים. עמ"נ (מינהליים י-ם) 45066-03-10 הועדה המקומית לתכנון ולבניה ירושלים נ'' שבתאי זכריה ו-35 אח'' (27.10.2010). בר"מ 8282/07 הוועדה המקומית לתכנון ולבנייה אשקלון נ'' בנימין גינוסר ואח'' (20.08.2008). עמ"נ (מינהליים ת"א) 41615-07-11 הועדה המקומית לתכנון ובנייה קרית אונו נ'' ציפורה גולדשפלד (16.04.2012)', 'הטעות הנפוצה היא לחפש ''מספר קסם'' או אחוז קבוע שיגדיר פגיעה סבירה, במקום להבין את המבחן המורכב והגמיש שנקבע בפסיקה.',
      '["סעיף 200 לחוק התכנון והבניה", "תנאי הסבירות", "הלכת הורוויץ", "שיעור ירידת ערך", "פיזור נזק", "אינטרס ציבורי", "איזון אינטרסים"]'::jsonb, '**וריאציה 1 — רף אחיד לאחוז פגיעה:** האם קיים רף אחיד באחוזים לפגיעה סבירה לפי סעיףלא, הפסיקה קבעה שאין לקבוע שיעור אחיד, ושאלת הסבירות נבחנת בכל מקרה לגופו (עמ"נ (מינהליים י-ם) 45066-03-10 הועדה המקומית לתכנון ולבניה ירושלים נ'' שבתאי זכריה ו-35 אח'').
**וריאציה 2 — שיקולים נוספים לסבירות:** אילו שיקולים נוספים נבחנים מעבר לשיעור ירידת הערךמידת פיזור הנזק וקיומו של אינטרס ציבורי חיוני הגלום בתכנית (עת"מ (מנהלי תל אביב-יפו) 253-09 הוועדה המקומית לתכנון ובנייה הוד השרון נ'' תומר וינשטיין).
**וריאציה 3 — נטל ההוכחה:** מי נושא בנטל ההוכחה שהפגיעה אינה עוברת את תחום הסבירהוועדה המקומית (עמ"נ (מינהליים י-ם) 305/06 הוועדה המקומית לתכנון ולבניה ירושלים נ'' יששכר מ. חברה לבנין ופיתוח בע"מ).', 'פגיעה זניחהאין רף אחיד לסבירותנבחן לפי נסיבות המקרה (שיעור, פיזור, אינטרס ציבורי).', '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 200", "עמ\"נ (מינהליים י-ם) 45066-03-10 הועדה המקומית לתכנון ולבניה ירושלים נ'' שבתאי זכריה ו-35 אח'' (27.10.2010)", "בר\"מ 8282/07 הוועדה המקומית לתכנון ולבנייה אשקלון נ'' בנימין גינוסר ואח'' (20.08.2008)", "עת\"מ (מנהלי תל אביב-יפו) 253-09 הוועדה המקומית לתכנון ובנייה הוד השרון נ'' תומר וינשטיין (06.11.2011)", "עמ\"נ (מינהליים י-ם) 305/06 הוועדה המקומית לתכנון ולבניה ירושלים נ'' יששכר מ. חברה לבנין ופיתוח בע\"מ (26.08.2010)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, הפסיקה קבעה כי פגיעה שאינה עולה על 3% מערך הנכס תיחשב תמיד כסבירה וזניחה.', false, 'תשובה זו שגויה. הפסיקה דחתה קביעת רף אחיד באחוזים, וקבעה כי שאלת הסבירות נבחנת בכל מקרה לגופו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, אין לקבוע רף אחיד באחוזים, ושאלת הסבירות תיקבע בכל מקרה ומקרה על פי נסיבותיו, תוך איזון בין זכות הקניין לאינטרס הציבורי.', true, 'זו התשובה הנכונה. הפסיקה (בעניין הורוויץ) קבעה במפורש כי אין לקבוע שיעור אחיד של פגיעה שייחשב סביר, אלא יש לבחון את מכלול השיקולים בכל מקרה לגופו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם הוועדה המקומית תוכיח שהפגיעה מפוזרת על פני אוכלוסייה רחבה, גם פגיעה של 2% תיחשב סבירה.', false, 'תשובה זו שגויה חלקית. פיזור הנזק הוא שיקול אחד מני רבים, אך אינו מכריע לבדו, ואין רף קבוע לאחוז הפגיעה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, שכן כל פגיעה בשווי המקרקעין, גם אם קטנה, מזכה בפיצוי מלא לפי סעיף 197 לחוק.', false, 'תשובה זו שגויה. סעיף 200 מאפשר פטור מפיצוי גם במקרים של פגיעה קטנה, אם היא עומדת בתנאי הסבירות והצדק.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q04';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות ועדת הערר למינוי שמאי מייעץ', 4,
      'ראובן הגיש תביעת פיצויים לפי סעיף 197 לחוק התכנון והבניה, בצירוף חוות דעת שמאית מטעמו. הוועדה המקומית חולקת על קביעות חוות הדעת. ראובן מבקש מוועדת הערר למנות שמאי מייעץ. באילו תנאים תמנה ועדת הערר שמאי מייעץ?', 'שאלה זו עוסקת בסמכותה של ועדת הערר למנות שמאי מייעץ בתביעות פיצויים לפי סעיף 197 לחוק התכנון והבניה. היא בוחנת את אמות המידה שנקבעו בפסיקה למינוי כזה, ומדגישה את הצורך בעמידה בנטל הוכחה ראשוני מצד התובע לפני שוועדת הערר תשקול מינוי שמאי מייעץ.', 'סמכותה של ועדת הערר למנות שמאי מייעץ בתביעות לפי סעיף 197 לחוק התכנון והבניה היא סמכות שבשיקול דעת. בית המשפט העליון (בעניין קמינצקי) קבע כי כדי שוועדת הערר תמנה שמאי מייעץ, על התובע לעמוד בנטל הראשוני ולשכנע כי הוא עומד בדרישותיו של סעיף 197 לחוק. נטל זה כולל שלושה תנאים מצטברים: (1) הוכחת זכות במקרקעין המזכה בפיצוי; (2) הוכחה שהמקרקעין נמצאים בתחום התכנית הפוגעת או גובלים עמה; (3) שכנוע, ולו באופן לכאורי, כי חלה פגיעה במקרקעין כתוצאה מהתכנית. רק אם התובע עמד בנטל ראשוני זה, קמה שאלה שמאית הטעונה הכרעה, ורק אז תשקול ועדת הערר מינוי שמאי מייעץ. עע"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'' (03.09.2015). ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה (14.09.2017). ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון (04.03.2025)', 'הטעות הנפוצה היא לחשוב שמינוי שמאי מייעץ הוא הליך אוטומטי במקרה של מחלוקת שמאית, מבלי להבין את הדרישה המוקדמת לעמידה בנטל הוכחה ראשוני מצד התובע.',
      '["שמאי מייעץ", "ועדת ערר", "סעיף 197 לחוק התכנון והבניה", "נטל הוכחה ראשוני", "שיקול דעת", "פגיעה במקרקעין"]'::jsonb, '**וריאציה 1 — תנאים למינוי שמאי:** באילו תנאים תמנה ועדת הערר שמאי מייעץעל התובע להוכיח זכות במקרקעין, שהמקרקעין גובלים בתכנית, ושחלה פגיעה לכאורית כתוצאה מהתכנית (ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה).
**וריאציה 2 — סמכות שבשיקול דעת:** האם מינוי שמאי מייעץ הוא חובהלא, זו סמכות שבשיקול דעת של ועדת הערר (עע"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'').
**וריאציה 3 — דחיית ערר ללא שמאי:** מתי ניתן לדחות ערר ללא מינוי שמאי מייעץכאשר התובע לא הרים את נטל ההוכחה הראשוני לפגיעה (ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה).', 'מינוי שמאי מייעץסמכות שבשיקול דעת של ועדת הערררק לאחר שהתובע עמד בנטל הוכחה ראשוני (זכות, גבול, פגיעה לכאורית).', '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "עע\"מ 683/13 רשות שדות התעופה נ'' אליהו טויטו ואח'' (03.09.2015)", "ערר (ועדות ערר - תכנון ובנייה צפון) 9070/16 אלי קלוסקי נ'' הועדה המקומית לתכנון ולבנייה חדרה (14.09.2017)", "ערר (ועדות ערר - תכנון ובנייה תל אביב-יפו) 95041-08-23 לילי קרין נ'' הוועדה מקומית לתכנון ובניה רמת השרון (04.03.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'ועדת הערר תמנה שמאי מייעץ בכל מקרה שבו קיימת מחלוקת שמאית בין הצדדים.', false, 'תשובה זו שגויה. מינוי שמאי מייעץ אינו אוטומטי, ודורש עמידה בנטל הוכחה ראשוני מצד התובע.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'ועדת הערר תמנה שמאי מייעץ רק אם התובע הוכיח זכות במקרקעין, שהמקרקעין גובלים בתכנית, ושחלה פגיעה לכאורית במקרקעין כתוצאה מהתכנית.', true, 'זו התשובה הנכונה. הפסיקה קבעה שלושה תנאים מצטברים שעל התובע לעמוד בהם בנטל ראשוני, ורק אז תישקל האפשרות למינוי שמאי מייעץ.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'ועדת הערר תמנה שמאי מייעץ רק אם הוועדה המקומית לא הגישה חוות דעת נגדית.', false, 'תשובה זו שגויה. מינוי שמאי מייעץ אינו תלוי בהגשת חוות דעת נגדית, אלא בעמידת התובע בנטל הראשוני.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'ועדת הערר אינה מוסמכת למנות שמאי מייעץ, אלא רק בית המשפט.', false, 'תשובה זו שגויה. לוועדת הערר סמכות מפורשת למנות שמאי מייעץ במקרים המתאימים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q04';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 4, '2024-W-S-Q04';
END
$$;

-- ============================================================
-- Q05 — angles backfill for 2024-W-S-Q05 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q05';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q05';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'נטל ההוכחה במקרה של טענת מרמה', 1,
      'מבוטח הגיש תביעה לחברת ביטוח בגין נזקי שריפה שנגרמו לרכושו. חברת הביטוח טוענת כי המבוטח הצית את הרכוש במתכוון, וכי מדובר במרמה. על מי מוטל נטל השכנוע להוכחת טענת המרמה?', 'שאלה זו בוחנת את חלוקת נטל השכנוע בתביעות ביטוח כאשר חברת הביטוח טוענת למרמה או לגרימת מקרה הביטוח במתכוון על ידי המבוטח. היא מתייחסת לסעיפים 25 ו-26 לחוק חוזה הביטוח, ואת ההלכה הפסוקה שקבעה כי נטל זה מוטל על המבטח, תוך דרישה לנטל הוכחה מוגבר.', 'הכלל הבסיסי בדיני ביטוח הוא שעל המבוטח להוכיח את קרות מקרה הביטוח, ועל המבטח הטוען לפטור מאחריות להוכיח את קיומו של סייג לחבות. סעיף 26 לחוק חוזה הביטוח קובע כי ''נגרם מקרה הביטוח בידי המבוטח או בידי המוטב במתכוון, פטור המבטח מחבותו''. הפסיקה, ובראשה ע"א 78/04 המגן חברה לביטוח בע"מ נ'' שלום גרשון הובלות בע"מ, אימצה את גישתו של הנשיא שמגר בע"א 1845/90 רוני סיני נ'' מגדל חברה לביטוח בע"מ, לפיה נטל השכנוע להוכחת טענה זו מוטל על המבטח. נטל זה הוא נטל מוגבר, הן בשל תוצאותיה הקשות של קבלת טענת מרמה ביחס לשמו הטוב של המבוטח, והן בשל שלילת הכיסוי הביטוחי. סעיף 26 לחוק חוזה הביטוח, תשמ"א-1981. ע"א 78/04 המגן חברה לביטוח בע"מ נ'' שלום גרשון הובלות בע"מ (05.10.2006). ת"א (שלום ראשל"צ) 41245-06-20 אחמד אלעסוי נ'' כלל חברה לביטוח בע"מ (17.05.2022). ת"א (שלום חי'') 13992-12-23 סאן בן שמואל נ'' אוהד אסולין (24.12.2025)', 'הטעות הנפוצה היא לחשוב שנטל ההוכחה להוכחת אי-מעורבות במרמה מוטל על המבוטח, במיוחד כאשר מדובר במקרים כמו גניבה או שריפה, מבלי להבחין בין נטל השכנוע לנטל הבאת הראיות.',
      '["נטל שכנוע", "מרמה", "מקרה ביטוח במתכוון", "סייג לחבות", "חוק חוזה הביטוח", "נטל הוכחה מוגבר"]'::jsonb, '**וריאציה 1 — נטל הוכחת מרמה:** על מי מוטל נטל השכנוע להוכחת טענת מרמה בתביעת ביטוחעל חברת הביטוח (ע"א 78/04 המגן חברה לביטוח בע"מ נ'' שלום גרשון הובלות בע"מ).
**וריאציה 2 — חומרת טענת מרמה:** מהי מידת ההוכחה הנדרשת להוכחת טענת מרמהנטל מוגבר, בשל חומרת הטענה והשלכותיה (ת"א (שלום חי'') 13992-12-23 סאן בן שמואל נ'' אוהד אסולין).
**וריאציה 3 — סעיף 26 לחוק חוזה הביטוח:** מה קובע סעיף 26 לחוק חוזה הביטוחאם מקרה הביטוח נגרם במתכוון על ידי המבוטח, המבטח פטור מחבותו (סעיף 26 לחוק חוזה הביטוח, תשמ"א-1981).', 'טענת מרמה/גרימה במתכווןנטל שכנוע על המבטחנטל מוגבר (סעיף 26 לחוק חוזה הביטוח).', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 26", "ע\"א 78/04 המגן חברה לביטוח בע\"מ נ'' שלום גרשון הובלות בע\"מ (05.10.2006)", "ע\"א 1845/90 רוני סיני נ'' מגדל חברה לביטוח בע\"מ (30.03.1993)", "ת\"א (שלום ראשל\"צ) 41245-06-20 אחמד אלעסוי נ'' כלל חברה לביטוח בע\"מ (17.05.2022)", "ת\"א (שלום חי'') 13992-12-23 סאן בן שמואל נ'' אוהד אסולין (24.12.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'על המבוטח, שכן עליו להוכיח כי מקרה הביטוח התרחש שלא במתכוון.', false, 'תשובה זו שגויה. אף שקיימת גישה בפסיקה התומכת בכך, ההלכה המחייבת מטילה את נטל השכנוע להוכחת מרמה על המבטח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'על חברת הביטוח, שכן טענת מרמה היא סייג לחבות, והנטל להוכחת סייג מוטל על המבטח.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי טענת מרמה או גרימת מקרה הביטוח במתכוון היא סייג לחבות, ונטל השכנוע להוכחתה מוטל על חברת הביטוח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נטל השכנוע מתחלק בין הצדדים: על המבוטח להוכיח את קרות מקרה הביטוח, ועל חברת הביטוח להוכיח את כוונת המרמה.', false, 'תשובה זו שגויה. אף שנטל השכנוע מתחלק באופן כללי, נטל השכנוע הספציפי להוכחת כוונת המרמה מוטל במלואו על המבטח.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'על חברת הביטוח, אך נטל זה הוא קל יותר בשל הקושי להוכיח כוונת מרמה.', false, 'תשובה זו שגויה. נטל השכנוע להוכחת מרמה הוא נטל מוגבר, ולא קל יותר, בשל חומרת הטענה והשלכותיה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q05';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הבחנה בין נטל שכנוע לנטל הבאת ראיות', 2,
      'מה ההבדל המהותי בין ''נטל השכנוע'' ל''נטל הבאת הראיות'' בתביעת ביטוח, וכיצד הם מתחלקים בין המבוטח למבטח?', 'שאלה זו עוסקת בהבחנה יסודית בדיני ראיות בין ''נטל השכנוע'' ל''נטל הבאת הראיות'', ובאופן יישומם בתביעות ביטוח. היא מדגישה את אופיו הקבוע של נטל השכנוע ואת אופיו הדינמי של נטל הבאת הראיות, ואת חשיבות ההבחנה ביניהם להבנת הליך ההוכחה המשפטי.', 'נטל ההוכחה משמש לתאר שני מושגים שונים: נטל השכנוע ונטל הבאת הראיות. נטל השכנוע מבטא את החובה העיקרית המוטלת על בעל דין להוכיח את טענותיו כלפי יריבו במידת ההוכחה הנדרשת בהליך אזרחי (מאזן ההסתברויות). נטל זה הוא קבוע בדרך כלל ואינו עובר בין בעלי הדין במהלך המשפט. נטל הבאת הראיות הוא חובה משנית הנלווית לנטל השכנוע. ככל שמדובר בצד הנושא בנטל השכנוע, משמעות החובה היא שעליו להביא ראיות מספיקות על מנת לעמוד בנטל. ביחס ליריבו, משמעותה שעליו להביא ראיות שישמטו את הבסיס תחת הראיות שהובאו כנגדו. נטל זה הוא דינמי ועשוי לעבור מבעל דין אחד למשנהו. בתביעת ביטוח, על המבוטח נטל השכנוע להוכיח את קרות מקרה הביטוח, ועל המבטח נטל השכנוע להוכיח קיומו של סייג לחבות. ע"א 78/04 המגן חברה לביטוח בע"מ נ'' שלום גרשון הובלות בע"מ (05.10.2006). ת"א (שלום חי'') 35799-06-16 תומר צפריר נ'' מגדל חברה לביטוח בע"מ (09.11.2021). ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושניים גרימת מקרה הביטוח במתכוון', 'הטעות הנפוצה היא לבלבל בין שני הנטלים, או לחשוב שנטל השכנוע יכול לעבור מצד לצד במהלך המשפט, בעוד שלמעשה רק נטל הבאת הראיות הוא דינמי.',
      '["נטל שכנוע", "נטל הבאת ראיות", "דיני ראיות", "מאזן הסתברויות", "תביעת ביטוח", "הליך אזרחי"]'::jsonb, '**וריאציה 1 — נטל השכנוע:** מהו נטל השכנועהחובה העיקרית להוכיח טענה במידת ההוכחה הנדרשת, והוא קבוע (ע"א 78/04 המגן חברה לביטוח בע"מ נ'' שלום גרשון הובלות בע"מ).
**וריאציה 2 — נטל הבאת הראיות:** מהו נטל הבאת הראיותחובה משנית להביא ראיות, והוא דינמי ועשוי לעבור בין הצדדים (ת"א (שלום חי'') 35799-06-16 תומר צפריר נ'' מגדל חברה לביטוח בע"מ).
**וריאציה 3 — חלוקת נטלים בתביעת ביטוח:** כיצד מתחלקים הנטלים בתביעת ביטוחעל המבוטח נטל השכנוע לקרות מקרה הביטוח, ועל המבטח נטל השכנוע לקיומו של סייג לחבות (ע"א 678/86 חסן חניפס נ'' "סהר" חברה לביטוח בע"מ).', 'נטל שכנועקבוע, להוכחת טענה. נטל הבאת ראיותדינמי, להצגת ראיות. בתביעת ביטוח: מבוטח מוכיח מקרה ביטוח, מבטח מוכיח סייג.', '["ע\"א 78/04 המגן חברה לביטוח בע\"מ נ'' שלום גרשון הובלות בע\"מ (05.10.2006)", "ת\"א (שלום חי'') 35799-06-16 תומר צפריר נ'' מגדל חברה לביטוח בע\"מ (09.11.2021)", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושניים גרימת מקרה הביטוח במתכוון", "ע\"א 678/86 חסן חניפס נ'' \"סהר\" חברה לביטוח בע\"מ (22.08.1989)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'נטל השכנוע הוא קבוע ומוטל על המבוטח בלבד, ואילו נטל הבאת הראיות הוא דינמי ועשוי לעבור בין הצדדים.', false, 'תשובה זו שגויה. נטל השכנוע אינו מוטל על המבוטח בלבד, אלא מתחלק בין הצדדים בהתאם לטענותיהם.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'נטל השכנוע הוא החובה העיקרית להוכיח טענה במידת ההוכחה הנדרשת, והוא קבוע. נטל הבאת הראיות הוא חובה משנית להביא ראיות, והוא דינמי ועשוי לעבור בין הצדדים.', true, 'זו התשובה הנכונה. נטל השכנוע הוא קבוע ומוטל על הצד הטוען לטענה מסוימת, ואילו נטל הבאת הראיות הוא דינמי ועשוי לעבור מצד לצד במהלך המשפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נטל השכנוע ונטל הבאת הראיות זהים במהותם, ושניהם מוטלים על המבוטח בתביעת ביטוח.', false, 'תשובה זו שגויה. שני הנטלים שונים במהותם, ואינם מוטלים באופן בלעדי על המבוטח.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'נטל השכנוע מוטל על המבטח, ואילו נטל הבאת הראיות מוטל על המבוטח.', false, 'תשובה זו שגויה. חלוקת הנטלים אינה כה פשוטה וחד-צדדית, והיא תלויה בטענות הספציפיות של כל צד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q05';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'נטל ההוכחה באי-קיום אמצעי מיגון', 3,
      'פוליסת ביטוח רכוש כוללת דרישה להתקנת מערכת אזעקה פעילה. המבוטח הגיש תביעה בגין גניבה, אך חברת הביטוח טוענת כי מערכת האזעקה לא הייתה פעילה במועד הגניבה. על מי מוטל נטל השכנוע להוכחת אי-קיום אמצעי המיגון?', 'שאלה זו עוסקת בסוגיית נטל ההוכחה כאשר חברת הביטוח טוענת לאי-קיום אמצעי מיגון שנדרשו בפוליסה. היא מדגישה את ההבחנה המורכבת בפסיקה בין ''תנאי מוקדם'' לתחולת הפוליסה (שנטל הוכחתו על המבוטח) לבין ''חריג'' או ''סייג'' לחבות (שנטל הוכחתו על המבטח), ומצביעה על הגישה הרווחת לגבי דרישות מיגון.', 'הפסיקה חלוקה לעיתים בשאלת ההבחנה בין ''תנאי מוקדם'' לתחולת הפוליסה לבין ''חריג'' או ''סייג'' לחבות. כאשר מדובר בתנאי מוקדם, נטל השכנוע להוכחת קיומו מוטל על המבוטח, כחלק מהוכחת עילת התביעה. לעומת זאת, כאשר מדובר בחריג, נטל השכנוע להוכחתו מוטל על המבטח. בנושא דרישות מיגון, קיימת בפסיקה נטייה לראות בהן תנאי מוקדם לתחולת הפוליסה, ועל כן נטל ההוכחה לקיומן מוטל על המבוטח. ת"א (שלום חיפה) 13322/99 אפרת שילר נ'' איילון חב'' לביטוח בע"מ (01.10.2002). ת"א (שלום כ"ס) 2701/02 קוויק פון פרינט בע"מ נ'' אליהו חברה לביטוח בע"מ (02.07.2006). ת"א (שלום הרצ'') 21399-12-10 חיים בן חיים נ'' הפניקס חברה לביטוח בע"מ (17.08.2015). ת"א (שלום הרצ'') 31701-04-13 רשת פתרונות להדפסה ירוקה בע"מ נ'' הפניקס חברה לביטוח בע"מ (20.06.2016)', 'הטעות הנפוצה היא לבלבל בין תנאי מוקדם לחריג, ולחשוב שנטל ההוכחה לאי-קיום אמצעי מיגון מוטל תמיד על המבטח, מבלי להבין את הניואנסים בפסיקה.',
      '["תנאי מוקדם", "חריג לחבות", "נטל שכנוע", "אמצעי מיגון", "פוליסת ביטוח", "חוק חוזה הביטוח"]'::jsonb, '**וריאציה 1 — דרישת מיגון כתנאי מוקדם:** האם דרישת מיגון בפוליסה היא תנאי מוקדם או חריגהפסיקה נוטה לראות בה תנאי מוקדם, שנטל הוכחתו על המבוטח (ת"א (שלום חיפה) 13322/99 אפרת שילר נ'' איילון חב'' לביטוח בע"מ).
**וריאציה 2 — נטל ההוכחה לתנאי מוקדם:** על מי מוטל נטל השכנוע להוכחת קיום תנאי מוקדםעל המבוטח, כחלק מעילת התביעה (ת"א (שלום הרצ'') 21399-12-10 חיים בן חיים נ'' הפניקס חברה לביטוח בע"מ).
**וריאציה 3 — חוסר אחידות בפסיקה:** האם קיימת אחידות בפסיקה בנושאלא, קיימת חוסר אחידות בולט בשאלת נטל ההוכחה בנושא מיגון הרכב (ת"א (שלום כ"ס) 2701/02 קוויק פון פרינט בע"מ נ'' אליהו חברה לביטוח בע"מ).', 'אי-קיום מיגוןנחשב לרוב כתנאי מוקדםנטל הוכחה על המבוטח (למרות חוסר אחידות בפסיקה).', '["ת\"א (שלום חיפה) 13322/99 אפרת שילר נ'' איילון חב'' לביטוח בע\"מ (01.10.2002)", "ת\"א (שלום כ\"ס) 2701/02 קוויק פון פרינט בע\"מ נ'' אליהו חברה לביטוח בע\"מ (02.07.2006)", "ת\"א (שלום הרצ'') 21399-12-10 חיים בן חיים נ'' הפניקס חברה לביטוח בע\"מ (17.08.2015)", "ת\"א (שלום הרצ'') 31701-04-13 רשת פתרונות להדפסה ירוקה בע\"מ נ'' הפניקס חברה לביטוח בע\"מ (20.06.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'על המבוטח, שכן קיום אמצעי המיגון הוא תנאי מוקדם לתחולת הפוליסה.', true, 'זו התשובה הנכונה. הפסיקה נוטה לראות בדרישות מיגון כתנאי מוקדם לתחולת הפוליסה, ועל המבוטח להוכיח את קיומו של תנאי זה כחלק מעילת התביעה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'על חברת הביטוח, שכן אי-קיום אמצעי מיגון הוא חריג לחבות, והנטל להוכחת חריג מוטל על המבטח.', false, 'תשובה זו שגויה. אף שקיימת גישה הרואה בכך חריג, הגישה הרווחת בפסיקה היא לראות בדרישות מיגון תנאי מוקדם, המטיל את הנטל על המבוטח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נטל השכנוע מתחלק בין הצדדים: על המבוטח להוכיח את התקנת המיגון, ועל המבטח להוכיח את אי-פעילותו.', false, 'תשובה זו שגויה. נטל השכנוע הוא קבוע, ובמקרה של תנאי מוקדם, הוא מוטל על המבוטח להוכיח את קיומו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'על חברת הביטוח, אלא אם כן המבוטח ידע על אי-פעילות המיגון ולא דיווח על כך.', false, 'תשובה זו שגויה. ידיעת המבוטח רלוונטית, אך אינה משנה את חלוקת נטל השכנוע הבסיסית כאשר מדובר בתנאי מוקדם.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q05';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'נטל הקטנת הנזק', 4,
      'מבוטח תובע תגמולי ביטוח לאחר שרכבו נגנב. חברת הביטוח טוענת כי המבוטח השאיר את מפתחות הרכב במתג ההנעה, ובכך הפר את חובתו להקטין את הנזק לפי סעיף 61 לחוק חוזה הביטוח. האם טענת המבטח תתקבל?', 'שאלה זו בוחנת את תחולתו של סעיף 61 לחוק חוזה הביטוח, העוסק בנטל הקטנת הנזק. היא מתמקדת בפרשנות המונח ''בקרות מקרה הביטוח או לאחר מכן'', ומדגישה את עמדת הפסיקה לפיה נטל זה אינו חל על אירועים שקדמו למקרה הביטוח, אלא רק על פעולות שנעשו לאחר התרחשותו.', 'סעיף 61(א) לחוק חוזה הביטוח קובע כי ''אין המבטח חייב בתגמולי ביטוח בעד נזק שהמבוטח יכול היה למנוע או להקטין, בקרות מקרה הביטוח או לאחר מכן, בנקיטת אמצעים סבירים או אמצעים שהמבטח הורה לו לנקוט''. הפסיקה פירשה הוראה זו באופן מצמצם, וקבעה כי נטל הקטנת הנזק אינו חל על אירועים שהתרחשו לפני שקרה מקרה הביטוח. השארת מפתחות במתג ההנעה, אף שהיא עשויה להקל על גניבה, היא פעולה שקדמה למקרה הביטוח (הגניבה), ולכן אינה נכנסת לגדרו של סעיף 61. סעיף 61(א) לחוק חוזה הביטוח, תשמ"א-1981. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ואחד נטל הקטנת הנזק. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ואחד נטל הקטנת הנזק', 'הטעות הנפוצה היא להרחיב את תחולת סעיף 61 גם על פעולות שקדמו למקרה הביטוח, במקום להבין את הפרשנות המצמצמת של הפסיקה למונח ''בקרות מקרה הביטוח או לאחר מכן''.',
      '["נטל הקטנת הנזק", "סעיף 61 לחוק חוזה הביטוח", "מקרה ביטוח", "גניבה", "פרשנות חוק", "חבות מבטח"]'::jsonb, '**וריאציה 1 — תחולת סעיף 61:** מתי חל סעיף 61 לחוק חוזה הביטוחבקרות מקרה הביטוח או לאחר מכן'' (סעיף 61(א) לחוק חוזה הביטוח, תשמ"א-1981).
**וריאציה 2 — אירועים קודמים למקרה הביטוח:** האם סעיף 61 חל על אירועים שקדמו למקרה הביטוחלא, הוא אינו מתגבש כל עוד לא קרה מקרה הביטוח (ירון אליאס דיני ביטוח (2016) | פרק עשרים-ואחד נטל הקטנת הנזק).
**וריאציה 3 — השארת מפתחות:** האם השארת מפתחות במתג ההנעה מהווה הפרה של סעיףלא, זו פעולה שקדמה למקרה הביטוח (הגניבה) (ירון אליאס דיני ביטוח (2016) | פרק עשרים-ואחד נטל הקטנת הנזק).', 'נטל הקטנת הנזק (סעיףחל רק לאחר קרות מקרה הביטוחלא על פעולות שקדמו לו (כמו השארת מפתחות).', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 61", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-ואחד נטל הקטנת הנזק"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, השארת מפתחות במתג ההנעה מהווה הפרה של חובת הקטנת הנזק, והמבטח פטור מחבותו.', false, 'תשובה זו שגויה. חובת הקטנת הנזק חלה ''בקרות מקרה הביטוח או לאחר מכן'', ולא על אירועים שקדמו לו. השארת מפתחות היא אירוע שקדם לגניבה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חובת הקטנת הנזק לפי סעיף 61 לחוק חוזה הביטוח חלה רק ''בקרות מקרה הביטוח או לאחר מכן'', ולא על אירועים שקדמו לו.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי סעיף 61 אינו חל על אירועים שקדמו למקרה הביטוח, אלא רק על פעולות למניעת נזק או הקטנתו לאחר שהמקרה כבר אירע.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך המבטח יהיה חייב בתגמולי ביטוח מופחתים, ולא פטור לחלוטין.', false, 'תשובה זו שגויה. אם סעיף 61 אינו חל, אין מקום להפחתה מכוחו. אם חל, התוצאה יכולה להיות פטור מלא או חלקי, אך לא מכוח טענה שגויה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן המבטח יוכיח שהשארת המפתחות נעשתה בכוונת מרמה.', false, 'תשובה זו שגויה. אף שמרמה יכולה לפטור את המבטח, הטענה כאן מתייחסת ספציפית לסעיף 61, שאינו חל על אירועים שקדמו למקרה הביטוח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q05';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 5, '2024-W-S-Q05';
END
$$;

-- ============================================================
-- Q06 — angles backfill for 2024-W-S-Q06 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q06';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q06';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'חיוב הורים בגין עבירת קטין', 1,
      'האם מעורבות ישירה או עקיפה של הורים בביצוע עבירה על ידי קטין משפיעה על סמכות בית המשפט לחייב אותם בהוצאות טיפול במעון יומי לפי סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)?', 'שאלה זו בוחנת את היקף תחולתו של סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול) ואת ההבחנה בינו לבין סעיפים אחרים בחוק הנוער. היא מדגישה כי חיוב הורים בהוצאות טיפול מותנה ביכולתם הכלכלית, בעוד שמעורבותם בעבירה עשויה להוביל לחיובים כספיים אחרים, אך לא משנה את תנאי סעיף 28.', 'סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע כי בית המשפט לנוער רשאי לחייב את הקטין או הורהו בהוצאות טיפול, כולן או מקצתן, ''אם נוכח שיש להם האמצעים הדרושים לכך''. תנאי זה מתמקד ביכולת הכלכלית של ההורים. לעומת זאת, סעיף 24א לחוק מאפשר לבית המשפט, לאחר שהרשיע קטין, לצוות על קבלת התחייבות מהורהו או על חיוב ההורה בתשלום קנס, הוצאות משפט או פיצוי, ''אם מצא כי קיימות נסיבות המצדיקות לעשות כן''. נסיבות אלו יכולות לכלול מעורבות של ההורים בעבירה. מכאן, שמעורבות הורים בעבירה אינה משפיעה ישירות על חיובם בהוצאות טיפול לפי סעיף 28, אלא פותחת אפשרות לחיובים כספיים אחרים לפי סעיף 24א. סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. סעיף 24א לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חוק הנוער (שפיטה, ענישה ודרכי טיפול)', 'הטעות הנפוצה היא לערבב בין העילות השונות לחיוב הורים בחוק הנוער, ולחשוב שמעורבות בעבירה היא תנאי לחיוב בהוצאות טיפול, במקום להבחין בין סעיף 28 לסעיף 24א.',
      '["חוק הנוער (שפיטה, ענישה ודרכי טיפול)", "הוצאות טיפול", "חיוב הורים", "אמצעים כלכליים", "מעורבות בעבירה", "סעיף 28", "סעיף 24א"]'::jsonb, '**וריאציה 1 — חיוב הוצאות טיפול:** האם מעורבות הורים בעבירה הופכת חיוב בהוצאות טיפול לחובהלא, סעיף 28 מתנה חיוב באמצאי ההורים ואינו הופך אותו לחובה (סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 2 — חיובים אחרים:** האם מעורבות הורים בעבירה יכולה להוביל לחיובים כספיים אחריםכן, סעיף 24א מאפשר חיוב בקנס או פיצוי אם קיימות נסיבות מצדיקות (סעיף 24א לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 3 — תנאי לחיוב הוצאות טיפול:** מהו התנאי העיקרי לחיוב הורים בהוצאות טיפול לפי סעיףקיומם של אמצעים כלכליים מספקים אצל ההורים (סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).', 'חיוב הורים בהוצאות טיפול (סעיףתלוי באמצעים כלכליים. מעורבות בעבירהעשויה להוביל לחיובים אחרים (סעיף 24א).', '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 24א", "חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 28", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חוק הנוער (שפיטה, ענישה ודרכי טיפול)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מעורבות כזו הופכת את חיוב ההורים בהוצאות הטיפול לחובה ולא לרשות.', false, 'תשובה זו שגויה. סעיף 28(א) קובע כי החיוב הוא רשות ולא חובה, והוא תלוי בקיומם של אמצעים כלכליים, ללא קשר למעורבות בעבירה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, סעיף 28 מתייחס רק לאמצעים הכלכליים של ההורים, ומעורבותם בעבירה רלוונטית לסעיפים אחרים בחוק, כגון חיוב בקנס או פיצוי.', true, 'זו התשובה הנכונה. סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול) מתמקד ביכולת הכלכלית של ההורים לשאת בהוצאות הטיפול. מעורבותם בעבירה עשויה להוביל לחיובים אחרים, כמו קנס או פיצוי, לפי סעיף 24א לחוק, אך אינה משנה את תנאי החיוב בהוצאות טיפול לפי סעיף 28.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, מעורבות כזו מאפשרת לבית המשפט לחייב את ההורים בהוצאות הטיפול גם אם אין להם את האמצעים הדרושים.', false, 'תשובה זו שגויה. סעיף 28(א) מתנה את החיוב בקיומם של אמצעים כלכליים, ואין בו חריג למקרים של מעורבות הורים בעבירה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, סעיף 28 אינו חל כלל במקרים של מעורבות הורים בעבירת הקטין.', false, 'תשובה זו שגויה. סעיף 28 יכול לחול גם במקרים של מעורבות הורים בעבירה, ובלבד שמתקיימים תנאיו, אך הוא אינו עוסק במעורבות זו כעילה לחיוב.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q06';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'שיקולי בית המשפט בחיוב הורים', 2,
      'אילו שיקולים, מעבר לאמצעים הכלכליים, רשאי בית המשפט לנוער לשקול בבואו להחליט אם לחייב הורים בהוצאות טיפול לפי סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)?', 'שאלה זו בוחנת את שיקול הדעת הרחב של בית המשפט לנוער בבואו להחליט על חיוב הורים בהוצאות טיפול. היא מדגישה את עיקרון העל של טובת הקטין, לצד שיקולים נוספים כמו אחריות הורית ושיתוף פעולה עם גורמי טיפול, כחלק מהאיזון הנדרש בהליכים אלו.', 'בית המשפט לנוער פועל תמיד מתוך עיקרון העל של טובת הקטין וההגנה עליו. סעיף 1א לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע כי מימוש זכויות של קטין, הפעלת סמכויות ונקיטת הליכים כלפיו ייעשו תוך שמירה על כבודו, ומתן משקל ראוי לשיקולים של שיקומו, הטיפול בו ושילובו בחברה. במסגרת שיקול הדעת הנתון לבית המשפט לפי סעיף 28 לחוק, הוא רשאי לשקול, בנוסף לאמצעים הכלכליים של ההורים, גם את מידת אחריותם למצב הקטין, את נכונותם לשתף פעולה עם גורמי הטיפול, ואת ההשפעה של החיוב על יכולתם לספק את צרכי הקטין. מטרת החיוב היא לסייע בטיפול בקטין, ולא להעניש את ההורים. סעיף 1א לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. רע"א 3411/16 פלוני נ'' משרד הרווחה ירושלים (20.06.2016). בע"מ 1764/24 פלוני נ'' המחלקה לשירותים חברתיים בעיר פלונית (07.03.2024). תנ"ז (משפחה תל אביב-יפו) 58802-04-24 יובל בורודטי עו"ס נ'' ר.ל (29.01.2025)', 'הטעות הנפוצה היא להתמקד רק בשיקול הכלכלי או רק בטובת הקטין, מבלי להבין את מכלול השיקולים שבית המשפט לנוער רשאי לשקול במסגרת סמכותו הרחבה.',
      '["טובת הקטין", "שיקול דעת שיפוטי", "אחריות הורית", "שיתוף פעולה", "חוק הנוער (שפיטה, ענישה ודרכי טיפול)", "סעיף 28"]'::jsonb, '**וריאציה 1 — עיקרון העל:** מהו עיקרון העל המנחה את בית המשפט לנוערטובת הקטין והגנה עליו (סעיף 1א לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 2 — שיקולים נוספים:** אילו שיקולים נוספים נבחנים בחיוב הורים בהוצאות טיפולמידת אחריות ההורים למצב הקטין ושיתוף הפעולה שלהם עם גורמי הטיפול (תנ"ז (משפחה תל אביב-יפו) 58802-04-24 יובל בורודטי עו"ס נ'' ר.ל).
**וריאציה 3 — איזון אינטרסים:** כיצד מאזן בית המשפט בין זכויות ההורים לטובת הקטיןזכותם של ההורים לגדל את ילדיהם כפופה בראש ובראשונה לטובת הילד (רע"א 3411/16 פלוני נ'' משרד הרווחה ירושלים).', 'חיוב הורים בהוצאות טיפולשיקול דעת רחב של בית המשפטכולל טובת הקטין, אחריות הורית, שיתוף פעולה, ואמצעים כלכליים.', '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 1א", "חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 28", "תנ\"ז (משפחה תל אביב-יפו) 58802-04-24 יובל בורודטי עו\"ס נ'' ר.ל (29.01.2025)", "בע\"מ 1764/24 פלוני נ'' המחלקה לשירותים חברתיים בעיר פלונית (07.03.2024)", "רע\"א 3411/16 פלוני נ'' משרד הרווחה ירושלים (20.06.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק את טובת הקטין, שכן היא עיקרון העל בדיני נוער.', false, 'תשובה זו שגויה. אף שטובת הקטין היא עיקרון על, היא אינה השיקול היחיד, וסעיף 28 מתייחס במפורש גם לאמצעים הכלכליים של ההורים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'את טובת הקטין, את מידת אחריות ההורים למצב הקטין, ואת מידת שיתוף הפעולה שלהם עם גורמי הטיפול.', true, 'זו התשובה הנכונה. בית המשפט לנוער פועל תמיד לטובת הקטין, ובמסגרת שיקול הדעת הרחב הנתון לו, הוא רשאי לשקול גם את מידת אחריות ההורים למצב הקטין ואת נכונותם לשתף פעולה עם גורמי הטיפול, לצד יכולתם הכלכלית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'את גיל הקטין בלבד, שכן ככל שהקטין צעיר יותר, כך גדלה אחריות ההורים.', false, 'תשובה זו שגויה. גיל הקטין הוא שיקול כללי, אך אינו השיקול הבלעדי או המכריע לעניין חיוב בהוצאות טיפול לפי סעיף 28.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק את חומרת העבירה שביצע הקטין.', false, 'תשובה זו שגויה. חומרת העבירה רלוונטית לענישה, אך אינה שיקול ישיר לחיוב הורים בהוצאות טיפול לפי סעיף 28, אשר מתמקד בטיפול ובאמצעים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q06';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חיוב הורה שאינו אפוטרופוס', 3,
      'האם בית המשפט לנוער רשאי לחייב הורה שאינו האפוטרופוס הטבעי של הקטין (למשל, הורה גרוש שאינו משמורן) בהוצאות טיפול במעון יומי לפי סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)?', 'שאלה זו עוסקת בפרשנות המונח ''הורה'' בהקשר של חיוב בהוצאות טיפול לפי חוק הנוער (שפיטה, ענישה ודרכי טיפול). היא מבהירה כי הגדרת ''הורה'' בחוק היא רחבה ואינה מוגבלת לאפוטרופוס הטבעי או המשמורן, ובכך מאפשרת לבית המשפט לחייב גם הורים שאינם משמורנים, ובלבד שיש להם את האמצעים הנדרשים.', 'סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול) מאפשר לבית המשפט לחייב את ''הורהו'' של הקטין בהוצאות טיפול. סעיף 1 לחוק זה מגדיר ''הורה'' באופן רחב: ''הורה – לרבות הורה חורג, מאמץ ואפוטרופוס''. הגדרה זו אינה מגבילה את החיוב להורה המשמורן או לאפוטרופוס הטבעי בלבד, אלא כוללת כל הורה במובן הרחב. לפיכך, בית המשפט רשאי לחייב גם הורה שאינו האפוטרופוס הטבעי או המשמורן, ובלבד שנוכח כי יש לו את האמצעים הדרושים לכך. סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. סעיף 1 לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. בע"מ 5710/05 פלוני נ'' פלוני, סא(2) 663 (06.07.2006). בני דון-יחייא תורת דיני המשפחה (2022) | אפוטרופסות לילדים קטינים', 'הטעות הנפוצה היא להניח שחיוב בהוצאות טיפול חל רק על ההורה המשמורן או האפוטרופוס הטבעי, מבלי להתייחס להגדרה הרחבה של ''הורה'' בחוק הנוער.',
      '["הורה", "אפוטרופוס", "חיוב הורים", "הוצאות טיפול", "חוק הנוער (שפיטה, ענישה ודרכי טיפול)", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — הגדרת הורה:** האם ''הורה'' בסעיף 28 כולל רק אפוטרופוס טבעילא, ההגדרה רחבה וכוללת הורה חורג, מאמץ ואפוטרופוס (סעיף 1 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 2 — חיוב הורה גרוש:** האם ניתן לחייב הורה גרוש שאינו משמורן בהוצאות טיפולכן, אם יש לו את האמצעים הדרושים לכך (סעיף 28(א) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 3 — סמכות בית המשפט:** האם סמכות בית המשפט לחייב הורה מותנית בהסכמתולא, הסמכות נתונה לבית המשפט על פי שיקול דעתו ובהתאם לאמצעים (בע"מ 5710/05 פלוני נ'' פלוני, סא(2) 663).', 'חיוב הורה בהוצאות טיפול (סעיףחל על כל ''הורה'' (הגדרה רחבהתלוי באמצעים כלכליים, לא בסטטוס אפוטרופוס/משמורן.', '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 1", "חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 28", "בע\"מ 5710/05 פלוני נ'' פלוני, סא(2) 663 (06.07.2006)", "בני דון-יחייא תורת דיני המשפחה (2022) | אפוטרופסות לילדים קטינים"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, סעיף 28 חל רק על האפוטרופוסים הטבעיים של הקטין.', false, 'תשובה זו שגויה. הגדרת ''הורה'' בחוק הנוער (שפיטה, ענישה ודרכי טיפול) רחבה יותר מאפוטרופוס טבעי בלבד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, סעיף 28 מתייחס ל"הורהו" של הקטין, והגדרה זו כוללת גם הורה שאינו אפוטרופוס טבעי, ובלבד שיש לו את האמצעים הדרושים.', true, 'זו התשובה הנכונה. סעיף 1 לחוק הנוער (שפיטה, ענישה ודרכי טיפול) מגדיר ''הורה'' באופן רחב הכולל הורה חורג, מאמץ ואפוטרופוס. סעיף 28 מאפשר חיוב ''הורהו'' של הקטין, ואינו מגביל זאת לאפוטרופוס הטבעי או המשמורן, כל עוד יש לו את האמצעים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הוכח שההורה שאינו אפוטרופוס התרשל בתפקידו ההורי.', false, 'תשובה זו שגויה. התרשלות אינה תנאי לחיוב לפי סעיף 28, אלא קיומם של אמצעים כלכליים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן ההורה שאינו אפוטרופוס הסכים לחיוב.', false, 'תשובה זו שגויה. סמכות בית המשפט לחייב לפי סעיף 28 אינה מותנית בהסכמת ההורה, אלא בשיקול דעתו וביכולתו הכלכלית של ההורה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q06';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'ערעור על חיוב הורה', 4,
      'הורה חויב על ידי בית המשפט לנוער בהוצאות טיפול במעון יומי עבור קטינו, לפי סעיף 28 לחוק הנוער (שפיטה, ענישה ודרכי טיפול). כיצד ניתן לערער על החלטה זו?', 'שאלה זו עוסקת בזכות הערעור על החלטות בית המשפט לנוער המטילות חיוב כספי על הורים. היא מבהירה את אופי הערעור (בזכות) ואת הערכאה המוסמכת לדון בו, בהתאם להוראות חוק הנוער (שפיטה, ענישה ודרכי טיפול).', 'סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע במפורש כי ''לעניין ערעור, צו כאמור בסעיף קטן (א), דינו כדין פסק דין בהליכים פליליים שניתן נגד הורה הקטין''. משמעות הדבר היא שעל צו לחיוב הורה בהוצאות טיפול, קנס או פיצוי, ניתן לערער בזכות לבית המשפט המחוזי, בדומה לערעור על פסק דין פלילי. סעיף 29(ג) מוסיף כי גם אם הוגש ערעור מטעם הקטין בלבד, רשאי בית המשפט הדן בערעור לדון גם בכל צו של בית המשפט לנוער המחייב את הורה הקטין. סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חיוב הורה הקטין. ע"פ 1589/23 פלוני נ'' מדינת ישראל (07.08.2023)', 'הטעות הנפוצה היא לחשוב שערעור על החלטה כזו הוא בבקשת רשות ערעור, או לבלבל בין הערכאות המוסמכות לערעור בהליכים פליליים ובהליכים אזרחיים/משפחתיים.',
      '["ערעור בזכות", "חיוב הורה", "חוק הנוער (שפיטה, ענישה ודרכי טיפול)", "הליכים פליליים", "בית המשפט המחוזי", "סעיף 29"]'::jsonb, '**וריאציה 1 — אופי הערעור:** האם ערעור על חיוב הורה לפי סעיף 28 הוא בזכות או ברשותבזכות (סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 2 — ערכאת הערעור:** לאיזו ערכאה מוגש הערעורלבית המשפט המחוזי, כערעור פלילי (סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).
**וריאציה 3 — ערעור הקטין:** האם ערעור של הקטין בלבד משפיע על צו חיוב ההורהכן, בית המשפט הדן בערעור רשאי לדון גם בצו חיוב ההורה (סעיף 29(ג) לחוק הנוער (שפיטה, ענישה ודרכי טיפול)).', 'ערעור על חיוב הורה (סעיףבזכות לבית המשפט המחוזיכדין ערעור פלילי (סעיף 29(ב)).', '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 29", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חיוב הורה הקטין", "ע\"פ 1589/23 פלוני נ'' מדינת ישראל (07.08.2023)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בדרך של בקשת רשות ערעור לבית המשפט המחוזי.', false, 'תשובה זו שגויה. סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע במפורש כי ערעור על חיוב הורה הוא ערעור בזכות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בדרך של ערעור בזכות לבית המשפט המחוזי, כאילו היה פסק דין פלילי שניתן נגד ההורה.', true, 'זו התשובה הנכונה. סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע כי צו לחיוב הורה דינו כדין פסק דין בהליכים פליליים שניתן נגד הורה הקטין, ולכן הערעור עליו הוא בזכות לבית המשפט המחוזי.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בדרך של ערעור בזכות לבית המשפט לענייני משפחה.', false, 'תשובה זו שגויה. ההליך הוא פלילי במהותו, ובית המשפט המוסמך לערעור הוא בית המשפט המחוזי, לא בית המשפט לענייני משפחה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא ניתן לערער על החלטה כזו, אלא רק לבקש מבית המשפט לנוער לעיין בה מחדש.', false, 'תשובה זו שגויה. קיימת זכות ערעור מפורשת על צו לחיוב הורה לפי סעיף 29(ב) לחוק הנוער (שפיטה, ענישה ודרכי טיפול).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q06';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 6, '2024-W-S-Q06';
END
$$;

-- ============================================================
-- Q07 — angles backfill for 2024-W-S-Q07 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q07';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q07';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תחולת סעיף 2 על רשות ציבורית', 1,
      'רשות מקומית גבתה אגרות מים מתושבים שלא כדין, והתושבים הגישו תביעת השבה. הרשות טוענת לפטור מהשבה לפי סעיף 2 לחוק עשיית עושר ולא במשפט. איזה שיקול נוסף, מעבר לשיקולי צדק רגילים, יבחן בית המשפט במקרה זה?', 'שאלה זו בוחנת את תחולתו של סעיף 2 לחוק עשיית עושר ולא במשפט כאשר הזוכה הוא רשות ציבורית. היא מדגישה כי במקרים אלו, בנוסף לשיקולי הצדק הרגילים, נכנסים למאזן גם עקרונות יסוד מהמשפט הציבורי, כגון שלטון החוק וחוקיות המינהל, המקבלים משקל מיוחד.', 'הלכה פסוקה היא כי סעיף 2 לחוק עשיית עושר ולא במשפט מקנה לבית המשפט שיקול דעת רחב לפטור זוכה מהשבה מטעמי צדק. כאשר הזוכה שהתעשר שלא כדין הוא רשות מינהלית, מצטרפים לסל השיקולים גם עקרונות שלטון החוק וחוקיות המינהל, ובפרט עיקרון חוקיות המס שהוא בסיס לכל משטר תקין. שיקולים אלו עשויים להטות את הכף נגד מתן פטור מהשבה, שכן אינטרס הציבור בשמירה על חוקיות פעולות הרשות גובר במקרים רבים על שיקולי צדק פרטניים של הרשות. הפטור מהשבה הוא חריג שיופעל במקרים מועטים. ע"א 4708/14 י.ח דמרי בניה ופיתוח בע"מ נ'' המועצה המקומית גן יבנה (24.08.2015). ע"א 9631/05 דוד ארד נ'' מדינת ישראל (16.12.2010). דנ"א 7398/09 עיריית ירושלים נ'' שירותי בריאות כללית (14.04.2015). הנריק רוסטוביץ, פנחס גלעד, משה וקנין, נורית לב, ארנונה עירונית - ספר ראשון (2001) | פרק 1 מבוא', 'הטעות הנפוצה היא להתייחס לרשות ציבורית כאל צד פרטי לכל דבר ועניין, מבלי להביא בחשבון את השיקולים המיוחדים הנובעים ממעמדה כרשות שלטונית.',
      '["רשות ציבורית", "חוקיות המינהל", "שלטון החוק", "חוק עשיית עושר ולא במשפט", "סעיף 2", "חוקיות המס"]'::jsonb, '**וריאציה 1 — שיקולים ציבוריים:** אילו שיקולים נוספים נבחנים כאשר רשות ציבורית היא הזוכהעקרונות שלטון החוק וחוקיות המינהל, ובפרט עיקרון חוקיות המס (ע"א 4708/14 י.ח דמרי בניה ופיתוח בע"מ נ'' המועצה המקומית גן יבנה).
**וריאציה 2 — מאזן אינטרסים:** כיצד מאזנים בין אינטרס הפרט לאינטרס הציבורינבחן את מאזן הנזק תוך התחשבות בשיקולים ציבוריים כמו שוויון וצדק חלוקתי (ע"א 9631/05 דוד ארד נ'' מדינת ישראל).
**וריאציה 3 — פטור חריג:** האם הפטור מהשבה לרשות ציבורית הוא כלל או חריגחובת ההשבה היא הכלל, והפטור הוא חריג שיופעל במקרים מועטים (ע"א 4708/14 י.ח דמרי בניה ופיתוח בע"מ נ'' המועצה המקומית גן יבנה).', 'רשות ציבורית כזוכהשיקולי צדק כוללים עקרונות שלטון החוק וחוקיות המינהלהפטור הוא חריג.', '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 2", "ע\"א 4708/14 י.ח דמרי בניה ופיתוח בע\"מ נ'' המועצה המקומית גן יבנה (24.08.2015)", "ע\"א 9631/05 דוד ארד נ'' מדינת ישראל (16.12.2010)", "דנ\"א 7398/09 עיריית ירושלים נ'' שירותי בריאות כללית (14.04.2015)", "הנריק רוסטוביץ, פנחס גלעד, משה וקנין, נורית לב, ארנונה עירונית - ספר ראשון (2001) | פרק 1 מבוא"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'האם הרשות פעלה בתום לב בעת הגבייה, שכן תום לב הוא תנאי הכרחי לפטור.', false, 'תשובה זו שגויה. אף שתום לב הוא שיקול חשוב, הוא אינו השיקול הנוסף והייחודי לרשות ציבורית, ואינו תנאי הכרחי לפטור.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'האם התושבים ידעו על הגבייה שלא כדין ולא מחו בזמן, שכן שיהוי מצד המזכה שולל את זכות ההשבה.', false, 'תשובה זו שגויה. שיהוי הוא טענת הגנה כללית, אך אינו השיקול הנוסף והייחודי לרשות ציבורית בהקשר של סעיף 2.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'עקרונות שלטון החוק וחוקיות המינהל, ובפרט עיקרון חוקיות המס, שכן אלו שיקולים בעלי משקל מיוחד כאשר הזוכה הוא רשות ציבורית.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי כאשר רשות מינהלית היא הזוכה, מצטרפים לסל השיקולים לפי סעיף 2 גם עקרונות שלטון החוק וחוקיות המינהל, ובפרט עיקרון חוקיות המס.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'האם הרשות שינתה את מצבה לרעה בהסתמך על הכספים שנגבו, שכן שינוי מצב לרעה הוא תנאי הכרחי לפטור.', false, 'תשובה זו שגויה. שינוי מצב לרעה הוא שיקול רלוונטי, אך אינו תנאי הכרחי לפטור, ואינו השיקול הנוסף והייחודי לרשות ציבורית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q07';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'שיקולי צדק ביישום סעיף 2', 2,
      'מהם השיקולים המרכזיים שבית המשפט בוחן בהפעלת סמכותו לפי סעיף 2 סיפא לחוק עשיית עושר ולא במשפט, המאפשרת פטור מהשבה בגין "נסיבות אחרות העושות את ההשבה בלתי צודקת"?', 'שאלה זו מתמקדת בשיקול הדעת הרחב הנתון לבית המשפט בהפעלת סעיף 2 סיפא לחוק עשיית עושר ולא במשפט. היא מפרטת את מגוון השיקולים הנבחנים, כגון תום לב הצדדים, שינוי מצב לרעה ומאזן הנזק, ומדגישה את אופיו הגמיש והפתוח של הסעיף המאפשר יציקת תוכן צודק לכל מקרה לגופו.', 'סעיף 2 סיפא לחוק עשיית עושר ולא במשפט מעניק לבית המשפט סמכות לפטור זוכה מהשבה אם ראה ''נסיבות אחרות העושות את ההשבה בלתי צודקת''. הפסיקה קבעה כי מדובר ב''רקמה פתוחה'' המאפשרת לבית המשפט שיקול דעת רחב ביותר לשקול מגוון שיקולים במטרה להביא לתוצאה המשקפת צדק יחסי בין הצדדים. בין השיקולים המרכזיים נמנים תום ליבם של שני הצדדים, שינוי נסיבות שחל בינתיים במצבו של הזוכה שבגינו תהיה ההשבה בלתי צודקת (שינוי מצב לרעה), ו''מאזן הנזק'' – השאלה אם הנזק שבחיוב הזוכה בהשבה עולה על הנזק שייגרם למזכה אם לא תושב לו זכייתו. ע"א 4708/14 י.ח דמרי בניה ופיתוח בע"מ נ'' המועצה המקומית גן יבנה (24.08.2015). ת"צ (מחוזי מרכז) 62174-03-17 אברהם אלעד גריינר נ'' שופרסל בע"מ (18.01.2026). ת"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע"מ (03.04.2024). ע"ע (ארצי ) 66524-09-14 רשות שדות התעופה בישראל - רון עניא (09.05.2017)', 'הטעות הנפוצה היא לנסות ולצמצם את שיקול הדעת של בית המשפט לרשימה סגורה של קריטריונים, במקום להבין את אופיו הגמיש והפתוח של סעיף 2 סיפא.',
      '["סעיף 2 לחוק עשיית עושר ולא במשפט", "שיקול דעת שיפוטי", "צדק יחסי", "תום לב", "שינוי מצב לרעה", "מאזן הנזק"]'::jsonb, '**וריאציה 1 — גמישות הסעיף:** האם סעיף 2 סיפא מפרט רשימה סגורה של נסיבותלא, הוא מציב ''מושג מסגרת'' ו''רקמה פתוחה'' המאפשרת גמישות שיפוטית (ע"א 588/87 אליעזר כהן נ'' צבי שמש).
**וריאציה 2 — שיקולים מרכזיים:** מהם השיקולים המרכזיים הנבחניםתום ליבם של הצדדים, שינוי נסיבות שחל במצבו של הזוכה, ומאזן הנזק (ת"צ (מחוזי מרכז) 62174-03-17 אברהם אלעד גריינר נ'' שופרסל בע"מ).
**וריאציה 3 — תפקיד בית המשפט:** מה תפקידו של בית המשפט בהפעלת סעיףיציקת ערכים של צדק יחסי אל תוך המסגרת של הוראת הסעיף (ת"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע"מ).', 'סעיף 2 סיפאשיקול דעת רחב לבית המשפטבחינת תום לב, שינוי מצב לרעה, מאזן נזקלמען צדק יחסי.', '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 2", "ע\"א 4708/14 י.ח דמרי בניה ופיתוח בע\"מ נ'' המועצה המקומית גן יבנה (24.08.2015)", "ת\"צ (מחוזי מרכז) 62174-03-17 אברהם אלעד גריינר נ'' שופרסל בע\"מ (18.01.2026)", "ת\"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע\"מ (03.04.2024)", "ע\"ע (ארצי ) 66524-09-14 רשות שדות התעופה בישראל - רון עניא (09.05.2017)", "ע\"א 247147/87 אליעזר כהן נ'' צבי שמש (24.09.1991)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק את מידת תום הלב של הזוכה, שכן זהו השיקול המרכזי והבלעדי.', false, 'תשובה זו שגויה. תום לב הוא שיקול חשוב, אך אינו השיקול הבלעדי, ובית המשפט בוחן מכלול רחב של נסיבות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'תום ליבם של שני הצדדים, שינוי נסיבות שחל במצבו של הזוכה, ומאזן הנזק בין הצדדים.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי במסגרת שיקול הדעת הרחב הנתון לבית המשפט לפי סעיף 2 סיפא, הוא בוחן מכלול שיקולים, ובהם תום לבם של הצדדים, שינוי מצב לרעה של הזוכה, ומאזן הנזק שייגרם לכל אחד מהצדדים אם תינתן או לא תינתן השבה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק את חומרת ההתעשרות שלא כדין, שכן ככל שההתעשרות חמורה יותר, כך יקטן הסיכוי לפטור.', false, 'תשובה זו שגויה. חומרת ההתעשרות רלוונטית לקביעת חובת ההשבה עצמה, אך לא בהכרח לפטור לפי סעיף 2, המתמקד בשיקולי צדק יחסי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק את העובדה שהזוכה לא היה מודע לכך שההתעשרות אינה כדין.', false, 'תשובה זו שגויה. אי-מודעות אינה עילה מספקת לפטור, ובית המשפט בוחן מכלול רחב יותר של שיקולים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q07';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריגים לכלל "זה נהנה וזה לא חסר"', 3,
      'ראובן השתמש בחצר של שמעון ללא רשותו, אך שמעון לא התכוון להשתמש בחצר בעצמו ולא נגרם לו כל חסרון כיס. שמעון גילה את השימוש ודרש מראובן לחדול ממנו, אך ראובן המשיך להשתמש בחצר. האם ראובן יהיה פטור מהשבה בגין הכלל "זה נהנה וזה לא חסר"?', 'שאלה זו בוחנת את אחד החריגים לכלל ''זה נהנה וזה לא חסר'' שבסעיף 2 לחוק עשיית עושר ולא במשפט. היא מדגישה כי הכלל, שמקורו במשפט העברי, אינו מוחלט, וכי מחאה מצד המזכה יכולה לשלול את הפטור מהשבה, גם אם לא נגרם לו חסרון כיס בפועל.', 'הכלל ''זה נהנה וזה לא חסר'' הוא אחד משני המצבים המפורשים בסעיף 2 לחוק עשיית עושר ולא במשפט, המאפשרים לבית המשפט לפטור זוכה מהשבה. כלל זה יונק את שורשיו מהמשפט העברי. עם זאת, המשפט העברי עצמו קבע סייגים לכלל זה. אחד הסייגים הרלוונטיים הוא מצב שבו המזכה מחה בפני הזוכה. במקרה כזה, גם אם לא נגרם חסרון למזכה, הזוכה לא יהיה פטור מהשבה. הפסיקה אימצה סייג זה, וקבעה כי אם המזכה מחה בפני הזוכה, הזוכה לא יהיה פטור מהשבה, שכן התנהגות זו של הזוכה נחשבת כ''עושה סחורה בפרתו של חברו''. ע"א 588/87 אליעזר כהן נ'' צבי שמש (24.09.1991). ע"א 290/80 ש.ג.מ. חניונים בע"מ נ'' מדינת ישראל (25.05.1983). דן חי דיני המידע האישי: בין פרטיות לקניין (2025) | פרק ד זכות הפרסום כקניין יחסי. יהונתן בלס עשיית עושר ולא במשפט (1991) | סעיף 2: פטור מהשבה', 'הטעות הנפוצה היא לראות בכלל ''זה נהנה וזה לא חסר'' כלל מוחלט, מבלי להכיר בסייגים שנקבעו לו, ובפרט בסייג של מחאה מצד המזכה.',
      '["זה נהנה וזה לא חסר", "סעיף 2 לחוק עשיית עושר ולא במשפט", "משפט עברי", "מחאה", "פטור מהשבה", "הסגת גבול"]'::jsonb, '**וריאציה 1 — סייג המחאה:** האם מחאה מצד המזכה שוללת פטור לפי ''זה נהנה וזה לא חסרכן, אם המזכה מחה בפני הזוכה, הזוכה אינו פטור מהשבה (ע"א 588/87 אליעזר כהן נ'' צבי שמש).
**וריאציה 2 — מקור הכלל:** מהו מקור הכלל ''זה נהנה וזה לא חסרהמשפט העברי, והוא אומץ בחוק עשיית עושר ולא במשפט (ע"א 290/80 ש.ג.מ. חניונים בע"מ נ'' מדינת ישראל).
**וריאציה 3 — אופי הכלל:** האם הכלל ''זה נהנה וזה לא חסר'' מוחלטלא, קיימים לו סייגים, והוא אינו מוחלט (יהונתן בלס עשיית עושר ולא במשפט (1991) | סעיף 2: פטור מהשבה).', 'כלל ''זה נהנה וזה לא חסר'' (סעיףאינו מוחלטסייג: מחאת המזכה שוללת פטור.', '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 2", "ע\"א 588/87 אליעזר כהן נ'' צבי שמש (24.09.1991)", "ע\"א 290/80 ש.ג.מ. חניונים בע\"מ נ'' מדינת ישראל (25.05.1983)", "דן חי דיני המידע האישי: בין פרטיות לקניין (2025) | פרק ד זכות הפרסום כקניין יחסי", "יהונתן בלס עשיית עושר ולא במשפט (1991) | סעיף 2: פטור מהשבה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, שכן הכלל "זה נהנה וזה לא חסר" הוא מוחלט ומונע השבה בכל מקרה שבו לא נגרם חסרון למזכה.', false, 'תשובה זו שגויה. הכלל "זה נהנה וזה לא חסר" אינו מוחלט, וקיימים לו סייגים, כגון מחאה מצד המזכה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן המשפט העברי, ממנו יונק הכלל, קובע סייג לפיו אם המזכה מחה בפני הזוכה, הזוכה לא יהיה פטור מהשבה.', true, 'זו התשובה הנכונה. הפסיקה הכירה בסייג לכלל ''זה נהנה וזה לא חסר'', שמקורו במשפט העברי, לפיו אם המזכה מחה בפני הזוכה, הזוכה אינו פטור מהשבה, גם אם לא נגרם חסרון למזכה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך בית המשפט רשאי לחייב את ראובן בפיצויים בגין הסגת גבול, ולא בהשבה.', false, 'תשובה זו שגויה. אף שייתכן חיוב בפיצויים, השאלה מתייחסת לפטור מהשבה, והמחאה משפיעה ישירות על הפטור מעשיית עושר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, שכן הכלל "זה נהנה וזה לא חסר" חל רק במקרים של טעות, ולא במקרים של שימוש מכוון.', false, 'תשובה זו שגויה. הכלל אינו מוגבל למקרים של טעות, והסייג של מחאה רלוונטי גם לשימוש מכוון.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q07';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'הבחנה בין פטור מהשבה לניכוי הוצאות', 4,
      'אדם התעשר שלא כדין על חשבון חברו, אך הוציא הוצאות סבירות להשגת הזכייה. מה ההבדל המהותי בין טענת פטור מהשבה לפי סעיף 2 לחוק עשיית עושר ולא במשפט לבין טענת ניכוי הוצאות לפי סעיף 3 לאותו חוק?', 'שאלה זו עוסקת בהבחנה חשובה בין שני מנגנוני הגנה בחוק עשיית עושר ולא במשפט: פטור מהשבה לפי סעיף 2 וניכוי הוצאות לפי סעיף 3. היא מדגישה את אופיו הרשותי של הפטור מול אופיה הקוגנטי של הזכות לניכוי הוצאות, ואת ההשלכות השונות של כל אחד מהם על שיקול הדעת השיפוטי.', 'סעיף 2 לחוק עשיית עושר ולא במשפט מעניק לבית המשפט סמכות שבשיקול דעת לפטור את הזוכה מחובת ההשבה, כולה או מקצתה, אם ראה שהזכייה לא הייתה כרוכה בחסרון המזכה או שראה נסיבות אחרות העושות את ההשבה בלתי צודקת. לעומת זאת, סעיף 3 לחוק מעניק לזוכה זכות לנכות ממה שעליו להשיב את מה שהוציא או התחייב להוציא או השקיע באופן סביר להשגת הזכייה. ההבדל המהותי הוא שסעיף 2 מקנה לבית המשפט שיקול דעת רחב, ואילו סעיף 3 מעניק לזוכה זכות קוגנטית לניכוי הוצאות סבירות, שמימושה אינו תלוי בשיקול דעת בית המשפט. ע"א 588/87 אליעזר כהן נ'' צבי שמש (24.09.1991). סעיף 2 לחוק עשיית עושר ולא במשפט, תשל"ט-1979. סעיף 3 לחוק עשיית עושר ולא במשפט, תשל"ט-1979. דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך ב (2017) | פרק 23: תחומי ההשבה, גובה ההשבה וצדדים להשבה', 'הטעות הנפוצה היא לבלבל בין שני הסעיפים ולייחס לבית המשפט שיקול דעת גם בניכוי הוצאות לפי סעיף 3, או לזוכה זכות מוחלטת לפטור לפי סעיף 2.',
      '["פטור מהשבה", "ניכוי הוצאות", "חוק עשיית עושר ולא במשפט", "שיקול דעת שיפוטי", "זכות קוגנטית", "הוצאות סבירות"]'::jsonb, '**וריאציה 1 — אופי הסמכות:** מה ההבדל באופי הסמכות בין סעיף 2 לסעיףסעיף 2 מעניק סמכות שבשיקול דעת לבית המשפט, ואילו סעיף 3 מעניק זכות לזוכה (ע"א 588/87 אליעזר כהן נ'' צבי שמש).
**וריאציה 2 — תנאי הפעלה:** מה התנאים להפעלת כל סעיףסעיף 2: זכייה ללא חסרון למזכה או נסיבות אחרות בלתי צודקות. סעיף 3: הוצאות סבירות להשגת הזכייה (סעיף 2 לחוק עשיית עושר ולא במשפט ו סעיף 3 לחוק עשיית עושר ולא במשפט).
**וריאציה 3 — מטרת הסעיפים:** מה מטרת כל אחד מהסעיפיםסעיף 2 נועד לעשיית צדק יחסי. סעיף 3 נועד להחזיר לזוכה הוצאות שהוציא באופן סביר (ע"א 588/87 אליעזר כהן נ'' צבי שמש).', 'סעיף 2 (פטורשיקול דעת בית המשפט, מטעמי צדק. סעיף 3 (ניכוי הוצאותזכות לזוכה, בגין הוצאות סבירות.', '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 2", "חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 3", "ע\"א 588/87 אליעזר כהן נ'' צבי שמש (24.09.1991)", "דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך ב (2017) | פרק 23: תחומי ההשבה, גובה ההשבה וצדדים להשבה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'סעיף 2 מעניק זכות מוחלטת לפטור, בעוד סעיף 3 מעניק לבית המשפט שיקול דעת בניכוי הוצאות.', false, 'תשובה זו שגויה. ההפך הוא הנכון: סעיף 2 מעניק שיקול דעת לבית המשפט, בעוד סעיף 3 מעניק זכות לניכוי הוצאות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'סעיף 2 מעניק לבית המשפט סמכות שבשיקול דעת לפטור מהשבה, כולה או חלקה, ואילו סעיף 3 מעניק לזוכה זכות לנכות הוצאות סבירות שהוציא, ללא שיקול דעת של בית המשפט.', true, 'זו התשובה הנכונה. סעיף 2 מעניק לבית המשפט שיקול דעת רחב לפטור מהשבה מטעמי צדק, בעוד סעיף 3 מעניק לזוכה זכות קוגנטית לנכות הוצאות סבירות שהוציא, ואינו תלוי בשיקול דעת בית המשפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'סעיף 2 חל רק במקרים של התעשרות ללא חסרון למזכה, ואילו סעיף 3 חל בכל מקרה של הוצאות סבירות.', false, 'תשובה זו שגויה. סעיף 2 חל גם במקרים של ''נסיבות אחרות העושות את ההשבה בלתי צודקת'', ולא רק במקרים של ''זה נהנה וזה לא חסר''.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'שני הסעיפים זהים במהותם ומהווים טענות הגנה מפני השבה, ללא הבדל מהותי.', false, 'תשובה זו שגויה. אף ששני הסעיפים מהווים טענות הגנה, קיים הבדל מהותי ביניהם באופי הסמכות ובשיקול הדעת הנתון לבית המשפט.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q07';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 7, '2024-W-S-Q07';
END
$$;

-- ============================================================
-- Q08 — angles backfill for 2024-W-S-Q08 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q08';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q08';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הקלטת שיחה עם עורך דין אחר', 1,
      'עורך דין פלוני הקליט שיחת טלפון עם עורך דין אלמוני, חברו למקצוע, בנוגע לתיק משפטי משותף, ללא ידיעתו של אלמוני. פלוני לא עשה שימוש בהקלטה. האם פלוני עבר עבירה אתית?', 'שאלה זו בוחנת את כלל 22(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), העוסק באיסור הקלטת שיחות עם לקוחות או עורכי דין אחרים ללא ידיעתם. היא מדגישה את ההבחנה בין הקלטת שיחה פרטית להקלטת דיון בבית המשפט, ואת חשיבות השמירה על יחסי אמון וכבוד בין עורכי דין.', 'כלל 22 לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע שלושה סעיפים נפרדים העוסקים בהקלטת הזולת. סעיף קטן (א) קובע כי ''לא יקליט עורך דין שיחה עם לקוחו או עם עורך דין אחר, אלא בידיעתם''. כלל זה נועד לשמור על יחסי אמון וכבוד בין עורכי דין, ולאפשר התנהלות פתוחה וגלוית לב. הפרת כלל זה מהווה עבירה אתית, גם אם לא נעשה שימוש בהקלטה. הפסיקה הדגישה כי אין איסור מוחלט על הקלטה של שיחה עם עורך דין אחר, אלא קיימת רק חובה לוודא שהצד האחר יודע על דבר ההקלטה. כלל 22(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986. עב"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה"ד במחוז חיפה (01.07.2019). נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | הקלטת הזולת', 'הטעות הנפוצה היא לבלבל בין כלל 22(א) לכלל 22(ב), או לחשוב שהאיסור על הקלטה ללא ידיעה חל רק אם נעשה שימוש בהקלטה.',
      '["כללי לשכת עורכי הדין (אתיקה מקצועית)", "הקלטת שיחה", "חובת ידיעה", "עבירה אתית", "כבוד המקצוע"]'::jsonb, '**וריאציה 1 — חובת ידיעה:** האם עורך דין רשאי להקליט שיחה עם עורך דין אחר ללא ידיעתולא, כלל 22(א) אוסר זאת במפורש (כלל 22(א) לכללי לשכת עורכי הדין (אתיקה מקצועית)).
**וריאציה 2 — שימוש בהקלטה:** האם אי-שימוש בהקלטה פוטר מעבירה אתיתלא, עצם ההקלטה ללא ידיעה מהווה עבירה אתית (עב"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה"ד במחוז חיפה).
**וריאציה 3 — תכלית הכלל:** מהי תכלית כלל 22(אלשמור על יחסי אמון וכבוד ולאפשר התנהלות פתוחה וגלוית לב בין עורכי דין (עב"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה"ד במחוז חיפה).', 'הקלטת שיחה עם עו"ד אחר ללא ידיעתועבירה אתית לפי כלל 22(אגם ללא שימוש בהקלטה.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 22(א)", "עב\"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה\"ד במחוז חיפה (01.07.2019)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | הקלטת הזולת"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, שכן הקלטת שיחה פרטית אינה אסורה על פי כללי האתיקה, כל עוד לא נעשה בה שימוש.', false, 'תשובה זו שגויה. כלל 22(א) אוסר על הקלטת שיחה עם עורך דין אחר ללא ידיעתו, גם אם לא נעשה בה שימוש.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, שכן כלל 22(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין להקליט שיחה עם עורך דין אחר ללא ידיעתו.', true, 'זו התשובה הנכונה. כלל 22(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע במפורש כי ''לא יקליט עורך דין שיחה עם לקוחו או עם עורך דין אחר, אלא בידיעתם''. הפרת כלל זה מהווה עבירה אתית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, אלא אם כן השיחה התנהלה במסגרת דיון בבית המשפט, שאז חלה חובת יידוע.', false, 'תשובה זו שגויה. כלל 22(א) חל על שיחות מחוץ לבית המשפט, בעוד כלל 22(ב) חל על דיונים בבית המשפט.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם עורך הדין המקליט היה מודע לכך שההקלטה אסורה, שכן נדרש יסוד נפשי לעבירה אתית.', false, 'תשובה זו שגויה. כללי האתיקה מטילים חובות אובייקטיביות, ואי-ידיעה על האיסור אינה פוטרת מעבירה אתית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q08';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'סמכות בית המשפט בענייני אתיקה', 2,
      'מהי סמכותו של בית המשפט האזרחי לדון בטענות הנוגעות להפרת כללי האתיקה של עורכי דין ולתת צווים או סעדים בגין הפרות אלו?', 'שאלה זו עוסקת בחלוקת הסמכויות בין בתי המשפט האזרחיים לבין מוסדות לשכת עורכי הדין בכל הנוגע לדיון בהפרות אתיות. היא מבהירה כי אף שהאכסניה הטבעית לבירור סוגיות אתיות היא מוסדות הלשכה, לבית המשפט האזרחי קיימת סמכות עקרונית להתערב במקרים חריגים, במיוחד כאשר ההפרה האתית משפיעה על זכויות בעלי הדין או על טוהר ההליך.', 'האכסניה הטבעית והרגילה לבירור שאלות אתיות היא מוסדות לשכת עורכי הדין. עם זאת, הפסיקה קבעה כי לבית המשפט האזרחי קיימת סמכות עקרונית לדון בטענות הנוגעות להפרת כללי האתיקה של עורכי דין ולתת צווים או סעדים בגין הפרות אלו, לרבות הוראה על הפסקת ייצוג. סמכות זו נובעת מסמכותו הכללית המעוגנת בסעיף 75 לחוק בתי המשפט. בית המשפט יפעיל את סמכותו זו רק במקרים חריגים, כשההפרה הנטענת עלולה לפגוע באינטרסים לגיטימיים של בעל הדין שהעלה אותה, ולא רק בטהרת המקצוע או כבודו. דוגמאות למקרים בהם בית המשפט מוסמך להתערב כוללות הפרת כלל 36 (עורך דין כעד) או אי-שמירה על יחס כבוד לבית המשפט (כלל 32(א)). רע"א 9930/17 אל מדאמין בע"מ נ'' חביב שחאדה חנא (28.03.2018). ת"א (מחוזי נצרת) 36506-04-25 יהושוע רובין עו"ד נ'' יואן סורינקה (15.03.2026). ת"א (שלום נצ'') 69773-03-18 סרוגי הידרוליקה נצרת בע"מ נ'' סמיר סרוג''י (07.01.2021). יעקב שקד סדר הדין האזרחי (2026) | נושאים כלליים בפרק זה אעמוד על נושאים שונים הכרוכים בהליך האזרחי, חלקם מופיעים בתקנות וחלקם בחיקוקים אחרים.', 'הטעות הנפוצה היא לחשוב שמוסדות לשכת עורכי הדין הם הגוף הבלעדי לדון בענייני אתיקה, מבלי להכיר בסמכות החריגה של בתי המשפט האזרחיים.',
      '["סמכות עניינית", "אתיקה מקצועית", "חוק בתי המשפט", "סעיף 75", "הפרת כללי אתיקה", "הפסקת ייצוג"]'::jsonb, '**וריאציה 1 — אכסניה טבעית:** מהי האכסניה הטבעית לבירור שאלות אתיותמוסדות לשכת עורכי הדין (רע"א 9930/17 אל מדאמין בע"מ נ'' חביב שחאדה חנא).
**וריאציה 2 — סמכות חריגה:** מתי יפעיל בית המשפט האזרחי את סמכותו לדון בענייני אתיקהבמקרים חריגים, כשההפרה עלולה לפגוע באינטרסים לגיטימיים של בעל הדין (ת"א (מחוזי נצרת) 36506-04-25 יהושוע רובין עו"ד נ'' יואן סורינקה).
**וריאציה 3 — מקור הסמכות:** מהו מקור הסמכות של בית המשפט האזרחי לדון בענייני אתיקהסמכותו הכללית המעוגנת בסעיף 75 לחוק בתי המשפט (ת"א (שלום נצ'') 69773-03-18 סרוגי הידרוליקה נצרת בע"מ נ'' סמיר סרוג''י).', 'סמכות בית המשפט האזרחי בענייני אתיקהקיימת אך חריגהמופעלת כשיש פגיעה בזכויות בעל דיןמכוח סעיף 75 לחוק בתי המשפט.', '["רע\"א 9930/17 אל מדאמין בע\"מ נ'' חביב שחאדה חנא (28.03.2018)", "ת\"א (מחוזי נצרת) 36506-04-25 יהושוע רובין עו\"ד נ'' יואן סורינקה (15.03.2026)", "ת\"א (שלום נצ'') 69773-03-18 סרוגי הידרוליקה נצרת בע\"מ נ'' סמיר סרוג''י (07.01.2021)", "יעקב שקד סדר הדין האזרחי (2026) | נושאים כלליים בפרק זה אעמוד על נושאים שונים הכרוכים בהליך האזרחי, חלקם מופיעים בתקנות וחלקם בחיקוקים אחרים."]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לבית המשפט האזרחי אין סמכות לדון בענייני אתיקה, שכן אלו נתונים באופן בלעדי למוסדות לשכת עורכי הדין.', false, 'תשובה זו שגויה. אף שהאכסניה הטבעית היא מוסדות הלשכה, לבית המשפט האזרחי קיימת סמכות עקרונית לדון בנושאים אלו במקרים חריגים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לבית המשפט האזרחי קיימת סמכות עקרונית לדון בטענות אלו מכוח סמכותו הכללית, אך הוא יפעיל אותה רק במקרים חריגים, כשההפרה עלולה לפגוע באינטרסים לגיטימיים של בעל הדין.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי לבית המשפט האזרחי סמכות עקרונית לדון בהפרות אתיות מכוח סעיף 75 לחוק בתי המשפט, אך הוא יפעיל אותה במשורה ובמקרים חריגים, בעיקר כאשר ההפרה פוגעת בזכויות בעל הדין בהליך.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט האזרחי מוסמך לדון בענייני אתיקה רק אם מוסדות לשכת עורכי הדין הפנו אליו את הסוגיה לקבלת חוות דעת.', false, 'תשובה זו שגויה. בית המשפט יכול ליזום דיון בסוגיה אתית במקרים מסוימים, ואינו תלוי בהפניה ממוסדות הלשכה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט האזרחי מוסמך לדון בענייני אתיקה רק אם מדובר בהפרה ברורה וחד-משמעית של כללי האתיקה, כגון אי-שמירה על כבוד בית המשפט.', false, 'תשובה זו שגויה. אף שבמקרים כאלה בית המשפט יתערב, זו אינה ההגדרה המלאה של סמכותו, והוא יכול להתערב גם במקרים אחרים הפוגעים בזכויות בעל הדין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q08';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'שימוש בהקלטה אסורה כראיה', 3,
      'עורך דין הקליט דיון בבית המשפט ללא ידיעת בית המשפט, בניגוד לכלל 22(ב). ההקלטה מכילה מידע קריטי להגנתו של לקוחו בתביעה אזרחית. האם בית המשפט יפסול את ההקלטה מלשמש כראיה בשל העבירה האתית?', 'שאלה זו עוסקת במתח שבין כללי האתיקה המקצועית לבין דיני הראיות, ובפרט בשאלת קבילותה של הקלטה שהושגה תוך הפרה אתית. היא מדגישה כי במשפט הישראלי אין כלל מוחלט של ''פירות העץ המורעל'', וכי בית המשפט יבחן את קבילות הראיה תוך איזון בין חומרת ההפרה לבין חשיבות הראיה לגילוי האמת.', 'כלל 22(ג) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי ''לא יעשה עורך דין שימוש בהקלטה שנעשתה תוך הפרת סעיף זה''. כלל זה מטיל איסור אתי על עורך הדין. עם זאת, במישור הראייתי, אין במשפט הישראלי איסור כללי על שימוש ב''פירות העץ המורעל'', כלומר, ראיות שהושגו שלא כדין. הפסיקה קבעה כי אף שעורך הדין המקליט שיחה עם לקוחו או עם עורך דין אחר עובר עבירת משמעת, ההקלטה עשויה להיות קבילה בהליך משפטי המתנהל נגדו. בית המשפט יבחן את קבילות ההקלטה לפי נסיבות המקרה, תוך שקילת חומרת ההפרה מול חשיבות הראיה לגילוי האמת ולעשיית צדק. כלל 22(ג) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986. עב"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה"ד במחוז חיפה (01.07.2019). נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | הקלטת הזולת. יעקב שקד סדר הדין האזרחי (2026) | פרוטוקול בהקלטה', 'הטעות הנפוצה היא להסיק מאיסור אתי על פסילה אוטומטית של ראיה, מבלי להבחין בין המישור האתי למישור הראייתי במשפט הישראלי.',
      '["קבילות ראיות", "הקלטה אסורה", "כלל 22(ג)", "עבירה אתית", "פירות העץ המורעל", "מאזן אינטרסים"]'::jsonb, '**וריאציה 1 — איסור אתי:** האם שימוש בהקלטה אסורה מהווה עבירה אתיתכן, כלל 22(ג) אוסר על עורך דין לעשות שימוש בהקלטה שנעשתה תוך הפרת סעיף זה (כלל 22(ג) לכללי לשכת עורכי הדין (אתיקה מקצועית)).
**וריאציה 2 — קבילות ראייתית:** האם הקלטה אסורה פסולה אוטומטית כראיהלא, אין איסור כללי על שימוש בראיות שהושגו שלא כדין, ובית המשפט יבחן את קבילותה (נבו - המתמחה אתיקה מקצועית - כללי האתיקה).
**וריאציה 3 — שיקול דעת בית המשפט:** מהם השיקולים בקבילות הקלטה אסורהבית המשפט ישקול את חומרת ההפרה מול חשיבות הראיה לגילוי האמת ולעשיית צדק (יעקב שקד סדר הדין האזרחי | פרוטוקול בהקלטה).', 'הקלטה אסורהעבירה אתית (כלל 22(גאך לא בהכרח פסולה כראיהבית המשפט יאזן שיקולים.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 22(ג)", "עב\"י (מינהליים י-ם) 39789-04-19 אביעד ויסולי נ'' ועדת האתיקה של לשכת עוה\"ד במחוז חיפה (01.07.2019)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | הקלטת הזולת", "יעקב שקד סדר הדין האזרחי (2026) | פרוטוקול בהקלטה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, שכן הקלטה שנעשתה תוך הפרת כללי האתיקה פסולה באופן מוחלט מלשמש כראיה בהליך משפטי.', false, 'תשובה זו שגויה. במשפט הישראלי אין כלל מוחלט של ''פירות העץ המורעל'', וקבילות ראיה שהושגה שלא כדין נבחנת לפי נסיבות העניין.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא בהכרח, שכן במשפט הישראלי אין איסור כללי על שימוש בראיות שהושגו שלא כדין, ובית המשפט יבחן את קבילות ההקלטה לפי נסיבות המקרה ומאזן האינטרסים.', true, 'זו התשובה הנכונה. אף שהקלטה ללא רשות מהווה עבירה אתית, אין במשפט הישראלי כלל מוחלט הפוסל ראיות שהושגו שלא כדין. בית המשפט יבחן את קבילות ההקלטה תוך שקילת חומרת ההפרה מול חשיבות הראיה לאמת ולצדק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, שכן כלל 22(ג) אוסר על עורך דין לעשות שימוש בהקלטה שנעשתה תוך הפרת סעיף זה, ואיסור זה חל גם על הגשתה כראיה.', false, 'תשובה זו שגויה. כלל 22(ג) קובע איסור אתי על עורך הדין, אך אינו קובע בהכרח פסילה אוטומטית של הראיה במישור הדיוני.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן ההקלטה פוגעת בפרטיות הצדדים באופן חמור, שאז היא תיפסל מטעמי הגנה על הפרטיות.', false, 'תשובה זו שגויה. פגיעה בפרטיות היא שיקול חשוב, אך אינה התנאי היחיד לפסילת ראיה שהושגה שלא כדין, ובית המשפט בוחן מכלול שיקולים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q08';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סנקציות על הפרעת דיון', 4,
      'עורך דין מפריע למהלך דיון בבית המשפט באופן חוזר ונשנה, למרות התראות השופט. אילו סנקציות רשאי בית המשפט להטיל עליו מכוח סעיף 72 לחוק בתי המשפט, ומהם התנאים להטלתן?', 'שאלה זו עוסקת בסמכות בית המשפט להטיל סנקציות על הפרעת דיון מכוח סעיף 72 לחוק בתי המשפט. היא מדגישה את אופיה הייחודי של סמכות זו, המאפשרת הטלת סנקציה עונשית ללא הליך פלילי מלא, ואת הסייגים הפרוצדורליים שנקבעו בפסיקה להפעלתה, כגון חובת התראה מפורשת ותיעוד מדויק בפרוטוקול.', 'סעיף 72 לחוק בתי המשפט מקנה לבית המשפט סמכות להטיל על אדם קנס או מאסר בשל הפרעתו למהלך הדיון. סמכות זו נושאת אופי ייחודי, שכן היא מאפשרת לבית המשפט להטיל סנקציה עונשית על אתר, מבלי לקיים הליך פלילי כסדרו. בשל אופיה זה, הפסיקה תוחמת את הסמכות בסייגים. תנאי מקדים להטלת קנס או מאסר הוא מתן התראה מפורשת לגורם המפריע בנוגע לאפשרות הטלת הסנקציה אם לא יימנע מהפרעה, ועל התראה זו למצוא ביטוי מפורש בפרוטוקול הדיון. יתרה מכך, על בית המשפט לציין בפרוטוקול בצורה מפורטת ומדויקת את מהות ההפרעה, ''משל היה פרוטוקול הדיון ''כתב אישום'' המוגש על-ידי בית משפט''. סעיף 72(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984. בש"פ 6242/21 מיכאל בר נ'' מדינת ישראל (17.11.2021). בש"פ 8503/22 פלונית נ'' פלוני (22.01.2023). יעקב שקד סדר הדין האזרחי (2026) | נושאים כלליים בפרק זה אעמוד על נושאים שונים הכרוכים בהליך האזרחי, חלקם מופיעים בתקנות וחלקם בחיקוקים אחרים.', 'הטעות הנפוצה היא להתעלם מהסייגים הפרוצדורליים המחמירים להטלת סנקציות לפי סעיף 72, או לבלבל בין סמכות זו לבין סמכויות משמעתיות של לשכת עורכי הדין.',
      '["סעיף 72 לחוק בתי המשפט", "הפרעת דיון", "קנס", "מאסר", "התראה מפורשת", "פרוטוקול דיון", "סמכות עונשית"]'::jsonb, '**וריאציה 1 — סמכות בית המשפט:** אילו סנקציות רשאי בית המשפט להטיל על מפריע דיוןקנס או מאסר, בנוסף להרחקה (סעיף 72(א) לחוק בתי המשפט).
**וריאציה 2 — תנאי התראה:** מהו התנאי המקדים להטלת קנס או מאסרמתן התראה מפורשת על סוג העונש שיוטל, שתתועד בפרוטוקול (בש"פ 6242/21 מיכאל בר נ'' מדינת ישראל).
**וריאציה 3 — תיעוד ההפרעה:** כיצד יש לתעד את ההפרעה בפרוטוקולבצורה מפורטת ומדויקת, ''משל היה פרוטוקול הדיון ''כתב אישום'' (בש"פ 8503/22 פלונית נ'' פלוני).', 'הפרעת דיון (סעיףקנס/מאסרדורש התראה מפורשת על העונשותיעוד מפורט בפרוטוקול.', '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 72", "בש\"פ 6242/21 מיכאל בר נ'' מדינת ישראל (17.11.2021)", "בש\"פ 8503/22 פלונית נ'' פלוני (22.01.2023)", "יעקב שקד סדר הדין האזרחי (2026) | נושאים כלליים בפרק זה אעמוד על נושאים שונים הכרוכים בהליך האזרחי, חלקם מופיעים בתקנות וחלקם בחיקוקים אחרים."]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט רשאי להטיל קנס או מאסר, ובלבד שניתנה התראה מפורשת על סוג העונש שיוטל, וההפרעה תועדה בפרוטוקול הדיון.', true, 'זו התשובה הנכונה. סעיף 72 לחוק בתי המשפט מקנה לבית המשפט סמכות להטיל קנס או מאסר. הפסיקה קבעה כי תנאי לכך הוא מתן התראה מפורשת על סוג העונש, ותיעוד מפורט של ההפרעה בפרוטוקול.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט רשאי להטיל קנס או מאסר, אך רק לאחר הגשת כתב אישום פלילי וניהול הליך פלילי מלא.', false, 'תשובה זו שגויה. סעיף 72 מאפשר הטלת סנקציה עונשית על אתר, ללא צורך בהליך פלילי מלא, אך עם סייגים פרוצדורליים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט רשאי להרחיק את עורך הדין מהאולם בלבד, שכן סנקציות כספיות או מאסר נתונות לשיקול דעת בתי הדין המשמעתיים.', false, 'תשובה זו שגויה. סעיף 72 מקנה לבית המשפט סמכות להטיל קנס או מאסר, בנוסף להרחקה, בכפוף לתנאים מסוימים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט רשאי להטיל קנס או מאסר, ובלבד שההפרעה הייתה חמורה במיוחד ופגעה באופן ממשי בטוהר ההליך השיפוטי.', false, 'תשובה זו שגויה. אף שחומרת ההפרעה רלוונטית, התנאים המרכזיים להטלת הסנקציה הם פרוצדורליים: התראה מפורשת ותיעוד בפרוטוקול.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q08';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 8, '2024-W-S-Q08';
END
$$;

-- ============================================================
-- Q09 — angles backfill for 2024-W-S-Q09 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q09';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q09';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'סמכות בינלאומית - נכסים בלבד', 1,
      'מורי, תושב חוץ, נפטר בחו"ל והותיר אחריו בישראל רק שעון יוקרתי אחד. האם בית המשפט בישראל מוסמך לדון בכלל ירושתו, או רק בשעון?', 'שאלה זו בוחנת את היקף הסמכות הבינלאומית של בית המשפט בישראל בענייני ירושה, כאשר הזיקה היחידה לישראל היא הנחת נכסים. היא מדגישה את הפרשנות הרחבה של סעיף 136 לחוק הירושה, המקנה סמכות על כלל העיזבון, אך גם את שיקול הדעת של בית המשפט להפעיל את דוקטרינת הפורום הבלתי נאות.', 'סעיף 136 לחוק הירושה קובע שתי חלופות אלטרנטיביות להקניית סמכות בינלאומית לבית המשפט בישראל: מושבו של המוריש בישראל ביום מותו, או שהניח נכסים בישראל. הפסיקה, ובפרט פסק הדין בעניין חאנזאליס (בג"ץ 171/68) וכהנא (ע"א 598/85), קבעה כי בשתי החלופות הסמכות משתרעת על כלל ירושתו של המוריש, לרבות נכסים מחוץ לישראל. גם אם מדובר בנכס זניח, עצם קיומו מקנה סמכות. עם זאת, בית המשפט רשאי להפעיל שיקול דעת בשלב הפעלת הסמכות, ולצמצם את היקף הדיון או לדחות אותו על בסיס דוקטרינת הפורום הבלתי נאות, במיוחד כאשר מרבית הזיקות מצביעות על פורום זר. סעיף 136 לחוק הירושה, תשכ"ה-1965. ע"מ (מחוזי תל אביב-יפו) 1069/08 ר. צ'' נ'' ו.י. צ''. א (04.11.2009). ת"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז"ל נ'' ר. צ'' (29.01.2008). שמואל שילה פירוש לחוק הירושה כרך ב (1995) | סעיף 136: סמכות בתי-המשפט הישראליים', 'הטעות הנפוצה היא לחשוב שהנחת נכסים זניחים בישראל אינה מקנה סמכות בינלאומית כלל, או שהיא מקנה סמכות רק לגבי אותם נכסים, מבלי להבחין בין שלב הקניית הסמכות לשלב הפעלתה.',
      '["סמכות בינלאומית", "חוק הירושה", "סעיף 136", "הנחת נכסים בישראל", "פורום בלתי נאות", "שיקול דעת שיפוטי"]'::jsonb, '**וריאציה 1 — סמכות על כלל העיזבון:** האם הנחת נכס זניח בישראל מקנה סמכות על כלל העיזבוןכן, סעיף 136 מקנה סמכות על ''ירושתו של כל אדם'' (סעיף 136 לחוק הירושה).
**וריאציה 2 — שיקול דעת בית המשפט:** האם בית המשפט חייב לדון בכלל העיזבוןלא, בית המשפט רשאי להפעיל שיקול דעת ולצמצם את היקף הדיון מכוח דוקטרינת הפורום הבלתי נאות (ע"מ (מחוזי תל אביב-יפו) 1069/08 ר. צ'' נ'' ו.י. צ''. א).
**וריאציה 3 — פרשנות לשונית:** כיצד מפורשת המילה "ירושתו" בסעיףללא הגבלה, ומשתרעת על כלל נכסי המוריש בכל מקום שהם (ת"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז"ל נ'' ר. צ'').', 'הנחת נכסים בישראלמקנה סמכות בינלאומית על כלל העיזבון (סעיףאך בית המשפט רשאי לצמצם את הדיון בפורום בלתי נאות.', '["חוק הירושה, תשכ\"ה-1965, סעיף 136", "ת\"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז\"ל נ'' ר. צ'' (29.01.2008)", "ע\"מ (מחוזי תל אביב-יפו) 1069/08 ר. צ'' נ'' ו.י. צ''. א (04.11.2009)", "שמואל שילה פירוש לחוק הירושה כרך ב (1995) | סעיף 136: סמכות בתי-המשפט הישראליים"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט בישראל מוסמך לדון בכלל ירושתו של מורי, אך רשאי להפעיל את דוקטרינת הפורום הבלתי נאות ולצמצם את הדיון לנכסים בישראל.', true, 'זו התשובה הנכונה. סעיף 136 לחוק הירושה מקנה סמכות בינלאומית לבית המשפט בישראל לדון בכלל ירושתו של אדם שהניח נכסים בישראל, גם אם מדובר בנכס זניח. עם זאת, בית המשפט רשאי להפעיל שיקול דעת ולצמצם את היקף הדיון מכוח דוקטרינת הפורום הבלתי נאות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט בישראל מוסמך לדון בשעון בלבד, שכן מדובר בנכס זניח ואין הצדקה להרחיב את הסמכות לכלל העיזבון.', false, 'תשובה זו שגויה. לשון סעיף 136 לחוק הירושה אינה מבחינה בין נכסים זניחים לנכסים מהותיים לעניין הקניית הסמכות הבינלאומית, אלא מתייחסת ל''נכסים בישראל'' באופן כללי.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט בישראל אינו מוסמך לדון כלל, שכן מקום מושבו של מורי לא היה בישראל.', false, 'תשובה זו שגויה. סעיף 136 לחוק הירושה קובע שתי חלופות אלטרנטיביות להקניית סמכות: מקום מושב בישראל או הנחת נכסים בישראל. הנחת נכסים בישראל מקנה סמכות גם אם המוריש אינו תושב ישראל.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט בישראל מוסמך לדון בכלל ירושתו של מורי, ואינו רשאי לצמצם את הדיון לנכסים בישראל.', false, 'תשובה זו שגויה. אף שהסמכות היא על כלל הירושה, בית המשפט רשאי להפעיל שיקול דעת ולצמצם את היקף הדיון מכוח דוקטרינת הפורום הבלתי נאות, כפי שנקבע בפסיקה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q09';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחן "מושב" המוריש', 2,
      'כיצד נקבע "מושבו" של מוריש לצורך סעיף 135 ו-136 לחוק הירושה?', 'שאלה זו מתמקדת בהגדרת המונח "מושב" בחוק הירושה, שהוא קריטי לקביעת הסמכות הבינלאומית וברירת הדין. היא מדגישה את מבחן "מרכז החיים" ואת מבחן "מרב הזיקות" ככלים פרשניים לקביעת המושב, ומבחינה בינו לבין זיקות אחרות שאינן רלוונטיות.', 'סעיף 135 לחוק הירושה מגדיר "מושב" של אדם כ"המקום בו נמצא מרכז חייו". הפסיקה מפרשת את "מרכז חייו" באמצעות "מבחן מרב הזיקות", הבוחן את מכלול הקשרים של המוריש למקום מסוים, כגון מקום מגורים קבוע, מקום עבודה, מרכז משפחתי וחברתי, מקום ניהול עסקיו וכדומה. מקום הפטירה, הקבורה או האזרחות אינם קובעים את המושב, אלא רק משמשים אינדיקציה אפשרית בין יתר הזיקות. במקרה של דני, העברת מרכז חייו לישראל היא הקובעת את מושבו בישראל. סעיף 135 לחוק הירושה, תשכ"ה-1965. נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | כללי ברירת הדין. ע"א 598/85 מסתורה כהנא נ'' מאיר כהנא, מד(3) 473 (14.08.1990)', 'הטעות הנפוצה היא לבלבל בין "מושב" לבין "אזרחות", "מקום פטירה" או "מקום קבורה", שהם אינם המבחן הקובע בחוק הירושה.',
      '["מושב", "מרכז חיים", "מבחן מרב הזיקות", "חוק הירושה", "סעיף 135", "סמכות בינלאומית", "ברירת דין"]'::jsonb, '**וריאציה 1 — הגדרת מושב:** מהי הגדרת "מושב" בחוק הירושההמקום שבו נמצא מרכז חייו של האדם (סעיף 135 לחוק הירושה).
**וריאציה 2 — מבחן קביעת מושב:** כיצד נקבע מרכז החייםלפי מבחן מרב הזיקות, הבוחן את מכלול הקשרים של המוריש (נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות).
**וריאציה 3 — חשיבות המושב:** מדוע עקרון המושב חשוב בחוק הירושההוא הכלל היסודי בברירת הדין ובקביעת הסמכות הבינלאומית, ומבטא העדפה מודעת של המחוקק (ע"א 598/85 מסתורה כהנא נ'' מאיר כהנא).', '"מושב" המורישנקבע לפי מרכז חייובאמצעות מבחן מרב הזיקותקובע סמכות וברירת דין.', '["חוק הירושה, תשכ\"ה-1965, סעיף 135", "ע\"א 598/85 מסתורה כהנא נ'' מאיר כהנא, מד(3) 473 (14.08.1990)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | כללי ברירת הדין"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'על פי מקום אזרחותו של המוריש ביום מותו.', false, 'תשובה זו שגויה. חוק הירושה אימץ את עקרון המושב ולא את עקרון האזרחות ככלל ברירת דין וסמכות בינלאומית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'על פי המקום שבו נמצא מרכז חייו של המוריש, הנקבע לפי מבחן מרב הזיקות.', true, 'זו התשובה הנכונה. סעיף 135 לחוק הירושה מגדיר "מושב" כ"המקום בו נמצא מרכז חייו", והפסיקה מפרשת זאת לפי מבחן מרב הזיקות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'על פי מקום פטירתו של המוריש.', false, 'תשובה זו שגויה. מקום הפטירה אינו רלוונטי לקביעת מקום המושב, אלא מרכז החיים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'על פי מקום קבורתו של המוריש.', false, 'תשובה זו שגויה. מקום הקבורה אינו רלוונטי לקביעת מקום המושב, אלא מרכז החיים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q09';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריג לדין המושב - סעיף 138', 3,
      'אילו נכסים נכללים בחריג הקבוע בסעיף 138 לחוק הירושה, לפיו יחול על ירושתם דין מקום הימצאם בלבד?', 'שאלה זו עוסקת בחריג לכלל ברירת הדין הקבוע בסעיף 137 לחוק הירושה, והוא סעיף 138. היא מדגישה את הפרשנות המצמצמת של סעיף 138, לפיה הוא חל רק במקרים בהם הדין המקומי של הנכס שולל במפורש תחולת כל דין אחר, ובכך מבטיח את האפקטיביות של פסק הדין הישראלי.', 'סעיף 137 לחוק הירושה קובע את הכלל לפיו על הירושה יחול דין מושבו של המוריש בשעת מותו. סעיף 138 מהווה חריג לכלל זה, וקובע כי "נכסים העוברים בירושה לפי דין מקום המצאם בלבד, יחול על ירושתם אותו דין". הפסיקה והמלומדים מפרשים את המילה "בלבד" באופן מצמצם, כך שהסעיף חל רק כאשר שיטת המשפט במקום הימצאם של הנכסים קובעת באופן מפורש ובלעדי כי היא תחול על ירושתם, תוך שלילת אפשרות תחולתן של שיטות משפט אחרות. מטרת החריג היא להבטיח את האפקטיביות של הדין הזר המוחל על ידי בתי המשפט בישראל, במקרים בהם הדין המקומי גובר על דין המושב. סעיף 138 לחוק הירושה, תשכ"ה-1965. ע"א 598/85 מסתורה כהנא נ'' מאיר כהנא, מד(3) 473 (14.08.1990). תמ"ש (משפחה ירושלים) 25065-11-24 פלונית נ'' פלוני (29.04.2025). שמואל שילה פירוש לחוק הירושה כרך ב (1995) | סעיף 138: דין נכסים מסויימים', 'הטעות הנפוצה היא לפרש את סעיף 138 באופן רחב, כאילו הוא חל על כל נכס מקרקעין זר, מבלי להבין את הדרישה לבלעדיות מפורשת של הדין המקומי.',
      '["סעיף 138 לחוק הירושה", "ברירת דין", "דין מקום הימצאם", "lex situs", "פרשנות מצמצמת", "אפקטיביות"]'::jsonb, '**וריאציה 1 — פרשנות "בלבד":** כיצד מפורשת המילה "בלבד" בסעיףרק כאשר ה-lex situs שולל במפורש תחולת כל דין אחר (ע"א 598/85 מסתורה כהנא נ'' מאיר כהנא).
**וריאציה 2 — מטרת החריג:** מהי מטרת סעיףלהבטיח אפקטיביות של הדין הזר המוחל על ידי בתי המשפט בישראל (ע"א 598/85 מסתורה כהנא נ'' מאיר כהנא).
**וריאציה 3 — סוגי נכסים:** האם סעיף 138 חל רק על מקרקעיןלא, הוא חל על נכסים (בין מקרקעין ובין מיטלטלין) העונים לדרישותיו (תמ"ש (משפחה ירושלים) 25065-11-24 פלונית נ'' פלוני).', 'סעיףחריג לדין המושבחל רק אם ה-lex situs קובע בלעדיות מפורשתמטרתו אפקטיביות.', '["חוק הירושה, תשכ\"ה-1965, סעיף 138", "ע\"א 598/85 מסתורה כהנא נ'' מאיר כהנא, מד(3) 473 (14.08.1990)", "תמ\"ש (משפחה ירושלים) 25065-11-24 פלונית נ'' פלוני (29.04.2025)", "שמואל שילה פירוש לחוק הירושה כרך ב (1995) | סעיף 138: דין נכסים מסויימים"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כל נכס מקרקעין המצוי במדינה זרה.', false, 'תשובה זו שגויה. סעיף 138 אינו חל אוטומטית על כל מקרקעין זרים, אלא רק אם הדין המקומי קובע במפורש שהוא בלבד חל על ירושתם.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'נכסים (מקרקעין או מיטלטלין) אשר שיטת המשפט במקום הימצאם קובעת כי היא בלבד תחול על ירושתם, תוך שלילת אפשרות תחולתן של שיטות משפט אחרות.', true, 'זו התשובה הנכונה. הפסיקה והמלומדים מפרשים את סעיף 138 באופן מצמצם, כך שהוא חל רק על נכסים שלגביהם הדין המקומי (lex situs) קובע באופן מפורש ובלעדי שהוא חל על ירושתם.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נכסים שהמוריש ציין בצוואתו כי יחול עליהם דין מקום הימצאם.', false, 'תשובה זו שגויה. סעיף 138 הוא כלל ברירת דין קוגנטי, ואינו תלוי ברצון המוריש בצוואתו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'נכסים שהדין הישראלי קובע כי הם עוברים בירושה לפי דין מקום הימצאם.', false, 'תשובה זו שגויה. סעיף 138 מתייחס למקרים בהם הדין הזר (lex situs) הוא זה שקובע את הבלעדיות, ולא הדין הישראלי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q09';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'פורום לא נאות בירושה', 4,
      'בית המשפט בישראל קבע כי יש לו סמכות בינלאומית לדון בירושתו של מוריש תושב חוץ שהותיר נכסים בישראל. באילו נסיבות עשוי בית המשפט לדחות את הדיון בטענת פורום בלתי נאות?', 'שאלה זו עוסקת בדוקטרינת הפורום הבלתי נאות (forum non conveniens) בהקשר של דיני ירושה בינלאומיים. היא מדגישה כי גם כאשר לבית המשפט בישראל קיימת סמכות בינלאומית לדון בעניין, הוא אינו חייב לעשות זאת, ורשאי לדחות את הדיון אם מאזן הנוחות והצדק מצביע על פורום זר כמתאים יותר, תוך שקילת מכלול הזיקות הרלוונטיות.', 'דוקטרינת הפורום הבלתי נאות מאפשרת לבית המשפט לדחות תביעה שהוגשה בפניו, גם אם קיימת לו סמכות בינלאומית, אם הוא משוכנע כי קיים פורום אחר, זר, שהוא מתאים יותר לדון בעניין. הפסיקה קבעה כי יש להבחין בין שלב הקניית הסמכות הבינלאומית (לפי סעיף 136 לחוק הירושה) לבין שלב הפעלת הסמכות, הנתון לשיקול דעת בית המשפט. בבחינת טענת פורום בלתי נאות, בית המשפט שוקל מכלול שיקולים, הכוללים את זיקות הצדדים, מיקום הנכסים, מקום מושבם של היורשים, הדין המהותי שיחול, נוחות ניהול ההליך, מיקום הראיות והעדים, ועקרון הכיבוד ההדדי של ריבונות זרה. הנטל להוכיח שהפורום הישראלי אינו נאות מוטל על הטוען זאת. ע"מ (מחוזי תל אביב-יפו) 1069/08 ר. צ'' נ'' ו.י. צ''. א (04.11.2009). ת"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז"ל נ'' ר. צ'' (29.01.2008). תמ"ש (משפחה תל אביב-יפו) 42807-11-13 מ. מ נ'' עז'' המנוחה י.מ (22.06.2015). בע"מ 9914/09 פלונית נ'' פלונית (19.01.2010)', 'הטעות הנפוצה היא לערבב בין סמכות בינלאומית לבין פורום נאות, ולחשוב שקיומה של סמכות בינלאומית מחייבת את בית המשפט לדון בעניין בכל מקרה.',
      '["פורום בלתי נאות", "סמכות בינלאומית", "שיקול דעת שיפוטי", "מאזן נוחות וצדק", "זיקות", "כיבוד ריבונות זרה"]'::jsonb, '**וריאציה 1 — הבחנה בין סמכות להפעלה:** האם קיימת הבחנה בין הקניית סמכות להפעלתהכן, בית המשפט רשאי להפעיל שיקול דעת בשלב הפעלת הסמכות (תמ"ש (משפחה תל אביב-יפו) 42807-11-13 מ. מ נ'' עז'' המנוחה י.מ).
**וריאציה 2 — שיקולים לדחייה:** אילו שיקולים נבחנים בטענת פורום בלתי נאותזיקות הצדדים, מיקום הנכסים, הדין החל, נוחות ניהול ההליך, ואפקטיביות פסק הדין (ת"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז"ל נ'' ר. צ'').
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח פורום בלתי נאותעל הטוען זאת, ועליו להוכיח שהמאזן נוטה בבירור לפורום זר (בע"מ 9914/09 פלונית נ'' פלונית).', 'פורום בלתי נאותדחיית דיון למרות סמכותנבחן מאזן נוחות וצדקנטל הוכחה על הטוען.', '["חוק הירושה, תשכ\"ה-1965, סעיף 136", "ת\"ע (משפחה תל אביב-יפו) 109310/06 עזבון המנוח א. ז. צ''. ז\"ל נ'' ר. צ'' (29.01.2008)", "ע\"מ (מחוזי תל אביב-יפו) 1069/08 ר. צ'' נ'' ו.י. צ''. א (04.11.2009)", "תמ\"ש (משפחה תל אביב-יפו) 42807-11-13 מ. מ נ'' עז'' המנוחה י.מ (22.06.2015)", "בע\"מ 9914/09 פלונית נ'' פלונית (19.01.2010)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק אם כלל נכסי העיזבון מחוץ לישראל, למעט נכס זניח אחד.', false, 'תשובה זו שגויה. אף שזהו שיקול, דחיית הדיון בטענת פורום בלתי נאות אינה מוגבלת רק למקרים של נכס זניח, אלא נבחנת לפי מכלול הזיקות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'אם מאזן הנוחות והצדק מצביע בבירור על פורום זר כמתאים יותר לדיון, תוך התחשבות בזיקות הצדדים, מיקום הנכסים, הדין החל ואפקטיביות פסק הדין.', true, 'זו התשובה הנכונה. דוקטרינת הפורום הבלתי נאות מאפשרת לבית המשפט לדחות דיון גם אם יש לו סמכות, אם מאזן הנוחות והצדק מצביע על פורום זר כמתאים יותר, תוך שקילת מכלול הזיקות הרלוונטיות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק אם הדין הזר החל על הירושה אינו מכיר בפסקי דין ישראליים.', false, 'תשובה זו שגויה. עקרון האפקטיביות אינו חזות הכל, ובית המשפט עשוי לדון גם אם אין ערובה לאכיפה בחו"ל.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט אינו רשאי לדחות דיון בטענת פורום בלתי נאות כאשר יש לו סמכות בינלאומית מפורשת לפי חוק הירושה.', false, 'תשובה זו שגויה. הפסיקה קבעה כי יש להבחין בין שלב הקניית הסמכות לשלב הפעלתה, וכי בית המשפט רשאי להפעיל שיקול דעת ולדחות דיון בטענת פורום בלתי נאות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q09';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 9, '2024-W-S-Q09';
END
$$;

-- ============================================================
-- Q10 — angles backfill for 2024-W-S-Q10 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q10';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q10';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'ניסיון בלתי צליח: טעות עובדתית מול משפטית', 1,
      'אדם ניסה לגנוב ארנק מכיסו של אדם אחר, אך הכיס היה ריק. אדם אחר ניסה להבריח גבינה צהובה מחו"ל, מתוך אמונה מוטעית שהיא חייבת במכס, אך בפועל לא חלה עליה חובת מכס. באילו מהמקרים ניתן להרשיע בניסיון?', 'שאלה זו ממחישה את ההבחנה המרכזית בדיני הניסיון הבלתי צליח בין טעות עובדתית לטעות משפטית. היא מדגישה כי ניסיון בלתי צליח עובדתית (כמו גניבה מכיס ריק) הוא בר-עונשין, בעוד שניסיון בלתי צליח משפטית (כמו הברחת מוצר שאינו אסור) אינו בר-עונשין, בהתאם לעקרון החוקיות.', 'סעיף 26 לחוק העונשין קובע כי ניסיון בלתי צליח הוא בר-עונשין אם אי-האפשרות להשלים את העבירה נבעה מ''מצב דברים שהמנסה לא היה מודע לו או טעה לגביו''. הפסיקה הבחינה בין ניסיון בלתי צליח מבחינה עובדתית לבין ניסיון בלתי צליח מבחינה משפטית. ניסיון בלתי צליח מבחינה עובדתית מתרחש כאשר העבירה לא הושלמה עקב מצב עובדתי שהמנסה לא ידע עליו (למשל, הכיס ריק). ניסיון כזה הוא בר-עונשין. לעומת זאת, ניסיון בלתי צליח מבחינה משפטית מתרחש כאשר המעשה, גם אם היה מושלם כפי שהמנסה דמיין, לא היה מהווה עבירה פלילית (למשל, הברחת מוצר שאינו אסור בדין). ניסיון כזה אינו בר-עונשין, שכן אין עבירה מושלמת שממנה ניתן לגזור את הניסיון. רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית (26.10.2017). תפ"ח (מחוזי ת"א) 1137/07 מדינת ישראל נ'' בן גיא אלדד (21.10.2009). יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון', 'הטעות הנפוצה היא לבלבל בין טעות עובדתית לטעות משפטית, ולחשוב שכל ניסיון בלתי צליח הוא בר-עונשין, ללא קשר לטיב הטעות.',
      '["ניסיון בלתי צליח", "טעות עובדתית", "טעות משפטית", "סעיף 26 לחוק העונשין", "עקרון החוקיות", "החזקת סם"]'::jsonb, '**וריאציה 1 — כיס ריק:** אדם מנסה לגנוב ארנק מכיס ריק. האם יורשע בניסיוןכן, זהו ניסיון בלתי צליח עובדתית, והוא בר-עונשין (ע"פ 675/85 ראובן בן חיים גרציאנו נ'' מדינת ישראל).
**וריאציה 2 — גבינה לא אסורה:** אדם מנסה להבריח גבינה צהובה שאינה חייבת במכס. האם יורשע בניסיוןלא, זהו ניסיון בלתי צליח משפטית, ואינו בר-עונשין (רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית).
**וריאציה 3 — הבחנה מהותית:** מה ההבדל המהותי בין המקריםטעות עובדתית נוגעת למצב הדברים הפיזי, בעוד שטעות משפטית נוגעת להיקף האיסור הפלילי (רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית).', 'ניסיון בלתי צליח עובדתית (כיס ריקבר-עונשין. ניסיון בלתי צליח משפטית (גבינה לא אסורהאינו בר-עונשין.', '["חוק העונשין, תשל\"ז-1977, סעיף 26", "רע\"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית (26.10.2017)", "תפ\"ח (מחוזי ת\"א) 1137/07 מדינת ישראל נ'' בן גיא אלדד (21.10.2009)", "ע\"פ 675/85 ראובן בן חיים גרציאנו נ'' מדינת ישראל, מ(3) 763 (03.09.1986)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בשני המקרים ניתן להרשיע בניסיון.', false, 'תשובה זו שגויה. ניסיון להברחת גבינה צהובה שאינה חייבת במכס אינו בר-עונשין, שכן מדובר בניסיון בלתי צליח מבחינה משפטית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'רק במקרה של ניסיון גניבת הארנק ניתן להרשיע בניסיון.', true, 'זו התשובה הנכונה. ניסיון גניבת ארנק מכיס ריק הוא ניסיון בלתי צליח מבחינה עובדתית (העבירה הייתה מתבצעת אם הכיס לא היה ריק), ולכן הוא בר-עונשין. ניסיון להברחת גבינה צהובה שאינה חייבת במכס הוא ניסיון בלתי צליח מבחינה משפטית, ואינו בר-עונשין.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק במקרה של ניסיון הברחת הגבינה הצהובה ניתן להרשיע בניסיון.', false, 'תשובה זו שגויה. ניסיון להברחת גבינה צהובה שאינה חייבת במכס אינו בר-עונשין, שכן מדובר בניסיון בלתי צליח מבחינה משפטית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'באף אחד מהמקרים לא ניתן להרשיע בניסיון.', false, 'תשובה זו שגויה. ניסיון גניבת ארנק מכיס ריק הוא ניסיון בלתי צליח מבחינה עובדתית, ולכן הוא בר-עונשין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q10';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחני ההבחנה בניסיון בלתי צליח', 2,
      'מהו המבחן המרכזי שנקבע בפסיקה להבחנה בין ניסיון בלתי צליח מבחינה עובדתית לניסיון בלתי צליח מבחינה משפטית?', 'שאלה זו מתמקדת במבחן המרכזי שנקבע בפסיקה להבחנה בין ניסיון בלתי צליח עובדתית לניסיון בלתי צליח משפטית. היא מדגישה את חשיבות בחינת המסכת העובדתית כפי שהמנסה האמין בה, ואת ההשלכות המשפטיות השונות של כל סוג טעות על האחריות הפלילית.', 'הנשיאה נאור ברע"פ 2220/16 קבעה מבחן ברור להבחנה בין ניסיון בלתי צליח עובדתית למשפטית. המבחן הוא לבודד את הגורמים שמהם נובעת אי-האפשרות להשלים את העבירה. לשם כך, יש לבחון את התנהגותו של המנסה ואת הלך רוחו לפי המסכת העובדתית שבקיומה הוא האמין. אם מצב הדברים העובדתי כפי שהמנסה האמין בו היה מגבש עבירה, ניתן להרשיעו בניסיון בלתי צליח עובדתית. לעומת זאת, אם העובדות שדימה המנסה אינן מגבשות עבירה, אך המנסה טעה לחשוב כי הוא מבצע מעשה אסור, מדובר בניסיון בלתי צליח מבחינה משפטית שאינו בר-עונשין. רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית (26.10.2017). ע"פ 675/85 ראובן בן חיים גרציאנו נ'' מדינת ישראל (03.09.1986). יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון', 'הטעות הנפוצה היא להתמקד במצב האובייקטיבי של הדברים במקום באמונתו הסובייקטיבית של המנסה, שהיא המפתח להבחנה בין סוגי הניסיון הבלתי צליח.',
      '["ניסיון בלתי צליח", "מבחן סובייקטיבי", "מסכת עובדתית", "טעות עובדתית", "טעות משפטית", "סעיף 26 לחוק העונשין"]'::jsonb, '**וריאציה 1 — אמונת המנסה:** מהו המבחן המרכזי להבחנהבחינת המסכת העובדתית שבקיומה האמין המנסה (רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית).
**וריאציה 2 — עבירה קיימת:** מתי ניסיון בלתי צליח הוא ענישאם העובדות שדימה המנסה היו מגבשות עבירה פלילית במציאות (רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית).
**וריאציה 3 — עקרון החוקיות:** מדוע ניסיון בלתי צליח משפטית אינו ענישבשל עקרון החוקיות, המחייב קיום איסור פלילי אובייקטיבי (רע"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית).', 'מבחן ההבחנה בניסיון בלתי צליחבחינת המסכת העובדתית שאותה דימה המנסהאם הייתה מגבשת עבירה: עובדתית (ענישאם לא: משפטית (לא עניש).', '["חוק העונשין, תשל\"ז-1977, סעיף 26", "רע\"פ 2220/16 רועי מור יוסף נ'' התביעה הצבאית הראשית (26.10.2017)", "ע\"פ 675/85 ראובן בן חיים גרציאנו נ'' מדינת ישראל, מ(3) 763 (03.09.1986)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'האם המנסה היה מודע לכך שהמעשה אינו יכול להתבצע בפועל.', false, 'תשובה זו שגויה. אם המנסה היה מודע לכך שהמעשה אינו יכול להתבצע, לא היה מתגבש ניסיון כלל. המבחן מתייחס למצב שבו המנסה לא היה מודע או טעה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'האם העבירה המושלמת הייתה אפשרית מבחינה אובייקטיבית, ללא קשר לאמונת המנסה.', false, 'תשובה זו שגויה. המבחן מתמקד באמונת המנסה ובמסכת העובדתית כפי שדמיין אותה, ולא במצב האובייקטיבי בלבד.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'יש לבחון את המסכת העובדתית שבקיומה האמין המנסה; אם מצב הדברים העובדתי כפי שהמנסה האמין בו היה מגבש עבירה, מדובר בניסיון בלתי צליח עובדתית. אם העובדות שדימה המנסה אינן מגבשות עבירה, מדובר בניסיון בלתי צליח משפטית.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי יש לבחון את העובדות מבעד לעיניו של המנסה, ולבדוק אם הן מגבשות מעבר לספק סביר את יסודות העבירה. אם כן, מדובר בניסיון בלתי צליח עובדתית. אם לא, מדובר בניסיון בלתי צליח משפטית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'האם המנסה התחרט על מעשיו לפני השלמת העבירה.', false, 'תשובה זו שגויה. חרטה היא עילה לפטור מאחריות פלילית לפי סעיף 28 לחוק העונשין, אך אינה המבחן להבחנה בין סוגי הניסיון הבלתי צליח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q10';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'ניסיון בלתי צליח באמצעים אבסורדיים', 3,
      'אדם ניסה להרוג את שכנו באמצעות הטלת כישוף, מתוך אמונה כנה ביעילותו. האם ניתן להרשיעו בניסיון לרצח?', 'שאלה זו עוסקת בחריג לכלל הניסיון הבלתי צליח העניש – ניסיון באמצעות אמצעים אבסורדיים. היא בוחנת את הרציונל העומד מאחורי אי-הפללת מקרים אלו, המבוסס על היעדר סכנה ממשית לציבור ועל תפיסה שהמנסה אינו בעל פוטנציאל עברייני במובן הרגיל.', 'הפסיקה והספרות (למשל, עניין גרציאנו, רבין וואקי) הבחינו בין סוגים שונים של ניסיון בלתי צליח. אחד החריגים לכלל הניסיון הבלתי צליח העניש הוא שימוש באמצעים אבסורדיים (כגון כישוף). במקרים אלו, גם אם המנסה האמין ביעילות האמצעים, אין נשקפת סכנה ממשית לציבור, והמעשה אינו מעיד על פוטנציאל עברייני במובן המקובל. לכן, ניסיון כזה אינו בר-עונשין. הרציונל הוא שאדם כזה ראוי אולי להתייחסות במישורים אחרים, אך לא לטיפול פלילי. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חוסר אפשרות לעשיית העבירה', 'הטעות הנפוצה היא להסיק מכוונתו הפלילית של המנסה כי כל ניסיון, גם באמצעים אבסורדיים, הוא בר-עונשין, מבלי להכיר בחריג זה.',
      '["ניסיון בלתי צליח", "אמצעים אבסורדיים", "אי-ענישות", "סכנה לציבור", "פוטנציאל עברייני", "עקרון החוקיות"]'::jsonb, '**וריאציה 1 — הגדרת אמצעים אבסורדיים:** מהם אמצעים אבסורדייםאמצעים שבהתאם לתפיסה המקובלת בחברה, נעדרים יכולת להגשים את העבירה (כגון כישוף) (יורם רבין, יניב ואקי דיני עונשין - כרך א).
**וריאציה 2 — ענישות:** האם ניסיון באמצעים אבסורדיים ענישלא, הגישה הרווחת היא שאינו עניש (יורם רבין, יניב ואקי דיני עונשין - כרך א).
**וריאציה 3 — רציונל:** מהו הרציונל לאי-ענישותאין נשקפת סכנה ממשית לציבור ממעשים אלה, והעושה אינו בעל פוטנציאל עברייני במובן הרגיל (יורם רבין, יניב ואקי דיני עונשין - כרך א).', 'ניסיון באמצעים אבסורדיים (כישוףאינו ענישאין סכנה לציבורמשקף תפיסת מציאות מעוותת.', '["ע\"פ 675/85 ראובן בן חיים גרציאנו נ'' מדינת ישראל, מ(3) 763 (03.09.1986)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 17 - עבירת הניסיון", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חוסר אפשרות לעשיית העבירה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, שכן המנסה גיבש כוונה פלילית והחל בביצועה, וזהו ניסיון בלתי צליח עובדתית.', false, 'תשובה זו שגויה. אף שקיימת כוונה, שימוש באמצעים אבסורדיים נחשב לחריג לכלל הניסיון הבלתי צליח העניש.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן שימוש באמצעים אבסורדיים אינו נחשב לניסיון בר-עונשין, גם אם המנסה האמין ביעילותם.', true, 'זו התשובה הנכונה. הפסיקה והספרות קבעו כי ניסיון באמצעות אמצעים אבסורדיים אינו עניש, שכן אין נשקפת ממנו סכנה לציבור, והוא משקף תפיסת מציאות מעוותת ולא פוטנציאל עברייני ממשי.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הוכח שהמנסה היה מסוכן לציבור ועלול היה לנסות שוב באמצעים יעילים יותר.', false, 'תשובה זו שגויה. המבחן אינו תלוי בהוכחת מסוכנות עתידית, אלא בטיב האמצעים שבהם נעשה שימוש.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הוכח שהמנסה סבל ממחלת נפש, שאז יחול סייג אי-שפיות הדעת.', false, 'תשובה זו שגויה. אף שאי-שפיות הדעת היא סייג לאחריות פלילית, אי-ענישות ניסיון באמצעים אבסורדיים נובעת מטיב הניסיון עצמו, ולא ממצב נפשי ספציפי של המנסה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q10';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'טעות במצב דברים מול טעות במצב משפטי', 4,
      'מהו ההבדל המהותי בין טעות במצב דברים (סעיף 34יח לחוק העונשין) לבין טעות במצב משפטי (סעיף 34יט לחוק העונשין) בהקשר של אחריות פלילית?', 'שאלה זו בוחנת את ההבחנה הקריטית בין טעות במצב דברים לטעות במצב משפטי בדיני העונשין, כפי שהיא מעוגנת בסעיפים 34יח ו-34יט לחוק העונשין. היא מדגישה את ההשלכות השונות של כל סוג טעות על האחריות הפלילית, ואת הרציונלים העומדים בבסיס ההבחנה.', 'סעיף 34יח לחוק העונשין עוסק בטעות במצב דברים (טעות עובדתית). הוא קובע כי מי שעשה מעשה בדמותו מצב דברים שאינו קיים, לא יישא באחריות פלילית אלא במידה שהיה נושא בה אילו היה המצב לאמיתו כפי שדימה אותו. טעות כנה במצב דברים שוללת את היסוד הנפשי הנדרש לעבירה, ולכן פוטרת מאחריות פלילית (ובעבירות רשלנות נדרשת גם סבירות הטעות). לעומת זאת, סעיף 34יט לחוק העונשין עוסק בטעות במצב משפטי (טעות בדין). הוא קובע כי לעניין האחריות הפלילית אין נפקא מינה אם האדם דימה שמעשהו אינו אסור, עקב טעות בדבר קיומו של איסור פלילי או בדבר הבנתו את האיסור, זולת אם הטעות הייתה בלתי נמנעת באורח סביר. כלומר, ככלל, טעות בדין אינה פוטרת מאחריות פלילית, למעט חריג צר של טעות בלתי נמנעת באורח סביר. סעיף 34יח לחוק העונשין, תשל"ז-1977. סעיף 34יט לחוק העונשין, תשל"ז-1977. יורם רבין, יניב ואקי דיני עונשין - כרך ב (2014) | פרק 30 טעות במצב משפטי. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | טעות במצב דברים', 'הטעות הנפוצה היא לבלבל בין שני סוגי הטעויות ולייחס להן את אותן השלכות משפטיות, מבלי להבחין בין טעות עובדתית השוללת יסוד נפשי לבין טעות משפטית שאינה פוטרת ככלל.',
      '["טעות במצב דברים", "טעות במצב משפטי", "סעיף 34יח", "סעיף 34יט", "אחריות פלילית", "יסוד נפשי", "טעות בלתי נמנעת"]'::jsonb, '**וריאציה 1 — טעות עובדתית:** אדם יורה בבובה מתוך אמונה שזה אדם. האם יישא באחריות לרצחלא, טעות במצב דברים שוללת את היסוד הנפשי לרצח (נבו - המתמחה דיני עונשין ודרכי ענישה).
**וריאציה 2 — טעות משפטית:** אדם שותה אלכוהול מתוך אמונה מוטעית שזה אסור בחוק. האם יישא באחריות פליליתלא, טעות במצב משפטי ככלל אינה פוטרת, אך כאן אין עבירה כלל (נבו - המתמחה דיני עונשין ודרכי ענישה).
**וריאציה 3 — תנאי לפטור:** מהו התנאי לפטור בטעות במצב משפטישהטעות הייתה בלתי נמנעת באורח סביר (סעיף 34יט לחוק העונשין).', 'טעות במצב דברים (34יחפוטרת אם כנה (שוללת יסוד נפשי). טעות במצב משפטי (34יטככלל אינה פוטרתלמעט טעות בלתי נמנעת באורח סביר.', '["חוק העונשין, תשל\"ז-1977, סעיף 34יח", "חוק העונשין, תשל\"ז-1977, סעיף 34יט", "יורם רבין, יניב ואקי דיני עונשין - כרך ב (2014) | פרק 30 טעות במצב משפטי", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | טעות במצב דברים"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'טעות במצב דברים אינה פוטרת מאחריות פלילית, בעוד שטעות במצב משפטי פוטרת תמיד.', false, 'תשובה זו שגויה. ההפך הוא הנכון: טעות במצב דברים יכולה לפטור, בעוד שטעות במצב משפטי ככלל אינה פוטרת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'טעות במצב דברים פוטרת מאחריות פלילית אם הטעות כנה (ובעבירות רשלנות גם סבירה), שכן היא שוללת את היסוד הנפשי. טעות במצב משפטי אינה פוטרת ככלל, אלא אם הייתה בלתי נמנעת באורח סביר.', true, 'זו התשובה הנכונה. סעיף 34יח עוסק בטעות עובדתית המשפיעה על היסוד הנפשי, וסעיף 34יט עוסק בטעות לגבי הדין, שלגביה נקבע חריג מצומצם לפטור.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שני הסעיפים עוסקים בטעות לגבי הדין, אך סעיף 34יח חל על עבירות קלות וסעיף 34יט על עבירות חמורות.', false, 'תשובה זו שגויה. סעיף 34יח עוסק בטעות עובדתית, ואין הבחנה בין עבירות קלות לחמורות בהקשר זה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'שני הסעיפים זהים במהותם ומהווים הגנה מפני אחריות פלילית באותם תנאים.', false, 'תשובה זו שגויה. קיים הבדל מהותי בין שני הסעיפים, הן בטיב הטעות והן בתנאים לפטור מאחריות פלילית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q10';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 10, '2024-W-S-Q10';
END
$$;

-- ============================================================
-- Q11 — angles backfill for 2024-W-S-Q11 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q11';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q11';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'פטור ממס שבח ליורש - תנאים מצטברים', 1,
      'משה, בן יחיד להוריו, ירש על פי צוואתם דירת מגורים. הוא מעוניין למכור אותה בפטור ממס שבח. אילו תנאים מצטברים עליו לקיים כדי לזכות בפטור לפי סעיף 49ב(5) לחוק מיסוי מקרקעין?', 'שאלה זו מתמקדת בתנאים המצטברים הספציפיים הנדרשים ליורש המבקש פטור ממס שבח במכירת דירה שהתקבלה בירושה, כפי שקבועים בסעיף 49ב(5) לחוק מיסוי מקרקעין. היא מדגישה את הדרישות הנוגעות לקרבה משפחתית, מצבת הדירות של המוריש, וזכאותו הפוטנציאלית לפטור אילו היה בחיים.', 'סעיף 49ב(5) לחוק מיסוי מקרקעין (שבח ורכישה) קובע שלושה תנאים מצטברים שרק בהתקיימם יהיה מוכר דירת מגורים מזכה שקיבל אותה בירושה זכאי לפטור ממס שבח. התנאים הם: (א) המוכר הוא בן זוגו של המוריש, או צאצא של המוריש, או בן זוגו של צאצא של המוריש; (ב) לפני פטירתו היה המוריש בעלה של דירת מגורים אחת בלבד; (ג) אילו היה המוריש עדיין בחיים ומוכר את דירת המגורים, היה פטור ממס בשל המכירה. במקרה הנדון, משה הוא צאצא של הוריו, ולכן התנאי הראשון מתקיים. יש לבחון גם את שני התנאים הנוספים. סעיף 49ב(5) לחוק מיסוי מקרקעין (שבח ורכישה), תשכ"ג-1963. ו"ע (מחוזי נצרת) 20627-03-24 בלה כהן נ'' מיסוי מקרקעין נצרת (09.04.2025). נבו - המתמחה מיסוי מקרקעין (2026) | פטור במכירת דירה שנתקבלה בירושה', 'הטעות הנפוצה היא להתמקד רק באחד מהתנאים או לבלבל בין תנאי הפטור ליורש (סעיף 49ב(5)) לבין תנאי פטורים אחרים בחוק.',
      '["מס שבח מקרקעין", "פטור ליורש", "סעיף 49ב(5)", "תנאים מצטברים", "דירת מגורים יחידה", "קרבה משפחתית"]'::jsonb, '**וריאציה 1 — תנאי הקרבה:** האם משה, כבן יחיד, עומד בתנאי הקרבה המשפחתיתכן, הוא צאצא של המוריש (סעיף 49ב(5)(א) לחוק מיסוי מקרקעין).
**וריאציה 2 — דירה יחידה למוריש:** האם המוריש חייב להיות בעל דירה יחידהכן, לפני פטירתו היה המוריש בעלה של דירת מגורים אחת בלבד (סעיף 49ב(5)(ב) לחוק מיסוי מקרקעין).
**וריאציה 3 — זכאות המוריש:** האם זכאות המוריש לפטור רלוונטיתכן, אילו היה המוריש עדיין בחיים ומוכר את הדירה, היה פטור ממס בשל המכירה (סעיף 49ב(5)(ג) לחוק מיסוי מקרקעין).', 'פטור ליורש (49בתנאים מצטברים: קרבה משפחתית, דירה יחידה למוריש, זכאות המוריש לפטור בחייו.', '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49ב(5)", "ו\"ע (מחוזי נצרת) 20627-03-24 בלה כהן נ'' מיסוי מקרקעין נצרת (09.04.2025)", "נבו - המתמחה מיסוי מקרקעין (2026) | פטור במכירת דירה שנתקבלה בירושה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'משה הוא צאצא של המוריש, לפני פטירת המוריש הייתה זו דירתו היחידה, ואילו המוריש היה מוכר את הדירה בחייו היה פטור ממס.', true, 'זו התשובה הנכונה. סעיף 49ב(5) לחוק מיסוי מקרקעין קובע שלושה תנאים מצטברים לפטור ממס שבח במכירת דירה שהתקבלה בירושה: קרבה משפחתית, בעלות יחידה של המוריש לפני פטירתו, וזכאות המוריש לפטור אילו היה מוכר בחייו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'משה הוא צאצא של המוריש, הדירה היא דירתו היחידה של משה, ומשה לא מכר דירה אחרת בפטור ב-18 החודשים האחרונים.', false, 'תשובה זו שגויה. תנאים אלו מתייחסים לפטור לפי סעיף 49ב(2) לחוק (פטור לדירה יחידה), ולא לפטור הספציפי ליורש לפי סעיף 49ב(5).', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'משה הוא צאצא של המוריש, הדירה שימשה למגורים לפחות 4/5 מהתקופה שבשלה מחושב השבח, והמוריש לא מכר דירה אחרת בפטור ב-4 השנים האחרונות.', false, 'תשובה זו שגויה. תנאי השימוש למגורים מתייחס להגדרת ''דירת מגורים מזכה'', ותנאי אי-מכירת דירה אחרת בפטור מתייחס לפטור שבוטל (סעיף 49ב(1) הישן).', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'משה הוא צאצא של המוריש, הדירה נרכשה כתחליף לדירה אחרת, וסכום השווי של הדירה לא עלה על תקרת הפטור.', false, 'תשובה זו שגויה. תנאים אלו מתייחסים לפטורים אחרים בחוק, כגון חזקת דירה יחידה (סעיף 49ג) או פטור חד-פעמי (סעיף 49ה), ואינם רלוונטיים לפטור ליורש לפי סעיף 49ב(5).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q11';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הגדרת "דירת מגורים מזכה"', 2,
      'מהם המאפיינים העיקריים של "דירת מגורים מזכה" לצורך פטור ממס שבח, כפי שנקבעו בחוק ובפסיקה?', 'שאלה זו בוחנת את ההגדרות המרכזיות בחוק מיסוי מקרקעין, "דירת מגורים" ו"דירת מגורים מזכה", שהן תנאי סף לקבלת פטור ממס שבח. היא מדגישה את המאפיינים הפיזיים, הקנייניים והתכליתיים של הנכס, ואת המועד הקובע לבחינתם.', 'הגדרת "דירת מגורים" בסעיף 1 לחוק מיסוי מקרקעין קובעת כי זו "דירה או חלק מדירה, שבנייתה נסתיימה והיא בבעלותו או בחכירתו של יחיד, ומשמשת למגורים או מיועדת למגורים לפי טיבה, למעט דירה המהווה מלאי עסקי לעניין מס הכנסה". הגדרת "דירת מגורים מזכה" בסעיף 49(א) לחוק מוסיפה כי זו "דירת מגורים ששימשה בעיקרה למגורים לפחות באחת משתי התקופות שלהלן: (1) ארבע חמישיות מהתקופה שבשלה מחושב השבח; (2) ארבע השנים שקדמו למכירתה". הפסיקה הדגישה כי המועד הקובע לבחינת התקיימותם של כל היסודות הללו הוא מועד אירוע המס, קרי יום מכירת הזכות במקרקעין. כמו כן, נקבע כי כאשר מבנה נהרס כליל, הוא אינו עומד עוד בתנאי הסף של דירה ש"בנייתה נסתיימה" ואינו יכול לשמש למגורים מבחינה אובייקטיבית. סעיף 49(א) לחוק מיסוי מקרקעין (שבח ורכישה), תשכ"ג-1963. ו"ע (מינהליים י-ם) 28295-10-20 אריאל יוסף סבג נ'' מנהל מיסוי מקרקעין ירושלים (26.03.2026). ו"ע (מינהליים י-ם) 23653-07-22 ויקטור אסולין נ'' מנהל מיסוי מקרקעין ירושלים (01.07.2025). אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה - כרך א (2017) | פרק חמישי: סכום המס', 'הטעות הנפוצה היא לבלבל בין הגדרת ''דירה'' ל''דירת מגורים מזכה'', או להתעלם מהדרישה ש''בנייתה נסתיימה'' או מתנאי השימוש העיקרי למגורים.',
      '["דירת מגורים", "דירת מגורים מזכה", "סעיף 1 לחוק מיסוי מקרקעין", "סעיף 49(א) לחוק מיסוי מקרקעין", "בנייתה נסתיימה", "שימוש עיקרי למגורים"]'::jsonb, '**וריאציה 1 — תנאי סף:** מהו תנאי סף פיזי לדירת מגוריםשבנייתה הסתיימה (ו"ע (מינהליים י-ם) 28295-10-20 אריאל יוסף סבג נ'' מנהל מיסוי מקרקעין ירושלים).
**וריאציה 2 — בעלות ושימוש:** מי הבעלים ומה השימוש הנדרשבבעלות יחיד, ומשמשת למגורים או מיועדת למגורים לפי טיבה (ו"ע (מינהליים י-ם) 23653-07-22 ויקטור אסולין נ'' מנהל מיסוי מקרקעין ירושלים).
**וריאציה 3 — תנאי זיכוי:** מה הופך דירת מגורים ל"מזכהשימשה בעיקרה למגורים לפחות באחת משתי התקופות הקבועות בחוק (סעיף 49(א) לחוק מיסוי מקרקעין).', 'דירת מגורים מזכהבנייה שהסתיימה + בבעלות יחיד + שימוש/ייעוד למגורים + שימוש עיקרי למגורים בתקופות קבועות.', '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 1", "חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49(א)", "ו\"ע (מינהליים י-ם) 28295-10-20 אריאל יוסף סבג נ'' מנהל מיסוי מקרקעין ירושלים (26.03.2026)", "ו\"ע (מינהליים י-ם) 23653-07-22 ויקטור אסולין נ'' מנהל מיסוי מקרקעין ירושלים (01.07.2025)", "אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה - כרך א (2017) | פרק חמישי: סכום המס"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'דירה שבנייתה הסתיימה, בבעלות יחיד, ושימשה למגורים או מיועדת למגורים לפי טיבה, ושימשה בעיקרה למגורים באחת משתי התקופות הקבועות בחוק.', true, 'זו התשובה הנכונה. הגדרת ''דירת מגורים'' בסעיף 1 כוללת דירה שבנייתה הסתיימה, בבעלות יחיד, ומשמשת/מיועדת למגורים. הגדרת ''דירת מגורים מזכה'' בסעיף 49(א) מוסיפה את תנאי השימוש העיקרי למגורים באחת משתי התקופות הקבועות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'דירה שבנייתה הסתיימה, בבעלות יחיד, ושימשה למגורים בפועל ביום המכירה, ללא קשר לייעודה המקורי.', false, 'תשובה זו שגויה. הדרישה היא לשימוש בפועל או ייעוד לפי טיבה, ולא רק שימוש בפועל ביום המכירה. כמו כן, יש תנאי נוסף של שימוש עיקרי למגורים בתקופות מסוימות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'דירה או חלק מדירה, גם אם בנייתה טרם הסתיימה, ובלבד שהיא מיועדת למגורים לפי תוכנית בניין עיר.', false, 'תשובה זו שגויה. תנאי הכרחי הוא ש''בנייתה נסתיימה''. נכס שנהרס או שטרם נבנה אינו נחשב ל''דירה'' לעניין זה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כל נכס מקרקעין המשמש למגורים, גם אם הוא בבעלות תאגיד, ובלבד שאינו מהווה מלאי עסקי.', false, 'תשובה זו שגויה. הדירה חייבת להיות בבעלות יחיד, ולא תאגיד, כדי להיחשב ''דירת מגורים'' לצורך הפטור.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q11';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חזקת "מוכר אחד" ופטורים', 3,
      'ראובן ושמעון נישאו זה לזה. לראובן הייתה דירה בבעלותו מלפני הנישואין, ולשמעון הייתה דירה בבעלותו מלפני הנישואין. הם ערכו הסכם ממון הקובע הפרדה רכושית מלאה. לאחר הנישואין, ראובן מכר את דירתו. האם הוא ייחשב כ"מוכר אחד" יחד עם שמעון לעניין הפטור ממס שבח?', 'שאלה זו בוחנת את חזקת "מוכר אחד" הקבועה בסעיף 49(ב) לחוק מיסוי מקרקעין, ואת פרשנותה בפסיקה, במיוחד במקרים של בני זוג עם הסכם ממון והפרדה רכושית. היא מדגישה את המתח בין תכלית החוק למנוע הערמה על המס לבין הצורך להגן על זכויותיהם של בני זוג המקפידים על הפרדה רכושית אמיתית.', 'סעיף 49(ב) לחוק מיסוי מקרקעין קובע כי "לעניין פרק זה יראו מוכר ובן זוגו, למעט בן זוג הגר דרך קבע בנפרד, וילדיהם שטרם מלאו להם 18 שנים למעט ילדים נשואים או ילדים יתומים מאחד או משני הוריהם - כמוכר אחד". חזקה זו נועדה למנוע פיצול מלאכותי של נכסים לצורך קבלת פטורים מרובים. עם זאת, הפסיקה, ובפרט ע"א 3489/99 עברי וע"א 3178/12 שלמי, קבעה כי במקרים בהם בני זוג הקפידו על הפרדה רכושית מלאה, ודירותיהם נרכשו לפני הנישואין, ניתן לראות כל אחד מהם כמוכר נפרד. זאת, כדי למנוע פגיעה לא מידתית בזכויותיהם וכדי להבטיח מתן פטור ממס שבח לכל יחידה כלכלית נפרדת. סעיף 49(ב) לחוק מיסוי מקרקעין (שבח ורכישה), תשכ"ג-1963. ע"א 3178/12 יגאל שלמי נ'' מנהל מיסוי מקרקעין נתניה (17.11.2014). ע"א 3489/99 מנהל מס שבח מקרקעין, חיפה נ'' אן מרי עברי (13.07.2003). ע"א 4298/18 מנהל מיסוי מקרקעין ת"א נ'' רועי בלנק (20.04.2021)', 'הטעות הנפוצה היא ליישם את חזקת "מוכר אחד" באופן גורף, מבלי להתחשב בנסיבות הספציפיות של הפרדה רכושית ומועד רכישת הדירות.',
      '["חזקת מוכר אחד", "סעיף 49(ב) לחוק מיסוי מקרקעין", "הסכם ממון", "הפרדה רכושית", "פטור ממס שבח", "תכלית החוק"]'::jsonb, '**וריאציה 1 — הסכם ממון:** האם הסכם ממון הקובע הפרדה רכושית משפיע על חזקת "מוכר אחדכן, הפסיקה הכירה בכך שניתן לראות כל אחד מבני הזוג כמוכר נפרד במקרים של הפרדה רכושית אמיתית (ע"א 3178/12 יגאל שלמי נ'' מנהל מיסוי מקרקעין נתניה).
**וריאציה 2 — דירה מלפני הנישואין:** האם דירה שנרכשה לפני הנישואין משנה את המצבכן, אין לייחס מכירות שבוצעו לפני הנישואין לבן הזוג האחר לאחר הנישואין (ע"א 4298/18 מנהל מיסוי מקרקעין ת"א נ'' רועי בלנק).
**וריאציה 3 — תכלית החזקה:** מהי תכלית חזקת "מוכר אחדלמנוע הערמה על חוק מס שבח ופיצול מלאכותי של נכסים לצורך קבלת פטורים מרובים (ע"א 3489/99 מנהל מס שבח מקרקעין, חיפה נ'' אן מרי עברי).', 'חזקת "מוכר אחד" (49(בניתנת לביטול בהסכם ממון והפרדה רכושית אמיתיתבמיוחד לדירות מלפני הנישואין.', '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49(ב)", "ע\"א 3178/12 יגאל שלמי נ'' מנהל מיסוי מקרקעין נתניה (17.11.2014)", "ע\"א 3489/99 מנהל מס שבח מקרקעין, חיפה נ'' אן מרי עברי (13.07.2003)", "ע\"א 4298/18 מנהל מיסוי מקרקעין ת\"א נ'' רועי בלנק (20.04.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, תמיד יראו בני זוג כ"מוכר אחד" לעניין פטור ממס שבח, ללא קשר להסכם ממון או למועד רכישת הדירה.', false, 'תשובה זו שגויה. אף שהכלל הוא לראות בני זוג כמוכר אחד, הפסיקה הכירה בחריגים במקרים של הפרדה רכושית אמיתית ודירות שנרכשו לפני הנישואין.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, במקרה של הסכם ממון הקובע הפרדה רכושית מלאה ודירות שנרכשו לפני הנישואין, יראו כל אחד מבני הזוג כ"מוכר" נפרד לעניין הפטור ממס שבח.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי במקרים בהם בני זוג הקפידו על הפרדה רכושית אמיתית, ודירותיהם נרכשו לפני הנישואין, ניתן לראות כל אחד מהם כמוכר נפרד, וזאת כדי למנוע פגיעה לא מידתית בזכויותיהם.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אלא אם כן חלפו ארבע שנים מיום הנישואין, שאז יראו אותם כמוכרים נפרדים.', false, 'תשובה זו שגויה. מגבלת ארבע השנים הייתה רלוונטית לפטור שבוטל (סעיף 49ב(1)) ואינה קשורה להבחנה בין בני זוג כמוכר אחד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הדירה נמכרה לצורך רכישת דירה חלופית, שאז יראו אותם כמוכרים נפרדים.', false, 'תשובה זו שגויה. תנאי רכישת דירה חלופית רלוונטי לפטורים אחרים (כגון סעיף 49ה) ואינו משפיע על חזקת ''מוכר אחד''.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q11';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'אחריות מנהל עיזבון למס שבח', 4,
      'מנהל עיזבון מונה למכור דירת מגורים שהייתה בבעלות המנוח. האם מנהל העיזבון הוא המוכר לעניין מס שבח, ומה אחריותו בנוגע לתשלום המס?', 'שאלה זו עוסקת במעמדו ובאחריותו של מנהל עיזבון בהקשר של מס שבח מקרקעין. היא מבהירה כי אף שמנהל העיזבון הוא הגורם המבצע את המכירה בפועל, המכירה מיוחסת ליורשים, ומנהל העיזבון נושא באחריות פרוצדורלית למילוי חובות המס בשמם.', 'סעיף 5(ג)(1) לחוק מיסוי מקרקעין (שבח ורכישה) קובע כי "מכירת זכות במקרקעין הנמנית עם נכסי עזבון... יראו אותן כמכירת הזכות... בידי היורשים, על אף האמור בסעיף 4". כלומר, המכירה מיוחסת ליורשים ולא למנהל העיזבון כמוכר עצמאי. עם זאת, סעיף 5(ג)(3) לחוק מטיל על מנהל העיזבון את האחריות למילוי החובות הקבועות בסעיפים 73, 76, 90א ו-91 לחוק, שהם חובות דיווח ותשלום מס. הפסיקה הדגישה כי הפטור ממס שבח הוא אישי ואינו "צמוד" לדירה, ולכן זכותו של מנהל עיזבון לבקש פטור תלויה בזכאותם של היורשים עצמם לפטור. סעיף 5(ג)(1) לחוק מיסוי מקרקעין (שבח ורכישה), תשכ"ג-1963. סעיף 5(ג)(3) לחוק מיסוי מקרקעין (שבח ורכישה), תשכ"ג-1963. רע"א 7816/06 עו"ד יעקב מ. בויאר - בתפקידו ככונס נכסים נ'' עז'' המנוח מר דוד מרמלשטיין ז"ל (01.10.2009). דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | פרק כ'': עיקול מקרקעין ומכירתם', 'הטעות הנפוצה היא לחשוב שמנהל העיזבון הוא המוכר לעניין מס שבח, או שקיימת פטור אוטומטי במכירת נכס עיזבון, מבלי להבחין בין זהות המוכר לאחריות הפרוצדורלית.',
      '["מנהל עיזבון", "מס שבח מקרקעין", "מכירת נכס עיזבון", "אחריות לדיווח ותשלום", "סעיף 5(ג) לחוק מיסוי מקרקעין", "פטור אישי"]'::jsonb, '**וריאציה 1 — זהות המוכר:** מי נחשב למוכר לעניין מס שבח במכירת נכס עיזבוןהיורשים, ולא מנהל העיזבון (סעיף 5(ג)(1) לחוק מיסוי מקרקעין).
**וריאציה 2 — אחריות מנהל העיזבון:** מהי אחריותו של מנהל העיזבוןלמילוי חובות הדיווח והתשלום בשם היורשים (סעיף 5(ג)(3) לחוק מיסוי מקרקעין).
**וריאציה 3 — זכאות לפטור:** האם מנהל העיזבון יכול לבקש פטורכן, אם היורשים עצמם זכאים לפטור, שכן הפטור הוא אישי (רע"א 7816/06 עו"ד יעקב מ. בויאר - בתפקידו ככונס נכסים נ'' עז'' המנוח מר דוד מרמלשטיין ז"ל).', 'מכירת נכס עיזבוןמיוחסת ליורשיםמנהל עיזבון אחראי למיסוי בשמםפטור תלוי בזכאות היורשים.', '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 5(ג)", "רע\"א 7816/06 עו\"ד יעקב מ. בויאר - בתפקידו ככונס נכסים נ'' עז'' המנוח מר דוד מרמלשטיין ז\"ל (01.10.2009)", "דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | פרק כ'': עיקול מקרקעין ומכירתם"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'מנהל העיזבון נחשב למוכר לעניין מס שבח, והוא חייב בתשלום המס מתוך נכסי העיזבון.', false, 'תשובה זו שגויה. חוק מיסוי מקרקעין קובע כי המכירה תיחשב ככזו שבוצעה על ידי היורשים, ולא על ידי מנהל העיזבון כמוכר עצמאי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'המכירה תיחשב ככזו שבוצעה על ידי היורשים, ומנהל העיזבון אחראי למילוי חובות הדיווח והתשלום בשמם.', true, 'זו התשובה הנכונה. סעיף 5(ג)(1) לחוק מיסוי מקרקעין קובע כי מכירת נכס עיזבון תיחשב כמכירה בידי היורשים. סעיף 5(ג)(3) מטיל על מנהל העיזבון את האחריות למילוי חובות הדיווח והתשלום.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המכירה פטורה ממס שבח באופן אוטומטי, שכן מדובר במימוש נכס עיזבון.', false, 'תשובה זו שגויה. אין פטור אוטומטי ממס שבח במכירת נכס עיזבון. היורשים צריכים לעמוד בתנאי הפטור בעצמם.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'מנהל העיזבון אינו אחראי לתשלום מס שבח, שכן זו אחריותם הבלעדית של היורשים.', false, 'תשובה זו שגויה. אף שהמכירה מיוחסת ליורשים, החוק מטיל על מנהל העיזבון אחריות למילוי חובות המס.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q11';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 11, '2024-W-S-Q11';
END
$$;

-- ============================================================
-- Q12 — angles backfill for 2024-W-S-Q12 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q12';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q12';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'מניין תקופת תנאי ללא מאסר בפועל', 1,
      'פלוני הורשע בעבירה קלה ונגזר עליו ביום 1.1.2024 עונש של 6 חודשי מאסר על תנאי, לבל יעבור עבירה דומה למשך שנה. פלוני לא נדון למאסר בפועל. מתי תסתיים תקופת התנאי?', 'שאלה זו בוחנת את הכלל הבסיסי הקבוע בסעיף 52(ג) לחוק העונשין, לפיו תקופת התנאי מתחילה ביום מתן גזר הדין, כאשר לא מוטל עונש מאסר בפועל. היא מדגישה את ההבחנה בין הכלל לחריגיו.', 'סעיף 52(ג) לחוק העונשין קובע את הכלל הבסיסי שתקופת התנאי תתחיל ביום מתן גזר הדין. החריג, לפיו התקופה תחל ביום השחרור ממאסר, חל רק אם הנידון נושא עונש מאסר בפועל. במקרה זה, פלוני לא נדון למאסר בפועל, ולכן הכלל הוא הקובע. תקופת התנאי תחל ביום מתן גזר הדין ותסתיים שנה לאחר מכן. סעיף 52(ג) לחוק העונשין, תשל"ז-1977. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). פ"ל (תעבורה י-ם) 9812-10-20 מדינת ישראל נ'' חאלד דירבאס (18.07.2021)', 'הטעות הנפוצה היא ליישם שגוי של החריג הקבוע בסעיף 52(ג) גם במקרים בהם לא נגזר מאסר בפועל.',
      '["מאסר על תנאי", "תקופת תנאי", "סעיף 52(ג) לחוק העונשין", "כלל ברירת המחדל", "יום מתן גזר הדין"]'::jsonb, '**וריאציה 1 — ללא מאסר בפועל:** אם אין מאסר בפועל, מתי מתחילה תקופת התנאיביום מתן גזר הדין (סעיף 52(ג) לחוק העונשין).
**וריאציה 2 — תכלית הכלל:** מדוע התנאי מתחיל מידכי אין תקופת מאסר בפועל שבה הנאשם אינו חופשי, ולכן ההרתעה צריכה להתחיל מיד (פ"ל (תעבורה י-ם) 9812-10-20 מדינת ישראל נ'' חאלד דירבאס).
**וריאציה 3 — סיום התנאי:** מתי תסתיים תקופת התנאישנה מיום תחילתה, כלומר שנה מיום מתן גזר הדין.
', 'ללא מאסר בפועלתקופת התנאי מתחילה ביום מתן גזר הדיןמסתיימת בתום התקופה שנקבעה.', '["חוק העונשין, תשל\"ז-1977, סעיף 52(ג)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "פ\"ל (תעבורה י-ם) 9812-10-20 מדינת ישראל נ'' חאלד דירבאס (18.07.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'שנה מיום 1.1.2024.', true, 'זו התשובה הנכונה. כאשר לא מוטל עונש מאסר בפועל, תקופת התנאי מתחילה ביום מתן גזר הדין, בהתאם לכלל הקבוע בסעיף 52(ג) רישא לחוק העונשין.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'שנה מיום שחרורו ממאסר.', false, 'תשובה זו שגויה. חריג זה חל רק כאשר הנידון נושא עונש מאסר בפועל, מה שלא מתקיים במקרה זה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שנה מהמועד האחרון להגשת ערעור על גזר הדין.', false, 'תשובה זו שגויה. מועד תחילת תקופת התנאי אינו קשור למועד הגשת ערעור.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'שנה מיום התייצבותו לריצוי עונש (אם היה כזה).', false, 'תשובה זו שגויה. במקרה זה לא נגזר מאסר בפועל, ולכן אין מועד התייצבות רלוונטי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q12';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תכלית המאסר על תנאי', 2,
      'מהי התכלית העיקרית העומדת בבסיס ההוראה בסעיף 52(ג) לחוק העונשין, הקובעת את מועד תחילת תקופת התנאי?', 'שאלה זו מתמקדת בתכלית העומדת בבסיס סעיף 52(ג) לחוק העונשין, כפי שפורשה בפסיקה. היא מדגישה את הרציונל מאחורי קביעת מועד תחילת תקופת התנאי, שהוא להבטיח את האפקטיביות ההרתעתית של המאסר על תנאי.', 'הפסיקה עמדה על כך שתכלית ההסדר הקבוע בסעיף 52(ג) לחוק העונשין היא להבטיח שתקופת התנאי תהיה, ככל שניתן, תקופה שבה הנאשם חופשי, והתמודדותו כאדם חופשי עם המבחנים שנקבעו בהחלטה בדבר מאסר על תנאי תבוא לכלל ביטוי הלכה למעשה. במילים אחרות, ההתמודדות של מי שנידון, שביטוייה בהימנעות מביצוע עבירות נוספות, מתחילה, בדרך כלל, ביום תום ריצוי עונש המאסר. ע"פ 4180/92 מדינת ישראל נ'' אליהו בן מרדכי נעים (21.03.1994). פ"ל (תעבורה י-ם) 9812-10-20 מדינת ישראל נ'' חאלד דירבאס (18.07.2021). ע"פ 1779/92 מדינת ישראל נ'' עארף כחיל (29.03.1993)', 'הטעות הנפוצה היא לבלבל בין תכלית המאסר על תנאי לבין תכליות אחרות של הענישה, או לחשוב שהתנאי נועד לחול גם בזמן כליאה.',
      '["מאסר על תנאי", "תכלית הענישה", "הרתעה", "סעיף 52(ג) לחוק העונשין", "חופש הנידון"]'::jsonb, '**וריאציה 1 — מטרת התנאי:** מהי המטרה העיקרית של מאסר על תנאילהרתיע את הנידון מביצוע עבירות נוספות כשהוא חופשי (ע"פ 4180/92 מדינת ישראל נ'' אליהו בן מרדכי נעים).
**וריאציה 2 — חשיבות החופש:** מדוע חשוב שהנידון יהיה חופשיכדי שהתנאי יחול עליו בהיותו אדם חופשי היכול לבצע עבירות נוספות, ולא כשהוא ממילא נתון במאסר ומוגבל במעשיו (ת"פ (מחוזי חי'') 47548-07-15 מדינת ישראל נ'' אמיר ג''ראד (29.03.2016)).
**וריאציה 3 — מניעת אובדן אפקטיביות:** מה קורה אם התנאי חל בזמן מאסרהוא עשוי לאבד את האפקט המרתיע החבוי בו (ע"פ 1779/92 מדינת ישראל נ'' עארף כחיל).', 'תכלית סעיף 52(גלהבטיח אפקטיביות הרתעתיתכשהנידון חופשיולא כשהוא כלוא.', '["חוק העונשין, תשל\"ז-1977, סעיף 52(ג)", "ע\"פ 4180/92 מדינת ישראל נ'' אליהו בן מרדכי נעים (21.03.1994)", "פ\"ל (תעבורה י-ם) 9812-10-20 מדינת ישראל נ'' חאלד דירבאס (18.07.2021)", "ע\"פ 1779/92 מדינת ישראל נ'' עארף כחיל (29.03.1993)", "ת\"פ (מחוזי חי'') 47548-07-15 מדינת ישראל נ'' אמיר ג''ראד (29.03.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'להבטיח שהנידון ירצה את עונשו במלואו, ללא קיצור.', false, 'תשובה זו שגויה. תכלית זו אינה קשורה ישירות למועד תחילת תקופת התנאי, אלא לריצוי המאסר בפועל.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'להבטיח את האפקטיביות ההרתעתית של המאסר על תנאי, בכך שיחול כאשר הנידון חופשי ומתמודד עם פיתויי העבריינות.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי תכלית סעיף 52(ג) היא להבטיח שהמאסר על תנאי ישרת את מטרתו ההרתעתית כאשר הנידון נמצא מחוץ לכותלי הכלא.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'למנוע מצב שבו הנידון יבצע עבירות נוספות בזמן שהוא כלוא.', false, 'תשובה זו שגויה. בזמן כליאה, ממילא קשה יותר לבצע עבירות, והתנאי השיפוטי אינו חל. התכלית היא להרתיע כשהוא חופשי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לאפשר לבית המשפט גמישות בקביעת מועד תחילת התנאי לפי נסיבות המקרה.', false, 'תשובה זו שגויה. אף שלבית המשפט יש סמכות לקבוע אחרת, זו אינה התכלית העיקרית של ההוראה עצמה, אלא סמכות חריגה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q12';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'תקופת תנאי סטטוטורית', 3,
      'פלוני נדון למאסר בפועל ולמאסר על תנאי. במהלך ריצוי המאסר בפועל, הוא שוחרר לחופשה מיוחדת מבית הסוהר. האם בתקופת החופשה חלה עליו תקופת תנאי כלשהי?', 'שאלה זו עוסקת ב"חריג לחריג" הקבוע בסעיף 52(ג) לחוק העונשין, המכונה "תקופת תנאי סטטוטורית". היא בוחנת את המצבים בהם אסיר נמצא מחוץ לכותלי בית הסוהר (כגון בחופשה מיוחדת, שחרור בערובה או עבודות שירות) וכיצד תקופות אלו נחשבות לעניין המאסר על תנאי.', 'סעיף 52(ג) לחוק העונשין קובע חריג לכלל וחריג לחריג. הכלל הוא שתקופת התנאי השיפוטית מתחילה ביום מתן גזר הדין. החריג הוא שאם הנידון נושא עונש מאסר בפועל, תקופת התנאי השיפוטית תחל ביום שחרורו ממאסר. החריג לחריג קובע כי תקופה שאסיר נמצא בה מחוץ לבית הסוהר בשל שחרור בערובה, חופשה מיוחדת או ריצוי מאסר בעבודות שירות, תיחשב כתקופת תנאי מצטברת לתקופת התנאי שקבע בית המשפט. תקופות אלו מכונות "תקופות תנאי סטטוטוריות" והן נפרדות מתקופת התנאי השיפוטית. תכליתן למלא חללים בתקופת הכליאה שנוצרו בשל ההוראה הקובעת כי התנאי השיפוטי לא יחול על תקופת המאסר. סעיף 52(ג) לחוק העונשין, תשל"ז-1977. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). רע"פ 7589/97 שמעון רחמים נ'' מדינת ישראל (21.06.1998). יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי', 'הטעות הנפוצה היא לחשוב שתקופת התנאי השיפוטית חלה גם בזמן חופשה ממאסר, או להתעלם מקיומה של תקופת התנאי הסטטוטורית.',
      '["תקופת תנאי סטטוטורית", "תקופת תנאי שיפוטית", "סעיף 52(ג) לחוק העונשין", "חופשה מיוחדת", "שחרור בערובה", "עבודות שירות"]'::jsonb, '**וריאציה 1 — חופשה מיוחדת:** האם חופשה מיוחדת נחשבת לתקופת תנאיכן, היא נחשבת לתקופת תנאי סטטוטורית (סעיף 52(ג) לחוק העונשין).
**וריאציה 2 — סוג התנאי:** האם זו תקופת תנאי שיפוטית או סטטוטוריתסטטוטורית, הנפרדת מהשיפוטית (רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל).
**וריאציה 3 — תכלית התנאי הסטטוטורי:** מהי תכלית התנאי הסטטוטורילמלא חללים בתקופת הכליאה שבהם האסיר חופשי לבצע עבירות (רע"פ 7589/97 שמעון רחמים נ'' מדינת ישראל).', 'חופשה מיוחדת ממאסרחלה תקופת תנאי סטטוטוריתמצטברת לשיפוטיתלמילוי חללים בהרתעה.', '["חוק העונשין, תשל\"ז-1977, סעיף 52(ג)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "רע\"פ 7589/97 שמעון רחמים נ'' מדינת ישראל (21.06.1998)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, תקופת התנאי השיפוטית נדחית ליום השחרור ממאסר, ואין חלה עליו תקופת תנאי אחרת.', false, 'תשובה זו שגויה. סעיף 52(ג) קובע חריג לחריג, לפיו בתקופות מסוימות מחוץ לכלא חלה תקופת תנאי סטטוטורית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, חלה עליו תקופת תנאי סטטוטורית, המצטברת לתקופת התנאי השיפוטית שתחל ביום שחרורו ממאסר.', true, 'זו התשובה הנכונה. סעיף 52(ג) לחוק העונשין קובע כי תקופה שאסיר נמצא בה מחוץ לבית הסוהר בשל חופשה מיוחדת, תיחשב כתקופת תנאי מצטברת (סטטוטורית).', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, תקופת התנאי השיפוטית מתחילה לרוץ באופן חלקי בתקופת החופשה.', false, 'תשובה זו שגויה. תקופת התנאי השיפוטית אינה ניתנת לפיצול ואינה חלה בזמן כליאה או חופשה ממנה, אלא רק תקופת תנאי סטטוטורית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק אם בית המשפט הורה במפורש בגזר הדין שתחול עליו תקופת תנאי בתקופת החופשה.', false, 'תשובה זו שגויה. תקופת התנאי הסטטוטורית חלה מכוח החוק, אלא אם בית המשפט הורה אחרת במפורש.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q12';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות בית המשפט לקבוע מועד אחר', 4,
      'בית המשפט גזר על נאשם מאסר על תנאי וקבע במפורש בגזר הדין כי תקופת התנאי תחל ביום מתן גזר הדין, למרות שנגזר עליו גם מאסר בפועל. האם קביעה זו תקפה?', 'שאלה זו בוחנת את סמכותו של בית המשפט לסטות מהכללים הקבועים בסעיף 52(ג) לחוק העונשין לעניין מועד תחילת תקופת התנאי. היא מתמקדת בסייג "והכל כשבית המשפט לא הורה אחרת", המקנה לבית המשפט שיקול דעת לקבוע הוראות שונות, ובלבד שיורה על כך במפורש.', 'הסיפא של סעיף 52(ג) לחוק העונשין קובעת "והכל כשבית המשפט לא הורה אחרת". הוראה זו מקנה לבית המשפט סמכות לקבוע מועד אחר לתחילת המאסר על תנאי מזה הקבוע בסעיף, וכן לקבוע הוראות אחרות בנוגע לתקופות התנאי הסטטוטוריות. סמכות זו מאפשרת לבית המשפט להתאים את מועד תחילת התנאי לתכלית הענישה ולנסיבות המקרה, גם אם הדבר סוטה מהכללים הכלליים שנקבעו בסעיף. חשוב לציין כי על בית המשפט להורות על כך במפורש בגזר הדין. סעיף 52(ג) לחוק העונשין, תשל"ז-1977. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). ע"פ 7510/00 אליהו במנוקלר נ'' מדינת ישראל (09.05.2002). עפ"ת (מחוזי חי'') 4162-05-25 גמאל ג''ארחי נ'' מדינת ישראל (01.09.2025)', 'הטעות הנפוצה היא לחשוב שהכללים בסעיף 52(ג) הם קוגנטיים ואינם ניתנים לשינוי על ידי בית המשפט, מבלי לשים לב לסייג המפורש בחוק.',
      '["סמכות בית המשפט", "סעיף 52(ג) לחוק העונשין", "מאסר על תנאי", "שיקול דעת שיפוטי", "הוראה מפורשת בגזר הדין"]'::jsonb, '**וריאציה 1 — סייג "לא הורה אחרת":** מה משמעות הסייג "והכל כשבית המשפט לא הורה אחרתהוא מקנה לבית המשפט סמכות לקבוע מועד אחר לתחילת התנאי (סעיף 52(ג) לחוק העונשין).
**וריאציה 2 — היקף הסמכות:** האם הסמכות כוללת גם את תקופות התנאי הסטטוטוריותכן, בית המשפט רשאי לקבוע הוראה אחרת גם בנוגע לתקופות אלו (ע"פ 7510/00 אליהו במנוקלר נ'' מדינת ישראל).
**וריאציה 3 — חשיבות ההוראה המפורשת:** האם נדרשת הוראה מפורשתכן, אם לא נקבעה הוראה מפורשת, ידחה העונש כולו כחטיבה אחת (עפ"ת (מחוזי חי'') 4162-05-25 גמאל ג''ארחי נ'' מדינת ישראל).', 'בית המשפט רשאי לסטות מכללי סעיף 52(גאם הורה אחרת במפורש בגזר הדיןמכוח הסייג "והכל כשבית המשפט לא הורה אחרת".', '["חוק העונשין, תשל\"ז-1977, סעיף 52(ג)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "ע\"פ 7510/00 אליהו במנוקלר נ'' מדינת ישראל (09.05.2002)", "עפ\"ת (מחוזי חי'') 4162-05-25 גמאל ג''ארחי נ'' מדינת ישראל (01.09.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, קביעה זו מנוגדת להוראת סעיף 52(ג) לחוק העונשין, ולכן אינה תקפה.', false, 'תשובה זו שגויה. סעיף 52(ג) כולל סייג המאפשר לבית המשפט לקבוע הוראה אחרת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, סעיף 52(ג) לחוק העונשין מקנה לבית המשפט סמכות לקבוע מועד אחר לתחילת תקופת התנאי, ובלבד שהורה על כך במפורש.', true, 'זו התשובה הנכונה. הסיפא של סעיף 52(ג) קובעת "והכל כשבית המשפט לא הורה אחרת", המקנה לבית המשפט שיקול דעת לקבוע מועד שונה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק אם הקביעה נעשתה בהסכמת התביעה וההגנה.', false, 'תשובה זו שגויה. סמכות בית המשפט לקבוע מועד אחר אינה מותנית בהסכמת הצדדים, אלא בשיקול דעתו השיפוטי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק אם מדובר בעבירה קלה שאינה מסכנת את הציבור.', false, 'תשובה זו שגויה. סמכות בית המשפט לקבוע מועד אחר אינה מוגבלת לסוג העבירה, אלא לשיקול דעתו בנסיבות העניין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q12';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 12, '2024-W-S-Q12';
END
$$;

-- ============================================================
-- Q13 — angles backfill for 2024-W-S-Q13 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q13';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q13';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'ייצוג נגד לקוח לשעבר באותו עניין', 1,
      'עו"ד כהן ייצג בעבר את מר ישראלי בעסקת מקרקעין מורכבת. כעת, מר לוי פונה לעו"ד כהן ומבקש ממנו לייצגו בתביעה נגד מר ישראלי, בטענה למרמה באותה עסקת מקרקעין. האם עו"ד כהן רשאי לייצג את מר לוי?', 'שאלה זו עוסקת בכלל 16 לכללי לשכת עורכי הדין (אתיקה מקצועית), האוסר על עורך דין לטפל נגד לקוח לשעבר בעניין שטיפל בו למענו, או בעניין שיש לו זיקה של ממש למידע שקיבל ממנו. הכלל נועד להגן על אמון הלקוח ועל סודיות המידע שנמסר לעורך הדין.', 'כלל 16(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע כי עורך דין לא יטפל נגד לקוח (1) בעניין או בקשר לעניין שטיפל בו למען אותו לקוח; (2) בעניין אליו יש זיקה של ממש למידע שקיבל עורך הדין מאותו לקוח או מטעמו. איסור זה חל גם על לקוח לשעבר. תכלית הכלל היא למנוע מצב שבו עורך דין עלול לפעול תוך ניגוד עניינים ולעשות שימוש במידע או נתונים שמסר לו לקוח לשעבר, נגדו. המונח "עניין" מתפרש פרשנות מרחיבה בפסיקה. סעיף 16(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986. על"ע 10127/07 יוסף צוקרמן, עו"ד נ'' הוועד המחוזי של לשכת עורכי הדין בתל אביב יפו (24.05.2009). ת"א (שלום צפת) 29166-09-11 חברת נוגידאת פאוזי (1992) בע"מ נ'' סאפי נוג''ידאת (28.09.2016)', 'הטעות הנפוצה היא לחשוב שחובת הנאמנות והסודיות כלפי לקוח מסתיימת עם תום הייצוג, מבלי להבין את היקף האיסור שבכלל 16.',
      '["לקוח לשעבר", "כלל 16 לכללי האתיקה", "ניגוד עניינים", "זיקה של ממש למידע", "חובת סודיות", "חובת נאמנות"]'::jsonb, '**וריאציה 1 — אותו עניין:** עו"ד ייצג לקוח בעניין מסוים. האם רשאי לייצג צד אחר נגדו באותו ענייןלא, כלל 16(א)(1) אוסר זאת (סעיף 16(א)(1) לכללי האתיקה).
**וריאציה 2 — מידע סודי:** עו"ד קיבל מידע מלקוח. האם רשאי לייצג צד אחר נגדו בעניין שיש זיקה למידעלא, כלל 16(א)(2) אוסר זאת (סעיף 16(א)(2) לכללי האתיקה).
**וריאציה 3 — תכלית האיסור:** מהי תכלית כלללמנוע ניגוד עניינים ושימוש במידע סודי נגד הלקוח לשעבר (על"ע 10127/07 יוסף צוקרמן, עו"ד נ'' הוועד המחוזי של לשכת עורכי הדין בתל אביב יפו).', 'כללאיסור ייצוג נגד לקוח לשעברבאותו עניין או בזיקה למידעהגנה על אמון וסודיות.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 16", "על\"ע 10127/07 יוסף צוקרמן, עו\"ד נ'' הוועד המחוזי של לשכת עורכי הדין בתל אביב יפו (24.05.2009)", "ת\"א (שלום צפת) 29166-09-11 חברת נוגידאת פאוזי (1992) בע\"מ נ'' סאפי נוג''ידאת (28.09.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מאחר שייצוגו של מר ישראלי הסתיים, עו"ד כהן אינו כפוף עוד לחובת נאמנות כלפיו.', false, 'תשובה זו שגויה. חובת הנאמנות והסודיות כלפי לקוח לשעבר ממשיכה לחול, במיוחד באותו עניין או בעניין שיש לו זיקה למידע שהתקבל.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מאחר שחל איסור על עורך דין לטפל נגד לקוח לשעבר בעניין שטיפל בו למענו, או בעניין שיש לו זיקה של ממש למידע שקיבל ממנו.', true, 'זו התשובה הנכונה. כלל 16(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין לטפל נגד לקוח לשעבר באותו עניין או בעניין שיש לו זיקה של ממש למידע שהתקבל.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם מר ישראלי יסכים בכתב לייצוג זה.', false, 'תשובה זו שגויה. כלל 16 אינו כולל חריג של הסכמת הלקוח לשעבר, בניגוד לכלל 14(ד) החל על לקוחות קיימים או צדדים בעלי אינטרסים מנוגדים באותו עניין.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן עברו לפחות 7 שנים מסיום הייצוג של מר ישראלי.', false, 'תשובה זו שגויה. אין בחוק או בכללי האתיקה הוראה הקובעת מגבלת זמן כזו לעניין איסור ייצוג נגד לקוח לשעבר באותו עניין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q13';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'איסור ניגוד עניינים: התנהגותי או תוצאתי?', 2,
      'עו"ד דנה ייצגה את חברת ''אלפא'' בעסקת מיזוג. לאחר סיום העסקה, פנתה אליה חברת ''בטא'' בבקשה לייצגה בתביעה נגד חברת ''אלפא'' בעניין אחר לחלוטין, שאין לו כל זיקה לעסקת המיזוג. עו"ד דנה סבורה כי אין כל חשש לניגוד עניינים בפועל, וכי לא ייגרם כל נזק לחברת ''אלפא''. האם עו"ד דנה רשאית לייצג את חברת ''בטא''?', 'שאלה זו בוחנת את אופיו של האיסור על ניגוד עניינים, כפי שנקבע בכלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית). היא מדגישה כי האיסור הוא ''התנהגותי'' ולא ''תוצאתי'', כלומר די בקיומו של חשש לניגוד עניינים כדי להקים את האיסור, ואין צורך להוכיח נזק בפועל או הפרה ממשית של חובת נאמנות.', 'כלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי עורך דין לא ייצג לקוח, לא יקבל על עצמו לייצגו ולא ימשיך בייצוגו, אם קיים חשש שלא יוכל למלא את חובתו המקצועית כלפיו, בשל עניין אישי שלו, או בשל התחייבות או חובת נאמנות שיש לו כלפי אחר. הפסיקה קבעה כי איסור זה הוא ''עבירה התנהגותית'' ולא ''תוצאתית''. משמעות הדבר היא שאין רלוונטיות לשאלה מה תהיה התוצאה של פעולת עורך הדין במצב של חשש לניגוד עניינים. די בקיומו של חשש לניגוד עניינים, גם אם לא נוצר ניגוד עניינים בפועל או לא נגרם נזק. מטרת הכלל היא למנוע פיתוי ולשמור על אמון הציבור במקצוע עריכת הדין. סעיף 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986. ת"א (שלום ב"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי (16.03.2025). ת"א (שלום ת"א) 36346-01-20 עמית פולק מטלון ושות'' נ'' טל רויטל בסביץ בוגין (22.12.2024). ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (24.02.2026)', 'הטעות הנפוצה היא לחשוב שרק ניגוד עניינים בפועל או נזק מוכח מהווים הפרה אתית, ולא להבין את אופיו המניעתי של הכלל.',
      '["ניגוד עניינים", "כלל 14(א) לכללי האתיקה", "עבירה התנהגותית", "עבירה תוצאתית", "חשש לניגוד עניינים", "חובת נאמנות"]'::jsonb, '**וריאציה 1 — חשש בלבד:** האם נדרש ניגוד עניינים בפועללא, די בחשש לניגוד עניינים (ת"א (שלום ב"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי).
**וריאציה 2 — מניעת פיתוי:** מהי מטרת הכלללמנוע פיתוי מאדם ישר והגון (ת"א (שלום ב"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי).
**וריאציה 3 — חובת נאמנות:** כיצד קשור ל-14(א) לחובת הנאמנותהאיסור על ניגוד עניינים חל אף כאשר בפועל לא הופרה חובת הנאמנות ללקוח (ת"א (שלום ב"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי).', 'איסור ניגוד עניינים (14(אהתנהגותי (די בחששלא תוצאתי (לא נדרש נזקלמניעת פיתוי ושמירת אמון.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 14(א)", "ת\"א (שלום ב\"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי (16.03.2025)", "ת\"א (שלום ת\"א) 36346-01-20 עמית פולק מטלון ושות'' נ'' טל רויטל בסביץ בוגין (22.12.2024)", "ת\"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (24.02.2026)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מאחר שלא קיים חשש לניגוד עניינים בפועל ולא ייגרם נזק לחברת ''אלפא'', אין מניעה לייצוג.', false, 'תשובה זו שגויה. האיסור על ניגוד עניינים הוא התנהגותי ודי בחשש לניגוד עניינים, גם אם לא נגרם נזק בפועל.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן האיסור על ניגוד עניינים הוא ''עבירה התנהגותית'' ולא ''תוצאתית'', ודי בחשש לניגוד עניינים כדי למנוע את הייצוג.', true, 'זו התשובה הנכונה. כלל 14(א) לכללי האתיקה קובע איסור התנהגותי, כלומר די בקיומו של חשש לניגוד עניינים, גם אם בפועל לא נגרם נזק או לא הופרה חובת נאמנות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם חברת ''אלפא'' תסכים בכתב לייצוג זה.', false, 'תשובה זו שגויה. הסכמה בכתב רלוונטית לחריגים ספציפיים (כמו כלל 14(ד)), אך לא לכלל 14(א) העוסק בעניין אישי או חובת נאמנות כלפי אחר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן עברו לפחות שנתיים מסיום הייצוג של חברת ''אלפא''.', false, 'תשובה זו שגויה. אין בחוק או בכללי האתיקה מגבלת זמן כזו לעניין ניגוד עניינים כללי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q13';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריגים לאיסור ניגוד עניינים: הסכמה בכתב ותיחום שירות', 3,
      'עו"ד שרון מייצגת את מוכר הדירה ואת רוכש הדירה בעסקת מכר, לאחר ששניהם הסכימו בכתב כי היא תטפל בעסקה. בנוסף, עו"ד דוד מייצג לקוח קבוע שלו בעניין מסוים, ובהסכמה בכתב עם הלקוח, תיחם את השירות המקצועי כך שלא יתנגש עם ייצוג לקוח אחר. האם פעולותיהם של עו"ד שרון ועו"ד דוד מותרות על פי כללי האתיקה?', 'שאלה זו מתמקדת בחריגים לאיסור ניגוד עניינים הקבועים בכלל 14(ד) ו-14(ה) לכללי לשכת עורכי הדין (אתיקה מקצועית). היא בוחנת את האפשרות לייצג צדדים בעלי אינטרסים מנוגדים באותו עניין או נגד לקוח קבוע, וכן את האפשרות לתחום את השירות המקצועי, וזאת בתנאי של הסכמה בכתב ואי פגיעה בחובת הנאמנות.', 'כלל 14(ב) לכללי האתיקה אוסר על עורך דין לייצג צדדים בעלי אינטרסים מנוגדים באותו עניין, וכלל 14(ג) אוסר ייצוג נגד לקוח קבוע. עם זאת, כלל 14(ד) קובע חריג לפיו הוראות סעיפים קטנים (ב) ו-(ג) לא יחולו על עריכת הסכם ועל טיפול בעניין שהצדדים הסכימו, בכתב, כי ייעשה בידי אותו עורך דין. כלל 14(ה) מוסיף כי עורך דין ולקוחו רשאים להסכים, בכתב, לתחום את השירות המקצועי כדי למנוע התנגשות עם ייצוג לקוח אחר או עם עניין או חובה אחרת של עורך הדין, בתנאי שצמצום השירות סביר ואינו פוגע בחובת הנאמנות. חשוב לציין כי חריגים אלו אינם חלים על כלל 14(א) העוסק בעניין אישי של עורך הדין, הנחשב לקוגנטי. סעיף 14(ד) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986. סעיף 14(ה) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986. ע"א 3640/22 עו"ד יורם ל. כהן נ'' רבקה בוכמן (01.09.2024). ע"א 554/87 דוד מזור נ'' שמואל אריאלי (11.12.1990)', 'הטעות הנפוצה היא להניח שכללי ניגוד העניינים הם מוחלטים ואינם ניתנים להתניה, או לבלבל בין סוגי ניגודי העניינים השונים והחריגים החלים עליהם.',
      '["ניגוד עניינים", "חריגים לניגוד עניינים", "כלל 14(ד)", "כלל 14(ה)", "הסכמה בכתב", "תיחום שירות", "חובת נאמנות"]'::jsonb, '**וריאציה 1 — הסכמה בכתב:** מתי ניתן לייצג צדדים בעלי אינטרסים מנוגדים באותו ענייןאם הצדדים הסכימו בכתב לעריכת הסכם או טיפול בעניין על ידי אותו עו"ד (סעיף 14(ד) לכללי האתיקה).
**וריאציה 2 — תיחום שירות:** כיצד ניתן למנוע התנגשות עם ייצוג לקוח אחרעורך דין ולקוחו רשאים להסכים בכתב לתחום את השירות המקצועי (סעיף 14(ה) לכללי האתיקה).
**וריאציה 3 — עניין אישי:** האם חריגים אלו חלים גם על עניין אישי של עו"דלא, כלל 14(א) (עניין אישי) הוא קוגנטי ואינו ניתן להתניה (ת"א (שלום ב"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי).', 'חריגים לניגוד עניינים (14(ד), 14(ההסכמה בכתב או תיחום שירותלא חל על עניין אישי (14(א)).', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 14(ד)", "כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 14(ה)", "ע\"א 3640/22 עו\"ד יורם ל. כהן נ'' רבקה בוכמן (01.09.2024)", "ע\"א 554/87 דוד מזור נ'' שמואל אריאלי (11.12.1990)", "ת\"א (שלום ב\"ש) 59407-05-22 יוסי אפנג''ר נ'' רווית אזולאי (16.03.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'פעולותיהם של שני עורכי הדין מותרות, שכן כלל 14(ד) ו-14(ה) לכללי האתיקה מאפשרים חריגים לאיסור ניגוד עניינים בהסכמה בכתב.', true, 'זו התשובה הנכונה. כלל 14(ד) מאפשר ייצוג צדדים בעלי אינטרסים מנוגדים באותו עניין (כמו עסקת מכר) או נגד לקוח קבוע, אם הצדדים הסכימו בכתב. כלל 14(ה) מאפשר תיחום שירות בכתב למניעת התנגשות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פעולתה של עו"ד שרון מותרת, אך פעולתו של עו"ד דוד אסורה, שכן לא ניתן לתחום שירות מקצועי כדי למנוע ניגוד עניינים.', false, 'תשובה זו שגויה. כלל 14(ה) מאפשר תיחום שירות בכתב, בתנאי שהתיחום סביר ואינו פוגע בחובת הנאמנות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'פעולתו של עו"ד דוד מותרת, אך פעולתה של עו"ד שרון אסורה, שכן לא ניתן לייצג צדדים בעלי אינטרסים מנוגדים באותו עניין, גם בהסכמה בכתב.', false, 'תשובה זו שגויה. כלל 14(ד) מאפשר ייצוג צדדים בעלי אינטרסים מנוגדים באותו עניין (כמו עסקת מכר) אם הצדדים הסכימו בכתב.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'פעולותיהם של שני עורכי הדין אסורות, שכן האיסור על ניגוד עניינים הוא מוחלט ואינו ניתן להתניה.', false, 'תשובה זו שגויה. כלל 14(א) (עניין אישי) הוא קוגנטי, אך כלל 14(ב) ו-14(ג) ניתנים להתניה באמצעות חריגים הקבועים בכלל 14(ד) ו-14(ה).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q13';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות בית המשפט בסוגיות אתיות', 4,
      'במהלך דיון אזרחי, נטענה טענה לניגוד עניינים של עורך דין המייצג צד בהליך, וכי הדבר מהווה הפרה של כללי האתיקה. מהי הדרך הראויה לבירור טענה זו, ומהי סמכותו של בית המשפט האזרחי בעניין?', 'שאלה זו עוסקת בממשק שבין סמכותם של מוסדות לשכת עורכי הדין לבין סמכותו של בית המשפט האזרחי לדון בסוגיות אתיות. היא מדגישה את הכלל לפיו מוסדות הלשכה הם האכסניה הטבעית, אך לבית המשפט קיימת סמכות עקרונית מכוח סעיף 75 לחוק בתי המשפט, המופעלת במקרים חריגים של פגיעה באינטרסים לגיטימיים של בעל דין.', 'לבית המשפט האזרחי קיימת סמכות עקרונית לדון בטענות הנוגעות להפרת כללי האתיקה של עורכי דין ולתת צווים או סעדים בגין הפרות אלו, לרבות הוראה על הפסקת ייצוג. סמכות זו נובעת מסמכותו הכללית המעוגנת בסעיף 75 לחוק בתי המשפט [נוסח משולב], התשמ"ד-1984. עם זאת, האכסניה הטבעית והרגילה לבירור שאלות אתיות היא מוסדות לשכת עורכי הדין. בית המשפט יפעיל את סמכותו זו רק במקרים חריגים, כאשר ההפרה הנטענת עלולה לפגוע באינטרסים לגיטימיים של בעל הדין שהעלה אותה, ולא רק בטהרת המקצוע או כבודו. במקרים מסוימים, בית המשפט עשוי להפנות את הצדדים לקבלת חוות דעת מקדימה מוועדת האתיקה, אך חוות דעת זו אינה מחייבת את בית המשפט. ת"א (שלום ת"א) 49795-10-18 חיים בר נ'' עו"ד עידן קלינמן (02.06.2019). רע"א 3036/19 רותם אמפרט נגב בע"מ נ'' פרופסור אלון טל (25.02.2020). ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (24.02.2026). רמ"ש (מחוזי תל אביב-יפו) 24349-02-18 י'' ב'' נ'' ע'' ב'' (23.02.2018)', 'הטעות הנפוצה היא לחשוב שרק מוסדות לשכת עורכי הדין מוסמכים לדון בסוגיות אתיות, או שבית המשפט האזרחי יתערב בכל מקרה של טענה אתית.',
      '["סמכות בית המשפט", "סוגיות אתיות", "לשכת עורכי הדין", "סעיף 75 לחוק בתי המשפט", "אינטרס לגיטימי", "הפסקת ייצוג"]'::jsonb, '**וריאציה 1 — אכסניה טבעית:** היכן המקום הראוי לבירור שאלות אתיותבמוסדות לשכת עורכי הדין (רע"א 3036/19 רותם אמפרט נגב בע"מ נ'' פרופסור אלון טל).
**וריאציה 2 — סמכות בית המשפט:** האם לבית המשפט האזרחי יש סמכות לדון בסוגיות אתיותכן, סמכות עקרונית מכוח סעיף 75 לחוק בתי המשפט (ת"א (שלום ת"א) 49795-10-18 חיים בר נ'' עו"ד עידן קלינמן).
**וריאציה 3 — מתי יתערב בית המשפט:** מתי יפעיל בית המשפט את סמכותורק במקרים חריגים, כאשר ההפרה פוגעת באינטרסים לגיטימיים של בעל דין (ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי).', 'סוגיות אתיותלרוב ללשכת עו"דביהמ"ש יתערב בחריגכשנפגע אינטרס לגיטימי.', '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 75", "רע\"א 3036/19 רותם אמפרט נגב בע\"מ נ'' פרופסור אלון טל (25.02.2020)", "ת\"א (שלום ת\"א) 49795-10-18 חיים בר נ'' עו\"ד עידן קלינמן (02.06.2019)", "ת\"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (24.02.2026)", "רמ\"ש (מחוזי תל אביב-יפו) 24349-02-18 י'' ב'' נ'' ע'' ב'' (23.02.2018)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'האכסניה הטבעית לבירור שאלות אתיות היא מוסדות לשכת עורכי הדין, אך לבית המשפט האזרחי קיימת סמכות עקרונית לדון בכך במקרים חריגים, במיוחד אם יש פגיעה באינטרס לגיטימי של בעל דין.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי מוסדות לשכת עורכי הדין הם האכסניה הרגילה, אך לבית המשפט סמכות טבועה מכוח סעיף 75 לחוק בתי המשפט, המופעלת במקרים חריגים של פגיעה באינטרס לגיטימי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'רק ועדת האתיקה של לשכת עורכי הדין מוסמכת לדון בטענות אתיות, ובית המשפט האזרחי אינו רשאי להתערב בכך.', false, 'תשובה זו שגויה. לבית המשפט האזרחי קיימת סמכות עקרונית לדון בסוגיות אתיות, אם כי הוא מפעיל אותה במשורה ובמקרים חריגים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט האזרחי חייב להפנות את הצדדים לקבלת חוות דעת מוועדת האתיקה, וחוות דעת זו מחייבת את בית המשפט.', false, 'תשובה זו שגויה. חוות דעת מקדימה מוועדת האתיקה היא בגדר המלצה ואינה מחייבת את בית המשפט, והוא זה שיכריע בסופו של דבר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט האזרחי יורה על הפסקת ייצוג בכל מקרה של טענה להפרה אתית, כדי לשמור על טוהר המקצוע.', false, 'תשובה זו שגויה. בית המשפט יפעיל את סמכותו להפסקת ייצוג רק במקרים חריגים, ולא רק בגלל טוהר המקצוע אלא בעיקר כשיש פגיעה באינטרסים לגיטימיים של בעל דין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q13';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 13, '2024-W-S-Q13';
END
$$;

-- ============================================================
-- Q14 — angles backfill for 2024-W-S-Q14 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q14';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q14';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'נטל ההוכחה ביחסי מרות', 1,
      'פלונית, עובדת חדשה, חוותה הצעות חוזרות בעלות אופי מיני ממנהלה הישיר, תוך ניצול יחסי מרות. היא הגישה תביעה בגין הטרדה מינית בתוך שנה מיום האירועים. מהו נטל ההוכחה החל במקרה זה?', 'שאלה זו מתמקדת בנטל ההוכחה המיוחד החל בתביעות הטרדה מינית במקום העבודה, במיוחד כאשר מתקיימים יחסי מרות. היא בוחנת את סעיף 3(א)(6)(ג) לחוק למניעת הטרדה מינית, הפוטר את המוטרד מהוכחת חוסר עניין, ואת סעיף 6א לחוק, המעביר את נטל ההוכחה למעסיק בתנאים מסוימים.', 'סעיף 3(א)(6)(ג) לחוק למניעת הטרדה מינית קובע כי הצעות או התייחסויות חוזרות בעלות אופי מיני, המופנות לעובד במסגרת יחסי עבודה תוך ניצול מרות, ייחשבו להטרדה מינית גם אם המוטרד לא הראה למטריד כי אינו מעוניין בהן. כלומר, במקרים של יחסי מרות, אין צורך להוכיח את יסוד ''חוסר העניין''. בנוסף, סעיף 6א לחוק קובע כי בתובענה של עובד בשל פגיעה על רקע הטרדה מינית במסגרת יחסי עבודה, תהיה חובת ההוכחה על המעסיק כי לא פגע פגיעה כאמור, אם הוכיח העובד את התקיימות הפגיעה (לפי סעיף 7(א)(1)-(3) לחוק שוויון ההזדמנויות בעבודה) ובלבד שטרם חלפו שלוש שנים מיום שנוצרה העילה. במקרה זה, התביעה הוגשה בתוך שנה, ולכן נטל ההוכחה יעבור למעסיק לאחר שפלונית תוכיח את ההצעות החוזרות ואת ניצול יחסי המרות. סעיף 3(א)(6)(ג) לחוק למניעת הטרדה מינית, תשנ"ח-1998. סעיף 6א לחוק למניעת הטרדה מינית, תשנ"ח-1998. ס"ע (עבודה ירושלים) 48596-02-12 פלונית - אלמוני (23.07.2017). סע"ש (עבודה ירושלים) 8130-03-20 פלונית - אופטיקה הלפרין בע"מ (05.12.2022)', 'הטעות הנפוצה היא ליישם את הכלל הרגיל של נטל ההוכחה גם במקרים של יחסי מרות, מבלי להכיר בחריגים הקבועים בחוק למניעת הטרדה מינית.',
      '["נטל הוכחה", "הטרדה מינית", "יחסי מרות", "חוק למניעת הטרדה מינית", "סעיף 3(א)(6)(ג)", "סעיף 6א"]'::jsonb, '**וריאציה 1 — יחסי מרות וחוסר עניין:** האם ביחסי מרות יש צורך להוכיח חוסר ענייןלא, סעיף 3(א)(6)(ג) פוטר מכך (סעיף 3(א)(6)(ג) לחוק למניעת הטרדה מינית).
**וריאציה 2 — העברת נטל ההוכחה:** מתי עובר נטל ההוכחה למעסיקאם העובד הוכיח פגיעה על רקע הטרדה מינית בתוך 3 שנים מיום העילה (סעיף 6א לחוק למניעת הטרדה מינית).
**וריאציה 3 — תכלית החריג:** מדוע קיים חריג זהבשל פערי הכוחות בין בעל המרות לכפיף, המרתיעים את הכפיף מלהביע התנגדות (ס"ע (עבודה ירושלים) 48596-02-12 פלונית - אלמוני).', 'יחסי מרותפטור מהוכחת חוסר ענייןנטל הוכחה עובר למעסיק אם התביעה הוגשה תוך 3 שנים.', '["חוק למניעת הטרדה מינית, תשנ\"ח-1998, סעיף 3(א)(6)(ג)", "חוק למניעת הטרדה מינית, תשנ\"ח-1998, סעיף 6א", "ס\"ע (עבודה ירושלים) 48596-02-12 פלונית - אלמוני (23.07.2017)", "סע\"ש (עבודה ירושלים) 8130-03-20 פלונית - אופטיקה הלפרין בע\"מ (05.12.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'על פלונית להוכיח את ההצעות החוזרות ואת חוסר רצונה בהן, ועל המנהל להוכיח שלא ניצל יחסי מרות.', false, 'תשובה זו שגויה. במקרה של יחסי מרות, אין צורך להוכיח חוסר רצון, ונטל ההוכחה עובר למעסיק/מטריד לאחר הוכחת יסודות מסוימים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'על פלונית להוכיח את ההצעות החוזרות ואת ניצול יחסי המרות, ולאחר מכן נטל ההוכחה עובר למנהל/מעסיק להוכיח שלא פגע בה על רקע ההטרדה המינית.', true, 'זו התשובה הנכונה. סעיף 3(א)(6)(ג) לחוק למניעת הטרדה מינית קובע כי ביחסי מרות אין צורך להראות חוסר עניין. סעיף 6א לחוק קובע כי אם העובד הוכיח את התקיימות הפגיעה (כמו הטרדה מינית) בתוך 3 שנים, נטל ההוכחה עובר למעסיק להוכיח שלא פגע.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נטל ההוכחה כולו על המנהל/מעסיק מתחילת ההליך, שכן מדובר ביחסי מרות.', false, 'תשובה זו שגויה. נטל ההוכחה הראשוני להוכחת יסודות העבירה עדיין מוטל על התובע, ורק לאחר מכן הוא עובר לנתבע.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'על פלונית להוכיח את ההצעות החוזרות, ואין צורך להוכיח ניצול יחסי מרות.', false, 'תשובה זו שגויה. ניצול יחסי מרות הוא יסוד חשוב המאפשר את החריג לדרישת חוסר העניין ומעביר את נטל ההוכחה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q14';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הגדרת הטרדה מינית: מבחן אובייקטיבי', 2,
      'מהי אמת המידה המרכזית לסיווג התנהגות כהטרדה מינית על פי החוק והפסיקה?', 'שאלה זו עוסקת באמת המידה המשפטית לקביעת קיומה של הטרדה מינית. היא מדגישה את המבחן האובייקטיבי, כפי שנקבע בפסיקה, תוך התחשבות במכלול הנסיבות וההקשר שבו בוצעו המעשים, ולא רק בתחושות הסובייקטיביות של המוטרד או בכוונת המטריד.', 'הפסיקה קבעה כי אמת המידה לסיווג התנהגות כהטרדה מינית היא אמת מידה אובייקטיבית, הנגזרת מטיב ההתנהגות וממכלול הנסיבות שבהן התרחשה. אין צורך שהמתלוננת תדע לבטא את תחושותיה בביטויים משפטיים, ואין חשיבות לכוונת המטריד, אלא להתנהגות עצמה. המבחן האובייקטיבי משמש גם כאשר מדובר בפגיעה בכבוד או בביזוי, שאינם מותנים במידת הפגיעה הסובייקטיבית של הנפגע. יש לבחון את המעשים על פי ההקשר שבו בוצעו, טיב היחסים בין הצדדים ומכלול נסיבות העניין בכל מקרה לגופו. ע"ע (ארצי ) 39841-11-20 פלונית - אלמוני (11.07.2021). סע"ש (אזורי ת"א) 31118-07-14 יגאל צימט רביד - משה נסטלבאום (26.04.2017). עש"מ 6713/96 מדינת ישראל נ'' זוהר בן אשר (09.03.1998). ע"ע (עבודה ארצי) 68858-02-24 אלמוני - פלונית (16.02.2025)', 'הטעות הנפוצה היא להתמקד בכוונת המטריד או בתחושות הסובייקטיביות של המוטרד, במקום בבחינה אובייקטיבית של ההתנהגות והנסיבות.',
      '["הטרדה מינית", "מבחן אובייקטיבי", "נסיבות העניין", "טיב ההתנהגות", "כוונת המטריד", "פגיעה בכבוד"]'::jsonb, '**וריאציה 1 — אמת המידה:** מהי אמת המידה לסיווג הטרדה מיניתאמת מידה אובייקטיבית, הנגזרת מטיב ההתנהגות וממכלול הנסיבות (ע"ע (ארצי ) 39841-11-20 פלונית - אלמוני).
**וריאציה 2 — כוונת המטריד:** האם כוונת המטריד רלוונטיתלא, העיקר הוא ההתנהגות בעיני האדם הסביר (עש"מ 6713/96 מדינת ישראל נ'' זוהר בן אשר).
**וריאציה 3 — הקשר ונסיבות:** מה יש לבחוןאת ההקשר שבו בוצעו המעשים, טיב היחסים בין הצדדים ומכלול נסיבות העניין (סע"ש (אזורי ת"א) 31118-07-14 יגאל צימט רביד - משה נסטלבאום).', 'הטרדה מיניתמבחן אובייקטיבינסיבות והקשרלא כוונת המטריד או תחושה סובייקטיבית.', '["ע\"ע (ארצי ) 39841-11-20 פלונית - אלמוני (11.07.2021)", "סע\"ש (אזורי ת\"א) 31118-07-14 יגאל צימט רביד - משה נסטלבאום (26.04.2017)", "עש\"מ 6713/96 מדינת ישראל נ'' זוהר בן אשר (09.03.1998)", "ע\"ע (עבודה ארצי) 68858-02-24 אלמוני - פלונית (16.02.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'מבחן סובייקטיבי, המתמקד בתחושותיו הסובייקטיביות של המוטרד.', false, 'תשובה זו שגויה. אף שתחושות המוטרד חשובות, אמת המידה המרכזית היא אובייקטיבית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'מבחן אובייקטיבי, הנגזר מטיב ההתנהגות וממכלול הנסיבות שבהן התרחשה.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי אמת המידה לסיווג התנהגות כהטרדה מינית היא אובייקטיבית, תוך התחשבות בהקשר ובנסיבות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'מבחן כוונת המטריד, האם התכוון לפגוע או להטריד.', false, 'תשובה זו שגויה. הפסיקה קבעה כי אין חשיבות לכוונת המטריד, אלא להתנהגות עצמה ולהשפעתה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'מבחן תוצאתי, המתמקד בנזק שנגרם בפועל למוטרד.', false, 'תשובה זו שגויה. הטרדה מינית היא עוולה התנהגותית, ואין צורך להוכיח נזק בפועל.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q14';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'התיישנות תביעה אזרחית להטרדה מינית', 3,
      'פלונית הוטרדה מינית על ידי ממונה עליה ביום 1.1.2015. היא הגישה תביעה אזרחית בגין ההטרדה ביום 1.1.2023. האם תביעתה התיישנה? האם חלים עליה סעיפים 18א ו-18ב לחוק ההתיישנות?', 'שאלה זו בוחנת את תקופת ההתיישנות הספציפית לתביעות אזרחיות בגין הטרדה מינית והתנכלות, כפי שנקבעה בסעיף 6(ג) לחוק למניעת הטרדה מינית. היא מדגישה את העובדה שתקופה זו היא 7 שנים, וכי הסדרי ההתיישנות המיוחדים לעבירות מין (סעיפים 18א ו-18ב לחוק ההתיישנות) אינם חלים על תביעות אלו.', 'סעיף 6(ג) לחוק למניעת הטרדה מינית קובע כי בית המשפט או בית הדין לעבודה לא יזדקקו לתביעה בשל עוולה לפי סעיף זה או לפי סעיף 7, שהוגשה לאחר שחלפה התקופה הקבועה בסעיף 5 לחוק ההתיישנות, התשי"ח-1958 מיום שנוצרה העילה. סעיף 5 לחוק ההתיישנות קובע תקופת התיישנות של 7 שנים לתביעה שאינה במקרקעין. בנוסף, סעיף 6(ג) לחוק למניעת הטרדה מינית מבהיר במפורש כי הוראות סעיפים 18א ו-18ב לחוק ההתיישנות (העוסקים בהתיישנות תביעות בגין עבירות מין שבוצעו בקטינים או תוך ניצול יחסי תלות) לא יחולו על תביעה כאמור. במקרה הנדון, האירוע התרחש ב-1.1.2015 והתביעה הוגשה ב-1.1.2023, כלומר בדיוק 7 שנים לאחר מכן. לכן, התביעה לא התיישנה. סעיף 6(ג) לחוק למניעת הטרדה מינית, תשנ"ח-1998. נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | חוק למניעת הטרדה מינית, התשנ"ח-1998. טל חבקין התיישנות (2021) | חוק למניעת הטרדה מינית, התשנ"ח-1998. יצחק לובוצקי חוזה עבודה וזכויות במשפט העבודה (2021) | הטרדה מינית בעבודה', 'הטעות הנפוצה היא לבלבל בין תקופת ההתיישנות הכללית של 7 שנים לבין תקופת 3 השנים הרלוונטית להעברת נטל ההוכחה, או לחשוב שסעיפים 18א ו-18ב לחוק ההתיישנות חלים על תביעות אלו.',
      '["התיישנות", "חוק למניעת הטרדה מינית", "סעיף 6(ג)", "חוק ההתיישנות", "סעיף 5", "סעיפים 18א ו-18ב"]'::jsonb, '**וריאציה 1 — תקופת ההתיישנות:** מהי תקופת ההתיישנות לתביעה אזרחית בגין הטרדה מיניתשנים מיום היווצרות העילה (סעיף 6(ג) לחוק למניעת הטרדה מינית).
**וריאציה 2 — סעיפים 18א ו-18ב:** האם סעיפים 18א ו-18ב לחוק ההתיישנות חליםלא, סעיף 6(ג) לחוק למניעת הטרדה מינית קובע במפורש שהם לא יחולו (סעיף 6(ג) לחוק למניעת הטרדה מינית).
**וריאציה 3 — מועד היווצרות העילה:** מתי מתחילה תקופת ההתיישנותמיום שנוצרה העילה (סעיף 6(ג) לחוק למניעת הטרדה מינית).', 'התיישנות הטרדה מיניתשנים מיום העילהסעיפים 18א ו-18ב לא חלים.', '["חוק למניעת הטרדה מינית, תשנ\"ח-1998, סעיף 6(ג)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | חוק למניעת הטרדה מינית, התשנ\"ח-1998", "טל חבקין התיישנות (2021) | חוק למניעת הטרדה מינית, התשנ\"ח-1998", "יצחק לובוצקי חוזה עבודה וזכויות במשפט העבודה (2021) | הטרדה מינית בעבודה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'התביעה התיישנה, שכן חלפו 7 שנים מיום היווצרות העילה. סעיפים 18א ו-18ב חלים על תביעה זו.', false, 'תשובה זו שגויה. התביעה לא התיישנה (הוגשה בדיוק ביום האחרון של 7 השנים). סעיפים 18א ו-18ב אינם חלים על תביעות לפי החוק למניעת הטרדה מינית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'התביעה לא התיישנה, שכן תקופת ההתיישנות היא 7 שנים מיום היווצרות העילה. סעיפים 18א ו-18ב לחוק ההתיישנות אינם חלים על תביעה זו.', true, 'זו התשובה הנכונה. תקופת ההתיישנות לתביעה אזרחית בגין הטרדה מינית היא 7 שנים. התביעה הוגשה בדיוק ביום האחרון של תקופה זו. סעיף 6(ג) לחוק למניעת הטרדה מינית קובע במפורש שסעיפים 18א ו-18ב לחוק ההתיישנות אינם חלים על תביעות אלו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'התביעה התיישנה, שכן חלפו 3 שנים מיום היווצרות העילה. סעיפים 18א ו-18ב לחוק ההתיישנות חלים על תביעה זו.', false, 'תשובה זו שגויה. תקופת ההתיישנות היא 7 שנים, לא 3. סעיפים 18א ו-18ב אינם חלים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'התביעה לא התיישנה, שכן תקופת ההתיישנות היא 10 שנים מיום היווצרות העילה. סעיפים 18א ו-18ב לחוק ההתיישנות חלים על תביעה זו.', false, 'תשובה זו שגויה. תקופת ההתיישנות היא 7 שנים, לא 10. סעיפים 18א ו-18ב אינם חלים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q14';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'אחריות מעסיק למניעת הטרדה מינית', 4,
      'מהן חובותיו העיקריות של מעסיק למניעת הטרדה מינית והתנכלות במקום העבודה, ומהי אחריותו אם לא מילא חובות אלו?', 'שאלה זו עוסקת בחובות המעסיק למניעת הטרדה מינית והתנכלות במקום העבודה, ובאחריותו האזרחית במקרה של הפרת חובות אלו. היא מתבססת על סעיף 7 לחוק למניעת הטרדה מינית ועל תקנות למניעת הטרדה מינית (חובות מעסיק), המטילים על המעסיק חובות אקטיביות ליצירת סביבת עבודה בטוחה.', 'סעיף 7(א) לחוק למניעת הטרדה מינית מטיל על מעסיק חובה לנקוט אמצעים סבירים, בנסיבות העניין, כדי למנוע הטרדה מינית או התנכלות במסגרת יחסי עבודה, ולטפל בכל מקרה כאמור. חובות אלו כוללות קביעת דרך יעילה להגשת תלונה ולבירורה, וטיפול יעיל במקרה שידע אודותיו. מעסיק המעסיק יותר מ-25 עובדים חייב גם לקבוע ולפרסם תקנון. סעיף 7(ג) קובע כי מעסיק שלא מילא את חובותיו אלו, יהיה אחראי לעוולה אזרחית לפי סעיף 6 לחוק, או לעוולה אזרחית בשל פגיעה כאמור בסעיף 7 לחוק שוויון ההזדמנויות בעבודה, שעשה עובדו או ממונה מטעמו. אחריות זו נובעת מחובת האמון של המעסיק כלפי עובדיו לדאוג לרווחתם ולספק סביבת עבודה חפה ממעשים אלו. סעיף 7(א) לחוק למניעת הטרדה מינית, תשנ"ח-1998. סעיף 7(ג) לחוק למניעת הטרדה מינית, תשנ"ח-1998. ע"ע (עבודה ארצי) 2715-03-17 אלבר ציי רכב (ר.צ.) בע״מ - פלוני (28.04.2019). סע"ש (עבודה חיפה) 32518-02-20 פלונית - מדינת ישראל - משרד החינוך התרבות והספורט (01.09.2024)', 'הטעות הנפוצה היא לחשוב שאחריות המעסיק מוגבלת למעשיו הישירים או לפרסום תקנון בלבד, ולא להבין את היקף חובותיו האקטיביות ואחריותו השילוחית.',
      '["אחריות מעסיק", "חובות מעסיק", "חוק למניעת הטרדה מינית", "סעיף 7", "התנכלות", "סביבת עבודה בטוחה"]'::jsonb, '**וריאציה 1 — חובות אקטיביות:** מהן חובות המעסיק למניעה וטיפוללנקוט אמצעים סבירים, לקבוע דרך יעילה לתלונה ולטפל ביעילות (סעיף 7(א) לחוק למניעת הטרדה מינית).
**וריאציה 2 — אחריות שילוחית:** מתי המעסיק אחראי למעשי עובדיואם לא מילא את חובותיו לפי סעיף 7(א) ו-(ב) (סעיף 7(ג) לחוק למניעת הטרדה מינית).
**וריאציה 3 — תכלית האחריות:** מהי תכלית הטלת האחריות על המעסיקלהבטיח סביבת עבודה נאותה ושוויונית השומרת על כבוד העובדים (ע"ע (עבודה ארצי) 2715-03-17 אלבר ציי רכב (ר.צ.) בע״מ - פלוני).', 'מעסיקחובות מניעה וטיפול (סעיףאחריות לעוולות עובדיו אם הפר חובותיו (סעיף 7(גליצירת סביבת עבודה בטוחה.', '["חוק למניעת הטרדה מינית, תשנ\"ח-1998, סעיף 7", "ע\"ע (עבודה ארצי) 2715-03-17 אלבר ציי רכב (ר.צ.) בע״מ - פלוני (28.04.2019)", "סע\"ש (עבודה חיפה) 32518-02-20 פלונית - מדינת ישראל - משרד החינוך התרבות והספורט (01.09.2024)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'על המעסיק לנקוט אמצעים סבירים למניעה ולטיפול, ואם לא עשה כן, הוא יהיה אחראי לעוולה אזרחית שביצע עובדו או ממונה מטעמו.', true, 'זו התשובה הנכונה. סעיף 7 לחוק למניעת הטרדה מינית מטיל חובות אקטיביות על המעסיק, וסעיף 7(ג) קובע את אחריותו לעוולות שבוצעו על ידי עובדיו אם לא מילא חובות אלו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'על המעסיק לפרסם תקנון בלבד, ואין לו אחריות מעבר לכך למעשי עובדיו.', false, 'תשובה זו שגויה. פרסום תקנון הוא רק אחת מהחובות, והמעסיק נושא באחריות רחבה יותר למניעה ולטיפול.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המעסיק אחראי רק למעשים שביצע הוא עצמו, ולא למעשי עובדיו או ממונים מטעמו.', false, 'תשובה זו שגויה. סעיף 7(ג) לחוק מטיל אחריות על המעסיק גם למעשי עובדיו או ממונים מטעמו, אם לא מילא את חובותיו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'המעסיק חייב לנקוט אמצעים למניעה רק אם קיבל תלונה רשמית על הטרדה מינית.', false, 'תשובה זו שגויה. חובות המעסיק הן אקטיביות וכוללות מניעה גם ללא תלונה, וטיפול יעיל במקרה שידע אודותיו.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q14';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 14, '2024-W-S-Q14';
END
$$;

-- ============================================================
-- Q15 — angles backfill for 2024-W-S-Q15 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q15';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q15';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'מינוי ממונה במקרה של השעיה', 1,
      'עו"ד שרה הושעתה מלשכת עורכי הדין לתקופה של שלוש שנים. בית המשפט המחוזי מינה את עו"ד דניאל להיות ממונה על ענייניה המקצועיים. מהי תקופת המינוי המקסימלית במקרה זה?', 'שאלה זו בוחנת את היקף תחולתו של סעיף 89א לחוק לשכת עורכי הדין, העוסק במינוי ממונה על ענייניו המקצועיים של עורך דין. היא מדגישה כי תקופת המינוי המקסימלית היא שנתיים, וכי הוראה זו חלה באופן אחיד על כלל המקרים המנויים בסעיף, לרבות פטירה, השעיה, או נסיבות אחרות המונעות מעורך הדין לטפל בענייניו.', 'סעיף 89א(א) לחוק לשכת עורכי הדין, התשכ"א-1961, קובע כי בית המשפט המחוזי רשאי למנות ממונה על ענייניו המקצועיים של עורך דין במקרים שונים, ובהם פטירה, השעיה, או נסיבות אחרות המונעות ממנו לטפל בענייניו. סעיף 89א(ב) קובע במפורש כי "תקופת המינוי לא תעלה על שנתיים". הוראה זו היא כללית ואינה מבחינה בין עילות המינוי השונות. לכן, גם במקרה של השעיה, תקופת המינוי המקסימלית של הממונה תהיה שנתיים, ללא קשר לאורך תקופת ההשעיה עצמה. סעיף 89א(ב) לחוק לשכת עורכי הדין, התשכ"א-1961. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי', 'הטעות הנפוצה היא להניח שתקופת המינוי של הממונה תואמת את תקופת ההשעיה, במקום להכיר בהוראת החוק הספציפית המגבילה את המינוי לשנתיים.',
      '["מינוי ממונה", "חוק לשכת עורכי הדין", "השעיה", "תקופת מינוי", "סעיף 89א"]'::jsonb, '**וריאציה 1 — תקופת מינוי כללית:** מהי תקופת המינוי המקסימלית לממונהשנתיים, ללא קשר לעילת המינוי (סעיף 89א(ב) לחוק לשכת עורכי הדין).
**וריאציה 2 — השוואה לפטירה:** האם יש הבדל בין פטירה להשעיה לעניין תקופת המינוילא, בשני המקרים התקופה המקסימלית היא שנתיים (סעיף 89א(ב) לחוק לשכת עורכי הדין).
**וריאציה 3 — תכלית ההגבלה:** מדוע קיימת הגבלה על תקופת המינויכדי לאפשר טיפול מסודר בענייני עורך הדין, אך לא להנציח מצב זמני (יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022)).', 'מינוי ממונה (פטירה/השעיהתקופת מינוי מקסימלית שנתייםללא קשר לעילה.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 89א(ב)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'שנתיים, בדומה למקרה של פטירה.', true, 'זו התשובה הנכונה. סעיף 89א(ב) לחוק לשכת עורכי הדין קובע כי תקופת המינוי לא תעלה על שנתיים, בין אם המינוי נעשה עקב פטירה, השעיה או נסיבות אחרות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'שלוש שנים, בדומה לתקופת ההשעיה.', false, 'תשובה זו שגויה. תקופת המינוי המקסימלית של הממונה אינה נקבעת לפי תקופת ההשעיה, אלא לפי הוראת החוק העומדת על שנתיים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שנה, בדומה למקרה של פטירה.', false, 'תשובה זו שגויה. תקופת המינוי המקסימלית היא שנתיים, ולא שנה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'חמש שנים, שכן מדובר בהשעיה ולא בפטירה.', false, 'תשובה זו שגויה. תקופת המינוי המקסימלית היא שנתיים, ואין הבחנה לעניין זה בין פטירה להשעיה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q15';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תפקידי הממונה וסמכויותיו', 2,
      'עו"ד ראובן מונה כממונה על ענייניו המקצועיים של עו"ד פנחס המנוח. מהם תפקידיו וסמכויותיו העיקריים של עו"ד ראובן כממונה?', 'שאלה זו מתמקדת בתפקידים ובסמכויות המפורטים של ממונה על ענייניו המקצועיים של עורך דין, כפי שנקבעו בסעיף 89ב לחוק לשכת עורכי הדין. היא מדגישה את אופיו המוגבל של תפקיד הממונה, שנועד להבטיח את המשך הטיפול בענייני הלקוחות הקיימים ולשמור על האינטרסים המקצועיים, ולא לנהל את המשרד כעסק רגיל.', 'סעיף 89ב לחוק לשכת עורכי הדין, התשכ"א-1961, מפרט את תפקידי הממונה. בין היתר, תפקידיו כוללים: (1) לשמור על ענייני הלקוחות של עורך הדין; (2) להעביר תיקים לעורכי דין אחרים, לפי בקשת הלקוחות או לפי שיקול דעתו של הממונה, באישור בית המשפט; (3) לפעול לגביית שכר טרחה עבור עבודות שבוצעו על ידי עורך הדין; (4) להגיש דו"ח לבית המשפט וללשכת עורכי הדין. תפקיד הממונה אינו לנהל את המשרד כעסק חי, לקבל לקוחות חדשים או לטפל בענייני העיזבון הכלליים של עורך הדין. סעיף 89ב לחוק לשכת עורכי הדין, התשכ"א-1961. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי', 'הטעות הנפוצה היא להרחיב את סמכויות הממונה מעבר לתפקידיו המוגדרים בחוק, ולחשוב שהוא פועל כנאמן כללי או כמנהל עסק.',
      '["ממונה על ענייני עורך דין", "סמכויות ממונה", "חוק לשכת עורכי הדין", "שמירה על ענייני לקוחות", "העברת תיקים", "גביית שכר טרחה"]'::jsonb, '**וריאציה 1 — תפקיד מרכזי:** מהו התפקיד המרכזי של הממונהלשמור על ענייני הלקוחות של עורך הדין (סעיף 89ב(1) לחוק לשכת עורכי הדין).
**וריאציה 2 — העברת תיקים:** האם הממונה יכול להעביר תיקיםכן, לפי בקשת הלקוחות או שיקול דעתו, באישור בית המשפט (סעיף 89ב(2) לחוק לשכת עורכי הדין).
**וריאציה 3 — גביית שכר טרחה:** האם הממונה גובה שכר טרחהכן, עבור עבודות שבוצעו על ידי עורך הדין (סעיף 89ב(3) לחוק לשכת עורכי הדין).', 'תפקידי ממונהשמירה על לקוחות, העברת תיקים, גביית שכר טרחהלא ניהול עסק או עיזבון.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 89ב", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לנהל את משרדו של עו"ד פנחס כעסק חי, כולל קבלת לקוחות חדשים וייצוגם.', false, 'תשובה זו שגויה. תפקיד הממונה אינו לנהל את המשרד כעסק חי או לקבל לקוחות חדשים, אלא לטפל בעניינים קיימים ולשמור על האינטרסים של הלקוחות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לשמור על ענייני הלקוחות, להעביר תיקים לעורכי דין אחרים, ולפעול לגביית שכר טרחה עבור עבודות שבוצעו.', true, 'זו התשובה הנכונה. סעיף 89ב לחוק לשכת עורכי הדין מפרט את תפקידי הממונה, ובהם שמירה על ענייני הלקוחות, העברת תיקים וגביית שכר טרחה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לשמש כנאמן על נכסי העיזבון של עו"ד פנחס, ולחלקם בין היורשים.', false, 'תשובה זו שגויה. תפקיד הממונה מוגבל לעניינים המקצועיים של עורך הדין, ואינו כולל טיפול בנכסי העיזבון או חלוקתם ליורשים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לייצג את עזבונו של עו"ד פנחס בכל הליך משפטי שיתנהל נגדו.', false, 'תשובה זו שגויה. תפקיד הממונה הוא לטפל בעניינים המקצועיים של עורך הדין, ולא לייצג את העיזבון בהליכים משפטיים כלליים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q15';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'הארכת תקופת המינוי', 3,
      'עו"ד ראובן מונה כממונה על ענייניו המקצועיים של עו"ד פנחס המנוח לתקופה של שנתיים. לקראת תום התקופה, התברר כי נותרו מספר תיקים מורכבים שטרם הועברו או נסתיימו. האם ניתן להאריך את תקופת המינוי של עו"ד ראובן?', 'שאלה זו עוסקת בחריג לכלל תקופת המינוי של ממונה, והיא בוחנת את סמכותו של בית המשפט להאריך את תקופת המינוי מעבר לשנתיים הראשונות. היא מדגישה את ההגבלה הקבועה בחוק, לפיה סך כל תקופת המינוי, כולל הארכות, לא תעלה על שלוש שנים.', 'סעיף 89א(ב) לחוק לשכת עורכי הדין, התשכ"א-1961, קובע כי "תקופת המינוי לא תעלה על שנתיים, ואולם רשאי בית המשפט להאריך את תקופת המינוי לתקופה נוספת, ובלבד שסך כל תקופת המינוי לא תעלה על שלוש שנים". כלומר, אף שהכלל הוא שנתיים, במקרים חריגים שבהם נדרש זמן נוסף לטיפול בעניינים המקצועיים, בית המשפט רשאי להאריך את המינוי, אך הארכה זו מוגבלת כך שסך כל תקופת המינוי לא תעלה על שלוש שנים. סעיף 89א(ב) לחוק לשכת עורכי הדין, התשכ"א-1961. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי', 'הטעות הנפוצה היא לחשוב שתקופת המינוי היא מוחלטת ואינה ניתנת להארכה, או לחשוב שניתן להאריך אותה ללא הגבלת זמן.',
      '["הארכת מינוי", "ממונה על ענייני עורך דין", "חוק לשכת עורכי הדין", "סעיף 89א(ב)", "סמכות בית המשפט"]'::jsonb, '**וריאציה 1 — הארכה אפשרית:** האם ניתן להאריך את תקופת המינויכן, בית המשפט רשאי להאריך (סעיף 89א(ב) לחוק לשכת עורכי הדין).
**וריאציה 2 — הגבלת הארכה:** מהי ההגבלה על הארכת המינויסך כל תקופת המינוי לא תעלה על שלוש שנים (סעיף 89א(ב) לחוק לשכת עורכי הדין).
**וריאציה 3 — תכלית ההגבלה הכוללת:** מדוע קיימת הגבלה כוללת של שלוש שניםכדי לאפשר גמישות במקרים מורכבים, אך עדיין לשמור על אופי זמני של המינוי (יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022)).', 'הארכת מינוי ממונהאפשרית באישור ביהמ"שסך הכל עד 3 שנים.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 89א(ב)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, תקופת המינוי היא קוגנטית ואינה ניתנת להארכה בשום מקרה.', false, 'תשובה זו שגויה. החוק מאפשר הארכה של תקופת המינוי במקרים חריגים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, בית המשפט רשאי להאריך את תקופת המינוי לתקופה נוספת, ובלבד שסך כל תקופת המינוי לא תעלה על שלוש שנים.', true, 'זו התשובה הנכונה. סעיף 89א(ב) לחוק לשכת עורכי הדין מאפשר לבית המשפט להאריך את תקופת המינוי לתקופה נוספת, ובלבד שסך כל התקופה לא תעלה על שלוש שנים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, בית המשפט רשאי להאריך את תקופת המינוי ללא הגבלת זמן, אם הדבר נחוץ לטיפול בעניינים.', false, 'תשובה זו שגויה. החוק קובע הגבלה על סך כל תקופת המינוי, גם במקרה של הארכה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם הוועד המחוזי יבקש זאת וכל הלקוחות יסכימו בכתב.', false, 'תשובה זו שגויה. הארכה אינה מותנית בהסכמת כל הלקוחות, אלא בשיקול דעת בית המשפט, ובהגבלת זמן.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q15';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות בית המשפט למינוי ממונה', 4,
      'מי רשאי לבקש מבית המשפט המחוזי למנות ממונה על ענייניו המקצועיים של עורך דין, ומהם השיקולים המנחים את בית המשפט בהחלטתו?', 'שאלה זו עוסקת בסמכותו של בית המשפט המחוזי למנות ממונה על ענייניו המקצועיים של עורך דין, ובגורמים הרשאים לבקש מינוי כזה. היא מדגישה את שיקול הדעת הרחב של בית המשפט, הכולל בחינה של טובת הלקוחות, טובת עורך הדין עצמו, וטובת הציבור בכללותה.', 'סעיף 89א(א) לחוק לשכת עורכי הדין, התשכ"א-1961, קובע כי בית המשפט המחוזי רשאי למנות ממונה על ענייניו המקצועיים של עורך דין "לבקשת הוועד המחוזי או לבקשת היועץ המשפטי לממשלה". הפסיקה קבעה כי בית המשפט מפעיל שיקול דעת רחב בבואו להחליט על מינוי ממונה, וכי עליו לבחון את טובת הלקוחות, טובת עורך הדין (או עזבונו במקרה של פטירה), וכן את טובת הציבור בכללותה. המינוי אינו אוטומטי, ובית המשפט ישקול את כלל הנסיבות והאינטרסים הרלוונטיים. סעיף 89א(א) לחוק לשכת עורכי הדין, התשכ"א-1961. רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022). יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי', 'הטעות הנפוצה היא לחשוב שרק הוועד המחוזי רשאי לבקש מינוי, או שבית המשפט ממנה ממונה באופן אוטומטי ללא שיקול דעת.',
      '["סמכות בית המשפט", "מינוי ממונה", "חוק לשכת עורכי הדין", "וועד מחוזי", "יועץ משפטי לממשלה", "שיקול דעת שיפוטי"]'::jsonb, '**וריאציה 1 — מגישי הבקשה:** מי רשאי לבקש מינוי ממונההוועד המחוזי או היועץ המשפטי לממשלה (סעיף 89א(א) לחוק לשכת עורכי הדין).
**וריאציה 2 — שיקולי בית המשפט:** מהם השיקולים המנחים את בית המשפטטובת הלקוחות, טובת עורך הדין וטובת הציבור (רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל).
**וריאציה 3 — אופי המינוי:** האם המינוי אוטומטילא, בית המשפט מפעיל שיקול דעת רחב (רע"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל).', 'מינוי ממונהלבקשת הוועד המחוזי/יועמ"שביהמ"ש שוקל טובת לקוחות, עו"ד וציבור.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 89א(א)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (08.02.2022)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 7 מאסר על-תנאי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק הוועד המחוזי של לשכת עורכי הדין רשאי לבקש מינוי, ובית המשפט יבחן רק את טובת הלקוחות.', false, 'תשובה זו שגויה. גם היועץ המשפטי לממשלה רשאי לבקש מינוי, ובית המשפט שוקל שיקולים רחבים יותר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הוועד המחוזי או היועץ המשפטי לממשלה רשאים לבקש מינוי, ובית המשפט יבחן את טובת הלקוחות, טובת עורך הדין וטובת הציבור.', true, 'זו התשובה הנכונה. סעיף 89א(א) לחוק לשכת עורכי הדין קובע מי רשאי לבקש מינוי, והפסיקה מפרטת את השיקולים הרחבים של בית המשפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כל אדם המעוניין בדבר רשאי לבקש מינוי, ובית המשפט ימנה ממונה באופן אוטומטי אם מתקיימת אחת העילות.', false, 'תשובה זו שגויה. רק גורמים ספציפיים רשאים לבקש מינוי, ובית המשפט מפעיל שיקול דעת ולא ממנה באופן אוטומטי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק לקוחותיו של עורך הדין רשאים לבקש מינוי, ובית המשפט ימנה ממונה רק אם כל הלקוחות מסכימים.', false, 'תשובה זו שגויה. לקוחות אינם הגורם היחיד הרשאי לבקש מינוי, ואין דרישה להסכמת כל הלקוחות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q15';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 15, '2024-W-S-Q15';
END
$$;

-- ============================================================
-- Q16 — angles backfill for 2024-W-S-Q16 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q16';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q16';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'מבחני השפעה בלתי הוגנת', 1,
      'מר כהן, קשיש ערירי, התגורר בביתו עם מטפלת זרה. המטפלת דאגה לכל צרכיו, ניהלה את ענייניו הכספיים ומנעה ממנו קשר עם קרובי משפחה רחוקים. לאחר פטירתו, התגלתה צוואה שבה הוריש מר כהן את כל רכושו למטפלת. קרובי המשפחה טוענים להשפעה בלתי הוגנת. אילו מבחנים יבחן בית המשפט כדי לקבוע אם אכן הייתה השפעה בלתי הוגנת?', 'שאלה זו עוסקת במבחנים שנקבעו בפסיקה, בעיקר בהלכת דנ"א 1516/95 מרום, לבחינת קיומה של השפעה בלתי הוגנת על מצווה. מבחנים אלו מסייעים לבית המשפט להכריע בשאלת שלילת רצונו החופשי של המצווה, כאשר אין ראיות ישירות להשפעה פסולה.', 'הפסיקה, ובראשה הלכת דנ"א 1516/95 מרום, קבעה ארבעה מבחני עזר מרכזיים לבחינת קיומה של השפעה בלתי הוגנת: (1) מבחן התלות והעצמאות של המצווה – האם המצווה היה תלוי באדם אחר באופן מקיף ויסודי? (2) מבחן התלות והסיוע – האם המצווה נזקק לסיוע מהנהנה, ובאיזה היקף? (3) קשרי המצווה עם אחרים – האם הנהנה ניתק את המצווה מקשריו עם אנשים אחרים? (4) נסיבות עריכת הצוואה – האם הנהנה היה מעורב בעריכת הצוואה, והאם נסיבות העריכה מעלות חשד? בחינת כלל הנסיבות הללו מאפשרת לבית המשפט להסיק אם רצונו החופשי של המצווה נשלל. דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה (22.06.1998). ת"ע (משפחה חיפה) 19321-11-18 ג'' ו'' נ'' א'' ב'' ד'' (03.09.2020). ת"ע (משפחה תל אביב-יפו) 13844-04-22 ב.ג. נ'' מ. ג (15.01.2024). בני דון-יחייא תורת דיני הירושה (2024) | שער 17 התנגדות לצוואות וביטול צוואות', 'הטעות הנפוצה היא להתמקד בראיה אחת בלבד, במקום לבחון את מכלול הנסיבות והמבחנים שנקבעו בפסיקה.',
      '["השפעה בלתי הוגנת", "מבחני מרום", "תלות ועצמאות", "תלות וסיוע", "נסיבות עריכת צוואה", "רצון חופשי"]'::jsonb, '**וריאציה 1 — מבחן התלות:** האם המצווה היה תלוי בנהנה באופן מקיף ויסודיכן, זהו אחד ממבחני מרום (דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה).
**וריאציה 2 — קשרי המצווה עם אחרים:** האם הנהנה ניתק את המצווה מקשריוכן, זהו מבחן נוסף לבחינת השפעה בלתי הוגנת (דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה).
**וריאציה 3 — נסיבות עריכת הצוואה:** האם נסיבות עריכת הצוואה מעלות חשדכן, זהו מבחן עזר נוסף לקביעת השפעה בלתי הוגנת (דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה).', 'השפעה בלתי הוגנתנבחנת לפי מבחני מרום: תלות, סיוע, קשרים עם אחרים, נסיבות עריכהלשלילת רצון חופשי.', '["חוק הירושה, תשכ\"ה-1965, סעיף 30(א)", "דנ\"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה (22.06.1998)", "ת\"ע (משפחה חיפה) 19321-11-18 ג'' ו'' נ'' א'' ב'' ד'' (03.09.2020)", "ת\"ע (משפחה תל אביב-יפו) 13844-04-22 ב.ג. נ'' מ. ג (15.01.2024)", "בני דון-יחייא תורת דיני הירושה (2024) | שער 17 התנגדות לצוואות וביטול צוואות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק את מצבו הפיזי והנפשי של המצווה בעת עריכת הצוואה.', false, 'תשובה זו שגויה. מצבו הפיזי והנפשי הוא רק אחד ממבחני העזר, ואין הוא המבחן היחיד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'את מבחן התלות והעצמאות, מבחן התלות והסיוע, קשרי המצווה עם אחרים ונסיבות עריכת הצוואה.', true, 'זו התשובה הנכונה. אלו הם ארבעת מבחני העזר שנקבעו בפסיקה (הלכת מרום) לבחינת קיומה של השפעה בלתי הוגנת.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק את מידת המעורבות של המטפלת בעריכת הצוואה.', false, 'תשובה זו שגויה. מעורבות הנהנה בעריכת הצוואה היא עילה נפרדת לבטלות (סעיף 35 לחוק הירושה), וגם אם היא אינדיקציה להשפעה בלתי הוגנת, היא אינה המבחן היחיד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק את כוונת המטפלת לפגוע במר כהן.', false, 'תשובה זו שגויה. כוונת המטריד אינה רלוונטית לקביעת השפעה בלתי הוגנת, אלא ההשפעה עצמה והפגיעה ברצונו החופשי של המצווה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q16';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'נטל ההוכחה בהשפעה בלתי הוגנת', 2,
      'מי נושא בנטל ההוכחה לקיומה של השפעה בלתי הוגנת על מצווה, וכיצד נטל זה עשוי להשתנות במהלך ההליך?', 'שאלה זו עוסקת בחלוקת נטל ההוכחה בתביעות לביטול צוואה מחמת השפעה בלתי הוגנת. היא מבחינה בין נטל השכנוע (הנותר על המתנגד) לבין נטל הבאת הראיות (העשוי לעבור למבקש קיום הצוואה בנסיבות מסוימות), כפי שנקבע בהלכת דנ"א 1516/95 מרום.', 'הכלל הוא שנטל השכנוע לקיומה של השפעה בלתי הוגנת מוטל על הטוען לפסלות הצוואה, כלומר על המתנגד לקיומה. עם זאת, הפסיקה קבעה כי כאשר הנסיבות מצביעות על קיומה של תלות מקיפה ויסודית של המצווה בזולתו, באופן שניתן להניח שנשלל רצונו החופשי, אזי נטל הבאת הראיות (חובת ההוכחה לסתור) עובר אל שכמו של מבקש קיום הצוואה. נטל זה קל יותר מנטל השכנוע, והוא מחייב את מבקש הקיום להוכיח שלא התקיימה השפעה בלתי הוגנת. נטל השכנוע הסופי, לעומת זאת, נשאר תמיד על המתנגד לצוואה. דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה (22.06.1998). רמ"ש (מחוזי תל אביב-יפו) 27644-11-17 מ.מ.ח נ'' ת.מ (26.03.2018). ת"ע (משפחה צפת) 52648-11-22 פלונית נ'' אלמונית (05.01.2026). בני דון-יחייא תורת דיני הירושה (2024) | שער 17 התנגדות לצוואות וביטול צוואות', 'הטעות הנפוצה היא לבלבל בין נטל השכנוע לנטל הבאת הראיות, ולחשוב שנטל השכנוע עובר במלואו למבקש קיום הצוואה.',
      '["נטל הוכחה", "נטל שכנוע", "נטל הבאת ראיות", "השפעה בלתי הוגנת", "חזקה עובדתית", "תלות מקיפה ויסודית"]'::jsonb, '**וריאציה 1 — נטל שכנוע:** מי נושא בנטל השכנוע להשפעה בלתי הוגנתהמתנגד לצוואה (דנ"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה).
**וריאציה 2 — נטל הבאת ראיות:** מתי עובר נטל הבאת הראיותכאשר הוכחה תלות מקיפה ויסודית של המצווה בנהנה (רמ"ש (מחוזי תל אביב-יפו) 27644-11-17 מ.מ.ח נ'' ת.מ).
**וריאציה 3 — חזקה עובדתית:** מהי חזקה עובדתית בהקשר זהמערכת נסיבות המעלה חשד שנשלל רצונו החופשי של המצווה, ומקימה חזקה לשלילת הרצון החופשי (עמ"ש (מחוזי חיפה) 7980-01-15 עיזבון המנוח א. ק נ'' אלמוני).', 'נטל שכנוע על המתנגדנטל הבאת ראיות עובר למבקש קיום אם הוכחה תלות מקיפהנטל שכנוע נשאר על המתנגד.', '["חוק הירושה, תשכ\"ה-1965, סעיף 30(א)", "דנ\"א 1516/95 רינה מרום נ'' היועץ המשפטי לממשלה (22.06.1998)", "רמ\"ש (מחוזי תל אביב-יפו) 27644-11-17 מ.מ.ח נ'' ת.מ (26.03.2018)", "ת\"ע (משפחה צפת) 52648-11-22 פלונית נ'' אלמונית (05.01.2026)", "בני דון-יחייא תורת דיני הירושה (2024) | שער 17 התנגדות לצוואות וביטול צוואות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'נטל השכנוע מוטל תמיד על המתנגד לצוואה, אך נטל הבאת הראיות יכול לעבור למבקש קיום הצוואה אם הוכחה תלות מקיפה ויסודית.', true, 'זו התשובה הנכונה. הכלל הוא שנטל השכנוע על המתנגד. במקרים של תלות מקיפה, נטל הבאת הראיות עובר למבקש הקיום, אך נטל השכנוע נשאר על המתנגד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'נטל השכנוע ונטל הבאת הראיות מוטלים תמיד על המתנגד לצוואה.', false, 'תשובה זו שגויה. במקרים מסוימים, נטל הבאת הראיות יכול לעבור למבקש קיום הצוואה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'נטל השכנוע ונטל הבאת הראיות מוטלים תמיד על מבקש קיום הצוואה.', false, 'תשובה זו שגויה. נטל השכנוע הראשוני מוטל על המתנגד לצוואה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'נטל ההוכחה עובר אוטומטית למבקש קיום הצוואה אם הנהנה היה קרוב משפחה של המצווה.', false, 'תשובה זו שגויה. קרבת משפחה כשלעצמה אינה מעבירה את נטל ההוכחה, אלא נדרשת תלות מקיפה ויסודית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q16';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'מקרים בהם סעיף 31 אינו חל', 3,
      'המנוחה שרה ערכה צוואה לטובת בנה, לאחר שהלה איים עליה שינתק עמה קשר אם לא תעשה כן. האיומים נמשכו עד יום פטירתה של שרה, והיא לא הייתה מסוגלת לשנות את צוואתה עקב מצבה הקוגניטיבי שהתדרדר. האם במקרה זה יחול סעיף 31 לחוק הירושה, וימנע את ביטול הצוואה?', 'שאלה זו בוחנת את התנאים המצטברים לתחולת סעיף 31 לחוק הירושה, הקובע כי פגם בצוואה לא יהווה עילה לביטולה אם חלפה שנה מאז שהפגם חדל לפעול והמצווה יכול היה לבטל את הצוואה ולא עשה כן. השאלה מדגישה מקרים בהם תנאים אלו אינם מתקיימים, ולכן הסעיף לא יחול.', 'סעיף 31 לחוק הירושה קובע שני תנאים מצטברים לתחולתו: (1) עברה שנה מהיום שהאונס, האיום, ההשפעה הבלתי הוגנת או התחבולה חדלו לפעול על המצווה, או מהיום שנודע למצווה על התרמית או הטעות; ו-(2) היה בידי המצווה לבטל את הצוואה ולא עשה כן. במקרה הנדון, האיומים נמשכו עד יום פטירתה של שרה, ולכן התנאי הראשון (שהפגם חדל לפעול) לא התקיים. בנוסף, מצבה הקוגניטיבי של שרה התדרדר, ולכן היא לא הייתה ביכולתה לבטל את הצוואה, כך שגם התנאי השני לא התקיים. משכך, סעיף 31 לא יחול, והצוואה עשויה להיות בטלה מחמת איום. סעיף 31 לחוק הירושה, תשכ"ה-1965. עמ"ש (מחוזי תל אביב-יפו) 78000-05-24 בועז אפגין נ'' אלמוני (17.02.2025). ע"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי (16.03.2000). נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | חוק הירושה, התשכ"ה-1965', 'הטעות הנפוצה היא להניח שסעיף 31 חל באופן גורף לאחר שנה, מבלי לבחון אם הפגם אכן חדל לפעול ושהמצווה היה מסוגל לבטל את הצוואה.',
      '["סעיף 31 לחוק הירושה", "איום", "השפעה בלתי הוגנת", "כשרות לצוות", "ביטול צוואה", "תנאים מצטברים"]'::jsonb, '**וריאציה 1 — הפסקת הפגם:** האם סעיף 31 חל אם הפגם לא חדל לפעוללא, הסעיף דורש שהפגם יחדל לפעול (סעיף 31 לחוק הירושה).
**וריאציה 2 — יכולת ביטול:** האם סעיף 31 חל אם המצווה לא יכול היה לבטל את הצוואהלא, הסעיף דורש שהיה בידי המצווה לבטל את הצוואה (סעיף 31 לחוק הירושה).
**וריאציה 3 — נטל ההוכחה על הפסקת הפגם:** מי צריך להוכיח שההשפעה חדלה לפעולהחובה להוכיח כי ההשפעה הבלתי הוגנת פגה מוטלת על המבקש להכשיר צוואה שנעשתה מחמת השפעה בלתי הוגנת (ע"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי).', 'סעיף 31 לא חלאם הפגם לא חדל לפעולאו אם המצווה לא יכול היה לבטל את הצוואה.', '["חוק הירושה, תשכ\"ה-1965, סעיף 31", "עמ\"ש (מחוזי תל אביב-יפו) 78000-05-24 בועז אפגין נ'' אלמוני (17.02.2025)", "ע\"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי (16.03.2000)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | חוק הירושה, התשכ\"ה-1965"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, סעיף 31 חל תמיד אם עברה שנה ממועד עריכת הצוואה.', false, 'תשובה זו שגויה. סעיף 31 אינו חל אוטומטית ממועד עריכת הצוואה, אלא ממועד הפסקת ההשפעה או הידיעה על הפגם, ובתנאי שהמצווה יכול היה לבטל את הצוואה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, סעיף 31 לא יחול, שכן האיומים לא חדלו לפעול על המנוחה, והיא לא הייתה ביכולתה לבטל את הצוואה.', true, 'זו התשובה הנכונה. סעיף 31 דורש שהפגם יחדל לפעול ושהמצווה יוכל לבטל את הצוואה. במקרה זה, שני התנאים לא התקיימו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם בנה של שרה יוכיח כי שרה הייתה כשירה לצוות בעת עריכת הצוואה.', false, 'תשובה זו שגויה. כשרות לצוות בעת עריכת הצוואה אינה מבטלת את השפעת האיומים שנמשכו, ואינה מאפשרת את תחולת סעיף 31 במקרה זה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אך רק אם יוכח שהבן היה מעורב בעריכת הצוואה באופן ישיר.', false, 'תשובה זו שגויה. מעורבות ישירה של הנהנה היא עילה נפרדת לבטלות (סעיף 35), ואינה התנאי היחיד לאי-תחולת סעיף 31.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q16';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'מעורבות נהנה בעריכת צוואה', 4,
      'המנוח יוסף הוריש בצוואתו את כל רכושו לבתו היחידה, שרה. שרה היא זו שערכה את הצוואה בעצמה, והביאה אותה לאביה לחתימה. האם הוראת הצוואה המזכה את שרה בטלה?', 'שאלה זו עוסקת בסעיף 35 לחוק הירושה, הקובע בטלות מוחלטת של הוראת צוואה המזכה מי שערך אותה, היה עד לעשייתה, או לקח באופן אחר חלק בעריכתה. סעיף זה מבטא חזקה חלוטה בדבר השפעה בלתי הוגנת, ואינו מאפשר סתירה של חזקה זו.', 'סעיף 35 לחוק הירושה, תשכ"ה-1965, קובע כי "הוראת צוואה, פרט לצוואה בעל-פה, המזכה את מי שערך אותה או היה עד לעשייתה או לקח באופן אחר חלק בעריכתה, והוראת צוואה המזכה בן-זוגו של אחד מאלה - בטלה". סעיף זה יוצר חזקה חלוטה (שאינה ניתנת לסתירה) של השפעה בלתי הוגנת, או למצער, חשש כבד לניגוד עניינים, ונועד להבטיח את טוהר רצון המצווה. במקרה הנדון, שרה ערכה את הצוואה בעצמה, ולכן הוראת הצוואה המזכה אותה בטלה מכוח סעיף 35. סעיף 35 לחוק הירושה, תשכ"ה-1965. ע"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי (16.03.2000). ת"ע (משפחה תל אביב-יפו) 13844-04-22 ב.ג. נ'' מ. ג (15.01.2024). דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך ב (2017) | פרק 27: עושק והשפעה בלתי הוגנת', 'הטעות הנפוצה היא לנסות לסתור את החזקה שבסעיף 35, או לבלבל בין סעיף 35 (בטלות מוחלטת) לבין סעיף 30 (השפעה בלתי הוגנת הניתנת לסתירה).',
      '["סעיף 35 לחוק הירושה", "מעורבות נהנה", "בטלות מוחלטת", "חזקה חלוטה", "עריכת צוואה", "עד לצוואה"]'::jsonb, '**וריאציה 1 — עריכת צוואה:** האם הוראת צוואה המזכה מי שערך אותה בטלהכן, לפי סעיף 35 לחוק הירושה (סעיף 35 לחוק הירושה).
**וריאציה 2 — חזקה חלוטה:** מהי המשמעות של סעיףהוא מניח חזקה חלוטה (שאינה ניתנת לסתירה) של השפעה בלתי הוגנת (ע"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי).
**וריאציה 3 — השתתפות אחרת:** האם רק עריכה או עדות פוסלותלא, גם מי שלקח באופן אחר חלק בעריכתה (סעיף 35 לחוק הירושה).', 'סעיףבטלות מוחלטת של הוראה המזכה מי שערך, היה עד או לקח חלק בעריכת הצוואהחזקה חלוטה.', '["חוק הירושה, תשכ\"ה-1965, סעיף 35", "ע\"א 3828/98 רחל מיכקשווילי נ'' דוד מחקשווילי (16.03.2000)", "ת\"ע (משפחה תל אביב-יפו) 13844-04-22 ב.ג. נ'' מ. ג (15.01.2024)", "דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך ב (2017) | פרק 27: עושק והשפעה בלתי הוגנת"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, אלא אם כן יוכח שהייתה השפעה בלתי הוגנת מצד שרה על יוסף.', false, 'תשובה זו שגויה. סעיף 35 לחוק הירושה קובע בטלות מוחלטת במקרה של מעורבות הנהנה בעריכת הצוואה, ללא צורך בהוכחת השפעה בלתי הוגנת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, הוראת הצוואה המזכה את שרה בטלה, שכן היא ערכה את הצוואה בעצמה.', true, 'זו התשובה הנכונה. סעיף 35 לחוק הירושה קובע בטלות מוחלטת של הוראת צוואה המזכה מי שערך אותה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, אם יוסף היה כשיר לצוות בעת עריכת הצוואה.', false, 'תשובה זו שגויה. כשרות לצוות אינה מרפאת פגם של מעורבות הנהנה בעריכת הצוואה לפי סעיף 35.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם שרה הייתה גם עדה לעריכת הצוואה.', false, 'תשובה זו שגויה. סעיף 35 קובע בטלות גם אם הנהנה ערך את הצוואה, גם אם לא היה עד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q16';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 16, '2024-W-S-Q16';
END
$$;

-- ============================================================
-- Q17 — angles backfill for 2024-W-S-Q17 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q17';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q17';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הפסקת ייצוג עקב אי תשלום שכר טרחה', 1,
      'עו"ד דנה מייצגת את לקוחה, ראובן, בתביעה אזרחית. ראובן הפסיק לשלם את שכר הטרחה המוסכם. עו"ד דנה מעוניינת להפסיק את הייצוג. מה עליה לעשות?', 'שאלה זו בוחנת את הכללים החלים על עורך דין המבקש להפסיק ייצוג עקב אי תשלום שכר טרחה. היא מדגישה כי אף שאי תשלום הוא עילה מוצדקת להפסקת הייצוג, עורך הדין עדיין כפוף לחובות אתיות ופרוצדורליות, ובראשן קבלת אישור בית המשפט כאשר התיק תלוי ועומד.', 'כלל 13(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי עורך דין רשאי להפסיק טיפול בעניין אם נתגלעו חילוקי דעות, נוצרה מניעה חוקית או אתית, או בשל אי תשלום שכר טרחה והוצאות. אי תשלום שכר טרחה פוגע ביחסי האמון בין עורך הדין ללקוחו, ויכול להוות עילה מוצדקת להפסקת הייצוג. עם זאת, כאשר עניין תלוי ועומד בפני בית המשפט, כלל 13(ג) לכללי האתיקה ותקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018 (או תקנה 473 לתקנות סדר הדין האזרחי, תשמ"ד-1984, שהייתה בתוקף בעת מתן חלק מהפסקים) קובעים כי עורך הדין אינו רשאי להפסיק את הייצוג אלא ברשות בית המשפט. בנוסף, כלל 13(ב) מחייב את עורך הדין להודיע ללקוח ללא דיחוי ולפעול באופן שלא יפגע בענייניו. הפסיקה, ובראשה הלכת בלטר (רע"א 15/05), קובעת כי אין לכפות על פרקליט להמשיך לייצג לקוח שאינו משלם לו, שכן מדובר ב''שירות אישי'', אך זאת בכפוף לשיקול דעת בית המשפט. כלל 13(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986. תקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018. רע"א 15/05 עו"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי (23.08.2005). פש"ר (מחוזי חי'') 56612-01-13 ירשוב ולדימיר נ'' כונס הנכסים הרשמי מחוז חיפה (12.08.2018)', 'הטעות הנפוצה היא לחשוב שאי תשלום שכר טרחה מאפשר לעורך הדין לחדול מייצוג באופן מיידי וללא אישור בית המשפט, מבלי להתחשב בחובותיו כלפי הלקוח וההליך המשפטי.',
      '["הפסקת ייצוג", "אי תשלום שכר טרחה", "כללי אתיקה מקצועית", "אישור בית משפט", "שירות אישי", "חובת נאמנות"]'::jsonb, '**וריאציה 1 — עילה להפסקת ייצוג:** האם אי תשלום שכר טרחה הוא עילה להפסקת ייצוגכן, לפי כלל 13(א) לכללי האתיקה (כלל 13(א) לכללי לשכת עורכי הדין (אתיקה מקצועית)).
**וריאציה 2 — אישור בית משפט:** האם נדרש אישור בית משפטכן, כאשר התיק תלוי ועומד, לפי תקנה 172 (או 473) (תקנה 172 לתקנות סדר הדין האזרחי).
**וריאציה 3 — שירות אישי:** מהו הרציונל לאי כפיית ייצוג במקרה של אי תשלוםמדובר ב''שירות אישי'' שאין לכפותו, ויחסי האמון נפגעים (רע"א 15/05 עו"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי).', 'אי תשלום שכר טרחהעילה להפסקת ייצוגדורש אישור ביהמ"שתוך שמירה על ענייני הלקוח.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 13(א)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 172", "רע\"א 15/05 עו\"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי (23.08.2005)", "פש\"ר (מחוזי חי'') 56612-01-13 ירשוב ולדימיר נ'' כונס הנכסים הרשמי מחוז חיפה (12.08.2018)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'להודיע לראובן על הפסקת הייצוג ולחדול מייצוגו לאלתר.', false, 'תשובה זו שגויה. גם במקרה של אי תשלום שכר טרחה, כאשר התיק תלוי ועומד בפני בית המשפט, עורך הדין חייב לקבל את רשות בית המשפט להפסקת הייצוג, ולא יכול לחדול מיידית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'להגיש בקשה לבית המשפט לשחרורה מייצוג, תוך מתן הודעה לראובן ופעולה באופן שלא יפגע בענייניו.', true, 'זו התשובה הנכונה. אי תשלום שכר טרחה הוא עילה מוצדקת להפסקת ייצוג לפי כלל 13(א) לכללי האתיקה, אך עדיין נדרש אישור בית המשפט לפי תקנה 172 (או 473) ופעולה בזהירות כדי למנוע פגיעה בלקוח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'להמשיך לייצג את ראובן עד סיום ההליך, שכן אי תשלום שכר טרחה אינו עילה מספקת להפסקת ייצוג.', false, 'תשובה זו שגויה. אי תשלום שכר טרחה הוא עילה מפורשת להפסקת ייצוג לפי כלל 13(א) לכללי האתיקה, והפסיקה מכירה בכך כפגיעה ביחסי האמון המהווה בסיס לבקשת שחרור.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'להגיש תביעה נגד ראובן בגין אי תשלום שכר טרחה, ורק לאחר מכן לבקש להשתחרר מהייצוג.', false, 'תשובה זו שגויה. עורך הדין אינו חייב להגיש תביעה נפרדת לפני בקשת השחרור, והוא יכול לבקש להשתחרר מהייצוג במקביל או לפני הגשת תביעה לשכר טרחה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q17';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'שיקולי בית המשפט בשחרור מייצוג', 2,
      'כאשר עורך דין מבקש להשתחרר מייצוג לקוח בהליך תלוי ועומד, אילו שיקולים ינחו את בית המשפט בהחלטתו?', 'שאלה זו מתמקדת בשיקול הדעת השיפוטי בעת בחינת בקשת עורך דין להשתחרר מייצוג. היא מפרטת את מכלול הגורמים שבית המשפט שוקל, כפי שנקבעו בפסיקה, במטרה לאזן בין זכות עורך הדין שלא לכפות עליו שירות אישי לבין הצורך להגן על אינטרסי הלקוח, הצד שכנגד ותקינות ההליך המשפטי.', 'כאשר עורך דין מבקש להשתחרר מייצוג לקוח בהליך תלוי ועומד, בית המשפט מפעיל שיקול דעת רחב. הפסיקה, ובראשה הלכת בלטר (רע"א 15/05), קבעה מספר שיקולים מרכזיים: (1) השלב שבו נמצא ההליך: ככל שההליך נמצא בשלב מתקדם יותר, כך הנטייה לאשר את השחרור תפחת, מחשש לדחייה ופגיעה ביעילות הדיון. (2) מידת הפגיעה בלקוח: האם השחרור יגרום ללקוח נזק בלתי מידתי, למשל עקב קושי למצוא ייצוג חלופי או חוסר יכולת כלכלית. (3) מידת הפגיעה בצד שכנגד: האם השחרור יגרום לדחיית ההליך ולפגיעה באינטרס הצד שכנגד. (4) קיומה של עילה מוצדקת להפסקת הייצוג: כגון חילוקי דעות מהותיים, אי תשלום שכר טרחה, או מניעה אתית/חוקית. (5) אופי יחסי עורך דין-לקוח כ''שירות אישי'': אין לכפות על עורך דין להמשיך לייצג לקוח כאשר יחסי האמון נפגעו. בית המשפט יאזן בין כלל השיקולים הללו. רע"א 15/05 עו"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי (23.08.2005). רע"א (מחוזי חי'') 17575-12-18 עו"ד משה פרייליך ואח'' נ'' מנחם המר (10.01.2019). ת"א (שלום ת"א) 47654-01-14 תומר קרטנשטיין נ'' כלל חברה לביטוח בע"מ (24.12.2017). פש"ר (מחוזי חי'') 805/07 יהודה לוי נ'' כונס נכסים רשמי מחוז חיפה (28.02.2022)', 'הטעות הנפוצה היא להתמקד בשיקול אחד בלבד (למשל, זכות עורך הדין לשירות אישי) ולהתעלם ממכלול השיקולים המורכב שבית המשפט מפעיל, ובמיוחד מהשלב הדיוני של ההליך.',
      '["שיקול דעת בית המשפט", "הפסקת ייצוג", "שירות אישי", "שלב ההליך", "פגיעה בלקוח", "תקינות ההליך"]'::jsonb, '**וריאציה 1 — איזון אינטרסים:** מה בית המשפט מאזןזכות עו"ד שלא לכפות שירות אישי מול אינטרס הלקוח ותקינות ההליך (רע"א 15/05 עו"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי).
**וריאציה 2 — שלב ההליך:** האם שלב ההליך משנהכן, ככל שההליך מתקדם יותר, הנטייה לאשר שחרור פוחתת (רע"א 15/05 עו"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי).
**וריאציה 3 — פגיעה בלקוח:** האם פגיעה בלקוח רלוונטיתכן, בית המשפט יבחן אם השחרור יגרום ללקוח נזק בלתי מידתי (ת"א (שלום ת"א) 47654-01-14 תומר קרטנשטיין נ'' כלל חברה לביטוח בע"מ).', 'שיקולי ביהמ"ש לשחרור מייצוגשלב ההליך, פגיעה בלקוח/צד שכנגד, עילה מוצדקת, אופי שירות אישי.', '["רע\"א 15/05 עו\"ד מ'' בלטר ואחרים נ'' אמיתי יגאלי (23.08.2005)", "רע\"א (מחוזי חי'') 17575-12-18 עו\"ד משה פרייליך ואח'' נ'' מנחם המר (10.01.2019)", "ת\"א (שלום ת\"א) 47654-01-14 תומר קרטנשטיין נ'' כלל חברה לביטוח בע\"מ (24.12.2017)", "פש\"ר (מחוזי חי'') 805/07 יהודה לוי נ'' כונס נכסים רשמי מחוז חיפה (28.02.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק את קיומה של עילה אתית או חוקית להפסקת הייצוג.', false, 'תשובה זו שגויה. אף שקיומה של עילה אתית או חוקית הוא תנאי הכרחי, בית המשפט בוחן שיקולים רחבים יותר, ולא רק את העילה עצמה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'את השלב שבו נמצא ההליך, את מידת הפגיעה בלקוח ובצד שכנגד, ואת קיומה של עילה מוצדקת להפסקת הייצוג.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי בית המשפט יאזן בין זכות עורך הדין שלא לכפות עליו שירות אישי לבין אינטרס הלקוח, הצד שכנגד ותקינות ההליך, תוך התחשבות בשלב הדיוני ובנזק שעלול להיגרם.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק את רצונו של עורך הדין, שכן מדובר בשירות אישי שאין לכפותו.', false, 'תשובה זו שגויה. אף שמדובר בשירות אישי, רצונו של עורך הדין אינו השיקול היחיד, ובית המשפט חייב לאזן אותו מול אינטרסים נוספים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק את יכולתו הכלכלית של הלקוח לשכור עורך דין חלופי.', false, 'תשובה זו שגויה. יכולתו הכלכלית של הלקוח היא שיקול רלוונטי, אך אינה השיקול היחיד או המכריע, ובית המשפט בוחן מכלול נסיבות רחב יותר.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q17';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'הפסקת ייצוג ללא אישור בית המשפט', 3,
      'עו"ד יעל ייצגה את לקוחה, דוד, בתביעה אזרחית. לאחר שנתגלעו ביניהם חילוקי דעות מהותיים, הודיעה עו"ד יעל לדוד על הפסקת הייצוג וחדלה מלהופיע לדיונים, מבלי לקבל את אישור בית המשפט. מהן ההשלכות האפשריות של התנהלותה של עו"ד יעל?', 'שאלה זו עוסקת בהשלכות של הפסקת ייצוג על ידי עורך דין ללא קבלת אישור בית המשפט, כאשר התיק תלוי ועומד. היא מדגישה את העיקרון לפיו עורך הדין נחשב כממשיך לייצג את הלקוח עד לקבלת אישור כזה, ואת הסנקציות האפשריות על עורך דין המפר חובה זו.', 'כלל 13(ג) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי "היה ענין תלוי ועומד לפני בית המשפט, לא יפסיק עורך דין לייצג את לקוחו אלא בכפוף להוראות כל חיקוק". החיקוק הרלוונטי הוא תקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018 (או תקנה 473(ב) לתקנות הישנות), הקובעת כי "עורך דין רשאי להפסיק את הייצוג ברשות בית המשפט בלבד". משמעות הדבר היא שכל עוד לא ניתן אישור בית המשפט, עורך הדין עדיין נחשב כמייצג את הלקוח. הפסקת ייצוג ללא אישור בית המשפט מהווה הפרה של חובות עורך הדין כלפי בית המשפט וכלפי הלקוח, ועלולה לגרור סנקציות, כגון חיוב בהוצאות אישיות, ואף אחריות בגין רשלנות מקצועית אם נגרם נזק ללקוח. כלל 13(ג) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986. תקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018. ת"ק (תביעות קטנות חי'') 1486-07-17 אהובה זילברמן נ'' טל זלץ (06.04.2019). ת"א (שלום חי'') 8234-06 יוסף שפיק נסראלדין נ'' עו"ד מוניר כמאל (05.11.2008). ת"א (שלום עפ'') 6655-02-25 ראיק ח''ורי נ'' הרשות לאכיפה במקרקעין (22.08.2025)', 'הטעות הנפוצה היא לחשוב שעורך דין יכול להפסיק ייצוג באופן חד צדדי על ידי הודעה ללקוח בלבד, מבלי להבין את הדרישה המהותית לאישור בית המשפט ואת ההשלכות של אי קבלתו.',
      '["הפסקת ייצוג ללא אישור", "כללי אתיקה מקצועית", "תקנות סדר הדין האזרחי", "אחריות עורך דין", "חיוב בהוצאות אישיות", "המשך ייצוג"]'::jsonb, '**וריאציה 1 — אישור חובה:** האם עו"ד יכול להפסיק ייצוג ללא אישור ביהמ"ש כשהתיק תלוי ועומדלא, חייב אישור ביהמ"ש לפי תקנה 172/473 (תקנה 172 לתקנות סדר הדין האזרחי).
**וריאציה 2 — מעמד עו"ד:** מה מעמדו של עו"ד שהפסיק ייצוג ללא אישורהוא עדיין נחשב כמייצג את הלקוח בעיני בית המשפט (ת"א (שלום חי'') 8234-06 יוסף שפיק נסראלדין נ'' עו"ד מוניר כמאל).
**וריאציה 3 — סנקציות:** אילו סנקציות עלולות להיות מוטלותחיוב בהוצאות אישיות, ואף אחריות בגין רשלנות מקצועית (ת"ק (תביעות קטנות חי'') 1486-07-17 אהובה זילברמן נ'' טל זלץ).', 'הפסקת ייצוג ללא אישור ביהמ"שעו"ד עדיין נחשב מייצגעלול להיות מחויב בהוצאות אישיות.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 13(ג)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 172", "ת\"ק (תביעות קטנות חי'') 1486-07-17 אהובה זילברמן נ'' טל זלץ (06.04.2019)", "ת\"א (שלום חי'') 8234-06 יוסף שפיק נסראלדין נ'' עו\"ד מוניר כמאל (05.11.2008)", "ת\"א (שלום עפ'') 6655-02-25 ראיק ח''ורי נ'' הרשות לאכיפה במקרקעין (22.08.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'עו"ד יעל לא תיחשב כמי שחדלה לייצג את דוד, והיא עלולה להיות מחויבת בהוצאות אישיות.', true, 'זו התשובה הנכונה. כאשר עניין תלוי ועומד בפני בית המשפט, עורך הדין אינו רשאי להפסיק ייצוג ללא אישור בית המשפט. בהיעדר אישור, הוא עדיין נחשב כמייצג, ועלול להיות מחויב בהוצאות אישיות בגין מחדליו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הייצוג יופסק באופן אוטומטי, אך עו"ד יעל עלולה לאבד את זכותה לשכר טרחה.', false, 'תשובה זו שגויה. הייצוג אינו מופסק אוטומטית ללא אישור בית המשפט, ועורך הדין עדיין נחשב כמייצג. אובדן שכר טרחה הוא תוצאה אפשרית, אך לא ההשלכה היחידה או המיידית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט ימנה לדוד עורך דין חלופי על חשבון עו"ד יעל.', false, 'תשובה זו שגויה. בית המשפט אינו ממנה אוטומטית עורך דין חלופי על חשבון עורך הדין המתפטר, אלא אם כן מדובר בנסיבות חריגות ביותר, והלקוח נדרש למצוא ייצוג בעצמו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'עו"ד יעל תהיה רשאית להגיש תביעה נגד דוד בגין הפרת הסכם שכר טרחה.', false, 'תשובה זו שגויה. אף שעורך הדין יכול לתבוע שכר טרחה, התנהלותה של עו"ד יעל בהפסקת הייצוג ללא אישור בית המשפט עלולה לפגוע בעמדתה בתביעה כזו, ואף לחשוף אותה לתביעת רשלנות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q17';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'זכות הלקוח להחליף ייצוג', 4,
      'יוסי, לקוח המיוצג על ידי עו"ד שרון בתביעה אזרחית, החליט כי אינו מרוצה מהייצוג ומעוניין להחליף את עורך דינו. מה הדין?', 'שאלה זו עוסקת בזכותו של לקוח להחליף את עורך דינו, בניגוד למצב שבו עורך הדין מבקש להשתחרר מייצוג. היא מדגישה את ההבחנה הפרוצדורלית בין שני המצבים, ואת העיקרון לפיו זכות הלקוח להחליף ייצוג היא זכות יסוד, בכפוף לדרישות פרוצדורליות של הודעה לבית המשפט ולצדדים.', 'תקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018 (או תקנה 473(א) לתקנות סדר הדין האזרחי, תשמ"ד-1984, שהייתה בתוקף בעת מתן חלק מהפסקים) קובעת כי "בעל דין שמייצגו עורך דין רשאי לבטל את ייפוי הכוח של עורך דינו, ובלבד שנמסרה הודעה על כך לבית המשפט ולכל שאר בעלי הדין". זכות זו של הלקוח להחליף את עורך דינו היא זכות יסוד, ואינה דורשת את אישור בית המשפט או את הסכמת עורך הדין המייצג. הלקוח הוא ''אדון ענייניו'', ורשאי לבחור את ייצוגו המשפטי. הדרישה למסירת הודעה לבית המשפט ולצדדים נועדה להבטיח את תקינות ההליך המשפטי ואת ידיעת כל המעורבים בשינוי הייצוג. תקנה 172 לתקנות סדר הדין האזרחי, תשע"ט-2018. ת"א (שלום עפ'') 1857-06 עו"ד מרסי וינר נ'' ספיר תעשיות פלסטיק בע"מ (05.04.2013). ת"א (שלום י-ם) 5613-02-11 שפאר, סיטון , הניג, פילו, עו"ד (שותפות רשומה) נ'' רוברט דויטש (15.02.2016). ת"א (שלום בת ים) 10240-07-22 דורון גנסין נ'' רז עמנואל מעיין (18.02.2025)', 'הטעות הנפוצה היא לבלבל בין זכות הלקוח להחליף עורך דין (שאינה דורשת אישור בית משפט) לבין חובת עורך הדין לקבל אישור בית משפט כאשר הוא מבקש להשתחרר מייצוג.',
      '["החלפת ייצוג", "זכות הלקוח", "תקנות סדר הדין האזרחי", "הודעה לבית המשפט", "ייפוי כוח", "אדון ענייניו"]'::jsonb, '**וריאציה 1 — זכות הלקוח:** האם לקוח יכול להחליף עו"דכן, זו זכותו, בכפוף להודעה לביהמ"ש ולצדדים (תקנה 172 לתקנות סדר הדין האזרחי).
**וריאציה 2 — אישור ביהמ"ש:** האם נדרש אישור ביהמ"ש להחלפת ייצוג על ידי הלקוחלא, אישור נדרש רק כשהעו"ד מבקש להשתחרר (ת"א (שלום י-ם) 5613-02-11 שפאר, סיטון , הניג, פילו, עו"ד (שותפות רשומה) נ'' רוברט דויטש).
**וריאציה 3 — רצון הלקוח:** מי קובע את אופן ניהול התיקהלקוח הוא ''אדון ענייניו'', ועורך הדין פועל בשמו (ת"א (שלום בת ים) 10240-07-22 דורון גנסין נ'' רז עמנואל מעיין).', 'לקוח רשאי להחליף עו"ד בכל עתרק נדרשת הודעה לביהמ"ש ולצדדיםללא צורך באישור ביהמ"ש.', '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 172", "ת\"א (שלום עפ'') 1857-06 עו\"ד מרסי וינר נ'' ספיר תעשיות פלסטיק בע\"מ (05.04.2013)", "ת\"א (שלום י-ם) 5613-02-11 שפאר, סיטון , הניג, פילו, עו\"ד (שותפות רשומה) נ'' רוברט דויטש (15.02.2016)", "ת\"א (שלום בת ים) 10240-07-22 דורון גנסין נ'' רז עמנואל מעיין (18.02.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'יוסי רשאי להחליף את עורך דינו בכל עת, ובלבד שיודיע על כך לבית המשפט ולצדדים האחרים.', true, 'זו התשובה הנכונה. תקנה 172 לתקנות סדר הדין האזרחי (או 473(א) לתקנות הישנות) קובעת במפורש את זכותו של בעל דין להחליף את עורך דינו, בכפוף למסירת הודעה לבית המשפט ולצדדים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'יוסי רשאי להחליף את עורך דינו רק אם יקבל את אישור בית המשפט לכך.', false, 'תשובה זו שגויה. אישור בית המשפט נדרש כאשר עורך הדין הוא המבקש להשתחרר מהייצוג, אך לא כאשר הלקוח הוא המבקש להחליף עורך דין.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'יוסי אינו רשאי להחליף את עורך דינו אם הדבר יגרום לדחייה משמעותית בהליך המשפטי.', false, 'תשובה זו שגויה. זכות הלקוח להחליף עורך דין היא זכות יסוד, ואינה מותנית בכך שלא תיגרם דחייה. עם זאת, בית המשפט יכול שלא לאפשר דחיות נוספות עקב החלפת הייצוג.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'יוסי רשאי להחליף את עורך דינו רק אם עו"ד שרון יסכים לכך.', false, 'תשובה זו שגויה. זכות הלקוח להחליף עורך דין אינה מותנית בהסכמת עורך הדין המייצג, שכן הלקוח הוא ''אדון ענייניו''.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q17';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 17, '2024-W-S-Q17';
END
$$;

-- ============================================================
-- Q18 — angles backfill for 2024-W-S-Q18 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q18';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q18';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'חובת הזהירות של דירקטור', 1,
      'דנה היא דירקטורית בחברה ציבורית. היא אינה משתתפת באופן קבוע בישיבות הדירקטוריון, ומסתמכת בעיקר על דיווחים בעל פה ממנכ"ל החברה. האם דנה מקיימת את חובת הזהירות המוטלת עליה?', 'חובת הזהירות של דירקטור, כפי שמעוגנת בסעיף 253 לחוק החברות, מחייבת אותו לפעול ברמת מיומנות של נושא משרה סביר, תוך נקיטת אמצעים סבירים לקבלת מידע והקדשת זמן ראוי. השאלה בוחנת את היקף חובה זו, במיוחד בהקשר של השתתפות בישיבות דירקטוריון ופיקוח.', 'סעיף 253 לחוק החברות, התשנ"ט-1999, קובע כי "נושא משרה יפעל ברמת מיומנות שבה היה פועל נושא משרה סביר, באותה עמדה ובאותן נסיבות, ובכלל זה ינקוט, בשים לב לנסיבות הענין, אמצעים סבירים לקבלת מידע הנוגע לכדאיות העסקית של פעולה המובאת לאישורו או של פעולה הנעשית על ידיו בתוקף תפקידו, ולקבלת כל מידע אחר שיש לו חשיבות לענין פעולות כאמור". הפסיקה מדגישה כי חובה זו כוללת השתתפות פעילה בישיבות הדירקטוריון ופיקוח על ההנהלה. דירקטור אינו יכול להגשים את חובותיו ''בשלט רחוק'' או להסתפק בדיווחים בלבד. רמת הזהירות היא אובייקטיבית, אך האמצעים הנדרשים משתנים לפי הנסיבות. אי השתתפות קבועה בישיבות ואי היכרות עם מצב החברה מהווים הפרה של חובת הזהירות. ת"א (מחוזי מרכז) 14100-02-15 אורג''ניקס בע"מ נ'' דרור יפת (25.05.2025). ע"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה (11.05.2003). ע"א 4024/13 תקווה - כפר להכשרה מקצועית בגבעות זייד בע"מ נ'' אריה פינקוביץ (29.08.2016). סעיף 253 לחוק החברות, תשנ"ט-1999', 'הטעות הנפוצה היא לחשוב שדירקטור יכול להסתפק בדיווחים או לא להשתתף בישיבות באופן קבוע, מבלי להבין את הדרישה להקדשת זמן ראוי ונוכחות פעילה.',
      '["חובת זהירות", "נושא משרה סביר", "סעיף 253 לחוק החברות", "השתתפות בישיבות דירקטוריון", "פיקוח", "הקדשת זמן"]'::jsonb, '**וריאציה 1 — רמת מיומנות:** מהי רמת המיומנות הנדרשת מנושא משרהרמת מיומנות של נושא משרה סביר באותה עמדה ובאותן נסיבות (ת"א (מחוזי מרכז) 14100-02-15 אורג''ניקס בע"מ נ'' דרור יפת).
**וריאציה 2 — חובת השתתפות:** האם דירקטור חייב להשתתף בישיבותכן, חובת הזהירות כוללת השתתפות פעילה בישיבות הדירקטוריון (ע"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה).
**וריאציה 3 — הקדשת זמן:** האם דירקטור יכול להסתפק בדיווחיםלא, הקדשת זמן ראוי אינה יכולה להתבצע ללא נוכחות פעילה בישיבות הדירקטוריון (ע"א 4024/13 תקווה - כפר להכשרה מקצועית בגבעות זייד בע"מ נ'' אריה פינקוביץ).', 'חובת זהירות של דירקטורפעולה ברמת מיומנות סבירהכולל השתתפות פעילה בישיבותוקבלת מידע.', '["חוק החברות, תשנ\"ט-1999, סעיף 253", "ת\"א (מחוזי מרכז) 14100-02-15 אורג''ניקס בע\"מ נ'' דרור יפת (25.05.2025)", "ע\"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה (11.05.2003)", "ע\"א 4024/13 תקווה - כפר להכשרה מקצועית בגבעות זייד בע\"מ נ'' אריה פינקוביץ (29.08.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, כל עוד היא מקבלת דיווחים מהמנכ"ל, היא מקיימת את חובת הזהירות.', false, 'תשובה זו שגויה. חובת הזהירות דורשת השתתפות פעילה בישיבות הדירקטוריון ואינה מסתפקת בדיווחים בעל פה בלבד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חובת הזהירות מחייבת השתתפות פעילה בישיבות הדירקטוריון ואינה יכולה להתבצע ''בשלט רחוק''.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי חובת הזהירות של דירקטור כוללת השתתפות פעילה בישיבות הדירקטוריון ואינה יכולה להתבצע ללא נוכחות פעילה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אלא אם כן הוכח שהיא פעלה בחוסר תום לב.', false, 'תשובה זו שגויה. חוסר תום לב רלוונטי יותר לחובת אמונים. חובת הזהירות נבחנת במבחן אובייקטיבי של סבירות, ללא קשר לתום לב סובייקטיבי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אך רק אם נגרם נזק לחברה כתוצאה מהיעדרותה.', false, 'תשובה זו שגויה. הפרת חובת הזהירות אינה מותנית בהכרח בהוכחת נזק בפועל, אלא בסטייה מרמת ההתנהגות הנדרשת מ''נושא משרה סביר''.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q18';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הבחנה בין חובת אמונים לחובת זהירות', 2,
      'מהו ההבדל המהותי בין חובת האמונים לחובת הזהירות של נושא משרה בחברה?', 'השאלה עוסקת בהבחנה המהותית בין חובת האמונים לחובת הזהירות של נושאי משרה בחברה, שהן שתי חובות יסוד בדיני חברות. היא בוחנת את הרציונל השונה העומד בבסיס כל אחת מהן ואת ההשלכות המשפטיות של הפרתן.', 'חובת הזהירות (סעיף 252 לחוק החברות, התשנ"ט-1999) התפתחה מדיני הנזיקין, מתמקדת במניעת נזק לחברה, ונבחנת במבחן אובייקטיבי של סבירות (''נושא משרה סביר''). הפרתה דורשת הוכחת נזק וקשר סיבתי. לעומתה, חובת האמונים (סעיף 254 לחוק החברות) מבוססת על דיני הנאמנות ועשיית עושר ולא במשפט, מתמקדת במניעת ניצול כוחו של הדירקטור לטובתו האישית או לטובת אחר, ונבחנת במבחן סובייקטיבי של תום לב. הפרת חובת האמונים אינה טעונה קיומו של נזק לחברה, שכן מטרתה למנוע ניצול כוחו של הדירקטור לטובתו שלו. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016). ע"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה (11.05.2003). ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023). סעיף 252(א) לחוק החברות, תשנ"ט-1999. סעיף 254(א) לחוק החברות, תשנ"ט-1999', 'הטעות הנפוצה היא לבלבל בין המבחנים והרציונלים של חובת הזהירות וחובת האמונים, במיוחד בשאלת הצורך בהוכחת נזק או כוונה סובייקטיבית.',
      '["חובת אמונים", "חובת זהירות", "נושא משרה", "מבחן אובייקטיבי", "מבחן סובייקטיבי", "נזק", "ניצול כוח"]'::jsonb, '**וריאציה 1 — רציונל חובת זהירות:** מה מטרת חובת הזהירותלמנוע נזק לחברה, נבחנת באובייקטיביות (ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ).
**וריאציה 2 — רציונל חובת אמונים:** מה מטרת חובת האמוניםלמנוע ניצול כוח לטובת אישית, נבחנת בסובייקטיביות ואינה דורשת נזק (ע"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה).
**וריאציה 3 — תום לב:** היכן בא לידי ביטוי תום הלבחובת האמונים מחייבת נושא משרה לנהוג בתום לב ולפעול לטובת החברה (סעיף 254(א) לחוק החברות).', 'חובת זהירותמניעת נזק, אובייקטיבית. חובת אמוניםמניעת ניצול כוח, סובייקטיבית, לא דורשת נזק.', '["חוק החברות, תשנ\"ט-1999, סעיפים 252, 254", "ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)", "ע\"א 610/94 גדליה בוכבינדר נ'' כונס הנכסים הרשמי בתפקידו כמפרק בנק צפון אמריקה (11.05.2003)", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'חובת האמונים מתמקדת במניעת נזק לחברה ונבחנת במבחן אובייקטיבי, בעוד חובת הזהירות מתמקדת במניעת ניצול כוח לטובת אישית ונבחנת במבחן סובייקטיבי.', false, 'תשובה זו שגויה. היא מבלבלת בין הרציונלים והמבחנים של שתי החובות. חובת הזהירות היא האובייקטיבית ומתמקדת בנזק, וחובת האמונים היא הסובייקטיבית ומתמקדת בניצול כוח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'חובת הזהירות מתמקדת במניעת נזק לחברה ונבחנת במבחן אובייקטיבי של סבירות, בעוד חובת האמונים מתמקדת במניעת ניצול כוח לטובת אישית ונבחנת במבחן סובייקטיבי של תום לב.', true, 'זו התשובה הנכונה. חובת הזהירות (סעיף 252 לחוק החברות) היא נזיקית ואובייקטיבית, וחובת האמונים (סעיף 254 לחוק החברות) היא נאמנותית וסובייקטיבית, ואינה דורשת הוכחת נזק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'חובת האמונים חלה רק על דירקטורים, בעוד חובת הזהירות חלה על כל נושאי המשרה בחברה.', false, 'תשובה זו שגויה. שתי החובות חלות על כלל נושאי המשרה בחברה, כהגדרתם בחוק החברות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הפרת חובת הזהירות אינה דורשת הוכחת נזק, בעוד הפרת חובת האמונים דורשת הוכחת נזק לחברה.', false, 'תשובה זו שגויה. ההיפך הוא הנכון: הפרת חובת אמונים אינה טעונה קיומו של נזק לחברה, בעוד הפרת חובת זהירות דורשת הוכחת נזק.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q18';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'זכות דירקטור לקבלת מידע וייעוץ', 3,
      'דני, דירקטור בחברה, מבקש לבדוק מסמכים מסוימים של החברה ולקבל ייעוץ משפטי חיצוני בנוגע לפעולה עסקית מהותית. הדירקטוריון מסרב לבקשתו בטענה שדני פועל בחוסר תום לב ושהייעוץ יקר מדי. מה הדין?', 'שאלה זו עוסקת בזכותו של דירקטור לקבל מידע ולעשות שימוש בייעוץ מקצועי על חשבון החברה, כפי שמעוגנת בסעיפים 265 ו-266 לחוק החברות. היא בוחנת את הסייגים לזכויות אלו, ובמיוחד את סמכות הדירקטוריון למנוע מידע במקרה של חשש לחוסר תום לב או פגיעה בטובת החברה.', 'סעיף 265(א) לחוק החברות, התשנ"ט-1999, קובע כי "לכל דירקטור הזכות לבדוק את מסמכי החברה ואת רישומיה ולקבל העתקים מהם, ולבדוק את נכסי החברה, ככל שהדבר דרוש למילוי חובותיו כדירקטור". סעיף 265(ב) מסייג זכות זו וקובע כי "החברה רשאית למנוע מדירקטור לבדוק מסמך או נכס של החברה, אם סבר הדירקטוריון שהדירקטור פועל בחוסר תום לב או שבדיקה כאמור עלולה לפגוע בטובת החברה". בנוסף, סעיף 266 לחוק מאפשר לדירקטור להסתייע בייעוץ מקצועי על חשבון החברה, אך זאת רק אם כיסוי ההוצאות אושר על ידי הדירקטוריון או על ידי בית המשפט. בית המשפט יבחן אם המומחים של החברה אינם מספקים את הסיוע הנדרש ואת סבירות ההוצאות. סעיף 265(א) לחוק החברות, תשנ"ט-1999. סעיף 265(ב) לחוק החברות, תשנ"ט-1999. אירית חביב-סגל דיני חברות - כרך א (2007) | פרק ח: מנגנונים מבניים לפתרון בעיית הנציג. נבו - המתמחה דיני תאגידים (2026) | חוק החברות, התשנ"ט-1999', 'הטעות הנפוצה היא לחשוב שזכותו של דירקטור למידע היא מוחלטת, או שזכותו לייעוץ חיצוני אינה מותנית באישור כלשהו.',
      '["זכות למידע", "ייעוץ מקצועי", "סעיף 265 לחוק החברות", "סעיף 266 לחוק החברות", "חוסר תום לב", "טובת החברה"]'::jsonb, '**וריאציה 1 — זכות בדיקת מסמכים:** האם לדירקטור זכות לבדוק מסמכיםכן, ככל שהדבר דרוש למילוי חובותיו (סעיף 265(א) לחוק החברות).
**וריאציה 2 — סייג לזכות:** מתי ניתן למנוע ממידעאם הדירקטוריון סבר שהדירקטור פועל בחוסר תום לב או שהבדיקה תפגע בטובת החברה (סעיף 265(ב) לחוק החברות).
**וריאציה 3 — ייעוץ מקצועי:** האם דירקטור זכאי לייעוץ מקצועי על חשבון החברהכן, באישור הדירקטוריון או בית המשפט (אירית חביב-סגל דיני חברות - כרך א (2007)).', 'דירקטור זכאי למידע וייעוץבכפוף לסייגים של חוסר תום לב או פגיעה בחברהייעוץ על חשבון החברה דורש אישור.', '["חוק החברות, תשנ\"ט-1999, סעיפים 265, 266", "אירית חביב-סגל דיני חברות - כרך א (2007) | פרק ח: מנגנונים מבניים לפתרון בעיית הנציג", "נבו - המתמחה דיני תאגידים (2026) | חוק החברות, התשנ\"ט-1999"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הדירקטוריון רשאי למנוע מדני לבדוק מסמכים אם סבר שהוא פועל בחוסר תום לב, אך אינו רשאי למנוע ממנו לקבל ייעוץ מקצועי.', false, 'תשובה זו שגויה. הדירקטוריון רשאי למנוע ייעוץ מקצועי אם לא אישר את כיסוי ההוצאות, או אם בית המשפט לא אישר זאת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'דני זכאי לבדוק את מסמכי החברה ולקבל ייעוץ מקצועי על חשבון החברה, אלא אם כן הדירקטוריון הוכיח שדני פועל בחוסר תום לב או שהבדיקה תפגע בטובת החברה.', true, 'זו התשובה הנכונה. סעיף 265(א) לחוק החברות מקנה לדירקטור זכות לבדוק מסמכים, וסעיף 265(ב) קובע את הסייג. סעיף 266 מאפשר ייעוץ מקצועי באישור הדירקטוריון או בית המשפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'דני אינו זכאי לבדוק מסמכים או לקבל ייעוץ מקצועי ללא אישור רוב הדירקטוריון.', false, 'תשובה זו שגויה. זכותו של דירקטור לקבל מידע היא אישית ואינה מותנית באישור רוב הדירקטוריון, אלא בסייגים ספציפיים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'דני רשאי לפנות לבית המשפט בבקשה שיורה לדירקטוריון לאפשר לו לבדוק מסמכים ולקבל ייעוץ, ללא קשר לטענות הדירקטוריון.', false, 'תשובה זו שגויה. בית המשפט יבחן את טענות הדירקטוריון, ובמיוחד את טענת חוסר תום הלב, לפני שיורה על מתן מידע או ייעוץ.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q18';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'תביעה נגזרת של דירקטור', 4,
      'דניאל, דירקטור בחברה, גילה כי מנכ"ל החברה, אורי, ביצע פעולה שהסבה נזק כספי משמעותי לחברה, תוך הפרת חובת אמונים. הדירקטוריון, הנשלט על ידי אורי, מסרב להגיש תביעה נגד אורי. מה באפשרות דניאל לעשות?', 'שאלה זו עוסקת במנגנון התביעה הנגזרת, המאפשר לדירקטור או לבעל מניה להגיש תביעה בשם החברה, כאשר החברה עצמה אינה פועלת למיצוי זכויותיה. היא בוחנת את התנאים המוקדמים להגשת תביעה כזו, ובמיוחד את דרישת הפנייה המוקדמת לחברה ואת החריגים לה.', 'סעיף 194(א) לחוק החברות, התשנ"ט-1999, קובע כי "כל בעל מניה וכל דירקטור בחברה... רשאים להגיש תביעה נגזרת אם התקיימו הוראות סימן זה". תביעה נגזרת מאפשרת לדירקטור לתבוע בשם החברה בגין עילה העומדת לחברה, למשל, הפרת חובת אמונים של נושא משרה אחר. ככלל, על המבקש להגיש תביעה נגזרת לפנות תחילה לחברה בכתב ולדרוש ממנה למצות את זכויותיה (סעיף 194(ב)). אולם, סעיף 194(ד) קובע חריגים לדרישת הפנייה המוקדמת, ובהם מצב שבו לאורגן החברה המוסמך להחליט על הגשת התביעה (הדירקטוריון) יש עניין אישי בהחלטה, או קיים חשש סביר כי פנייה בדרישה תפגע באפשרות לקבל את הסעד המבוקש. במקרה הנדון, הדירקטוריון נשלט על ידי המנכ"ל אורי, שיש לו עניין אישי באי הגשת התביעה, ולכן דניאל רשאי להגיש תביעה נגזרת ללא פנייה מוקדמת. סעיף 194(א) לחוק החברות, תשנ"ט-1999. סעיף 194(ד)(1) לחוק החברות, תשנ"ט-1999. תנ"ג (מחוזי תל אביב-יפו) 9984-07-21 סינקו השקעות ויזמות בע"מ נ'' נקסט טאוור בע"מ (02.10.2023). ת"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע"מ נ'' ברוך חבס ייזום (2005) בע"מ (30.07.2020)', 'הטעות הנפוצה היא לחשוב שדרישת הפנייה המוקדמת לחברה היא מוחלטת, מבלי להכיר בחריגים המאפשרים הגשת תביעה נגזרת גם ללא פנייה כזו, במיוחד במקרים של ניגוד עניינים באורגן המוסמך.',
      '["תביעה נגזרת", "סעיף 194 לחוק החברות", "פנייה מוקדמת", "עניין אישי", "הפרת חובת אמונים", "דירקטור"]'::jsonb, '**וריאציה 1 — זכות דירקטור:** האם דירקטור רשאי להגיש תביעה נגזרתכן, לפי סעיף 194(א) לחוק החברות (סעיף 194(א) לחוק החברות).
**וריאציה 2 — חריג לפנייה מוקדמת:** מתי אין צורך בפנייה מוקדמת לחברהאם לאורגן המוסמך יש עניין אישי בהחלטה (סעיף 194(ד)(1) לחוק החברות).
**וריאציה 3 — שיקולי בית המשפט:** מה בוחן בית המשפט באישור תביעה נגזרתקיום עילת תביעה, טובת החברה, ותום לב של התובע (ת"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע"מ נ'' ברוך חבס ייזום (2005) בע"מ).', 'דירקטור יכול להגיש תביעה נגזרתלרוב דורש פנייה מוקדמת לחברהחריג: עניין אישי של האורגן המוסמך.', '["חוק החברות, תשנ\"ט-1999, סעיף 194", "תנ\"ג (מחוזי תל אביב-יפו) 9984-07-21 סינקו השקעות ויזמות בע\"מ נ'' נקסט טאוור בע\"מ (02.10.2023)", "ת\"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע\"מ נ'' ברוך חבס ייזום (2005) בע\"מ (30.07.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'דניאל אינו יכול לעשות דבר, שכן רק החברה עצמה רשאית להגיש תביעה נגד נושא משרה.', false, 'תשובה זו שגויה. חוק החברות מאפשר לדירקטור להגיש תביעה נגזרת בשם החברה במקרים מסוימים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'דניאל רשאי להגיש תביעה נגזרת בשם החברה נגד אורי, לאחר שפנה לחברה בדרישה שתמצה את זכויותיה, או אם מתקיים חריג לפנייה מוקדמת.', true, 'זו התשובה הנכונה. סעיף 194 לחוק החברות מאפשר לדירקטור להגיש תביעה נגזרת, בכפוף לפנייה מוקדמת לחברה או לקיומם של חריגים המייתרים פנייה כזו (כמו עניין אישי של האורגן המוסמך).', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'דניאל רשאי לפנות לבית המשפט בבקשה לצו מניעה, אך לא להגיש תביעה בגין נזק שכבר נגרם.', false, 'תשובה זו שגויה. סעיף 267 לחוק החברות מאפשר צו מניעה לפעולה עתידית. תביעה בגין נזק שכבר נגרם נעשית באמצעות תביעה נגזרת.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'דניאל רשאי להגיש תביעה אישית נגד אורי בגין הנזק שנגרם לחברה.', false, 'תשובה זו שגויה. הנזק נגרם לחברה, ולכן עילת התביעה שייכת לחברה. דניאל אינו יכול לתבוע באופן אישי בגין נזק שנגרם לחברה, אלא באמצעות תביעה נגזרת.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q18';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 18, '2024-W-S-Q18';
END
$$;

-- ============================================================
-- Q19 — angles backfill for 2024-W-S-Q19 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q19';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q19';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'ניכוי ימי מעצר בית רגיל', 1,
      'ראובן שהה במעצר בית מלא (ללא פיקוח אלקטרוני) במשך 10 חודשים לפני שהורשע ונגזר דינו. כמה חודשים ינוכו בכל מקרה מעונש המאסר בפועל שיושת עליו?', 'שאלה זו עוסקת בהבחנה בין סוגי שלילת חירות שונים לעניין ניכוי ימי מעצר מעונש מאסר בפועל. היא מדגישה כי מעצר בית רגיל, אף אם הוא מלא, אינו נחשב למעצר לצורך ניכוי אוטומטי, אלא כשיקול ענישה בלבד, בניגוד למעצר מאחורי סורג ובריח.', 'סעיף 43 לחוק העונשין, תשל"ז-1977, קובע כי תקופת מאסר תיחשב מיום גזר הדין, אלא אם בית המשפט הורה אחרת. הפסיקה פירשה זאת כהיתר לנכות ימי מעצר מאחורי סורג ובריח. עם זאת, מעצר בית רגיל, גם אם הוא מלא, אינו נחשב לשלילת חירות מוחלטת כמו מעצר מאחורי סורג ובריח. הפסיקה קבעה כי מעצר בית מהווה הגבלה על החירות בלבד, ואינו מנוכה אוטומטית מתקופת המאסר. בית המשפט רשאי להתחשב באורכו של מעצר הבית כנסיבה לקולא בעת גזירת הדין, אך אין חובה לנכותו. סעיף 43 לחוק העונשין, תשל"ז-1977. ת"פ (מחוזי י-ם) 23513-03-14 מדינת ישראל נ'' ויטאלי שצ''ינוב (10.11.2016). בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016).', 'הטעות הנפוצה היא להשוות מעצר בית רגיל למעצר מאחורי סורג ובריח או למעצר בפיקוח אלקטרוני, ולחשוב שגם הוא מנוכה אוטומטית מהמאסר.',
      '["ניכוי ימי מעצר", "מעצר בית", "חלופת מעצר", "סעיף 43 לחוק העונשין", "שיקולי ענישה", "שלילת חירות"]'::jsonb, '**וריאציה 1 — מעצר בית רגיל:** האם מעצר בית רגיל מנוכה אוטומטית מהמאסרלא, הוא אינו נחשב לשלילת חירות מוחלטת (ת"פ (מחוזי י-ם) 23513-03-14 מדינת ישראל נ'' ויטאלי שצ''ינוב).
**וריאציה 2 — שיקול דעת:** האם מעצר בית רגיל נלקח בחשבוןכן, בית המשפט רשאי להתחשב בו כנסיבה לקולא בעת גזירת הדין (ת"פ (מחוזי י-ם) 23513-03-14 מדינת ישראל נ'' ויטאלי שצ''ינוב).
**וריאציה 3 — סעיף 43:** מה קובע סעיף 43 לחוק העונשיןתקופת מאסר תיחשב מיום גזר הדין, אלא אם בית המשפט הורה אחרת (סעיף 43 לחוק העונשין).', 'מעצר בית רגילאינו מנוכה אוטומטית מהמאסראך נלקח בחשבון כשיקול ענישה.', '["חוק העונשין, תשל\"ז-1977, סעיף 43", "ת\"פ (מחוזי י-ם) 23513-03-14 מדינת ישראל נ'' ויטאלי שצ''ינוב (10.11.2016)", "בש\"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', '10 חודשים.', false, 'תשובה זו שגויה. מעצר בית רגיל אינו נחשב למעצר לצורך ניכוי אוטומטי מעונש המאסר, אלא כשיקול ענישה בלבד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', '5 חודשים.', false, 'תשובה זו שגויה. חישוב זה מבוסס על יחס המרה של 1:2, שאינו חל על מעצר בית רגיל לצורך ניכוי מעונש מאסר.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', '0 חודשים.', true, 'זו התשובה הנכונה. מעצר בית רגיל (ללא פיקוח אלקטרוני) אינו מנוכה אוטומטית מעונש המאסר בפועל, אלא נלקח בחשבון כשיקול ענישה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט יחליט לפי שיקול דעתו, אך לא פחות מ-3 חודשים.', false, 'תשובה זו שגויה. אין קביעה בחוק או בפסיקה לניכוי מינימלי של מעצר בית רגיל.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q19';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'שיקול דעת בית המשפט בניכוי מעצר', 2,
      'האם לנאשם שהורשע בדין יש זכות קנויה לניכוי ימי מעצרו מתקופת המאסר שנגזרה עליו?', 'שאלה זו בוחנת את מעמדו המשפטי של ניכוי ימי מעצר מתקופת מאסר בפועל. היא מדגישה כי על אף שהדבר הפך לפרקטיקה שיפוטית מקובלת, אין מדובר בזכות קנויה לנאשם, אלא בסמכות הנתונה לשיקול דעתו של בית המשפט, בהתאם לסעיף 43 לחוק העונשין.', 'סעיף 43 לחוק העונשין, תשל"ז-1977, קובע כי "מי שנידון למאסר תיחשב תקופת מאסרו מיום גזר הדין, אם לא הורה בית המשפט הוראה אחרת". מלשון הסעיף עולה כי ניכוי ימי מעצר אינו אוטומטי. הפסיקה קבעה כי לנאשם אין זכות קנויה לניכוי ימי מעצרו, והשאלה אם לנכות את ימי המעצר נתונה לשיקול דעתו של בית המשפט, אשר שוקל את הנושא במסגרת העונש הראוי. עם השנים, השתרשה פרקטיקה שיפוטית לפיה בית המשפט מתחשב בדרך כלל בתקופת מעצרו של נאשם מורשע, ובהיעדר נימוקים מיוחדים לחומרה, ראוי כי הערכאה המבררת תביא תקופה זו בחשבון. סעיף 43 לחוק העונשין, תשל"ז-1977. ע"פ 201/18 ליאור טויזר נ'' מדינת ישראל (08.07.2018). בש"פ 2596/23 פלוני נ'' מדינת ישראל (18.05.2023). עפ"ת (מחוזי חיפה) 36608-03-26 אברהים סמחאת נ'' מדינת ישראל (30.03.2026).', 'הטעות הנפוצה היא לחשוב שניכוי ימי מעצר הוא זכות אוטומטית, מבלי להבין את שיקול הדעת הרחב הנתון לבית המשפט.',
      '["ניכוי ימי מעצר", "סעיף 43 לחוק העונשין", "שיקול דעת שיפוטי", "זכות קנויה", "פרקטיקה שיפוטית", "עקרונות ענישה"]'::jsonb, '**וריאציה 1 — זכות קנויה:** האם ניכוי ימי מעצר הוא זכות קנויהלא, אין זכות קנויה לכך (ע"פ 201/18 ליאור טויזר נ'' מדינת ישראל).
**וריאציה 2 — שיקול דעת:** מי מחליט על ניכוי ימי מעצרבית המשפט, בשיקול דעת רחב במסגרת העונש הראוי (בש"פ 2596/23 פלוני נ'' מדינת ישראל).
**וריאציה 3 — פרקטיקה שיפוטית:** האם ניכוי ימי מעצר הוא נוהג מקובלכן, השתרשה פרקטיקה שיפוטית לנכות ימי מעצר בהיעדר נימוקים מיוחדים לחומרה (ע"פ 201/18 ליאור טויזר נ'' מדינת ישראל).', 'ניכוי ימי מעצרלא זכות קנויהנתון לשיקול דעת ביהמ"שאך פרקטיקה מקובלת.', '["חוק העונשין, תשל\"ז-1977, סעיף 43", "ע\"פ 201/18 ליאור טויזר נ'' מדינת ישראל (08.07.2018)", "בש\"פ 2596/23 פלוני נ'' מדינת ישראל (18.05.2023)", "עפ\"ת (מחוזי חיפה) 36608-03-26 אברהים סמחאת נ'' מדינת ישראל (30.03.2026)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, ניכוי ימי מעצר הוא זכות קנויה לכל נאשם שהורשע, למעט במקרים חריגים.', false, 'תשובה זו שגויה. ניכוי ימי מעצר אינו זכות קנויה, אלא נתון לשיקול דעת בית המשפט, אף שהפך לפרקטיקה שיפוטית מקובלת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, ניכוי ימי מעצר נתון לשיקול דעתו של בית המשפט, ואין לנאשם זכות קנויה לכך, אף שהפך לפרקטיקה שיפוטית מקובלת.', true, 'זו התשובה הנכונה. סעיף 43 לחוק העונשין קובע כי הניכוי נתון לשיקול דעת בית המשפט, והפסיקה אישרה כי אין זכות קנויה, אלא פרקטיקה שיפוטית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם המעצר היה מאחורי סורג ובריח ולא בפיקוח אלקטרוני.', false, 'תשובה זו שגויה. אף שמעצר מאחורי סורג ובריח הוא המנוכה בפועל, עדיין אין מדובר בזכות קנויה, אלא בשיקול דעת.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, ניכוי ימי מעצר אפשרי רק אם המאשימה מסכימה לכך.', false, 'תשובה זו שגויה. הסכמת המאשימה אינה תנאי לניכוי, אלא שיקול דעת בית המשפט.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q19';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'אי ניכוי מעצר חופף למאסר אחר', 3,
      'דניאל שהה במעצר מאחורי סורג ובריח במשך 4 חודשים בגין עבירה חדשה, כאשר במקביל ריצה עונש מאסר בפועל של 10 חודשים בגין עבירה קודמת. כמה חודשים ינוכו בכל מקרה מעונש המאסר בפועל שיושת עליו בגין העבירה החדשה?', 'שאלה זו עוסקת בחריג לכלל ניכוי ימי מעצר, כאשר תקופת המעצר חופפת לתקופת מאסר אחרת שהנאשם כבר מרצה. היא מדגישה את הרציונל של מניעת כפל הנאה ואת ברירת המחדל של אי-ניכוי במקרים אלו.', 'הכלל הוא שניכוי ימי מעצר נועד למנוע כפל ענישה, שכן המעצר אינו עונשי אלא מניעתי. אולם, כאשר נאשם מרצה ימי מעצר בחופף לעונש מאסר אחר, רציונל זה מאבד מערכו. במצב כזה, חירותו של הנאשם כבר נשללה בגין העונש הקודם. הפסיקה קבעה כי ברירת המחדל במקרים אלו היא ש''ימי מעצר אלה לא ינוכו מן העונש'' החדש, כדי למנוע מצב שבו הנאשם ייהנה פעמיים מתקופה אחת שבה נשללה חירותו. סעיף 43 לחוק העונשין, תשל"ז-1977. ע"פ 3242/19 היועץ המשפטי לממשלה נ'' אליקים אלציק (18.08.2019). פ"ל (תעבורה י-ם) 1014-05-25 מדינת ישראל נ'' אסמאעיל עמלה (19.11.2025). בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016).', 'הטעות הנפוצה היא להחיל את הכלל הכללי של ניכוי ימי מעצר גם במקרים של חפיפה, מבלי להבין את החריג ואת הרציונל שמאחוריו.',
      '["ניכוי ימי מעצר", "מעצר חופף", "כפל ענישה", "מאסר בפועל", "ברירת מחדל", "סעיף 43 לחוק העונשין"]'::jsonb, '**וריאציה 1 — מעצר חופף:** האם ימי מעצר החופפים למאסר אחר מנוכיםלא, ברירת המחדל היא אי-ניכוי (ע"פ 3242/19 היועץ המשפטי לממשלה נ'' אליקים אלציק).
**וריאציה 2 — רציונל:** מה הרציונל לאי-ניכוי במקרה של חפיפהמניעת כפל הנאה, שכן החירות כבר נשללה בגין המאסר הקודם (בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר).
**וריאציה 3 — סעיף 43:** האם סעיף 43 לחוק העונשין מחייב ניכוי במקרה זהלא, הסעיף קובע ברירת מחדל של מניין מיום גזר הדין, ואינו מחייב ניכוי במקרה של חפיפה (סעיף 43 לחוק העונשין).', 'מעצר חופף למאסר אחרלא מנוכה מהעונש החדשלמניעת כפל הנאה.', '["חוק העונשין, תשל\"ז-1977, סעיף 43", "ע\"פ 3242/19 היועץ המשפטי לממשלה נ'' אליקים אלציק (18.08.2019)", "פ\"ל (תעבורה י-ם) 1014-05-25 מדינת ישראל נ'' אסמאעיל עמלה (19.11.2025)", "בש\"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', '4 חודשים.', false, 'תשובה זו שגויה. במקרה של מעצר החופף לריצוי מאסר אחר, ברירת המחדל היא אי-ניכוי ימי המעצר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', '0 חודשים.', true, 'זו התשובה הנכונה. כאשר ימי מעצר חופפים לריצוי עונש מאסר אחר, ברירת המחדל היא שאין לנכותם מעונש המאסר החדש, כדי למנוע כפל הנאה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט יחליט לפי שיקול דעתו, אך לא פחות מ-2 חודשים.', false, 'תשובה זו שגויה. אין קביעה לניכוי מינימלי במקרה של חפיפה, וברירת המחדל היא אי-ניכוי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', '10 חודשים.', false, 'תשובה זו שגויה. ניכוי זה מתייחס לתקופת המאסר הקודמת, ואינו רלוונטי לניכוי מהעונש החדש.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q19';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'ימי מעצר בפיקוח אלקטרוני למניין 9 חודשים', 4,
      'נאשם שהה במעצר מאחורי סורג ובריח במשך 6 חודשים, ולאחר מכן במעצר בפיקוח אלקטרוני במשך 8 חודשים. האם תקופת המעצר בפיקוח אלקטרוני תיכלל במניין 9 חודשי המעצר המקסימליים עד תום ההליכים, המחייבים פנייה לבית המשפט העליון להארכה?', 'שאלה זו עוסקת בהבחנה קריטית בין ניכוי ימי מעצר מעונש מאסר (סעיף 43 לחוק העונשין) לבין מניין ימי מעצר לצורך מגבלות הזמן הקבועות בחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), ובפרט סעיף 61(א) העוסק בשחרור באין הכרעת דין. היא בוחנת את מעמדו של מעצר בפיקוח אלקטרוני בהקשר זה ואת המחלוקת הפרשנית לגבי יחס ההמרה.', 'סעיף 61(א) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996, קובע כי נאשם שלאחר הגשת כתב אישום נגדו היה נתון במעצר בשל אותו כתב אישום תקופה המצטרפת כדי תשעה חודשים (מאחורי סורג ובריח), או 18 חודשים (בפיקוח אלקטרוני), ומשפטו בערכאה הראשונה לא נגמר בהכרעת דין, ישוחרר מן המעצר. השאלה היא כיצד לחשב תקופה משולבת של שני סוגי מעצר אלו. בבש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר, קבע השופט מלצר (בדעת רוב לעניין זה) כי בהיעדר הוראה מפורשת בסעיף 61(א) הקובעת יחס המרה בין ימי מעצר בפיקוח אלקטרוני לימי מעצר מאחורי סורג ובריח, יש לקרוא את הסעיף כך שימי המעצר בפיקוח אלקטרוני יבואו במניין תשעת חודשי המעצר מאחורי סורג ובריח ביחס זהה של 1:1. זאת, בשים לב לחירויות יסוד ולחזקת החפות. השופט הנדל (בדעת מיעוט לעניין זה) סבר כי מתכלית החוק עולה שהמחוקק לא התכוון לתת ליום מעצר בפיקוח אלקטרוני משקל זהה ליום מעצר מאחורי סורג ובריח, וכי יש להחיל יחס המרה של 1:2. בית המשפט המחוזי בהחלטתו המקורית (עמ"ת 31476-05-16) אכן קבע יחס המרה של 1:2. אולם, ההלכה שנקבעה בבש"פ 4206/16 היא כי בהיעדר הוראה מפורשת, היחס הוא 1:1. סעיף 61(א) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996. בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016). עמ"ת (מחוזי חיפה) 31476-05-16 מדינת ישראל נ'' מוחסן טחימר (22.05.2016). מ"ת (שלום עכו) 54134-05-15 מדינת ישראל נ'' מוחסן טחימר (11.05.2016).', 'הטעות הנפוצה היא לבלבל בין הכללים החלים על ניכוי ימי מעצר מעונש מאסר (סעיף 43 לחוק העונשין) לבין הכללים החלים על מניין ימי מעצר לצורך מגבלות הזמן הקבועות בחוק המעצרים (סעיף 61(א)).',
      '["מעצר עד תום ההליכים", "פיקוח אלקטרוני", "סעיף 61 לחוק המעצרים", "יחס המרה", "חזקת החפות", "זכות לחירות", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — מניין ימים:** האם מעצר בפיקוח אלקטרוני נכלל במניין 9 חודשי המעצר לפי סעיף 61(אכן, נכלל (בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר).
**וריאציה 2 — יחס המרה:** מהו יחס ההמרה המקובל בהיעדר הוראה מפורשתיום בפיקוח שווה ליום מאחורי סורג ובריח) (בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר).
**וריאציה 3 — רציונל:** מה הרציונל מאחורי הכללת מעצר בפיקוח אלקטרוני במנייןחשיבות הזכות לחירות וחזקת החפות, וצורך בביקורת שיפוטית על משך המעצר (בש"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר).', 'מעצר בפיקוח אלקטרונינכלל במניין 9 חודשי מעצר עד תום הליכיםביחס 1:1 (מלצרלמרות מחלוקת על יחס ההמרה.', '["חוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ\"ו-1996, סעיף 61(א)", "בש\"פ 4206/16 מדינת ישראל נ'' מוחסן טחימר (03.11.2016)", "עמ\"ת (מחוזי חיפה) 31476-05-16 מדינת ישראל נ'' מוחסן טחימר (22.05.2016)", "מ\"ת (שלום עכו) 54134-05-15 מדינת ישראל נ'' מוחסן טחימר (11.05.2016)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מעצר בפיקוח אלקטרוני אינו נכלל כלל במניין 9 חודשי המעצר מאחורי סורג ובריח.', false, 'תשובה זו שגויה. מעצר בפיקוח אלקטרוני נכלל במניין 9 חודשי המעצר לצורך סעיף 61(א) לחוק המעצרים, אך קיימת מחלוקת לגבי יחס ההמרה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, תקופת המעצר בפיקוח אלקטרוני תיכלל במניין 9 חודשי המעצר, ביחס של 1:1 (יום בפיקוח שווה ליום מאחורי סורג ובריח).', true, 'זו התשובה הנכונה, לפי עמדת הרוב בבש"פ 4206/16 (השופט מלצר), בהיעדר הוראת חוק מפורשת ליחס המרה אחר לצורך סעיף 61(א) לחוק המעצרים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, תקופת המעצר בפיקוח אלקטרוני תיכלל במניין 9 חודשי המעצר, ביחס של 1:2 (יום מאחורי סורג ובריח שווה ליומיים בפיקוח אלקטרוני).', false, 'תשובה זו שגויה, אף שהיא משקפת את עמדת המיעוט בבש"פ 4206/16 (השופט הנדל) ואת עמדת בית המשפט המחוזי, היא אינה ההלכה המחייבת בהיעדר הוראת חוק מפורשת.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם סך כל תקופת המעצר (מאחורי סורג ובריח ובפיקוח אלקטרוני) עולה על 18 חודשים.', false, 'תשובה זו שגויה. מגבלת 18 החודשים מתייחסת למעצר בפיקוח אלקטרוני בלבד, ולא לסך המצטבר של שני סוגי המעצר לצורך סעיף 61(א).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q19';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 19, '2024-W-S-Q19';
END
$$;

-- ============================================================
-- Q21 — angles backfill for 2024-W-S-Q21 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q21';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q21';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הטלת קנס שלא נתבקש בהליך אזרחי', 1,
      'במהלך דיון אזרחי, עד שהוזמן להעיד לא התייצב ללא סיבה מוצדקת. בית המשפט סבור כי יש להטיל עליו קנס כספי בגין אי-התייצבותו, אף שהצדדים לא ביקשו זאת. מה הדין?', 'שאלה זו עוסקת בסמכותו של בית המשפט האזרחי להטיל סנקציות על אי-ציות לצו שיפוטי, ובפרט על עד שלא התייצב. היא בוחנת את הוראות סעיף 73 לחוק בתי המשפט, המאפשרות הטלת קנס או מאסר, תוך שמירה על זכות הטיעון של העד.', 'סעיף 73(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "מי שהוזמן להעיד ולא התייצב, או נצטווה להמציא מסמך ולא המציאו, רשאי בית המשפט או הרשם – (1) לצוות על הבאתו לפני בית המשפט; (2) להטיל עליו, אף שלא בפניו, מחצית הקנס האמור בסעיף 40(2) לחוק העונשין, התשל"ז-1977, ואם הוזמן או נצטווה פעם נוספת ולא התייצב או לא המציא את המסמך – מאסר שלא יעלה על חודש ימים או קנס כאמור בסעיף 40(2) לחוק האמור". סעיף 73(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984 סמכות זו היא יזומה של בית המשפט ואינה דורשת בקשה מצד בעלי הדין. עם זאת, סעיף 73(ב) קובע כי מי שהוטל עליו קנס שלא בפניו, רשאי לבקש מבית המשפט לעיין שנית בהחלטה, להקל או לבטל את הקנס, אם שוכנע שלא התייצב מסיבות שלא הייתה לו שליטה עליהן. סעיף 73(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984 מכאן עולה כי יש לאפשר לעד זכות טיעון, גם אם בדיעבד, בטרם הקנס הופך לסופי. יעקב שקד סדר הדין האזרחי (2026) | פרק טז אולם המשפט - ניהול וסמכויות', 'הטעות הנפוצה היא להניח שסמכות בית המשפט להטיל קנסות בהליך אזרחי מוגבלת רק למקרים של ביזיון בית משפט, או שהיא דורשת בקשה מפורשת של אחד הצדדים.',
      '["סמכות בית המשפט", "אי-ציות לצו", "קנס כספי", "חוק בתי המשפט", "זכות טיעון", "עד"]'::jsonb, '**וריאציה 1 — סמכות יזומה:** האם בית המשפט יכול להטיל קנס על עד שלא התייצב מיוזמתו? ← כן, לפי סעיף 73(א) לחוק בתי המשפט. סעיף 73(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984
**וריאציה 2 — זכות טיעון:** האם לעד יש זכות טיעון לפני הטלת הקנס? ← כן, גם אם הקנס הוטל שלא בפניו, הוא רשאי לבקש עיון חוזר (סעיף 73(ב)). סעיף 73(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984
**וריאציה 3 — סכום הקנס:** מהו סכום הקנס המקסימלי שניתן להטיל? ← מחצית הקנס האמור בסעיף 40(2) לחוק העונשין (סעיף 73(א)(2)). סעיף 73(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984', 'עד לא התייצב ← ביהמ"ש מוסמך להטיל קנס מיוזמתו (ס'' 73 לחוק בתי המשפט) ← חובה לתת זכות טיעון (גם בדיעבד).', '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 73", "חוק העונשין, תשל\"ז-1977, סעיף 40(2)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט אינו מוסמך להטיל קנס על עד שלא התייצב, אלא אם כן התביעה הגישה בקשה מפורשת לכך.', false, 'טענה זו שגויה, שכן סעיף 73 לחוק בתי המשפט מקנה לבית המשפט סמכות יזומה להטיל קנס על עד שלא התייצב, ללא צורך בבקשת התביעה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט מוסמך להטיל קנס על העד מיוזמתו, ובלבד שתינתן לעד הזדמנות לטעון טענותיו לעניין זה.', true, 'תשובה זו נכונה, שכן סעיף 73(א)(2) לחוק בתי המשפט מקנה לבית המשפט סמכות להטיל קנס על עד שלא התייצב, וכללי הצדק הטבעי מחייבים מתן זכות טיעון לעד.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט רשאי רק לצוות על הבאת העד בכוח, ואינו מוסמך להטיל עליו קנס כספי.', false, 'טענה זו שגויה, שכן סעיף 73(א) לחוק בתי המשפט מעניק לבית המשפט שתי סמכויות חלופיות: צו הבאה או הטלת קנס/מאסר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הטלת קנס על עד שלא התייצב אפשרית רק אם העד הוזהר מראש על אפשרות זו בהזמנה לדיון.', false, 'טענה זו שגויה, שכן סעיף 73 לחוק בתי המשפט אינו דורש אזהרה מוקדמת בהזמנה לדיון לצורך הטלת קנס על עד שלא התייצב, אם כי זו פרקטיקה רצויה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q21';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאים להטלת עונש יזום', 2,
      'מהם התנאים שבית המשפט חייב לקיים לפני הטלת עונש מיוזמתו, שלא נתבקש על ידי התביעה?', 'שאלה זו מתמקדת בסדרי הדין שבית המשפט חייב לנקוט כאשר הוא שוקל להטיל עונש מיוזמתו, שלא נתבקש על ידי התביעה. היא מדגישה את חשיבות זכות הטיעון של הנאשם ואת חובת ההנמקה של בית המשפט, כפי שנקבעו בפסיקת בית המשפט העליון.', 'הלכת בית המשפט העליון, כפי שנקבעה בע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל, ובהתבסס על עמדת השופט הנדל בעניין קוואסמה, מבהירה כי בית המשפט מוסמך להטיל עונש מיוזמתו, אך עליו לנקוט בשני מהלכי סדרי דין עיקריים. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016) ראשית, עליו ליידע את הצדדים (הסניגוריה או הנאשם אם אינו מיוצג) על כוונתו לשקול הטלת עונש שלא התבקש, ולאפשר להם להציג את עמדתם בעניין. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016) שנית, על בית המשפט לנמק בגזר הדין מדוע מצא לנכון להטיל עונש זה, ובפרט להבהיר מדוע אין לשיטתו די בעונשים שנתבקשו על ידי התביעה. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016) מהלכים אלו מבטאים עקרונות של צדק והגינות, מאפשרים לנאשם לגבש את הגנתו ומבטיחים את מימוש זכות הטיעון שלו, וכן מאפשרים ביקורת אפקטיבית על הפעלת הסמכות. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)', 'הטעות הנפוצה היא להתעלם מהדרישות הפרוצדורליות המחמירות שנקבעו בפסיקה, ולחשוב שסמכות בית המשפט להטיל עונש מיוזמתו היא בלתי מוגבלת.',
      '["עונש יזום", "סדרי דין", "זכות טיעון", "חובת הנמקה", "עקרון ההלימה", "ע\"פ מעוז"]'::jsonb, '**וריאציה 1 — יידוע הצדדים:** האם בית המשפט חייב ליידע את הצדדים על כוונתו להטיל עונש יזום? ← כן, ולאפשר להם לטעון לעניין (ע"פ מעוז). ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)
**וריאציה 2 — חובת הנמקה:** האם בית המשפט חייב לנמק את החלטתו להטיל עונש יזום? ← כן, ובפרט להבהיר מדוע אין די בעונש שנתבקש על ידי התביעה (ע"פ מעוז). ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)
**וריאציה 3 — עקרונות יסוד:** אילו עקרונות מנחים את הדרישות הפרוצדורליות? ← צדק, הגינות, זכות טיעון, חובת הנמקה וביקורת אפקטיבית (ע"פ מעוז). ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)', 'ביהמ"ש מטיל עונש יזום ← חובה ליידע צדדים + זכות טיעון ← חובה לנמק החלטה ← עקרונות צדק והגינות.', '["ע\"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)", "ע\"פ 3341/14 שריף קוואסמה נ'' מדינת ישראל (03.11.2015)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט חייב ליידע את הצדדים על כוונתו להטיל עונש כזה, לאפשר להם לטעון לעניין, ולנמק את החלטתו בגזר הדין.', true, 'תשובה זו נכונה, שכן היא משקפת את סדרי הדין שנקבעו בפסיקת בית המשפט העליון (עניין מעוז ועניין קוואסמה) כתנאי להפעלת סמכות בית המשפט להטיל עונש מיוזמתו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט רשאי להטיל עונש מיוזמתו ללא צורך ביידוע הצדדים, שכן סמכות גזירת הדין נתונה לו בלעדית.', false, 'טענה זו שגויה, שכן למרות שסמכות גזירת הדין נתונה לבית המשפט, עליו לקיים סדרי דין מתאימים, ובכלל זה יידוע הצדדים ומתן זכות טיעון, כדי להבטיח הליך הוגן.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט חייב לקבל את הסכמת התביעה להטלת עונש נוסף, שכן התביעה מייצגת את האינטרס הציבורי.', false, 'טענה זו שגויה, שכן בית המשפט אינו כפוף לעמדת התביעה בעניין העונש, ואינו נדרש להסכמתה כדי להטיל עונש מיוזמתו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט רשאי להטיל עונש מיוזמתו רק אם העונש המוצע על ידי התביעה חורג באופן קיצוני לקולא מהעונש הראוי.', false, 'טענה זו שגויה, שכן זהו שיקול מהותי לבחינת הסדר טיעון, אך אינו תנאי סף להפעלת סמכות בית המשפט להטיל עונש מיוזמתו, אלא רק אחד השיקולים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q21';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'הטלת מאסר שלא נתבקש בהיעדר נאשם', 3,
      'נאשם הורשע בעבירת פשע שלא בפניו, לאחר שביקש שמשפטו יתנהל כך והוא מיוצג על ידי סניגור. התביעה ביקשה להטיל עליו קנס בלבד. בית המשפט שוקל להטיל עליו עונש מאסר בפועל. מה הדין?', 'שאלה זו עוסקת במגבלות על הטלת עונש מאסר בפועל על נאשם בפשע, במיוחד כאשר הדיון מתנהל שלא בפניו. היא מדגישה את חשיבות נוכחות הנאשם וזכות הטיעון שלו לעניין העונש, כפי שמעוגן בחוק סדר הדין הפלילי.', 'סעיף 130 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע את התנאים לדיון ושפיטת נאשם שלא בפניו. סעיף 130(ג) קובע כי "הורשע נאשם שלא בפניו לפי סעיף זה, רשאי בית המשפט לגזור את דינו שלא בפניו ובלבד שבית המשפט לא יטיל עליו עונש מאסר". סעיף 130(ג) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982 אולם, סעיף 130(ג1) קובע חריג חשוב לעבירות פשע: "על אף האמור בסעיף קטן (ג), לא יגזור בית המשפט את דינו של נאשם בפשע אלא בפניו ולאחר שניתנה לו הזדמנות להשמיע את טענותיו לענין העונש, כאמור בסעיף 192". סעיף 130(ג1) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982 במקרה הנדון, מדובר בעבירת פשע (גרימת חבלה חמורה), ולכן בית המשפט אינו רשאי להטיל עונש מאסר בפועל אלא אם הנאשם יתייצב בפניו ויתאפשר לו לטעון לעניין העונש. נבו - המתמחה סדר הדין הפלילי (2026) | ז. נוכחות בעלי דין במשפט', 'הטעות הנפוצה היא להניח שכללי הדיון שלא בפני נאשם זהים לכל סוגי העבירות, מבלי להבחין בין חטא/עוון לפשע, ובמיוחד במקרים של הטלת מאסר בפועל.',
      '["דיון שלא בפני נאשם", "עבירת פשע", "עונש מאסר בפועל", "זכות טיעון", "חוק סדר הדין הפלילי", "סעיף 130"]'::jsonb, '**וריאציה 1 — פשע והיעדרות:** האם ניתן לגזור מאסר בפועל על פשע שלא בפני נאשם? ← לא, רק בפניו ולאחר זכות טיעון (סעיף 130(ג1) לחסד"פ). סעיף 130(ג1) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982
**וריאציה 2 — חטא/עוון והיעדרות:** האם ניתן לגזור מאסר על חטא/עוון שלא בפני נאשם? ← כן, אם ניתנה הזדמנות לטעון לעונש (סעיף 130(ג) לחסד"פ). סעיף 130(ג) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982
**וריאציה 3 — ייצוג סניגור:** האם ייצוג על ידי סניגור משנה את הדרישה לנוכחות הנאשם בפשע? ← לא, הדרישה לנוכחות הנאשם בפשע וזכות הטיעון שלו לעונש נשארת בעינה (סעיף 130(ג1)). סעיף 130(ג1) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982', 'נאשם בפשע ← הורשע שלא בפניו ← לא ניתן לגזור מאסר בפועל ← אלא אם יתייצב ויטען לעונש (ס'' 130(ג1) לחסד"פ).', '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 130"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט רשאי להטיל עונש מאסר בפועל, שכן הנאשם ביקש שמשפטו יתנהל שלא בפניו והוא מיוצג.', false, 'טענה זו שגויה, שכן גם במקרה זה, סעיף 130(ג1) לחוק סדר הדין הפלילי קובע כי לא יגזור בית המשפט את דינו של נאשם בפשע אלא בפניו ולאחר שניתנה לו הזדמנות לטעון לעניין העונש.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט אינו רשאי להטיל עונש מאסר בפועל, אלא אם כן הנאשם יתייצב בפניו ויתאפשר לו לטעון לעניין העונש.', true, 'תשובה זו נכונה, שכן סעיף 130(ג1) לחוק סדר הדין הפלילי קובע כי לא יגזור בית המשפט את דינו של נאשם בפשע אלא בפניו ולאחר שניתנה לו הזדמנות להשמיע את טענותיו לעניין העונש.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט רשאי להטיל עונש מאסר בפועל, ובלבד שינמק את החלטתו בגזר הדין.', false, 'טענה זו שגויה, שכן חובת ההנמקה אינה מספקת במקרה של הטלת מאסר בפועל על נאשם בפשע שלא בפניו; נדרשת נוכחות הנאשם וזכות טיעון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט אינו רשאי להטיל עונש מאסר בפועל, שכן התביעה ביקשה קנס בלבד.', false, 'טענה זו שגויה, שכן בית המשפט אינו כפוף לבקשת התביעה לעניין העונש, אך הוא כפוף לדרישות הפרוצדורליות של נוכחות הנאשם וזכות טיעון במקרה של מאסר בפועל על פשע.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q21';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות ערכאת הערעור בעונש יזום', 4,
      'בית המשפט המחוזי הטיל על אורטל עונש קנס כספי מיוזמתו, בנוסף למאסר, מבלי ליידע את הצדדים ומבלי לנמק את החלטתו. אורטל מערערת על גזר הדין. מהי סמכות בית המשפט העליון כערכאת ערעור במקרה זה?', 'שאלה זו עוסקת בסמכותה של ערכאת הערעור להתערב בגזר דין שבו הוטל עונש מיוזמת הערכאה הדיונית, מבלי שנשמרו סדרי הדין הנדרשים. היא מדגישה את שיקול הדעת הרחב של ערכאת הערעור, המאפשר לה לבחור בין מספר סעדים, ולא רק לבטל את העונש.', 'הלכת בית המשפט העליון בעניין ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל קובעת כי גם כאשר הפעלת הסמכות להטיל עונש יזום לא נעשתה על פי סדרי הדין שפורטו (יידוע הצדדים והנמקה), אין לקבוע בהכרח כי הפעלת הסמכות נעשתה באופן שאינו תקין וכי דין הערעור להתקבל. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016) לערכאת הערעור, כמו לערכאה הדיונית, שיקול דעת רחב, והיא רשאית להחליט בהתאם למקרה שלפניה האם להורות על החזרת התיק לשמיעת טיעונים; להתערב בעונש; או להותירו על כנו. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016) סעיף 213 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, מעניק לבית המשפט שלערעור סמכות רחבה לקבל את הערעור, לשנות את פסק הדין או לבטלו, או להחזיר את המשפט עם הוראות לערכאה הקודמת. סעיף 213 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982 במקרה הנדון, אי-קיום סדרי הדין פגע בזכות הטיעון של אורטל, ולכן בית המשפט העליון יבחן את מכלול הנסיבות ויחליט על הסעד המתאים ביותר. ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)', 'הטעות הנפוצה היא לחשוב שאי-קיום סדרי דין מוביל בהכרח לביטול אוטומטי של העונש, מבלי להבין את שיקול הדעת הרחב של ערכאת הערעור ואת מגוון הסעדים העומדים לרשותה.',
      '["ערעור פלילי", "סמכות ערכאת ערעור", "עונש יזום", "סדרי דין", "שיקול דעת שיפוטי", "חוק סדר הדין הפלילי"]'::jsonb, '**וריאציה 1 — סעדים אפשריים:** אילו סעדים יכולה ערכאת הערעור לנקוט במקרה של פגם בסדרי דין? ← החזרת התיק לטיעונים, התערבות בעונש, או השארת העונש על כנו (ע"פ מעוז). ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)
**וריאציה 2 — חובת ביטול:** האם ערכאת הערעור חייבת לבטל את העונש? ← לא, אין חובה אוטומטית לביטול, אלא שיקול דעת רחב (ע"פ מעוז). ע"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)
**וריאציה 3 — סמכות כללית:** מהי סמכותה הכללית של ערכאת הערעור? ← לקבל את הערעור, לשנות או לבטל את פסק הדין, או להחזיר את התיק עם הוראות (סעיף 213 לחסד"פ). סעיף 213 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982', 'ערעור על עונש יזום ללא סדרי דין ← לערכאת הערעור שיקול דעת רחב ← יכולה להחזיר לטיעונים, להתערב או להותיר על כנו.', '["ע\"פ 5733/13 דניאל מעוז נ'' מדינת ישראל (05.07.2016)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 213"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'בית המשפט העליון חייב לבטל את עונש הקנס, שכן לא נשמרו סדרי הדין הנדרשים.', false, 'טענה זו שגויה, שכן לערכאת הערעור שיקול דעת רחב, והיא אינה חייבת לבטל את העונש, אלא יכולה גם להחזיר את התיק לטיעונים או להתערב בעונש באופן אחר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'בית המשפט העליון רשאי להחזיר את התיק לבית המשפט המחוזי לשמיעת טיעונים לעונש, להתערב בעונש או להותירו על כנו, לפי שיקול דעתו הרחב.', true, 'תשובה זו נכונה, שכן היא משקפת את הלכת בית המשפט העליון בעניין מעוז, לפיה לערכאת הערעור שיקול דעת רחב בטיפול במקרים בהם לא נשמרו סדרי הדין בהטלת עונש יזום.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'בית המשפט העליון אינו מוסמך להתערב בעונש שהוטל מיוזמת הערכאה הדיונית, שכן סמכות גזירת הדין נתונה לערכאה הדיונית בלבד.', false, 'טענה זו שגויה, שכן ערכאת הערעור מוסמכת להתערב בגזר דין של הערכאה הדיונית, ובכלל זה בעונשים שהוטלו מיוזמתה, במיוחד כאשר נפלו פגמים בסדרי הדין.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'בית המשפט העליון יורה על ביטול גזר הדין כולו, ויחזיר את התיק לדיון מחודש בבית המשפט המחוזי.', false, 'טענה זו שגויה, שכן ביטול גזר הדין כולו והחזרת התיק לדיון מחודש הוא סעד קיצוני, וערכאת הערעור יכולה לנקוט בסעדים פחות דרסטיים, כמו התערבות בעונש הספציפי או החזרת התיק לשמיעת טיעונים בלבד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q21';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 21, '2024-W-S-Q21';
END
$$;

-- ============================================================
-- Q22 — angles backfill for 2024-W-S-Q22 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q22';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q22';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'ביטול עסקת מכר מרחוק על ידי אזרח ותיק', 1,
      'שרה, בת 70, ראתה פרסום לחבילת נופש באתר אינטרנט של חברת תיירות. היא התקשרה לחברה, שוחחה עם נציג, וביצעה הזמנה טלפונית. כעבור חודשיים היא התחרטה ורוצה לבטל את העסקה. עד מתי רשאית שרה לבטל את העסקה?', 'שאלה זו עוסקת בזכות הביטול המורחבת הניתנת לאוכלוסיות מיוחדות, כגון אזרחים ותיקים, בעסקאות מכר מרחוק. היא בוחנת את תנאי סעיף 14ג1 לחוק הגנת הצרכן, המאריך את תקופת הביטול ל-4 חודשים, ודורש שההתקשרות תכלול שיחה בין העוסק לצרכן.', 'חוק הגנת הצרכן (תיקון מס'' 47) האריך את תקופת הביטול עבור אנשים עם מוגבלות, עולים חדשים ואזרחים ותיקים. סעיף 14ג1(ג) לחוק הגנת הצרכן קובע כי בעסקת מכר מרחוק שנערכה עם צרכן שהוא אזרח ותיק (מי שמלאו לו 65 שנים), רשאי הצרכן לבטל את העסקה בתוך ארבעה חודשים מיום עשיית העסקה, מיום קבלת הנכס או מיום קבלת המסמך המכיל את הפרטים, לפי המאוחר. סעיף 14ג1(ג) לחוק הגנת הצרכן, תשמ"א-1981 תנאי נוסף הוא שההתקשרות בעסקה כללה שיחה בין העוסק לצרכן, ובכלל זה שיחה באמצעות תקשורת אלקטרונית. רת"ק (מחוזי ת"א) 52608-09-24 קרוז תור בע"מ נ'' מיכאל בורשטיין (28.11.2024) במקרה של שרה, היא בת 70 (אזרחית ותיקה) וביצעה שיחה טלפונית עם נציג החברה, ולכן היא עומדת בתנאים לזכות ביטול מורחבת של 4 חודשים. ת"ק (תביעות קטנות ראשל"צ) 22796-12-20 דניאל לב נ'' בשביל הזהב תיירות בע"מ (15.04.2021)', 'הטעות הנפוצה היא להתעלם מההגנות המיוחדות הניתנות לאוכלוסיות מוחלשות, כמו אזרחים ותיקים, וליישם עליהן את תקופת הביטול הכללית של 14 ימים.',
      '["עסקת מכר מרחוק", "אזרח ותיק", "זכות ביטול מורחבת", "חוק הגנת הצרכן", "סעיף 14ג1", "שיחה עם עוסק"]'::jsonb, '**וריאציה 1 — אזרח ותיק:** מהי תקופת הביטול לאזרח ותיק בעסקת מכר מרחוק? ← 4 חודשים, בתנאי שההתקשרות כללה שיחה. סעיף 14ג1(ג) לחוק הגנת הצרכן, תשמ"א-1981
**וריאציה 2 — הגדרת אזרח ותיק:** מי נחשב ל"אזרח ותיק" לעניין זה? ← מי שמלאו לו 65 שנים. סעיף 14ג1(א) לחוק הגנת הצרכן, תשמ"א-1981
**וריאציה 3 — תכלית התיקון:** מהי מטרת התיקון שהאריך את תקופת הביטול? ← להגן על צרכנים מאוכלוסיות מיוחדות מפני לחץ שיווקי או אי-הבנה של פרטי העסקה. ת"ק (תביעות קטנות ראשל"צ) 22796-12-20 דניאל לב נ'' בשביל הזהב תיירות בע"מ (15.04.2021)', 'אזרח ותיק (65+) בעסקת מכר מרחוק שכללה שיחה ← זכאי לביטול תוך 4 חודשים ← הגנה מפני לחץ ופערי מידע.', '["חוק הגנת הצרכן, תשמ\"א-1981, סעיף 14ג1", "רת\"ק (מחוזי ת\"א) 52608-09-24 קרוז תור בע\"מ נ'' מיכאל בורשטיין (28.11.2024)", "ת\"ק (תביעות קטנות ראשל\"צ) 22796-12-20 דניאל לב נ'' בשביל הזהב תיירות בע\"מ (15.04.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'עד 14 ימים ממועד קבלת מסמך פרטי העסקה.', false, 'טענה זו שגויה, שכן תקופה זו חלה על צרכן רגיל, אך שרה היא אזרחית ותיקה הזכאית לתקופת ביטול ארוכה יותר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'עד 4 חודשים מיום עשיית העסקה, קבלת הנכס או קבלת המסמך המכיל את הפרטים, לפי המאוחר.', true, 'תשובה זו נכונה, שכן שרה היא אזרחית ותיקה (מעל גיל 65) וההתקשרות כללה שיחה, ולכן היא זכאית לתקופת ביטול מורחבת של 4 חודשים לפי סעיף 14ג1(ג) לחוק הגנת הצרכן.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא ניתן לבטל את העסקה, שכן חלפו יותר מ-14 ימים מיום עשיית העסקה.', false, 'טענה זו שגויה, שכן עבור אזרחים ותיקים, תקופת הביטול ארוכה יותר מ-14 ימים, ואינה מוגבלת למועד עשיית העסקה בלבד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'עד 7 ימים שאינם ימי מנוחה קודם למועד מתן השירות.', false, 'טענה זו שגויה, שכן תקופה זו מתייחסת לחריג לזכות הביטול, ולא לתקופת הביטול עצמה, והיא רלוונטית רק אם מועד הביטול חל בתוך 7 ימים אלו.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q22';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הגדרת "עסקת מכר מרחוק"', 2,
      'מהם המאפיינים המרכזיים של "עסקת מכר מרחוק" לפי חוק הגנת הצרכן והפסיקה?', 'שאלה זו בוחנת את ההגדרה המשפטית של "עסקת מכר מרחוק" ו"שיווק מרחוק" לפי חוק הגנת הצרכן, ואת הפרשנות שניתנה לה בפסיקה, במיוחד בהקשר של עסקאות מקוונות. היא מדגישה את העובדה שגם פנייה יזומה של צרכן לאתר אינטרנט של עוסק יכולה להיחשב כעסקת מכר מרחוק.', 'סעיף 14ג(ו) לחוק הגנת הצרכן מגדיר "עסקת מכר מרחוק" כ"התקשרות בעסקה של מכר נכס או של מתן שירות, כאשר ההתקשרות נעשית בעקבות שיווק מרחוק, ללא נוכחות משותפת של הצדדים לעסקה". סעיף 14ג(ו) לחוק הגנת הצרכן, תשמ"א-1981 "שיווק מרחוק" מוגדר כ"פניה של עוסק לצרכן באמצעות דואר, טלפון, רדיו, טלויזיה, תקשורת אלקטרונית מכל סוג שהוא, פקסימיליה, פרסום קטלוגים או מודעות, או באמצעי כיוצא באלה, במטרה להתקשר בעסקה שלא בנוכחות משותפת של הצדדים". סעיף 14ג(ו) לחוק הגנת הצרכן, תשמ"א-1981 הפסיקה קבעה כי אתר אינטרנט המציע שירותים למכירה הוא כשלעצמו פנייה לציבור, ואין בעובדה שהצרכן יזם את הפנייה לאתר כדי לאיין את הגדרת העסקה כ"עסקת מכר מרחוק". רת"ק (מחוזי תל אביב-יפו) 72588-12-25 פגסוס תיירות ונסיעות בע"מ נ'' שאול טוויג (22.02.2026) רת"ק (מחוזי ת"א) 52608-09-24 קרוז תור בע"מ נ'' מיכאל בורשטיין (28.11.2024)', 'הטעות הנפוצה היא לחשוב ש"שיווק מרחוק" דורש פנייה אקטיבית ואישית של העוסק לצרכן, ולא לכלול פרסום כללי באתר אינטרנט כפנייה כזו.',
      '["עסקת מכר מרחוק", "שיווק מרחוק", "חוק הגנת הצרכן", "סעיף 14ג(ו)", "פנייה יזומה של צרכן", "אתר אינטרנט"]'::jsonb, '**וריאציה 1 — יזמת הפנייה:** האם פנייה יזומה של צרכן לאתר עוסק שוללת "מכר מרחוק"? ← לא, אתר אינטרנט הוא כשלעצמו פנייה לציבור. רת"ק (מחוזי תל אביב-יפו) 72588-12-25 פגסוס תיירות ונסיעות בע"מ נ'' שאול טוויג (22.02.2026)
**וריאציה 2 — רכיבי ההגדרה:** מהם שני הרכיבים העיקריים בהגדרת "עסקת מכר מרחוק"? ← התקשרות בעקבות שיווק מרחוק וללא נוכחות משותפת. סעיף 14ג(ו) לחוק הגנת הצרכן, תשמ"א-1981
**וריאציה 3 — דוגמאות לשיווק מרחוק:** אילו אמצעים נכללים ב"שיווק מרחוק"? ← דואר, טלפון, רדיו, טלוויזיה, תקשורת אלקטרונית, פרסום קטלוגים או מודעות. סעיף 14ג(ו) לחוק הגנת הצרכן, תשמ"א-1981', 'עסקת מכר מרחוק ← שיווק מרחוק (כולל אתר אינטרנט) + ללא נוכחות משותפת ← גם אם הצרכן יזם פנייה לאתר.', '["חוק הגנת הצרכן, תשמ\"א-1981, סעיף 14ג(ו)", "רת\"ק (מחוזי תל אביב-יפו) 72588-12-25 פגסוס תיירות ונסיעות בע\"מ נ'' שאול טוויג (22.02.2026)", "רת\"ק (מחוזי ת\"א) 52608-09-24 קרוז תור בע\"מ נ'' מיכאל בורשטיין (28.11.2024)", "רת\"ק (מחוזי מרכז) 60485-01-25 אלטו איטליה בע\"מ נ'' משה אפרתי (12.08.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'התקשרות בעסקה של מכר נכס או שירות, שנעשית בעקבות שיווק מרחוק וללא נוכחות משותפת של הצדדים, גם אם הצרכן יזם את הפנייה לאתר העוסק.', true, 'תשובה זו נכונה, שכן היא משלבת את הגדרת החוק עם הפרשנות המקובלת בפסיקה, לפיה פרסום באתר אינטרנט נחשב ל''שיווק מרחוק'' גם אם הצרכן יזם את הפנייה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'התקשרות בעסקה של מכר נכס או שירות, שנעשית ללא נוכחות משותפת של הצדדים, ורק אם העוסק יזם את הפנייה לצרכן באופן אישי.', false, 'טענה זו שגויה, שכן היא דורשת פנייה אישית יזומה מהעוסק, בעוד שהפסיקה קבעה כי פרסום כללי באתר אינטרנט יכול להיחשב כ''שיווק מרחוק''.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כל עסקה שנעשית באמצעות האינטרנט או הטלפון, ללא קשר לשיווק מרחוק.', false, 'טענה זו שגויה, שכן ההגדרה דורשת שההתקשרות תהיה ''בעקבות שיווק מרחוק'', ולא כל עסקה מקוונת או טלפונית נכנסת להגדרה זו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'עסקה שבה הצרכן אינו יכול להתרשם מהנכס או השירות באופן בלתי אמצעי, ללא קשר לאופן ההתקשרות.', false, 'טענה זו שגויה, שכן למרות שזהו אחד הרציונלים להגנת הצרכן, ההגדרה החוקית מתמקדת באופן ההתקשרות (שיווק מרחוק וללא נוכחות משותפת).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q22';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריגים לזכות הביטול בעסקת מכר מרחוק', 3,
      'יוסי רכש כרטיסי טיסה לאילת באתר אינטרנט של חברת תעופה. הטיסה אמורה לצאת בעוד 3 ימים. יוסי התחרט ורוצה לבטל את הכרטיסים. האם יוסי רשאי לבטל את העסקה ולקבל החזר כספי (בניכוי דמי ביטול)?', 'שאלה זו עוסקת בחריגים לזכות הביטול בעסקת מכר מרחוק, כפי שנקבעו בסעיף 14ג(ד) לחוק הגנת הצרכן. היא מתמקדת בחריג הספציפי לשירותי הארחה, נסיעה, חופש או בילוי, כאשר מועד הביטול קרוב למועד מתן השירות.', 'סעיף 14ג(ג) לחוק הגנת הצרכן מעניק לצרכן זכות לבטל עסקת מכר מרחוק בתוך 14 ימים מיום עשיית העסקה או קבלת המסמך. סעיף 14ג(ג) לחוק הגנת הצרכן, תשמ"א-1981 אולם, סעיף 14ג(ד)(2) לחוק קובע חריג לזכות ביטול זו, לפיו הוראות סעיף קטן (ג) לא יחולו על עסקת מכר מרחוק של "שירותי הארחה, נסיעה, חופש או בילוי, אם מועד ביטול העסקה חל בתוך שבעה ימים שאינם ימי מנוחה, קודם למועד שבו אמור השירות להינתן". סעיף 14ג(ד)(2) לחוק הגנת הצרכן, תשמ"א-1981 במקרה של יוסי, הוא רכש כרטיסי טיסה (שירותי נסיעה) והטיסה אמורה לצאת בעוד 3 ימים. מכיוון שמועד הביטול חל בתוך 7 ימים שאינם ימי מנוחה קודם למועד מתן השירות, יוסי אינו זכאי לבטל את העסקה לפי הוראות סעיף 14ג(ג) לחוק. ת"ק (תביעות קטנות עכו) 50231-05-22 כסיף יניר נ'' מונה טורס בע"מ (25.03.2023)', 'הטעות הנפוצה היא להתעלם מהחריגים לזכות הביטול, במיוחד אלו הנוגעים לשירותי תיירות ונסיעות קצרי מועד, וליישם את הכלל הכללי של 14 ימי ביטול.',
      '["עסקת מכר מרחוק", "חריגים לביטול עסקה", "שירותי נסיעה", "חוק הגנת הצרכן", "סעיף 14ג(ד)(2)", "מועד מתן השירות"]'::jsonb, '**וריאציה 1 — חריג שירותי נסיעה:** מתי לא ניתן לבטל עסקת מכר מרחוק של שירותי נסיעה? ← אם מועד הביטול חל בתוך 7 ימים שאינם ימי מנוחה קודם למתן השירות. סעיף 14ג(ד)(2) לחוק הגנת הצרכן, תשמ"א-1981
**וריאציה 2 — רציונל החריג:** מהו הרציונל לחריג זה? ← לצמצם פגיעה קשה באינטרסים של העוסקים בשירותים אלו. רע"א 3429/13 ישי רז נ'' גוליבר תיירות בע''''מ (13.04.2014)
**וריאציה 3 — ביטול עקב פגם:** האם החריג חל גם אם הביטול הוא עקב פגם בשירות? ← לא, החריג חל רק על ביטול שלא מהטעמים המנויים בסעיף 14ה(א) (פגם, אי-התאמה, הפרה). סעיף 14ה(א) לחוק הגנת הצרכן, תשמ"א-1981', 'שירותי נסיעה ← ביטול בתוך 7 ימים שאינם ימי מנוחה לפני השירות ← אין זכות ביטול (ס'' 14ג(ד)(2)) ← למעט ביטול עקב פגם.', '["חוק הגנת הצרכן, תשמ\"א-1981, סעיף 14ג(ד)(2)", "חוק הגנת הצרכן, תשמ\"א-1981, סעיף 14ה(א)", "רע\"א 3429/13 ישי רז נ'' גוליבר תיירות בע''''מ (13.04.2014)", "ת\"ק (תביעות קטנות עכו) 50231-05-22 כסיף יניר נ'' מונה טורס בע\"מ (25.03.2023)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, יוסי רשאי לבטל את העסקה בתוך 14 ימים מיום עשיית העסקה או קבלת המסמך, לפי המאוחר.', false, 'טענה זו שגויה, שכן למרות שזו תקופת הביטול הכללית, קיים חריג ספציפי לשירותי נסיעה כאשר מועד הביטול קרוב למועד מתן השירות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן מדובר בשירותי נסיעה שמועד ביטולם חל בתוך שבעה ימים שאינם ימי מנוחה קודם למועד מתן השירות.', true, 'תשובה זו נכונה, שכן סעיף 14ג(ד)(2) לחוק הגנת הצרכן קובע חריג לזכות הביטול בעסקאות מכר מרחוק של שירותי נסיעה, אם מועד הביטול חל בתוך 7 ימים שאינם ימי מנוחה לפני מועד מתן השירות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם חברת התעופה לא גילתה לו את תנאי הביטול בטרם ההתקשרות.', false, 'טענה זו שגויה, שכן חובת הגילוי רלוונטית בעיקר לעסקאות תיירות מחוץ לישראל לפי סעיף 14ג2, אך אינה מבטלת את החריג הכללי לשירותי נסיעה קצרי מועד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, שכן כרטיסי טיסה נחשבים לטובין פסידים שאינם ניתנים לביטול.', false, 'טענה זו שגויה, שכן כרטיסי טיסה אינם מוגדרים כ''טובין פסידים'' לעניין זה, והחריג הרלוונטי הוא ספציפי לשירותי נסיעה קצרי מועד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q22';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'דמי ביטול בעסקת מכר מרחוק', 4,
      'אדם רכש באתר אינטרנט של חברת תעופה 3 כרטיסי טיסה במחיר כולל של 3,000 ש"ח. הוא התחרט וביטל את כל הכרטיסים באותה פעולה, שלא עקב פגם. מהו סכום דמי הביטול המקסימלי שחברת התעופה רשאית לגבות ממנו?', 'שאלה זו עוסקת בסוגיית דמי הביטול בעסקת מכר מרחוק, ובפרט בחישובם כאשר מדובר ברכישת מספר כרטיסי טיסה. היא בוחנת את הוראות סעיף 14ה(ב) לחוק הגנת הצרכן ואת הפרשנות שניתנה לה בפסיקת בית המשפט העליון בעניין צמח, לפיה דמי הביטול נגבים פר-כרטיס ולא פר-עסקה כוללת.', 'סעיף 14ה(ב) לחוק הגנת הצרכן קובע כי כאשר צרכן מבטל חוזה שלא מהטעמים המנויים בסעיף קטן (א) (כלומר, עקב חרטה ולא עקב פגם או הפרה), העוסק רשאי לגבות דמי ביטול בשיעור שלא יעלה על 5% ממחיר הנכס נושא החוזה או העסקה, או 100 ש"ח, לפי הנמוך מביניהם. סעיף 14ה(ב)(1) לחוק הגנת הצרכן, תשמ"א-1981 הפסיקה, ובראשה דנ"א 5783/14 צמח נ'' אל על נתיבי אויר לישראל בע"מ, קבעה כי בעסקת מכר מרחוק של כרטיסי טיסה, ניתן לגבות דמי ביטול בגין כל כרטיס טיסה בנפרד, ולא עבור העסקה כמכלול. דנ"א 5783/14 עו"ד ליאור צמח נ'' אל על נתיבי אויר לישראל בע"מ (12.09.2017) במקרה זה, מחיר כל כרטיס הוא 1,000 ש"ח (3,000 ש"ח / 3 כרטיסים). 5% מ-1,000 ש"ח הם 50 ש"ח. מכיוון ש-50 ש"ח נמוך מ-100 ש"ח, חברת התעופה רשאית לגבות 50 ש"ח לכרטיס. עבור 3 כרטיסים, הסכום הכולל יהיה 3 * 50 ש"ח = 150 ש"ח. נבו - המתמחה דיני נזיקין (2026) | תעריף שקבע לפי דין – איסור גביית עמלה ודרכי תשלום', 'הטעות הנפוצה היא לחשב את דמי הביטול על בסיס מחיר העסקה הכולל, במקום על בסיס כל רכיב בנפרד, במיוחד בעסקאות כרטיסי טיסה, או להתעלם מתקרת 100 השקלים לכל רכיב.',
      '["דמי ביטול", "עסקת מכר מרחוק", "כרטיסי טיסה", "חוק הגנת הצרכן", "סעיף 14ה(ב)", "דנ\"א צמח"]'::jsonb, '**וריאציה 1 — חישוב דמי ביטול כללי:** מהם דמי הביטול המקסימליים בעסקת מכר מרחוק (ללא פגם)? ← 5% ממחיר העסקה או 100 ש"ח, לפי הנמוך. סעיף 14ה(ב)(1) לחוק הגנת הצרכן, תשמ"א-1981
**וריאציה 2 — דמי ביטול לכרטיסי טיסה:** כיצד מחושבים דמי ביטול לכרטיסי טיסה? ← פר-כרטיס, ולא פר-עסקה כוללת. דנ"א 5783/14 עו"ד ליאור צמח נ'' אל על נתיבי אויר לישראל בע"מ (12.09.2017)
**וריאציה 3 — דוגמת חישוב:** 3 כרטיסים ב-3,000 ש"ח, ביטול. כמה דמי ביטול? ← 150 ש"ח (50 ש"ח לכרטיס * 3). נבו - המתמחה דיני נזיקין (2026) | תעריף שקבע לפי דין – איסור גביית עמלה ודרכי תשלום', 'דמי ביטול מכר מרחוק (חרטה) ← 5% או 100 ש"ח (הנמוך) ← לכרטיסי טיסה: פר-כרטיס (דנ"א צמח).', '["חוק הגנת הצרכן, תשמ\"א-1981, סעיף 14ה(ב)", "דנ\"א 5783/14 עו\"ד ליאור צמח נ'' אל על נתיבי אויר לישראל בע\"מ (12.09.2017)", "נבו - המתמחה דיני נזיקין (2026) | תעריף שקבע לפי דין – איסור גביית עמלה ודרכי תשלום"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', '100 ש"ח.', false, 'טענה זו שגויה, שכן 100 ש"ח הוא הסכום המקסימלי לכרטיס בודד, אך במקרה של מספר כרטיסים שבוטלו, ניתן לגבות דמי ביטול עבור כל כרטיס בנפרד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', '150 ש"ח.', true, 'תשובה זו נכונה, שכן לפי הפסיקה בעניין צמח, בעסקת מכר מרחוק של כרטיסי טיסה, ניתן לגבות דמי ביטול עבור כל כרטיס בנפרד, בשיעור של 5% ממחיר הכרטיס או 100 ש"ח, לפי הנמוך. במקרה זה, 5% מ-1,000 ש"ח (מחיר ממוצע לכרטיס) הם 50 ש"ח, ולכן 3 כרטיסים יחויבו ב-3 * 50 = 150 ש"ח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', '5% ממחיר העסקה הכולל, כלומר 150 ש"ח.', false, 'טענה זו שגויה, שכן למרות שהחישוב הסופי נכון במקרה זה, הרציונל הוא גבייה פר-כרטיס ולא פר-עסקה כוללת, והתקרה של 100 ש"ח חלה על כל כרטיס בנפרד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'אין לגבות דמי ביטול, שכן הצרכן התחרט בתוך תקופת הביטול.', false, 'טענה זו שגויה, שכן זכות הביטול במקרה של חרטה כרוכה בתשלום דמי ביטול, בניגוד לביטול עקב פגם או הפרה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q22';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 22, '2024-W-S-Q22';
END
$$;

-- ============================================================
-- Q23 — angles backfill for 2024-W-S-Q23 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q23';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q23';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תחלוף בביטוח ימי על ידי מבטח זר', 1,
      'חברת ספנות ישראלית ביטחה מטען ימי אצל מבטח זר. המטען ניזוק בנמל חיפה עקב רשלנות של חברת נמל חיפה. המבטח הזר שילם לחברת הספנות את תגמולי הביטוח. האם המבטח הזר רשאי לתבוע את חברת נמל חיפה מכוח זכות התחלוף?', 'שאלה זו בוחנת את תחולת זכות התחלוף על מבטח זר, ובפרט בהקשר של ביטוח ימי. היא מדגישה את החריג הקבוע בסעיף 72(א)(2) לחוק חוזה הביטוח, המאפשר למבטח ימי זר לתבוע מכוח סעיף 62, וכן את האפשרות לתבוע מכוח דיני עשיית עושר ולא במשפט.', 'סעיף 62(א) לחוק חוזה הביטוח מקנה למבטח ששילם למבוטח תגמולי ביטוח זכות תחלוף נגד צד שלישי. סעיף 62(א) לחוק חוזה הביטוח, תשמ"א-1981 באופן כללי, עלתה בפסיקה השאלה האם מבטח זר, שאינו עונה להגדרת "מבטח" בחוק הפיקוח על שירותים פיננסיים (ביטוח), זכאי לזכות תחלוף לפי סעיף 62. רע"א 8588/19 חברת נמל חיפה בע"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020) אולם, סעיף 72(א)(2) לחוק חוזה הביטוח קובע כי הוראות חוק חוזה הביטוח לא יחולו על ביטוח ימי, למעט סעיפים 62 ו-69 לחוק. רע"א 8588/19 חברת נמל חיפה בע"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020) משמעות הדבר היא שסעיף 62 חל גם על מבטח ימי זר, ובכך מקנה לו זכות תחלוף. רע"א 8588/19 חברת נמל חיפה בע"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020) בנוסף, גם אם חוק חוזה הביטוח אינו חל, מבטח זר יכול להגיש תביעת תחלוף מכוח העיקרון הכללי של דיני עשיית עושר ולא במשפט. ע"א 206/20 טבע תעשיות פרמצבטיות בע"מ נ'' טי.אנד.אם גושן - שירותי ביטחון בע"מ (13.12.2021)', 'הטעות הנפוצה היא להניח שמבטח זר לעולם אינו זכאי לזכות תחלוף לפי חוק חוזה הביטוח, מבלי להכיר בחריג הספציפי לביטוח ימי או באפשרות לתבוע מכוח דיני עשיית עושר ולא במשפט.',
      '["תחלוף", "מבטח זר", "ביטוח ימי", "חוק חוזה הביטוח", "סעיף 62", "סעיף 72(א)(2)", "עשיית עושר ולא במשפט"]'::jsonb, '**וריאציה 1 — מבטח זר כללי:** האם מבטח זר זכאי לתחלוף לפי סעיף 62 לחוק חוזה הביטוח? ← לא באופן כללי, אלא אם חל חריג. רע"א 8588/19 חברת נמל חיפה בע"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020)
**וריאציה 2 — ביטוח ימי:** האם ביטוח ימי הוא חריג? ← כן, סעיף 72(א)(2) לחוק חוזה הביטוח מחיל את סעיף 62 גם על ביטוח ימי. רע"א 8588/19 חברת נמל חיפה בע"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020)
**וריאציה 3 — עשיית עושר:** האם קיימת עילה חלופית? ← כן, תביעת תחלוף מכוח דיני עשיית עושר ולא במשפט. ע"א 206/20 טבע תעשיות פרמצבטיות בע"מ נ'' טי.אנד.אם גושן - שירותי ביטחון בע"מ (13.12.2021)', 'מבטח ימי זר ← זכאי לתחלוף לפי סעיף 62 לחוק חוזה הביטוח (ס'' 72(א)(2)) ← או מכוח דיני עשיית עושר ולא במשפט.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 62", "חוק חוזה הביטוח, תשמ\"א-1981, סעיף 72(א)(2)", "רע\"א 8588/19 חברת נמל חיפה בע\"מ נ'' Certasig Insurance and Reinsurance Company S.A Rom (22.12.2020)", "ע\"א 206/20 טבע תעשיות פרמצבטיות בע\"מ נ'' טי.אנד.אם גושן - שירותי ביטחון בע\"מ (13.12.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שהמבטח הזר אינו עונה להגדרת "מבטח" בחוק הפיקוח על שירותים פיננסיים (ביטוח), ולכן אינו זכאי לזכות תחלוף לפי סעיף 62 לחוק חוזה הביטוח.', false, 'טענה זו שגויה, שכן למרות שהמבטח הזר אינו עונה להגדרת "מבטח" בחוק הפיקוח, סעיף 72(א)(2) לחוק חוזה הביטוח קובע חריג לביטוח ימי, המאפשר תחולת סעיף 62 גם על מבטח ימי זר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, מכיוון שסעיף 72(א)(2) לחוק חוזה הביטוח קובע כי הוראות סעיף 62 יחולו על ביטוח ימי, גם אם המבטח הוא זר.', true, 'תשובה זו נכונה, שכן הפסיקה (רע"א 8588/19) קבעה כי סעיף 72(א)(2) לחוק חוזה הביטוח מהווה "חריג לחריג" ומחיל את סעיף 62 על ביטוח ימי, ובכך מקנה זכות תחלוף גם למבטח ימי זר.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק מכוח העיקרון הכללי של דיני עשיית עושר ולא במשפט, ולא מכוח סעיף 62 לחוק חוזה הביטוח.', false, 'טענה זו שגויה, שכן למרות שקיימת אפשרות לתבוע מכוח דיני עשיית עושר ולא במשפט, במקרה של ביטוח ימי, סעיף 62 לחוק חוזה הביטוח חל במפורש מכוח סעיף 72(א)(2).', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן חוזה הביטוח נשלט על ידי הדין הישראלי.', false, 'טענה זו שגויה, שכן הפסיקה (ע"א 206/20 טבע) קבעה כי גם אם חוזה הביטוח נשלט על פי דין זר, עומדת למבטחת הזרה זכות להיפרע מהמזיק, בין אם מכוח סעיף 62 (בביטוח ימי) ובין אם מכוח דיני עשיית עושר ולא במשפט.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q23';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאים לגיבוש זכות התחלוף', 2,
      'מהם התנאים המצטברים הנדרשים לגיבוש זכות התחלוף של מבטח כלפי צד שלישי, לפי סעיף 62 לחוק חוזה הביטוח?', 'שאלה זו מתמקדת ביסודות המהותיים הנדרשים לגיבוש זכות התחלוף של המבטח, כפי שנקבעו בסעיף 62 לחוק חוזה הביטוח וכפי שפורשו בפסיקה. היא מדגישה את שלושת התנאים המצטברים: חבות חוזית של המבטח, תשלום בפועל, וזכות של המבוטח כלפי צד שלישי.', 'הפסיקה קבעה באופן עקבי כי זכות התחלוף של המבטח, המעוגנת בסעיף 62 לחוק חוזה הביטוח, קמה בהתקיים שלושה תנאים מצטברים. ת"א (שלום ת"א) 5865-03-10 ביטוח ישיר איי.די.איי חברה לביטוח בע''''מ נ'' ירון חיים רחמין (20.05.2013) התנאי הראשון הוא התגבשות חבות חוזית של המבטח כלפי המבוטח, על פי פוליסת ביטוח תקפה. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמישה תחלוף (שיבוב) התנאי השני הוא ביצוע תשלום בפועל של תגמולי הביטוח למבוטח בהתאם לחבות זו. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב) התנאי השלישי הוא קיומה של זכות בידי המבוטח כלפי צד שלישי לפצות או לשפות אותו בגין מקרה הביטוח, כאשר מקור החובה יכול להיות חוזי, נזיקי, חוקי או אחר, למעט אם מקור החובה נובע מחוזה ביטוח נוסף של המבוטח. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב) ת"א (שלום רמ'') 3383-12-20 יעקב גרא נ'' הרשות הארצית לכבאות והצלה (08.05.2022)', 'הטעות הנפוצה היא להתבלבל בין התנאים לגיבוש זכות התחלוף לבין רציונלים העומדים בבסיסה, או להשמיט אחד מהתנאים המצטברים.',
      '["תחלוף", "סעיף 62 לחוק חוזה הביטוח", "חבות חוזית", "תשלום תגמולי ביטוח", "זכות פיצוי/שיפוי", "צד שלישי"]'::jsonb, '**וריאציה 1 — תנאי 1:** מהו התנאי הראשון לגיבוש תחלוף? ← חבות חוזית של המבטח כלפי המבוטח לפי פוליסה תקפה. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)
**וריאציה 2 — תנאי 2:** מהו התנאי השני? ← תשלום בפועל של תגמולי הביטוח למבוטח. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)
**וריאציה 3 — תנאי 3:** מהו התנאי השלישי? ← קיומה של זכות בידי המבוטח כלפי צד שלישי לפיצוי או שיפוי. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)', 'תחלוף (ס'' 62) ← 3 תנאים: חבות מבטח, תשלום בפועל, זכות מבוטח כלפי צד ג''.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 62", "ת\"א (שלום ת\"א) 5865-03-10 ביטוח ישיר איי.די.איי חברה לביטוח בע''''מ נ'' ירון חיים רחמין (20.05.2013)", "תא\"מ (שלום ת\"א) 170775-09 איילון בע\"מ - חברה לבטוח נ'' עמאד אבו סרארי (10.05.2012)", "ע\"א 7287/12 חתמי לויד''ס נ'' חברת נמל אשדוד בע\"מ (09.12.2014)", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'התגבשות חבות חוזית של המבטח כלפי המבוטח, תשלום בפועל של תגמולי הביטוח למבוטח, וקיומה של זכות בידי המבוטח כלפי צד שלישי לפיצוי או שיפוי.', true, 'תשובה זו נכונה, שכן היא מפרטת את שלושת התנאים המצטברים שנקבעו בפסיקה לגיבוש זכות התחלוף מכוח סעיף 62 לחוק חוזה הביטוח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'התרחשות מקרה ביטוח, הגשת תביעה על ידי המבוטח, וקביעת אחריות של צד שלישי על ידי בית המשפט.', false, 'טענה זו שגויה, שכן התרחשות מקרה ביטוח היא תנאי לחבות המבטח, אך לא לגיבוש זכות התחלוף, וקביעת אחריות על ידי בית המשפט אינה תנאי מוקדם לגיבוש הזכות, אלא תוצאה אפשרית של מימושה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הסכמה מפורשת של המבוטח להעברת זכות התביעה למבטח, ותשלום תגמולי ביטוח למבוטח.', false, 'טענה זו שגויה, שכן זכות התחלוף לפי סעיף 62 היא מכוח הדין ואינה דורשת הסכמה מפורשת של המבוטח, אלא עוברת למבטח באופן אוטומטי עם התשלום.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הוכחת רשלנות של צד שלישי, ותשלום תגמולי ביטוח למבוטח.', false, 'טענה זו שגויה, שכן חבות הצד השלישי אינה חייבת לנבוע מרשלנות דווקא, אלא יכולה לנבוע ממקורות אחרים (חוזי, חוקי), ונדרשים תנאים נוספים מעבר לתשלום תגמולי הביטוח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q23';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריג התחלוף בקרבת משפחה', 3,
      'ראובן נהג ברכב של בנו וגרם נזק לרכב של שמעון. חברת הביטוח של שמעון שילמה לו את תגמולי הביטוח. האם חברת הביטוח של שמעון רשאית לתבוע את חברת הביטוח של ראובן (המזיק)?', 'שאלה זו עוסקת בחריג לזכות התחלוף הקבוע בסעיף 62(ד) לחוק חוזה הביטוח, הנוגע למקרים של קרבת משפחה או יחסי עובד-מעביד. היא בוחנת את פרשנותו של חריג זה בפסיקת בית המשפט העליון, אשר צמצמה את תחולתו למקרים בהם התביעה היא נגד בן המשפחה/עובד עצמו, ולא נגד חברת הביטוח שלו.', 'סעיף 62(ד) לחוק חוזה הביטוח קובע חריג לזכות התחלוף, לפיו הוראות הסעיף לא יחולו אם מקרה הביטוח נגרם שלא בכוונה בידי אדם שמבוטח סביר לא היה תובע ממנו פיצוי או שיפוי, מחמת קרבת משפחה או יחס של מעביד ועובד שביניהם. סעיף 62(ד) לחוק חוזה הביטוח, תשמ"א-1981 הרציונל שבבסיס חריג זה הוא שמירה על התא המשפחתי או על יחסי העבודה. רע"א 4179/20 בסט קאר חברה לשירותי רכב בע"מ נ'' איי. די .איי חברה לביטוח בע"מ (18.11.2020) אולם, בית המשפט העליון קבע ברע"א 4179/20 בסט קאר כי חריג זה אינו חל כאשר התביעה מתנהלת בין שתי חברות ביטוח (מבטח הניזוק נגד מבטח המזיק), שכן במקרה כזה, הרציונל של שמירה על התא המשפחתי אינו מתקיים. רע"א 4179/20 בסט קאר חברה לשירותי רכב בע"מ נ'' איי. די .איי חברה לביטוח בע"מ (18.11.2020) לכן, במקרה הנדון, חברת הביטוח של שמעון רשאית לתבוע את חברת הביטוח של ראובן, למרות קרבת המשפחה בין ראובן לבנו. רע"א 4179/20 בסט קאר חברה לשירותי רכב בע"מ נ'' איי. די .איי חברה לביטוח בע"מ (18.11.2020)', 'הטעות הנפוצה היא לפרש את סעיף 62(ד) באופן מרחיב ולחשוב שהוא שולל זכות תחלוף בכל מקרה של קרבת משפחה, גם כאשר התביעה היא בין חברות ביטוח ולא פוגעת בתא המשפחתי.',
      '["תחלוף", "חריג קרבת משפחה", "סעיף 62(ד) לחוק חוזה הביטוח", "רציונל שמירה על התא המשפחתי", "תביעה בין מבטחים", "פרשנות מצמצמת"]'::jsonb, '**וריאציה 1 — תביעה נגד בן משפחה:** האם מבטח יכול לתבוע בן משפחה מזיק? ← לא, אם מבוטח סביר לא היה תובע (סעיף 62(ד)). סעיף 62(ד) לחוק חוזה הביטוח, תשמ"א-1981
**וריאציה 2 — תביעה נגד מבטח בן משפחה:** האם מבטח יכול לתבוע את חברת הביטוח של בן המשפחה המזיק? ← כן, הרציונל של שמירה על התא המשפחתי אינו נפגע (רע"א 4179/20). רע"א 4179/20 בסט קאר חברה לשירותי רכב בע"מ נ'' איי. די .איי חברה לביטוח בע"מ (18.11.2020)
**וריאציה 3 — נזק בכוונה:** האם החריג חל אם הנזק נגרם בכוונה? ← לא, החריג חל רק אם הנזק נגרם שלא בכוונה (סעיף 62(ד)). סעיף 62(ד) לחוק חוזה הביטוח, תשמ"א-1981', 'חריג קרבת משפחה (ס'' 62(ד)) ← לא חל בתביעה בין מבטחים ← הרציונל (שמירה על תא משפחתי) לא נפגע.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 62(ד)", "רע\"א 4179/20 בסט קאר חברה לשירותי רכב בע\"מ נ'' איי. די .איי חברה לביטוח בע\"מ (18.11.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שסעיף 62(ד) לחוק חוזה הביטוח שולל זכות תחלוף במקרה של קרבת משפחה.', false, 'טענה זו שגויה, שכן הפסיקה (רע"א 4179/20) קבעה כי חריג קרבת המשפחה חל רק כאשר התביעה היא נגד בן המשפחה עצמו, ולא כאשר היא נגד חברת הביטוח שלו, שכן אז לא נפגע התא המשפחתי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, מכיוון שהרציונל של שמירה על התא המשפחתי אינו מתקיים כאשר התביעה מתנהלת בין שתי חברות ביטוח.', true, 'תשובה זו נכונה, שכן היא משקפת את הלכת בית המשפט העליון (רע"א 4179/20), לפיה סעיף 62(ד) אינו מונע תביעת תחלוף של מבטח הניזוק נגד מבטח המזיק, גם אם המזיק הוא בן משפחה, שכן אין פגיעה בתא המשפחתי.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם ראובן לא היה מבוטח בביטוח חובה.', false, 'טענה זו שגויה, שכן שאלת ביטוח החובה אינה רלוונטית לתחולת חריג קרבת המשפחה בסעיף 62(ד) לחוק חוזה הביטוח, אלא לכיסוי נזקי גוף.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הנזק נגרם בכוונה על ידי ראובן.', false, 'טענה זו שגויה, שכן סעיף 62(ד) חל רק כאשר הנזק נגרם *שלא בכוונה*, ולכן אם הנזק נגרם בכוונה, החריג אינו חל והמבטח יכול לתבוע את המזיק.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q23';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'היקף התחלוף: הוצאות שמאות', 4,
      'חברת ביטוח שילמה למבוטח תגמולי ביטוח בגין נזק לרכבו. לצורך הערכת הנזק, הוציאה חברת הביטוח הוצאות שמאות. האם חברת הביטוח רשאית לתבוע מהמזיק גם את הוצאות השמאות הללו מכוח זכות התחלוף?', 'שאלה זו עוסקת בהיקף זכות התחלוף של המבטח, ובפרט בשאלה האם הוצאות שהוציא המבטח לצורך בירור חבותו (כגון הוצאות שמאות) נכללות בזכות זו. היא בוחנת את הפרשנות המצמצמת של סעיף 62(א) לחוק חוזה הביטוח, לפיה זכות התחלוף מוגבלת לשיעור התגמולים ששולמו למבוטח.', 'סעיף 62(א) לחוק חוזה הביטוח קובע כי זכות התחלוף עוברת למבטח "כשיעור התגמולים ששילם". סעיף 62(א) לחוק חוזה הביטוח, תשמ"א-1981 הפסיקה והספרות המשפטית מפרשות לשון זו באופן מצמצם, וקובעות כי הסכומים שזכאי המבטח לקבל מידי המזיק מכוח זכות התחלוף אינם כוללים הוצאות שהוציא המבטח לשם בירור החבות והיקפה, כגון הוצאות חקירה ושמאות. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב) ע"א 2906/01 עירית חיפה נ'' מנורה חברה לביטוח בע"מ (25.05.2006) הטעם לכך הוא שהוצאות אלו מוצאות על ידי המבטח בראש ובראשונה על מנת להפחית את חיובו שלו, ואין בהכרח זיקה בינן לבין חבות המזיק. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)', 'הטעות הנפוצה היא להניח שזכות התחלוף כוללת את כל ההוצאות שהוציא המבטח בקשר למקרה הביטוח, ולא להבחין בין תגמולי ביטוח ששולמו למבוטח לבין הוצאות פנימיות של המבטח.',
      '["תחלוף", "היקף זכות התחלוף", "הוצאות שמאות", "חוק חוזה הביטוח", "סעיף 62(א)", "תגמולי ביטוח"]'::jsonb, '**וריאציה 1 — היקף התחלוף:** מה כוללת זכות התחלוף? ← שיעור תגמולי הביטוח ששולמו למבוטח. סעיף 62(א) לחוק חוזה הביטוח, תשמ"א-1981
**וריאציה 2 — הוצאות שמאות:** האם הוצאות שמאות נכללות בתחלוף? ← לא, הן אינן חלק מהתגמולים ששולמו למבוטח. ע"א 2906/01 עירית חיפה נ'' מנורה חברה לביטוח בע"מ (25.05.2006)
**וריאציה 3 — רציונל:** מדוע הוצאות שמאות אינן נכללות? ← הן מוצאות להפחתת חיוב המבטח ואין זיקה הכרחית לחבות המזיק. ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)', 'תחלוף (ס'' 62(א)) ← מוגבל לתגמולי ביטוח ששולמו ← לא כולל הוצאות שמאות של המבטח.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 62(א)", "ע\"א 2906/01 עירית חיפה נ'' מנורה חברה לביטוח בע\"מ (25.05.2006)", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-וחמשה תחלוף (שיבוב)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהוצאות השמאות הן חלק בלתי נפרד מהנזק שנגרם למבוטח.', false, 'טענה זו שגויה, שכן הוצאות השמאות הן הוצאות של המבטח עצמו לצורך בירור חבותו, ואינן חלק מהנזק הישיר שנגרם למבוטח, ולכן אינן נכללות בזכות התחלוף.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שזכות התחלוף מוגבלת לשיעור תגמולי הביטוח ששולמו למבוטח, ואינה כוללת הוצאות שהוציא המבטח לשם בירור החבות.', true, 'תשובה זו נכונה, שכן הפסיקה והספרות המשפטית קובעות כי זכות התחלוף לפי סעיף 62(א) לחוק חוזה הביטוח מוגבלת לסכום תגמולי הביטוח ששולמו למבוטח, ואינה כוללת הוצאות נלוות של המבטח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם המבוטח הסכים מראש לכך.', false, 'טענה זו שגויה, שכן זכות התחלוף היא מכוח הדין, והיקפה אינו תלוי בהסכמת המבוטח להכללת הוצאות שמאות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הוצאות השמאות עולות על 5% מסכום תגמולי הביטוח.', false, 'טענה זו שגויה, שכן אין קשר בין שיעור הוצאות השמאות לבין זכות התחלוף, והיקף הזכות אינו נקבע באחוזים מסכום התגמולים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q23';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 23, '2024-W-S-Q23';
END
$$;

-- ============================================================
-- Q24 — angles backfill for 2024-W-S-Q24 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q24';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q24';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'התנגדות מבוטח לפשרה - טעמים לגיטימיים', 1,
      'חברת ביטוח הודיעה למבוטח שלה, קבלן בניין, על כוונתה להתפשר עם צד שלישי שנפגע באתר בנייה. הקבלן מתנגד לפשרה. איזה מבין הטעמים הבאים נחשב לגיטימי להתנגדותו של המבוטח לפשרה?', 'שאלה זו בוחנת את הטעמים הלגיטימיים להתנגדות מבוטח להסדר פשרה שמציעה חברת הביטוח עם צד שלישי. היא מדגישה את האינטרסים השונים של המבוטח, מעבר להיבט הכספי הישיר, כגון מוניטין ורצון להוכיח חפות.', 'סעיף 68 לחוק חוזה הביטוח מעניק למבוטח זכות להתנגד לתשלום לצד השלישי. סעיף 68 לחוק חוזה הביטוח, תשמ"א-1981 הפסיקה והספרות המשפטית מפרטות מגוון טעמים לגיטימיים להתנגדות זו. בין הטעמים הלגיטימיים נמנים: רצון להימנע מתשלום השתתפות עצמית כתוצאה מתשלום התגמולים לצד השלישי, חשש מייקור עתידי של פרמיות הביטוח כתוצאה מהפעלת הפוליסה, וחשש מפגיעה במוניטין המקצועי של המבוטח עקב הכרה באחריותו כלפי הצד השלישי. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות כמו כן, מבוטח עשוי להתנגד לפשרה מתוך אמונה בלתי מסויגת במופרכות התביעה נגדו. שחר ולר חוק חוזה הביטוח כרך ב (2005) | סעיף 66. היקף החבות של המבטח השימוש בזכות ההתנגדות צריך להיעשות בתום לב ומטעמים סבירים. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'הטעות הנפוצה היא לחשוב שהתנגדות המבוטח לפשרה חייבת להיות מבוססת על טעמים כספיים בלבד, ולהתעלם מאינטרסים לגיטימיים אחרים כמו מוניטין או עקרונות.',
      '["זכות התנגדות המבוטח", "סעיף 68 לחוק חוזה הביטוח", "טעמים לגיטימיים להתנגדות", "מוניטין מקצועי", "השתתפות עצמית", "תום לב"]'::jsonb, '**וריאציה 1 — טעמים כספיים:** האם חשש מייקור פרמיות הוא טעם לגיטימי? ← כן, זהו אינטרס כלכלי לגיטימי של המבוטח. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות
**וריאציה 2 — טעמים לא כספיים:** האם פגיעה במוניטין היא טעם לגיטימי? ← כן, במיוחד בביטוח אחריות מקצועית. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות
**וריאציה 3 — עקרון תום הלב:** האם כל התנגדות לגיטימית? ← לא, השימוש בזכות ההתנגדות צריך להיעשות בתום לב ומטעמים סבירים. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'התנגדות מבוטח לפשרה (ס'' 68) ← לגיטימית אם מבוססת על טעמים סבירים ← כולל חשש ממוניטין, ייקור פרמיות, או אמונה בחפות.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 68", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות", "שחר ולר חוק חוזה הביטוח כרך ב (2005) | סעיף 66. היקף החבות של המבטח"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'חשש מפגיעה במוניטין המקצועי של הקבלן עקב הכרה באחריותו לאירוע.', false, 'טענה זו נכונה, שכן חשש מפגיעה במוניטין הוא טעם לגיטימי להתנגדות המבוטח לפשרה, במיוחד כאשר מדובר באחריות מקצועית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'רצון להימנע מתשלום השתתפות עצמית כתוצאה מתשלום התגמולים לצד השלישי.', false, 'טענה זו נכונה, שכן הימנעות מתשלום השתתפות עצמית היא אינטרס לגיטימי של המבוטח בהתנגדות לפשרה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'אמונה בלתי מסויגת במופרכות התביעה נגדו ורצון לנהל משפט עד תום.', false, 'טענה זו נכונה, שכן אמונה בחפותו ורצון להוכיח זאת בבית המשפט נחשבים לטעם לגיטימי להתנגדות לפשרה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כל התשובות נכונות.', true, 'תשובה זו נכונה, שכן כל הטעמים המפורטים באפשרויות א-ג נחשבים לגיטימיים להתנגדות המבוטח לפשרה, כפי שעולה מהפסיקה והספרות המשפטית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q24';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'חובת המבטח ליידע את המבוטח', 2,
      'חברת ביטוח מעוניינת להתפשר עם צד שלישי בתביעת אחריות. מה צריכה לכלול ההודעה בכתב שהיא שולחת למבוטח, כדי לעמוד בדרישות סעיף 68 לחוק חוזה הביטוח?', 'שאלה זו מתמקדת בפרשנות דרישת ההודעה בכתב למבוטח לפי סעיף 68 לחוק חוזה הביטוח. היא בוחנת את היקף המידע שחברת הביטוח מחויבת למסור למבוטח כדי לאפשר לו לממש את זכות ההתנגדות באופן אפקטיבי.', 'סעיף 68 לחוק חוזה הביטוח קובע כי המבטח רשאי לשלם לצד שלישי תגמולי ביטוח, ובלבד שהודיע על כך בכתב למבוטח 30 ימים מראש והמבוטח לא התנגד. סעיף 68 לחוק חוזה הביטוח, תשמ"א-1981 הפסיקה מדגישה כי כדי שזכות ההתנגדות של המבוטח תשרת את מטרתה, עליה להיות אפקטיבית ולא ערטילאית. ע"א (מחוזי חי'') 45011-12-20 מוסך חיים אבני חיפה בע"מ נ'' מנורה מבטחים ביטוח בע"מ (05.07.2021) לכן, ההודעה צריכה לכלול את כל הפרטים הרלוונטיים שיאפשרו למבוטח להביע דעה מושכלת, לרבות פרטי התביעה, סכום הפשרה המוצע, וההשלכות האפשריות על המבוטח, כגון חובתו לשלם השתתפות עצמית והפסד הנחת פרמיה. ע"א (מחוזי חי'') 45011-12-20 מוסך חיים אבני חיפה בע"מ נ'' מנורה מבטחים ביטוח בע"מ (05.07.2021)', 'הטעות הנפוצה היא לפרש את דרישת ההודעה בכתב באופן מצומצם, כאילו די בהודעה כללית, מבלי להבין את הצורך בפירוט שיאפשר למבוטח להפעיל את זכותו באופן משמעותי.',
      '["חובת הודעה בכתב", "סעיף 68 לחוק חוזה הביטוח", "זכות התנגדות אפקטיבית", "פירוט פרטי פשרה", "השלכות על המבוטח", "תום לב"]'::jsonb, '**וריאציה 1 — תוכן ההודעה:** מה צריכה לכלול הודעה על פשרה? ← פרטי התביעה, סכום הפשרה, והשלכות על המבוטח. ע"א (מחוזי חי'') 45011-12-20 מוסך חיים אבני חיפה בע"מ נ'' מנורה מבטחים ביטוח בע"מ (05.07.2021)
**וריאציה 2 — מטרת ההודעה:** מהי מטרת ההודעה למבוטח? ← לאפשר לו להביע דעה אפקטיבית בנוגע לפשרה. ע"א (מחוזי חי'') 45011-12-20 מוסך חיים אבני חיפה בע"מ נ'' מנורה מבטחים ביטוח בע"מ (05.07.2021)
**וריאציה 3 — חובת המבטח:** האם המבטח חייב לשתף את המבוטח? ← כן, המבטח מחויב לאפשר למבוטח להיות שותף לפשרה המתגבשת. תאד"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע"מ נ'' בזיני אברהם (23.04.2024)', 'הודעת מבטח למבוטח (ס'' 68) ← חייבת להיות בכתב, 30 יום מראש ← לכלול פרטי תביעה, סכום פשרה, והשלכות ← כדי לאפשר התנגדות אפקטיבית.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 68", "ע\"א (מחוזי חי'') 45011-12-20 מוסך חיים אבני חיפה בע\"מ נ'' מנורה מבטחים ביטוח בע\"מ (05.07.2021)", "תאד\"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע\"מ נ'' בזיני אברהם (23.04.2024)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הודעה כללית על כוונת המבטח להתפשר, ללא פירוט סכום הפשרה.', false, 'טענה זו שגויה, שכן הודעה כללית אינה מספקת כדי לאפשר למבוטח להפעיל את זכות ההתנגדות באופן אפקטיבי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פירוט מלא של פרטי התביעה, סכום הפשרה המוצע, וההשלכות האפשריות על המבוטח (כגון השתתפות עצמית וייקור פרמיות).', true, 'תשובה זו נכונה, שכן הפסיקה מדגישה כי כדי שזכות ההתנגדות תהיה אפקטיבית, על ההודעה לכלול את כל הפרטים הרלוונטיים שיאפשרו למבוטח להביע דעה מושכלת.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק את סכום הפשרה המוצע, ללא צורך בפירוט נוסף.', false, 'טענה זו שגויה, שכן סכום הפשרה לבדו אינו מספיק כדי שהמבוטח יוכל להעריך את מלוא ההשלכות ולהחליט אם להתנגד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הודעה על הפשרה המוצעת, בצירוף דרישה לתשלום השתתפות עצמית.', false, 'טענה זו שגויה, שכן דרישה לתשלום השתתפות עצמית היא תוצאה אפשרית של הפשרה, אך אינה מהווה את מלוא חובת ההודעה המוקדמת.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q24';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'תוצאות הפרת חובת ההודעה על ידי המבטח', 3,
      'חברת ביטוח התפשרה עם צד שלישי בתביעת אחריות ושילמה לו פיצוי, מבלי שהודיעה על כך למבוטח בכתב 30 ימים מראש, כנדרש בסעיף 68 לחוק חוזה הביטוח. מהן התוצאות המשפטיות של הפרה זו?', 'שאלה זו עוסקת בתוצאות המשפטיות של הפרת חובת ההודעה הקבועה בסעיף 68 לחוק חוזה הביטוח. היא בוחנת את ההשלכות על מערכת היחסים בין המבטח למבוטח, תוך הבחנה בין תוקף הפשרה מול הצד השלישי לבין זכויות המבוטח כלפי המבטח.', 'סעיף 68 לחוק חוזה הביטוח קובע חובת הודעה בכתב למבוטח 30 ימים מראש לפני תשלום תגמולי ביטוח לצד שלישי. סעיף 68 לחוק חוזה הביטוח, תשמ"א-1981 הגישה השלטת בפסיקה היא כי הפרת חובה זו על ידי המבטח אינה מפקיעה את תוקף הסדר הפשרה שנחתם עם הצד השלישי. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות אולם, במישור היחסים בין המבטח למבוטח, הפרת חובת ההודעה עלולה לגרור שתי תרופות עיקריות: ראשית, המבטח עלול לאבד את זכותו לדרוש מהמבוטח תשלום השתתפות עצמית. ע"א (מחוזי תל אביב-יפו) 2539/07 הפניקס חברה לבטוח בע"מ נ'' מאיירס שיווק (1981) בע"מ (29.10.2008) שנית, המבוטח זכאי לפיצויים חוזיים או נזיקיים בגין כל נזק שנגרם לו עקב הפרת החובה, לרבות פגיעה באוטונומיה או נזק ראייתי. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'הטעות הנפוצה היא להסיק שהפרת חובת ההודעה מבטלת את הפשרה כולה, במקום להבין שההשלכות הן בעיקרן על מערכת היחסים הפנימית בין המבטח למבוטח.',
      '["הפרת חובה חקוקה", "סעיף 68 לחוק חוזה הביטוח", "אובדן זכות השתתפות עצמית", "פיצויים למבוטח", "תוקף הסכם פשרה", "נזק ראייתי"]'::jsonb, '**וריאציה 1 — תוקף הפשרה:** האם פשרה ללא הודעה כדין בטלה? ← לא, הפשרה מול הצד השלישי נשארת תקפה. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות
**וריאציה 2 — השתתפות עצמית:** האם המבטח יכול לדרוש השתתפות עצמית? ← לא, הוא עלול לאבד את זכותו לדרוש השתתפות עצמית. ע"א (מחוזי תל אביב-יפו) 2539/07 הפניקס חברה לבטוח בע"מ נ'' מאיירס שיווק (1981) בע"מ (29.10.2008)
**וריאציה 3 — פיצוי למבוטח:** האם המבוטח זכאי לפיצוי? ← כן, בגין נזקים שנגרמו לו עקב הפרת החובה. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'הפרת חובת הודעה (ס'' 68) ← פשרה תקפה מול צד ג'' ← מבטח מאבד זכות השתתפות עצמית ← מבוטח זכאי לפיצויים מהמבטח.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 68", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות", "ע\"א (מחוזי תל אביב-יפו) 2539/07 הפניקס חברה לבטוח בע\"מ נ'' מאיירס שיווק (1981) בע\"מ (29.10.2008)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הסכם הפשרה בטל, והצד השלישי אינו זכאי לפיצוי מחברת הביטוח.', false, 'טענה זו שגויה, שכן הגישה השלטת בפסיקה היא שפעולת המבטח בניגוד לסעיף 68 אינה מפקיעה את תוקף הסדר הפשרה מול הצד השלישי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'חברת הביטוח מאבדת את זכותה לדרוש מהמבוטח תשלום השתתפות עצמית.', false, 'טענה זו נכונה, שכן הפרת חובת ההודעה עלולה לשלול מהמבטח את זכותו לדרוש השתתפות עצמית מהמבוטח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המבוטח זכאי לפיצויים מחברת הביטוח בגין כל נזק שנגרם לו עקב הפרת החובה.', false, 'טענה זו נכונה, שכן הפרת חובה קוגנטית זו יכולה להקים עילה לפיצויים חוזיים או נזיקיים למבוטח.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'תשובות ב'' ו-ג'' נכונות.', true, 'תשובה זו נכונה, שכן הפרת חובת ההודעה על ידי המבטח עלולה לגרור הן שלילת זכותו לדרוש השתתפות עצמית והן חיוב בפיצויים למבוטח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q24';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'זכות המבוטח לדרוש ניהול משפט', 4,
      'חברת ביטוח הודיעה למבוטח שלה, רופא, על כוונתה להתפשר עם מטופל שתבע אותו בגין רשלנות רפואית. הרופא מתנגד לפשרה, בטענה שהתביעה מופרכת וכי הוא מעוניין להוכיח את חפותו בבית המשפט. האם הרופא יכול לכפות על חברת הביטוח להמשיך בניהול המשפט במקום להתפשר?', 'שאלה זו עוסקת במתח שבין זכות ההתנגדות של המבוטח לפשרה (סעיף 68 לחוק חוזה הביטוח) לבין שיקול הדעת של המבטח בניהול התביעה. היא בוחנת את היקף זכותו של המבוטח לכפות על המבטח להמשיך בניהול משפט, ואת ההשלכות של התעלמות המבטח מהתנגדות סבירה של המבוטח.', 'סעיף 68 לחוק חוזה הביטוח מקנה למבוטח זכות להתנגד לתשלום תגמולי ביטוח לצד שלישי. סעיף 68 לחוק חוזה הביטוח, תשמ"א-1981 אולם, הפסיקה קבעה כי למבוטח אין זכות וטו מוחלטת על תשלומים לצד שלישי. תאד"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע"מ נ'' בזיני אברהם (23.04.2024) על המבטח לשקול את טעמי ההתנגדות של המבוטח מול טעמיו שלו ומול מכלול הנתונים ונסיבות המקרה, ולפעול בתום לב ובשיתוף פעולה. תאד"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע"מ נ'' בזיני אברהם (23.04.2024) אם המבטח מתפשר בניגוד להתנגדות סבירה ובתום לב של המבוטח, הוא עלול לשאת בתוצאות אם יתברר שהפשרה לא הייתה מוצדקת, למשל, אם סכום התגמולים ששולם גבוה יותר ממה שהיה נפסק בבית המשפט. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'הטעות הנפוצה היא לחשוב שהמבוטח יכול לכפות על המבטח את דרך ניהול התביעה, או לחילופין, שהמבטח יכול להתעלם לחלוטין מהתנגדות המבוטח, מבלי להבין את האיזון העדין הנדרש.',
      '["זכות וטו", "התנגדות סבירה", "תום לב", "שיקול דעת המבטח", "השלכות פשרה", "סעיף 68 לחוק חוזה הביטוח"]'::jsonb, '**וריאציה 1 — זכות וטו:** האם למבוטח יש זכות וטו מוחלטת? ← לא, למבוטח אין זכות וטו מוחלטת על תשלומים לצד שלישי. תאד"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע"מ נ'' בזיני אברהם (23.04.2024)
**וריאציה 2 — חובת המבטח:** מה חובת המבטח כלפי התנגדות סבירה? ← לשקול אותה בכובד ראש ולפעול בתום לב. תאד"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע"מ נ'' בזיני אברהם (23.04.2024)
**וריאציה 3 — תוצאות התעלמות:** מה קורה אם המבטח מתעלם מהתנגדות סבירה? ← הוא עלול לשאת בתוצאות אם הפשרה לא הייתה מוצדקת. ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות', 'מבוטח מתנגד לפשרה (ס'' 68) ← אין וטו מוחלט ← מבטח חייב לשקול התנגדות סבירה ← התעלמות עלולה לגרור חיוב המבטח בנזקים.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 68", "תאד\"מ (שלום אשד'') 10152-07-22 מגדל חברה לביטוח בע\"מ נ'' בזיני אברהם (23.04.2024)", "ירון אליאס דיני ביטוח (2016) | פרק עשרים-ושישה ביטוח אחריות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, למבוטח יש זכות וטו מוחלטת על כל הסדר פשרה.', false, 'טענה זו שגויה, שכן הפסיקה קבעה כי למבוטח אין זכות וטו מוחלטת על תשלומים לצד שלישי, אלא אם התנגדותו לגיטימית ובתום לב.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חברת הביטוח היא בעלת שיקול הדעת הבלעדי בניהול התביעה, כולל החלטה על פשרה.', false, 'טענה זו שגויה, שכן למרות שלמבטח שיקול דעת רחב, הוא אינו בלעדי וחייב להתחשב באינטרסים הלגיטימיים של המבוטח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'למבוטח אין זכות וטו מוחלטת, אך אם התנגדותו סבירה ובתום לב, על המבטח לשקול אותה בכובד ראש. אם המבטח יתפשר בניגוד להתנגדות סבירה, הוא עלול לשאת בתוצאות אם יתברר שהפשרה לא הייתה מוצדקת.', true, 'תשובה זו נכונה, שכן היא משקפת את האיזון בין זכות ההתנגדות של המבוטח לבין שיקול הדעת של המבטח, כפי שפורש בפסיקה ובספרות המשפטית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הרופא יכול לכפות על חברת הביטוח להמשיך בניהול המשפט רק אם יסכים לשאת בעצמו בכל הוצאות המשפט הנוספות.', false, 'טענה זו שגויה, שכן אין בחוק הוראה המחייבת את המבוטח לשאת בהוצאות המשפט כדי לכפות את המשך ניהולו, אם כי זה יכול להיות שיקול במשא ומתן.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q24';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 24, '2024-W-S-Q24';
END
$$;

