DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q25';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q25';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'זכאות תלויים של נהג חסר ביטוח', 1,
      'ראובן נהג ברכבו ללא ביטוח חובה ונפגע בתאונת דרכים שבה נהרג. האם תלוייו של ראובן (אלמנתו וילדיו) זכאים לפיצויים בגין מותו, ואם כן, ממי?', 'שאלה זו עוסקת בזכאותם של תלויים בנפגע תאונת דרכים שנהג ללא ביטוח חובה. היא בוחנת את החריג הקבוע בסעיף 7ב לחוק הפיצויים לנפגעי תאונות דרכים, המעניק לתלויים זכות תביעה מקרנית, גם כאשר הנפגע עצמו לא היה זכאי לפיצויים.', 'סעיף 7(5) לחוק הפיצויים לנפגעי תאונות דרכים קובע כי מי שנהג ברכב ללא ביטוח אינו זכאי לפיצויים לפי חוק זה. סעיף 7(5) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 אולם, סעיף 7ב לחוק קובע חריג מיוחד לעניין תלויים בנפגע. סעיף 7ב לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 לפי סעיף זה, תלויים בנפגע יהיו זכאים לתבוע פיצויים לפי חוק הפלת"ד גם אם הנפגע עצמו לא היה זכאי לכך לפי סעיף 7. אם התלויים היו תלויים במי שנפגע כשנהג ללא ביטוח, הם זכאים לתבוע פיצויים מקרנית. נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות זאת, מתוך תפיסה סוציאלית המבקשת להגן על התלויים, שאינם אשמים בהפרת חובת הביטוח של הנפגע. נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות', 'הטעות הנפוצה היא להסיק משלילת הזכאות של הנפגע עצמו את שלילת זכאותם של תלוייו, מבלי להכיר בחריג הספציפי הקבוע בסעיף 7ב לחוק הפלת"ד.',
      '["תלויים", "נהג חסר ביטוח", "חוק פיצויים לנפגעי תאונות דרכים", "סעיף 7ב", "קרנית", "אחריות מוחלטת"]'::jsonb, '**וריאציה 1 — זכאות הנפגע:** האם נהג חסר ביטוח זכאי לפיצויים לפי חוק הפלת"ד? ← לא, זכאותו נשללת לפי סעיף 7(5). סעיף 7(5) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 2 — זכאות התלויים:** האם תלוייו זכאים לפיצויים? ← כן, סעיף 7ב מעניק להם זכות תביעה עצמאית. סעיף 7ב לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 3 — ממי התלויים תובעים?** ← מקרנית. נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות', 'נהג חסר ביטוח ← אינו זכאי לפיצוי לפי חוק הפלת"ד (ס'' 7(5)) ← אך תלוייו זכאים לתבוע מקרנית (ס'' 7ב).', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 7(5)", "חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 7ב", "נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שראובן עצמו לא היה זכאי לפיצויים, גם תלוייו אינם זכאים.', false, 'טענה זו שגויה, שכן סעיף 7ב לחוק הפלת"ד קובע במפורש כי תלויים זכאים לתבוע פיצויים גם אם הנפגע עצמו לא היה זכאי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, תלוייו זכאים לתבוע פיצויים מקרנית, הקרן לפיצוי נפגעי תאונות דרכים.', true, 'תשובה זו נכונה, שכן סעיף 7ב לחוק הפלת"ד קובע כי תלויים במי שנפגע כשנהג ללא ביטוח, זכאים לתבוע פיצויים מקרנית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, תלוייו זכאים לתבוע פיצויים מנהג הרכב הפוגע וחברת הביטוח שלו, אך רק לפי פקודת הנזיקין.', false, 'טענה זו שגויה, שכן למרות שקיימת עילה לפי פקודת הנזיקין, סעיף 7ב לחוק הפלת"ד מעניק לתלויים זכות תביעה ישירה מקרנית במקרה זה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, תלוייו זכאים לתבוע פיצויים מקרנית, אך רק אם יוכיחו אשם תורם של הנהג הפוגע.', false, 'טענה זו שגויה, שכן הזכאות לפי חוק הפלת"ד היא על בסיס אחריות מוחלטת ואינה תלויה בהוכחת אשם תורם של הנהג הפוגע.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q25';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאי זכאות לנהג חסר ביטוח מקרנית', 2,
      'יוסי נהג ברכב של חברו ללא ביטוח חובה, ונפגע בתאונת דרכים. יוסי טוען כי לא ידע שהרכב אינו מבוטח. באילו תנאים יוכל יוסי לתבוע פיצויים מקרנית?', 'שאלה זו עוסקת בתנאים המיוחדים המאפשרים לנהג שנפגע בתאונת דרכים ללא ביטוח חובה לתבוע פיצויים מקרנית. היא מתמקדת בסעיף 7א לחוק הפיצויים לנפגעי תאונות דרכים, המפרט שלושה תנאים מצטברים לזכאות זו: נהיגה בהיתר, אי-ידיעה סובייקטיבית ואי-ידיעה אובייקטיבית על היעדר הביטוח.', 'סעיף 7(5) לחוק הפיצויים לנפגעי תאונות דרכים שולל זכאות לפיצויים ממי שנהג ברכב ללא ביטוח. סעיף 7(5) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 אולם, סעיף 7א לחוק קובע חריג לכלל זה, המאפשר לנהג חסר ביטוח לתבוע פיצויים מקרנית בתנאים מסוימים. סעיף 7א לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 התנאים המצטברים לזכאות זו הם: 1. נהיגה בהיתר מבעל הרכב או המחזיק בו. 2. אי-ידיעה בפועל (מבחן סובייקטיבי) אודות היעדר כיסוי ביטוחי. 3. סבירות אי-הידיעה (מבחן אובייקטיבי). ת"א (שלום ראשל"צ) 9695-03-17 פלוני נ'' שנטי עודאי (31.03.2025) אם כל התנאים הללו מתקיימים, יוסי יהיה זכאי לתבוע פיצויים מקרנית. אליעזר ריבלין תאונת הדרכים (2020) | פרק רביעי תביעה נגד קרנית', 'הטעות הנפוצה היא לחשוב שכל נהג חסר ביטוח מנוע מלתבוע מקרנית, או לחילופין, שדי באחד מהתנאים כדי לזכות בפיצוי, מבלי להבין את הצורך בקיום כל התנאים המצטברים.',
      '["קרנית", "סעיף 7א לחוק הפלת\"ד", "נהיגה בהיתר", "אי-ידיעה סובייקטיבית", "סבירות אי-ידיעה", "נהג חסר ביטוח"]'::jsonb, '**וריאציה 1 — נהיגה בהיתר:** האם נהיגה בהיתר היא תנאי? ← כן, נהיגה בהיתר מבעל הרכב או המחזיק בו. סעיף 7א לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 2 — אי-ידיעה:** האם אי-ידיעה על היעדר ביטוח היא תנאי? ← כן, אי-ידיעה בפועל וסבירות אי-הידיעה. סעיף 7א לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 3 — בעל הרכב:** האם סעיף 7א חל על בעל הרכב? ← לא, סעיף 7א לא יחול על מי שהוגדר כבעל רכב או מחזיק בו ונהג ללא כיסוי ביטוחי. ת"א (שלום ראשל"צ) 9695-03-17 פלוני נ'' שנטי עודאי (31.03.2025)', 'נהג חסר ביטוח תובע מקרנית (ס'' 7א) ← נהיגה בהיתר + אי-ידיעה סובייקטיבית + סבירות אי-ידיעה ← לא חל על בעל הרכב.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 7א", "ת\"א (שלום ראשל\"צ) 9695-03-17 פלוני נ'' שנטי עודאי (31.03.2025)", "אליעזר ריבלין תאונת הדרכים (2020) | פרק רביעי תביעה נגד קרנית"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'יוסי יוכל לתבוע מקרנית אם יוכיח שנהג בהיתר מבעל הרכב, וכי לא ידע ולא היה סביר שיידע על היעדר הביטוח.', true, 'תשובה זו נכונה, שכן היא מפרטת את שלושת התנאים המצטברים הקבועים בסעיף 7א לחוק הפלת"ד לזכאות לפיצויים מקרנית לנהג חסר ביטוח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'יוסי יוכל לתבוע מקרנית אם יוכיח שנהג בהיתר מבעל הרכב, ללא קשר לידיעתו על הביטוח.', false, 'טענה זו שגויה, שכן סעיף 7א לחוק הפלת"ד דורש גם אי-ידיעה סובייקטיבית ואובייקטיבית על היעדר הביטוח, בנוסף לנהיגה בהיתר.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'יוסי יוכל לתבוע מקרנית אם יוכיח שלא ידע על היעדר הביטוח, גם אם לא נהג בהיתר.', false, 'טענה זו שגויה, שכן סעיף 7א לחוק הפלת"ד דורש נהיגה בהיתר כחלק מהתנאים המצטברים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'יוסי אינו יכול לתבוע מקרנית בשום מקרה, מכיוון שנהג ללא ביטוח חובה.', false, 'טענה זו שגויה, שכן סעיף 7א לחוק הפלת"ד קובע חריג המאפשר לנהג חסר ביטוח לתבוע מקרנית בתנאים מסוימים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q25';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'היקף הפיצוי בתביעה נזיקית לנהג חסר ביטוח', 3,
      'איריס, שנהגה ברכבה ללא ביטוח חובה, נפגעה בתאונת דרכים שנגרמה באשמו של רון. איריס הגישה תביעה נגד רון וחברת הביטוח שלו לפי פקודת הנזיקין. האם הפיצויים שאיריס תהיה זכאית להם כפופים לתקרת הפיצויים הקבועה בחוק הפיצויים לנפגעי תאונות דרכים?', 'שאלה זו בוחנת את היקף הפיצויים בתביעה נזיקית המוגשת על ידי נפגע תאונת דרכים שזכאותו לפי חוק הפלת"ד נשללה. היא מתמקדת בשאלה האם תביעה כזו כפופה לתקרות הפיצויים הקבועות בחוק הפלת"ד, ומדגישה את ההלכה הפסוקה לפיה תביעה לפי פקודת הנזיקין אינה כפופה לתקרות אלו.', 'כאשר זכאותו של נפגע לפיצויים לפי חוק הפיצויים לנפגעי תאונות דרכים נשללת (למשל, עקב נהיגה ללא ביטוח חובה לפי סעיף 7(5) לחוק), הוא רשאי להגיש תביעה לפי פקודת הנזיקין. סעיף 7(5) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 סעיף 8(ג) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 הפסיקה קבעה כי תביעה לפי פקודת הנזיקין אינה כפופה לתקרת הפיצויים הקבועה בחוק הפלת"ד (סעיף 4 לחוק). ע"א 2591/09 אנואר אלנסארה נ'' אברהם שליסל (22.02.2011) נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות בית המשפט העליון הדגיש כי המחוקק בחר שלא לשלול את זכות התביעה בנזיקין של משוללי הזכאות לפי חוק הפלת"ד, ואף לא לצמצם את הפיצויים שלהם, ולכן אין לבית המשפט לעשות כן. ע"א 2591/09 אנואר אלנסארה נ'' אברהם שליסל (22.02.2011)', 'הטעות הנפוצה היא להניח שתקרות הפיצויים של חוק הפלת"ד חלות על כל תאונת דרכים, גם כאשר התביעה מוגשת לפי פקודת הנזיקין, מבלי להבחין בין העילות המשפטיות השונות.',
      '["פקודת הנזיקין", "חוק פיצויים לנפגעי תאונות דרכים", "תקרת פיצויים", "נהג חסר ביטוח", "ייחוד העילה", "פיצוי מלא"]'::jsonb, '**וריאציה 1 — עילת תביעה:** האם נהג חסר ביטוח יכול לתבוע לפי פקודת הנזיקין? ← כן, מכוח סעיף 8(ג) לחוק הפלת"ד. סעיף 8(ג) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 2 — תקרת פיצוי:** האם תביעה נזיקית כפופה לתקרת הפלת"ד? ← לא, תביעה לפי פקודת הנזיקין אינה כפופה לתקרת הפיצויים שבחוק הפלת"ד. נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות
**וריאציה 3 — רציונל:** מדוע אין הגבלה? ← המחוקק בחר שלא להגביל את הפיצוי בתביעה נזיקית, ואין לבית המשפט לעשות כן. ע"א 2591/09 אנואר אלנסארה נ'' אברהם שליסל (22.02.2011)', 'נהג חסר ביטוח תובע לפי פקודת הנזיקין (ס'' 8(ג)) ← פיצויים אינם כפופים לתקרת חוק הפלת"ד ← המחוקק לא הגביל, ואין לבית המשפט לעשות כן.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 8(ג)", "חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 4", "ע\"א 2591/09 אנואר אלנסארה נ'' אברהם שליסל (22.02.2011)", "נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהתאונה היא תאונת דרכים, הפיצויים כפופים לתקרות חוק הפלת"ד.', false, 'טענה זו שגויה, שכן תביעה לפי פקודת הנזיקין אינה כפופה לתקרות הפיצויים שבחוק הפלת"ד, גם אם מדובר בתאונת דרכים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שהתביעה מוגשת לפי פקודת הנזיקין, היא אינה כפופה לתקרת הפיצויים שבחוק הפלת"ד.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי תביעה המוגשת לפי פקודת הנזיקין על ידי נפגע שזכאותו לפי חוק הפלת"ד נשללה, אינה כפופה לתקרות הפיצויים הקבועות בחוק הפלת"ד.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם בית המשפט ימצא כי יש להטיל על איריס אשם תורם משמעותי.', false, 'טענה זו שגויה, שכן תקרת הפיצויים בחוק הפלת"ד אינה קשורה לשאלת האשם התורם, אלא לסוג העילה המשפטית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן איריס הייתה מבוטחת בביטוח מקיף.', false, 'טענה זו שגויה, שכן ביטוח מקיף מכסה נזקי רכוש ולא נזקי גוף, ואינו רלוונטי לשאלת תקרת הפיצויים בתביעה נזיקית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q25';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'זכות חזרה של קרנית על נהג חסר ביטוח', 4,
      'דני נהג ברכבו ללא ביטוח חובה ופגע בהולך רגל. הולך הרגל הגיש תביעה נגד קרנית וקיבל ממנה פיצויים. האם קרנית רשאית לחזור אל דני ולתבוע ממנו את סכום הפיצויים ששילמה?', 'שאלה זו עוסקת בזכות החזרה של קרנית על נהג שגרם לתאונת דרכים בהיותו חסר ביטוח חובה. היא בוחנת את הוראת סעיף 9(א)(2) לחוק הפיצויים לנפגעי תאונות דרכים, המאפשרת לקרנית לתבוע שיפוי מנהג כזה, וכן את הרציונל שמאחורי הוראה זו, שהוא הרתעה ומניעת הטלת מלוא הנטל על ציבור המבוטחים.', 'קרנית היא קרן לפיצוי נפגעי תאונות דרכים, שתפקידה לפצות נפגעים הזכאים לפיצויים לפי חוק הפלת"ד ואין בידם לתבוע פיצויים ממבטח. סעיף 12(א) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 אחד המקרים בהם קרנית נכנסת לתמונה הוא כאשר לנוהג אין ביטוח לפי פקודת הביטוח. סעיף 12(א)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 במקרים אלו, לאחר שקרנית פיצתה את הנפגע, היא זכאית לחזור אל המזיק חסר הביטוח. נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות סעיף 9(א)(2) לחוק הפלת"ד קובע במפורש כי מי ששילם פיצויים לפי חוק זה (כמו קרנית) זכאי לחזור על מי שאין לו ביטוח לפי פקודת הביטוח. סעיף 9(א)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 זכות חזרה זו נועדה לשמש גורם מרתיע כנגד הימנעות מרכישת ביטוח חובה ולמנוע הטלת מלוא נטל הפיצוי על ציבור המבוטחים. ת"א (מחוזי תל אביב-יפו) 6186-01-20 פלונית נ'' פניקס חברה לביטוח בע"מ (29.12.2024)', 'הטעות הנפוצה היא לחשוב שקרנית היא מעין "רשת ביטחון" ללא זכות חזרה, מבלי להבין את תפקידה הכפול: פיצוי נפגעים מחד, והרתעה ואכיפה מאידך.',
      '["קרנית", "זכות חזרה", "נהג חסר ביטוח", "חוק פיצויים לנפגעי תאונות דרכים", "סעיף 9(א)(2)", "הרתעה"]'::jsonb, '**וריאציה 1 — תפקיד קרנית:** מתי קרנית מפצה? ← כשאין ביטוח לנוהג. סעיף 12(א)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 2 — זכות חזרה:** האם קרנית יכולה לחזור על נהג חסר ביטוח? ← כן, מכוח סעיף 9(א)(2) לחוק הפלת"ד. סעיף 9(א)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975

**וריאציה 3 — תכלית זכות החזרה:** מהי מטרת זכות החזרה? ← הרתעה ומניעת הטלת נטל על ציבור המבוטחים. ת"א (מחוזי תל אביב-יפו) 6186-01-20 פלונית נ'' פניקס חברה לביטוח בע"מ (29.12.2024)', 'קרנית מפצה נפגעים מנהג חסר ביטוח (ס'' 12(א)(2)) ← וזכאית לחזור אל הנהג המזיק (ס'' 9(א)(2)) ← למטרת הרתעה והגנה על ציבור המבוטחים.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 9(א)(2)", "חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 12(א)(2)", "ת\"א (מחוזי תל אביב-יפו) 6186-01-20 פלונית נ'' פניקס חברה לביטוח בע\"מ (29.12.2024)", "נבו - המתמחה דיני נזיקין (2026) | סימן ג'': שונות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שקרנית הוקמה כדי לפצות נפגעים במקרים כאלה, ואין לה זכות חזרה על המזיק.', false, 'טענה זו שגויה, שכן סעיף 9(א)(2) לחוק הפלת"ד מקנה לקרנית זכות חזרה מפורשת על מי שאין לו ביטוח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, קרנית רשאית לחזור אל דני ולתבוע ממנו את סכום הפיצויים ששילמה, מכוח סעיף 9(א)(2) לחוק הפיצויים לנפגעי תאונות דרכים.', true, 'תשובה זו נכונה, שכן סעיף 9(א)(2) לחוק הפלת"ד קובע כי מי ששילם פיצויים לפי חוק זה (כמו קרנית) זכאי לחזור על מי שאין לו ביטוח.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם דני נהג ברכב ללא רישיון נהיגה תקף.', false, 'טענה זו שגויה, שכן זכות החזרה של קרנית על נהג חסר ביטוח אינה מותנית בנהיגה ללא רישיון, אלא בעצם היעדר הביטוח.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן דני גרם לתאונה במתכוון.', false, 'טענה זו שגויה, שכן זכות החזרה של קרנית על נהג חסר ביטוח אינה מותנית בכוונה לגרום לתאונה, אלא בעצם היעדר הביטוח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q25';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 25, '2024-W-S-Q25';
END
$$;

-- ============================================================
-- Q26 — angles backfill for 2024-W-S-Q26 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q26';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q26';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תחולת סעיף 15 על מחדלי תובע', 1,
      'ראובן הגיש תביעה בגין נזקי גוף שנגרמו לו בתאונת דרכים. התביעה נמחקה מחמת חוסר מעש לאחר שראובן לא מילא אחר הוראות בית המשפט ולא התייצב לדיונים, למרות התראות חוזרות. ראובן הגיש תביעה חדשה באותה עילה. האם ראובן יוכל ליהנות מהארכת תקופת ההתיישנות מכוח סעיפים 15 ו-16 לחוק ההתיישנות?', 'שאלה זו בוחנת את היקף תחולתם של סעיפים 15 ו-16 לחוק ההתיישנות במקרים בהם התביעה הראשונה נמחקה מחמת מחדלי התובע. הפסיקה בעניין זה אינה אחידה, אך הגישה הרווחת היא שאין לשלול את תחולת הסעיפים באופן אוטומטי, אלא רק במקרים קיצוניים של חוסר תום לב או שימוש לרעה בהליכי משפט.', 'סעיפים 15 ו-16 לחוק ההתיישנות נועדו להקל עם תובע שפעל למימוש זכויותיו, אך מסיבות שונות לא עלה הדבר בידו, ומאפשרים להשעות את מרוץ ההתיישנות. סעיף 15 לחוק ההתיישנות, תשי"ח-1958 סעיף 16 לחוק ההתיישנות, תשי"ח-1958 הפסיקה הרחיבה את פרשנות המונח ''נדחתה'' בסעיף 15 לכלול גם מחיקת תביעה מחוסר מעש, כל עוד לא נוצר מעשה בית דין. רע"א 5687/22 הכשרת הישוב חברה לביטוח בע"מ נ'' פלוני (21.09.2022) ת"א (שלום נצ'') 25220-01-21 פלוני נ'' שומרה חב'' לביטוח בע"מ (07.04.2021) עם זאת, התפתחה בפסיקה מגמה לסייג את תחולת הסעיפים במקרים של רשלנות או מחדלים של התובע. ת"א (שלום חי'') 43377-04-22 פלוני נ'' משרד הכלכלה המסחר והתעשיה תל אביב (08.08.2022) הגישה המקלה יותר, כפי שבאה לידי ביטוי בפסיקות מסוימות, היא שאין לשלול את תחולת סעיפים 15 ו-16 אלא במקרים קיצוניים של חוסר תום לב או שימוש לרעה בהליכי משפט, ולא במקרים של רשלנות בלבד. ת"א (שלום חי'') 65401-08-22 פלונית ואח'' נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (04.04.2023)', 'הטעות הנפוצה היא להניח שכל מחדל של התובע שולל אוטומטית את תחולת סעיפים 15 ו-16, מבלי להבחין בין רשלנות רגילה לחוסר תום לב קיצוני או שימוש לרעה בהליכי משפט.',
      '["התיישנות", "סעיף 15 לחוק ההתיישנות", "סעיף 16 לחוק ההתיישנות", "מחיקה מחוסר מעש", "חוסר תום לב", "שימוש לרעה בהליכי משפט"]'::jsonb, '**וריאציה 1 — מחיקה מחוסר מעש:** האם מחיקה מחוסר מעש נכללת ב"נדחתה" בסעיף 15? ← כן, הפסיקה הרחיבה את הפרשנות. רע"א 5687/22 הכשרת הישוב חברה לביטוח בע"מ נ'' פלוני (21.09.2022)
**וריאציה 2 — רשלנות תובע:** האם רשלנות התובע שוללת תחולה? ← לא בהכרח, רק חוסר תום לב קיצוני או שימוש לרעה בהליכי משפט. ת"א (שלום חי'') 65401-08-22 פלונית ואח'' נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (04.04.2023)
**וריאציה 3 — מועד הגשה מאוחר:** מה קורה אם התביעה הראשונה הוגשה ביום האחרון להתיישנות ונמחקה? ← סעיף 15 לא יועיל אם התובע המשיך במחדליו ולא הגיש תביעה חדשה מיד. ת"א (שלום חי'') 43377-04-22 פלוני נ'' משרד הכלכלה המסחר והתעשיה תל אביב (08.08.2022)', 'סעיפים 15 ו-16 לחוק ההתיישנות ← חלים גם על מחיקה מחוסר מעש ← אלא אם מדובר בחוסר תום לב קיצוני או שימוש לרעה בהליכי משפט ← לא נשללים אוטומטית עקב רשלנות.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 15", "חוק ההתיישנות, תשי\"ח-1958, סעיף 16", "רע\"א 5687/22 הכשרת הישוב חברה לביטוח בע\"מ נ'' פלוני (21.09.2022)", "ת\"א (שלום חי'') 65401-08-22 פלונית ואח'' נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (04.04.2023)", "ת\"א (שלום חי'') 43377-04-22 פלוני נ'' משרד הכלכלה המסחר והתעשיה תל אביב (08.08.2022)", "ת\"א (שלום נצ'') 25220-01-21 פלוני נ'' שומרה חב'' לביטוח בע\"מ (07.04.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שמחיקת תביעה מחוסר מעש אינה יוצרת מעשה בית דין, וסעיפים 15 ו-16 חלים גם במקרים של מחדלי תובע, אלא אם מדובר בחוסר תום לב קיצוני או שימוש לרעה בהליכי משפט.', true, 'תשובה זו נכונה, שכן היא משקפת את הגישה הרווחת בפסיקה, לפיה סעיפים 15 ו-16 חלים גם במקרים של מחיקה מחוסר מעש, אלא אם מדובר בהתנהלות קיצונית של חוסר תום לב או שימוש לרעה בהליכי משפט.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שהתנהלותו של ראובן עולה כדי רשלנות חמורה, השוללת את תחולת סעיפים 15 ו-16 לחוק ההתיישנות.', false, 'טענה זו שגויה, שכן הפסיקה נוטה שלא לשלול את תחולת הסעיפים במקרים של רשלנות בלבד, אלא רק במקרים קיצוניים של חוסר תום לב או שימוש לרעה בהליכי משפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם יוכיח כי מחדליו נבעו מסיבות אובייקטיביות שלא היו בשליטתו.', false, 'טענה זו שגויה, שכן למרות שסיבות אובייקטיביות מחזקות את הטענה, הפסיקה אינה דורשת זאת כתנאי בלעדי לתחולת הסעיפים במקרים של מחיקה מחוסר מעש.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, מכיוון שסעיף 15 חל רק כאשר התביעה נדחתה לגופה, ולא כאשר נמחקה מחוסר מעש.', false, 'טענה זו שגויה, שכן הפסיקה הרחיבה את פרשנות המונח ''נדחתה'' בסעיף 15 לכלול גם מחיקה מחוסר מעש, כל עוד לא נוצר מעשה בית דין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q26';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאים מצטברים לתחולת סעיף 15', 2,
      'מהם התנאים המצטברים לתחולתו של סעיף 15 לחוק ההתיישנות, המאפשר השעיית מרוץ ההתיישנות?', 'שאלה זו מפרטת את התנאים המצטברים הנדרשים לתחולתו של סעיף 15 לחוק ההתיישנות, כפי שפורשו בפסיקה. הבנת תנאים אלו חיונית ליישום נכון של הוראת החוק המאפשרת הגשת תביעה חדשה לאחר דחייה או מחיקה של תביעה קודמת.', 'סעיף 15 לחוק ההתיישנות קובע כי התקופה שבין הגשת תובענה ובין דחייתה לא תבוא במניין תקופת ההתיישנות, אם התובענה נדחתה באופן שלא נבצר מן התובע להגיש תובענה חדשה בשל אותה עילה. סעיף 15 לחוק ההתיישנות, תשי"ח-1958 הפסיקה קבעה שלושה תנאים מצטברים לתחולתו של סעיף זה: 1. הוגשה תובענה בעבר (שנדחתה או נמחקה). 2. התובענה השנייה הוגשה בגין ''אותה עילה'' כבתובענה שלפניה. 3. התובענה הראשונה נדחתה בדרך שאינה מונעת הגשת תובענה חדשה בגין אותה עילה (כלומר, לא נוצר מעשה בית דין). ס"ע (אזורי חי'') 47770-12-10 דבורה קינן ואח'' - האגודה למען שירותי בריאות הציבור (13.06.2011) ת"א (שלום הרצ'') 21275-09-13 רבקה וילנצ''יק נ'' המאגר הישראלי לביטוחי רכב בע"מ (11.03.2016) המונח "נדחתה" פורש באופן רחב וכולל גם מקרים של מחיקת תובענה או הפסקתה, כל עוד לא נוצר מעשה בית דין. ת"א (שלום נצ'') 25220-01-21 פלוני נ'' שומרה חב'' לביטוח בע"מ (07.04.2021)', 'הטעות הנפוצה היא לבלבל בין התנאים לתחולת סעיף 15 לבין תכליתו, או להשמיט אחד מהתנאים המצטברים, במיוחד את הדרישה שלא נוצר מעשה בית דין.',
      '["התיישנות", "סעיף 15 לחוק ההתיישנות", "תנאים מצטברים", "אותה עילה", "מעשה בית דין", "מחיקת תובענה"]'::jsonb, '**וריאציה 1 — תנאי 1:** מהו התנאי הראשון? ← הוגשה תובענה בעבר. ס"ע (אזורי חי'') 47770-12-10 דבורה קינן ואח'' - האגודה למען שירותי בריאות הציבור (13.06.2011)
**וריאציה 2 — תנאי 2:** מהו התנאי השני? ← התובענה השנייה הוגשה בגין אותה עילה. ס"ע (אזורי חי'') 47770-12-10 דבורה קינן ואח'' - האגודה למען שירותי בריאות הציבור (13.06.2011)
**וריאציה 3 — תנאי 3:** מהו התנאי השלישי? ← התובענה הראשונה נדחתה באופן שאינו מונע הגשת תובענה חדשה (לא מעשה בית דין). ס"ע (אזורי חי'') 47770-12-10 דבורה קינן ואח'' - האגודה למען שירותי בריאות הציבור (13.06.2011)', 'סעיף 15 לחוק ההתיישנות ← 3 תנאים מצטברים: תובענה קודמת נדחתה/נמחקה, אותה עילה, ללא מעשה בית דין.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 15", "ס\"ע (אזורי חי'') 47770-12-10 דבורה קינן ואח'' נ'' האגודה למען שירותי בריאות הציבור (13.06.2011)", "ת\"א (שלום הרצ'') 21275-09-13 רבקה וילנצ''יק נ'' המאגר הישראלי לביטוחי רכב בע\"מ (11.03.2016)", "ת\"א (שלום נצ'') 25220-01-21 פלוני נ'' שומרה חב'' לביטוח בע\"מ (07.04.2021)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הוגשה תובענה בעבר, התובענה השנייה הוגשה בגין אותה עילה, והתובענה הראשונה נדחתה באופן שאינו מונע הגשת תובענה חדשה.', true, 'תשובה זו נכונה, שכן היא מפרטת את שלושת התנאים המצטברים שנקבעו בפסיקה לתחולתו של סעיף 15 לחוק ההתיישנות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הוגשה תובענה בעבר, התובענה השנייה הוגשה בגין אותה עילה, והתובענה הראשונה נדחתה לגופה.', false, 'טענה זו שגויה, שכן סעיף 15 חל גם כאשר התביעה נדחתה שלא לגופה (כגון מחיקה מחוסר מעש), ובלבד שלא נוצר מעשה בית דין.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הוגשה תובענה בעבר, התובענה השנייה הוגשה בגין עילה דומה, והתובענה הראשונה נמחקה מחוסר מעש.', false, 'טענה זו שגויה, שכן נדרשת ''אותה עילה'' ולא ''עילה דומה'', ומחיקה מחוסר מעש היא רק אחת הדרכים שבהן תביעה יכולה להידחות באופן שאינו מונע הגשה חדשה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הוגשה תובענה בעבר, התובענה השנייה הוגשה נגד אותו נתבע, והתובענה הראשונה נדחתה מטעמים טכניים בלבד.', false, 'טענה זו שגויה, שכן סעיף 15 אינו דורש שהדחייה תהיה מטעמים טכניים בלבד, אלא כל דחייה שאינה יוצרת מעשה בית דין, ואינו מתייחס במפורש לדרישה של ''אותו נתבע'' כתנאי עצמאי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q26';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'תחולת סעיף 15 על נתבע שלא הומצאה לו התביעה הראשונה', 3,
      'שמעון הגיש תביעה נגד לוי. התביעה נמחקה מחוסר מעש, מבלי שלוי קיבל אי פעם את כתב התביעה לידיו. שמעון הגיש תביעה חדשה באותה עילה נגד לוי. האם לוי יכול לטעון כי סעיף 15 לחוק ההתיישנות אינו חל עליו, מכיוון שלא הומצאה לו התביעה הראשונה?', 'שאלה זו עוסקת בסוגיית תחולת סעיף 15 לחוק ההתיישנות כאשר התביעה הראשונה לא הומצאה לנתבע. היא בוחנת את הרציונל שמאחורי הסעיף, הדורש שהנתבע יהיה מודע לתביעה כדי שיוכל לשמור את ראיותיו, ומדגישה את חשיבות המצאת כתב התביעה לצורך השעיית מרוץ ההתיישנות כלפי הנתבע.', 'סעיף 15 לחוק ההתיישנות קובע כי התקופה שבין הגשת תובענה ובין דחייתה לא תבוא במניין תקופת ההתיישנות. סעיף 15 לחוק ההתיישנות, תשי"ח-1958 הרציונל העומד בבסיס הוראה זו הוא שהגשת התביעה בתוך תקופת ההתיישנות מעמידה את הנתבע על כך שהתובע לא ויתר על זכויותיו, אלא מבקש למצותן, כך שעל הנתבע לשמור את ראיותיו ולהכין את הגנתו. ת"א (שלום חי'') 43377-04-22 פלוני נ'' משרד הכלכלה המסחר והתעשיה תל אביב (08.08.2022) מכאן, שאם התביעה הראשונה כלל לא הומצאה לנתבע, או שהתובע לא פעל בשקידה ראויה להמצאתה, הרי שהרציונל של הסעיף אינו מתקיים כלפי אותו נתבע. ת"א (שלום נצ'') 56709-09-11 גיל ארביב נ'' אורן הראל (23.02.2015) במצב כזה, אין בכוחה של התובענה להשעות את מרוץ ההתיישנות כלפי הנתבע שלא ידע על קיומה. ת"א (שלום ת"א) 24266-11-09 ויויאן ריבי בן שמעון נ'' הראל חברה לביטוח (30.01.2011)', 'הטעות הנפוצה היא להתמקד בלשון החוק ("הוגשה תובענה") מבלי להבין את הפרשנות התכליתית של הפסיקה, הדורשת שהנתבע יהיה מודע לקיומה של התביעה כדי שהשעיית ההתיישנות תחול עליו.',
      '["התיישנות", "סעיף 15 לחוק ההתיישנות", "המצאת כתב תביעה", "רציונל ההתיישנות", "ידיעת הנתבע", "שקידה ראויה"]'::jsonb, '**וריאציה 1 — רציונל סעיף 15:** מהי תכלית סעיף 15? ← להודיע לנתבע שהתובע לא ויתר על זכויותיו. ת"א (שלום חי'') 43377-04-22 פלוני נ'' משרד הכלכלה המסחר והתעשיה תל אביב (08.08.2022)
**וריאציה 2 — אי-המצאה:** האם אי-המצאה שוללת תחולה? ← כן, אם התובע לא פעל בשקידה ראויה להמצאה, הרציונל לא מתקיים. ת"א (שלום נצ'') 56709-09-11 גיל ארביב נ'' אורן הראל (23.02.2015)
**וריאציה 3 — נתבע חליף:** האם סעיף 15 חל על נתבע חליף? ← ייתכן, אם מתקיימים תנאי סעיף 18 לחוק ההתיישנות. ת"א (מחוזי חי'') 42124-02-25 נציגות הבית המשותף ברחוב דורון מייבלום 13 חיפה נ'' א.פ איב סחר והפצה בע"מ (14.08.2025)', 'סעיף 15 לחוק ההתיישנות ← דורש ידיעת הנתבע על התביעה ← אי-המצאה או חוסר שקידה בהמצאה ← שוללת תחולת הסעיף כלפי הנתבע.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 15", "חוק ההתיישנות, תשי\"ח-1958, סעיף 18", "ת\"א (שלום נצ'') 56709-09-11 גיל ארביב נ'' אורן הראל (23.02.2015)", "ת\"א (שלום ת\"א) 24266-11-09 ויויאן ריבי בן שמעון נ'' הראל חברה לביטוח (30.01.2011)", "ת\"א (מחוזי חי'') 42124-02-25 נציגות הבית המשותף ברחוב דורון מייבלום 13 חיפה נ'' א.פ איב סחר והפצה בע\"מ (14.08.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהרציונל של סעיף 15 הוא שהנתבע ידע על התביעה, ובהיעדר המצאה, רציונל זה אינו מתקיים.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי אם התובע לא פעל בשקידה ראויה להמצאת התביעה לנתבע, אין בכוחה של התובענה להשעות את מרוץ ההתיישנות כלפי אותו נתבע.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שסעיף 15 מתייחס ל"הוגשה תובענה", ואינו דורש המצאה בפועל לנתבע.', false, 'טענה זו שגויה, שכן למרות לשון החוק, הפסיקה פירשה את הסעיף באופן תכליתי, הדורש ידיעה או לפחות ניסיון סביר להמצאה לנתבע.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם לוי יוכיח שנגרם לו נזק ראייתי כתוצאה מאי-המצאת התביעה הראשונה.', false, 'טענה זו שגויה, שכן אי-המצאה מספקת כשלעצמה כדי לשלול את תחולת סעיף 15, ואינה מותנית בהוכחת נזק ראייתי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן התביעה הראשונה נמחקה ביוזמת התובע ולא ביוזמת בית המשפט.', false, 'טענה זו שגויה, שכן שאלת המצאת התביעה לנתבע קודמת לשאלת יוזם המחיקה, והיא תנאי מהותי לתחולת סעיף 15 כלפי הנתבע.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q26';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'תחולת סעיף 15 על הליכי בוררות', 4,
      'ראובן הגיש תביעה נגד שמעון בפני בורר. הליך הבוררות התנהל במשך שנתיים, ולאחר מכן בוטל פסק הבוררות על ידי בית המשפט. ראובן מעוניין להגיש תביעה חדשה באותה עילה נגד שמעון בבית המשפט. האם התקופה שבה התנהל הליך הבוררות תיחשב כ"זמן שבין הגשת התובענה ובין דחייתה" לעניין סעיף 15 לחוק ההתיישנות?', 'שאלה זו בוחנת את תחולתו של סעיף 15 לחוק ההתיישנות על הליכי בוררות. היא מדגישה את ההגדרה הרחבה של המונח "בית משפט" בחוק ההתיישנות, הכוללת גם בורר, ובכך מאפשרת להחיל את הוראות השעיית מרוץ ההתיישנות גם על תקופת ניהול הליך בוררות.', 'סעיף 15 לחוק ההתיישנות קובע כי התקופה שבין הגשת תובענה ובין דחייתה לא תבוא במניין תקופת ההתיישנות. סעיף 15 לחוק ההתיישנות, תשי"ח-1958 סעיף 1 לחוק ההתיישנות מגדיר "בית משפט" כ"כל רשות שיפוטית או בורר, ולמעט בית דין דתי". ת"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025) מכאן, שסעיף 15 לחוק ההתיישנות חל גם על הליכי בוררות, והתקופה שבה התנהל הליך הבוררות לא תבוא במניין תקופת ההתיישנות, כל עוד הליך הבוררות הסתיים באופן שלא נוצר מעשה בית דין. ת"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025)', 'הטעות הנפוצה היא לפרש את המונח "בית משפט" בסעיף 15 באופן מצומצם, מבלי להתייחס להגדרה הרחבה יותר הקבועה בסעיף 1 לחוק ההתיישנות, הכוללת גם בורר.',
      '["התיישנות", "סעיף 15 לחוק ההתיישנות", "הליכי בוררות", "הגדרת בית משפט", "השעיית מרוץ ההתיישנות", "מעשה בית דין"]'::jsonb, '**וריאציה 1 — הגדרת "בית משפט":** האם "בית משפט" בסעיף 15 כולל בורר? ← כן, לפי סעיף 1 לחוק ההתיישנות. ת"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025)
**וריאציה 2 — תחולת סעיף 15:** האם סעיף 15 חל על בוררות? ← כן, באופן עקרוני. ת"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025)
**וריאציה 3 — חוסר תום לב בבוררות:** האם חוסר תום לב בבוררות יכול לשלול תחולה? ← כן, בדומה למחדלים בהליך משפטי. ת"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025)', 'סעיף 15 לחוק ההתיישנות ← חל גם על הליכי בוררות ← מכוח הגדרת "בית משפט" בסעיף 1 ← תקופת הבוררות לא תבוא במניין ההתיישנות.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 1", "חוק ההתיישנות, תשי\"ח-1958, סעיף 15", "ת\"א (מחוזי י-ם) 66492-04-25 רחמים טהוליאן נ'' רפאל כהן (11.12.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שסעיף 15 מתייחס במפורש ל"בית משפט, לרבות בית דין דתי", ואינו כולל הליכי בוררות.', false, 'טענה זו שגויה, שכן סעיף 1 לחוק ההתיישנות מגדיר "בית משפט" באופן רחב הכולל גם בורר, ולכן סעיף 15 חל גם על הליכי בוררות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, מכיוון שהמונח "בית משפט" בסעיף 15 לחוק ההתיישנות כולל גם בורר, ולכן הסעיף חל גם על הליכי בוררות.', true, 'תשובה זו נכונה, שכן סעיף 1 לחוק ההתיישנות מגדיר "בית משפט" כ"כל רשות שיפוטית או בורר", ולכן סעיף 15 חל גם על הליכי בוררות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הצדדים הסכימו מראש בכתב כי הליכי הבוררות יעצרו את מרוץ ההתיישנות.', false, 'טענה זו שגויה, שכן תחולת סעיף 15 על הליכי בוררות נובעת מהגדרת "בית משפט" בחוק, ואינה מותנית בהסכמה מפורשת של הצדדים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן פסק הבוררות בוטל עקב חוסר סמכות של הבורר.', false, 'טענה זו שגויה, שכן סיבת ביטול פסק הבוררות אינה משפיעה על תחולת סעיף 15 על תקופת ניהול הבוררות עצמה, כל עוד לא נוצר מעשה בית דין.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q26';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 26, '2024-W-S-Q26';
END
$$;

-- ============================================================
-- Q28 — angles backfill for 2024-W-S-Q28 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q28';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q28';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תחולת איסור טובת הנאה על קרוב נאמן', 1,
      'נאמן על נכסים הוא בעל מניות עיקרי בתאגיד מסוים. התאגיד מעוניין לרכוש נכס מנכסי הנאמנות. האם איסור טובת ההנאה הקבוע בסעיף 13(א) לחוק הנאמנות חל גם על רכישה זו?', 'שאלה זו בוחנת את היקף תחולתו של איסור טובת ההנאה על נאמן וקרוביו, כפי שנקבע בסעיף 13(א) לחוק הנאמנות. היא מתמקדת בהגדרת המונח ''קרוב'' בסעיף 13(ב), ובפרט על תחולתו על תאגיד שבו לנאמן יש עניין כלכלי משמעותי.', 'סעיף 13(א) לחוק הנאמנות קובע איסור על נאמן לרכוש לעצמו או לקרובו נכס מנכסי הנאמנות, להפיק טובת הנאה מהם, או לעשות דבר שיש בו סתירה בין טובת הנאמנות לטובתו שלו או של קרובו. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979 המונח ''קרוב'' מוגדר בסעיף 13(ב) לחוק, וכולל, בין היתר, תאגיד שבהונו, ברווחיו או בשליטתו יש לנאמן או למנויים בפסקאות (1) עד (3) חלק העולה על 5%. סעיף 13(ב)(5) לחוק הנאמנות, תשל"ט-1979 תכלית האיסור היא למנוע חשש לניגוד עניינים ולהבטיח שהנאמן יפעל אך ורק לטובת הנהנה. ת"א (מחוזי ת"א) 27470-07-19 בית יורב 1997 בע"מ נ'' טובה כהן (21.06.2022) לכן, אם הנאמן הוא בעל מניות עיקרי בתאגיד (מעל 5%), התאגיד ייחשב ''קרוב'' לנאמן, ואיסור טובת ההנאה יחול גם על רכישה של נכס נאמנות על ידי התאגיד. ע"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו"ד משה מימרן (04.01.2009)', 'הטעות הנפוצה היא להניח שהאיסור חל רק על הנאמן באופן אישי, ולא על גופים תאגידיים הקשורים אליו, מבלי להכיר את ההגדרה הרחבה של ''קרוב'' בחוק הנאמנות.',
      '["נאמן", "קרוב נאמן", "תאגיד", "ניגוד עניינים", "חוק הנאמנות", "סעיף 13(א)", "סעיף 13(ב)(5)"]'::jsonb, '**וריאציה 1 — איסור על קרוב:** האם האיסור בסעיף 13(א) חל על קרוב נאמן? ← כן, נאמן לא ירכוש לעצמו או לקרובו. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979
**וריאציה 2 — תאגיד כקרוב:** מתי תאגיד נחשב קרוב? ← אם לנאמן או לקרובו חלק העולה על 5% בהון, ברווחים או בשליטה. סעיף 13(ב)(5) לחוק הנאמנות, תשל"ט-1979
**וריאציה 3 — תכלית האיסור:** מהי תכלית האיסור על טובת הנאה? ← למנוע חשש לניגוד עניינים ולהבטיח פעולה לטובת הנהנה. ת"א (מחוזי ת"א) 27470-07-19 בית יורב 1997 בע"מ נ'' טובה כהן (21.06.2022)', 'נאמן או קרובו ← אסור להפיק טובת הנאה מנכסי הנאמנות (ס'' 13(א)) ← ''קרוב'' כולל תאגיד עם חלק העולה על 5% (ס'' 13(ב)(5)) ← תכלית: מניעת ניגוד עניינים.', '["חוק הנאמנות, תשל\"ט-1979, סעיף 13(א)", "חוק הנאמנות, תשל\"ט-1979, סעיף 13(ב)(5)", "ע\"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו\"ד משה מימרן (04.01.2009)", "בד\"מ (ועדת משמעת לשכת עוה\"ד ירושלים) 34/20 ועדת האתיקה של לשכת עורכי הדין נ'' עו״ד ניר לוי (01.01.2026)", "ע\"מ (מחוזי תל אביב-יפו) 1303/04 פלוני נ'' פלונית (04.07.2006)", "ת\"א (מחוזי ת\"א) 27470-07-19 בית יורב 1997 בע\"מ נ'' טובה כהן (21.06.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שהאיסור חל רק על הנאמן עצמו ולא על תאגיד שבבעלותו.', false, 'טענה זו שגויה, שכן סעיף 13(ב)(5) לחוק הנאמנות מגדיר תאגיד כ''קרוב'' לנאמן בתנאים מסוימים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, אם לנאמן או לקרובו חלק העולה על 5% בהון, ברווחים או בשליטה של התאגיד.', true, 'תשובה זו נכונה, שכן סעיף 13(ב)(5) לחוק הנאמנות מגדיר ''קרוב'' ככולל תאגיד שבו לנאמן או לקרובו חלק העולה על 5%.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, אלא אם כן הנאמן הוא הבעלים היחיד של התאגיד.', false, 'טענה זו שגויה, שכן די בחלק העולה על 5% כדי שהתאגיד ייחשב ''קרוב'', ואין צורך בבעלות מלאה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם התאגיד הוקם במיוחד לצורך רכישת נכסי הנאמנות.', false, 'טענה זו שגויה, שכן תכלית הקמת התאגיד אינה רלוונטית להגדרת ''קרוב'' בסעיף 13(ב)(5).', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q28';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחן אישור פעולת נאמן בניגוד עניינים', 2,
      'נאמן פנה לבית המשפט בבקשה לאשר לו לרכוש נכס מנכסי הנאמנות. מהו המבחן העיקרי שבית המשפט יפעיל בבואו להחליט אם לאשר את הפעולה?', 'שאלה זו עוסקת במבחן המשפטי לאישור פעולה של נאמן המצויה בניגוד עניינים, כפי שקבוע בסעיף 13(ג) לחוק הנאמנות. היא מדגישה את הדרישה המרכזית כי הפעולה תהיה ''לטובת הנאמנות'', ומבהירה כי שיקולים אחרים, כגון טובת הנאמן או הסכמת הנהנים, אינם מספיקים כשלעצמם.', 'סעיף 13(א) לחוק הנאמנות אוסר על נאמן להפיק טובת הנאה מנכסי הנאמנות או מפעולותיה. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979 עם זאת, סעיף 13(ג) לחוק מאפשר לבית המשפט לאשר מראש פעולה כזו, אך ורק ''אם ראה שהיא לטובת הנאמנות''. סעיף 13(ג) לחוק הנאמנות, תשל"ט-1979 מבחן זה הוא קפדני ומחייב בחינה זהירה של מכלול הנתונים, תוך מתן עדיפות מוחלטת לאינטרסים של הנאמנות והנהנים. ע"א 4377/04 גל גורן הולצברג נ'' אביבה מירז (22.07.2007) בית המשפט לא יאשר פעולה שנועדה בעיקר לטובת הנאמן, אלא אם כן היא משרתת באופן מובהק את מטרות הנאמנות. עמ"ש (מחוזי תל אביב-יפו) 35105-01-25 נ.ק נ'' א.י (23.03.2026)', 'הטעות הנפוצה היא לחשוב שדי בכך שהפעולה אינה מזיקה לנאמנות, או שהיא מועילה גם לנאמן, כדי שבית המשפט יאשר אותה, מבלי להבין את הדרישה המפורשת ל''טובת הנאמנות'' כתנאי בלעדי.',
      '["נאמן", "ניגוד עניינים", "אישור בית משפט", "טובת הנאמנות", "סעיף 13(ג) לחוק הנאמנות", "חובת אמון"]'::jsonb, '**וריאציה 1 — תנאי לאישור:** מהו התנאי לאישור פעולה אסורה? ← רק אם היא לטובת הנאמנות. סעיף 13(ג) לחוק הנאמנות, תשל"ט-1979
**וריאציה 2 — אישור מראש:** האם ניתן לאשר בדיעבד? ← לא, נדרש אישור מראש. ע"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו"ד משה מימרן (04.01.2009)
**וריאציה 3 — תכלית האיסור:** מהי תכלית האיסור על טובת הנאה? ← למנוע חשש לניגוד עניינים והגנה על הנהנה. ת"א (מחוזי ת"א) 27470-07-19 בית יורב 1997 בע"מ נ'' טובה כהן (21.06.2022)', 'אישור פעולה אסורה (ס'' 13(א)) ← רק מראש (ס'' 13(ג)) ← ורק אם לטובת הנאמנות ← לא לטובת הנאמן.', '["חוק הנאמנות, תשל\"ט-1979, סעיף 13(א)", "חוק הנאמנות, תשל\"ט-1979, סעיף 13(ג)", "ע\"א 4377/04 גל גורן הולצברג נ'' אביבה מירז (22.07.2007)", "ע\"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו\"ד משה מימרן (04.01.2009)", "עמ\"ש (מחוזי תל אביב-יפו) 35105-01-25 נ.ק נ'' א.י (23.03.2026)", "ת\"א (מחוזי ת\"א) 27470-07-19 בית יורב 1997 בע\"מ נ'' טובה כהן (21.06.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'האם הרכישה תועיל לנאמן ותאפשר לו להמשיך לשרת את הנאמנות ביעילות.', false, 'טענה זו שגויה, שכן טובת הנאמן אינה השיקול המרכזי, אלא טובת הנאמנות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'האם הרכישה היא לטובת הנאמנות, וזאת לאחר בחינה זהירה של מכלול הנתונים.', true, 'תשובה זו נכונה, שכן סעיף 13(ג) לחוק הנאמנות קובע במפורש כי בית המשפט יאשר פעולה כזו רק ''אם ראה שהיא לטובת הנאמנות''.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'האם הנאמן פעל בתום לב והציע מחיר הוגן עבור הנכס.', false, 'טענה זו שגויה, שכן תום לב ומחיר הוגן הם שיקולים חשובים, אך אינם התנאי הבלעדי והעיקרי לאישור, אלא טובת הנאמנות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'האם הנהנים הסכימו לרכישה, וזאת ללא קשר לטובת הנאמנות.', false, 'טענה זו שגויה, שכן הסכמת הנהנים אינה מחליפה את שיקול דעת בית המשפט בדבר טובת הנאמנות, במיוחד במקרים של ניגוד עניינים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q28';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'תוקף פעולה ללא אישור בית משפט', 3,
      'נאמן מכר נכס מנכסי הנאמנות לקרובו, ללא קבלת אישור מבית המשפט. הקרוב שילם תמורה מלאה ופעל בתום לב. מהו תוקף פעולת המכירה?', 'שאלה זו עוסקת בתוצאות המשפטיות של פעולה שנעשתה בניגוד לאיסור טובת הנאה, ללא אישור בית המשפט, ובפרט על החריג הקבוע בסעיף 13(ה) לחוק הנאמנות. היא מדגישה את ההבחנה בין פעולה עם קרוב נאמן לבין פעולה עם צד שלישי תם לב ובתמורה.', 'סעיף 13(א) לחוק הנאמנות אוסר על נאמן לרכוש לעצמו או לקרובו נכס מנכסי הנאמנות או להפיק מהם טובת הנאה. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979 סעיף 13(ה) קובע כי פעולה מן המנויות בסעיף זה שנעשתה בלי אישור בית המשפט – בטלה. סעיף 13(ה) לחוק הנאמנות, תשל"ט-1979 החריג לבטלות הוא אם הפעולה נעשתה בתמורה כלפי אדם שאינו קרוב לנאמן (כפי שהוגדר בסעיף 13(ב)) ושפעל בתום לב. במקרה הנדון, הקונה הוא קרוב של הנאמן, ולכן החריג אינו חל, והפעולה בטלה מעיקרה. ע"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו"ד משה מימרן (04.01.2009) יש להבחין בין בטלות לפי סעיף 13(ה) לבין אפשרות ביטול לפי סעיף 14 לחוק, החל על הפרת חובת נאמנות שאינה נכללת בגדר האיסורים של סעיף 13. ה"פ (מחוזי ירושלים) 4283/05 יוסף עמרם נ'' עו"ד איתן צחי (30.03.2008)', 'הטעות הנפוצה היא להתעלם מההבחנה בין ''קרוב'' ל''צד שלישי'' לעניין החריג לבטלות, או לבלבל בין בטלות מוחלטת (סעיף 13(ה)) לבין פעולה הניתנת לביטול (סעיף 14).',
      '["נאמן", "ניגוד עניינים", "בטלות", "קרוב נאמן", "צד שלישי תם לב", "תמורה", "סעיף 13(ה) לחוק הנאמנות"]'::jsonb, '**וריאציה 1 — פעולה ללא אישור:** מה תוקפה של פעולה אסורה ללא אישור ביהמ"ש? ← בטלה (סעיף 13(ה)). סעיף 13(ה) לחוק הנאמנות, תשל"ט-1979
**וריאציה 2 — חריג לבטלות:** מתי הפעולה אינה בטלה? ← אם נעשתה בתמורה כלפי אדם שאינו קרוב לנאמן ושפעל בתום לב. סעיף 13(ה) לחוק הנאמנות, תשל"ט-1979
**וריאציה 3 — קרוב נאמן:** האם קרוב נאמן נהנה מהחריג? ← לא, החריג אינו חל על קרוב נאמן. ע"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו"ד משה מימרן (04.01.2009)', 'פעולה אסורה ללא אישור (ס'' 13(א)) ← בטלה (ס'' 13(ה)) ← חריג: צד ג'' תם לב ובתמורה ← לא חל על קרוב נאמן.', '["חוק הנאמנות, תשל\"ט-1979, סעיף 13(א)", "חוק הנאמנות, תשל\"ט-1979, סעיף 13(ב)", "חוק הנאמנות, תשל\"ט-1979, סעיף 13(ה)", "חוק הנאמנות, תשל\"ט-1979, סעיף 14", "ע\"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו\"ד משה מימרן (04.01.2009)", "ה\"פ (מחוזי ירושלים) 4283/05 יוסף עמרם נ'' עו\"ד איתן צחי (30.03.2008)", "ת\"א (מחוזי חי'') 52865-12-15 פדל אלבסול נ'' הארכיבישוף ג''ורג'' חכים (23.07.2019)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הפעולה בטלה מעיקרה, מכיוון שנעשתה ללא אישור בית המשפט.', false, 'טענה זו שגויה, שכן סעיף 13(ה) לחוק הנאמנות קובע חריג לבטלות במקרה של צד שלישי תם לב ובתמורה, אך חריג זה אינו חל על קרוב נאמן.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הפעולה בטלה, מכיוון שהקונה הוא קרוב של הנאמן, ועל כן אינו נהנה מהחריג של צד שלישי תם לב ובתמורה.', true, 'תשובה זו נכונה, שכן סעיף 13(ה) לחוק הנאמנות קובע כי החריג לבטלות חל רק כלפי אדם שאינו קרוב לנאמן, ועל כן במקרה זה הפעולה בטלה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הפעולה תקפה, מכיוון שהקרוב שילם תמורה מלאה ופעל בתום לב.', false, 'טענה זו שגויה, שכן תום לב ותמורה אינם מספיקים כדי להכשיר פעולה עם קרוב נאמן ללא אישור בית המשפט.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הפעולה ניתנת לביטול על ידי בית המשפט, אך אינה בטלה מעיקרה.', false, 'טענה זו שגויה, שכן סעיף 13(ה) קובע בטלות מוחלטת לפעולה עם קרוב ללא אישור, בניגוד לסעיף 14 המאפשר ביטול.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q28';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'השלכת ניגוד עניינים על אפוטרופוס', 4,
      'אפוטרופוס שמונה על ידי בית המשפט מעוניין לקבל מתנה מהחסוי. האם איסור טובת ההנאה הקבוע בסעיף 13(א) לחוק הנאמנות חל על האפוטרופוס, ומה נדרש כדי להכשיר את קבלת המתנה?', 'שאלה זו בוחנת את תחולת עקרון ניגוד העניינים ואיסור טובת ההנאה, כפי שבא לידי ביטוי בסעיף 13 לחוק הנאמנות, על יחסי אפוטרופוס-חסוי. היא מדגישה את ההלכה הפסוקה לפיה יחסים אלו נחשבים ליחסי נאמנות, ועל כן נדרש אישור מראש של בית המשפט לכל פעולה שיש בה טובת הנאה לאפוטרופוס, וזאת רק אם היא לטובת החסוי.', 'הפסיקה קבעה כי יחסי אפוטרופוס-חסוי הם יחסי נאמנות, ועל כן חלות עליהם הוראות חוק הנאמנות, ובפרט סעיף 13, על דרך ההיקש או כדין משלים. ע"א 4377/04 גל גורן הולצברג נ'' אביבה מירז (22.07.2007) תמ"ש (משפחה חיפה) 8468-10-09 עזבון החסויה נ'' עזבון האפוטרופוס המנוח (18.06.2014) סעיף 13(א) לחוק הנאמנות אוסר על נאמן להפיק טובת הנאה מנכסי הנאמנות. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979 לכן, קבלת מתנה מהחסוי על ידי האפוטרופוס מהווה טובת הנאה אסורה. כדי להכשיר פעולה כזו, נדרש אישור מראש של בית המשפט, וזאת רק אם בית המשפט רואה שהפעולה היא לטובת הנאמנות (החסוי). סעיף 13(ג) לחוק הנאמנות, תשל"ט-1979 הפסיקה מדגישה כי אישור בדיעבד אינו אפשרי במקרים אלו. ע"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו"ד משה מימרן (04.01.2009)', 'הטעות הנפוצה היא לחשוב שיחסי אפוטרופסות אינם כפופים לחוק הנאמנות, או שדי ברצון החופשי של החסוי כדי להכשיר מתנה לאפוטרופוס, מבלי להבין את הדרישה לאישור מראש של בית המשפט.',
      '["אפוטרופוס", "חסוי", "נאמנות", "ניגוד עניינים", "טובת הנאה", "אישור בית משפט מראש", "חוק הנאמנות, סעיף 13"]'::jsonb, '**וריאציה 1 — יחסי נאמנות:** האם יחסי אפוטרופוס-חסוי הם יחסי נאמנות? ← כן, הפסיקה קבעה זאת. ע"א 4377/04 גל גורן הולצברג נ'' אביבה מירז (22.07.2007)
**וריאציה 2 — איסור טובת הנאה:** האם אפוטרופוס יכול לקבל מתנה מהחסוי? ← אסור, מכוח סעיף 13(א) לחוק הנאמנות. סעיף 13(א) לחוק הנאמנות, תשל"ט-1979
**וריאציה 3 — תנאי להכשרה:** מה נדרש כדי להכשיר מתנה כזו? ← אישור מראש של בית המשפט, אם היא לטובת החסוי. סעיף 13(ג) לחוק הנאמנות, תשל"ט-1979', 'יחסי אפוטרופוס-חסוי ← יחסי נאמנות (הלכת הולצברג) ← חל איסור טובת הנאה (ס'' 13(א)) ← נדרש אישור מראש של ביהמ"ש (ס'' 13(ג)) ← רק אם לטובת החסוי.', '["חוק הנאמנות, תשל\"ט-1979, סעיף 13(א)", "חוק הנאמנות, תשל\"ט-1979, סעיף 13(ג)", "ע\"א 4377/04 גל גורן הולצברג נ'' אביבה מירז (22.07.2007)", "דנ\"א 6770/07 אביבה מירז נ'' גל גורן הולצברג (13.05.2008)", "ע\"א (מחוזי ירושלים) 11344/07 פלונית נ'' עו\"ד משה מימרן (04.01.2009)", "עמ\"ש (מחוזי תל אביב-יפו) 35105-01-25 נ.ק נ'' א.י (23.03.2026)", "עמ\"ש (מחוזי תל אביב-יפו) 19960-05-18 ר'' י'' נ'' י'' י'' (07.01.2020)", "תמ\"ש (משפחה אשדוד) 1519-08-21 י.א נ'' ג.ה (26.10.2025)", "תמ\"ש (משפחה חיפה) 8468-10-09 עזבון החסויה נ'' עזבון האפוטרופוס המנוח (18.06.2014)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'האיסור אינו חל על אפוטרופוס, מכיוון שיחסי אפוטרופסות מוסדרים בחוק הכשרות המשפטית והאפוטרופסות בלבד.', false, 'טענה זו שגויה, שכן הפסיקה קבעה כי הוראות חוק הנאמנות, ובפרט סעיף 13, חלות על יחסי אפוטרופוס-חסוי על דרך ההיקש או כדין משלים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'האיסור חל על האפוטרופוס, וקבלת המתנה תהיה תקפה רק אם בית המשפט אישר אותה מראש, וראה שהיא לטובת החסוי.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי יחסי אפוטרופוס-חסוי הם יחסי נאמנות, ועל כן חל עליהם סעיף 13 לחוק הנאמנות, הדורש אישור מראש של בית המשפט לפעולה כזו, אם היא לטובת הנאמנות (החסוי).', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'האיסור חל על האפוטרופוס, אך די בהסכמת החסוי לקבלת המתנה, ואין צורך באישור בית המשפט.', false, 'טענה זו שגויה, שכן במקרים של ניגוד עניינים בין אפוטרופוס לחסוי, הסכמת החסוי אינה מספיקה, ונדרש אישור בית המשפט מראש.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'האיסור חל על האפוטרופוס, וניתן לקבל אישור בדיעבד מבית המשפט אם יוכח שהמתנה ניתנה מרצונו החופשי של החסוי.', false, 'טענה זו שגויה, שכן הפסיקה מדגישה את הצורך באישור מראש, ואינה מכשירה אישור בדיעבד במקרים אלו.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q28';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 28, '2024-W-S-Q28';
END
$$;

-- ============================================================
-- Q29 — angles backfill for 2024-W-S-Q29 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q29';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q29';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'דרישות דח"צ בשותפות פרטית', 1,
      'שותפות מוגבלת פרטית, שאינה מוגדרת כ"ציבורית" לפי פקודת השותפויות, מעוניינת למנות דירקטוריון. האם חלה עליה חובה למנות דירקטורים חיצוניים?', 'שאלה זו בוחנת את תחולת חובת מינוי דירקטורים חיצוניים על שותפויות מוגבלות, תוך הבחנה בין שותפות ציבורית לפרטית. היא מדגישה את העובדה כי הוראות חוק החברות בעניין זה מוחלות על שותפויות מוגבלות ציבוריות בלבד, מכוח הפניה מפורשת בפקודת השותפויות.', 'פקודת השותפויות [נוסח חדש], תשל"ה-1975, מבחינה בין שותפות מוגבלת רגילה לשותפות מוגבלת ציבורית. סעיף 65ט לפקודת השותפויות קובע כי הוראות סעיפים 239(א) ו-240 לחוק החברות, התשנ"ט-1999, יחולו, בשינויים המחויבים, על שותפות מוגבלת ציבורית. סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975 סעיף 239(א) לחוק החברות קובע את חובת מינוי דירקטורים חיצוניים בחברה ציבורית. סעיף 239(א) לחוק החברות, התשנ"ט-1999 מכיוון שסעיף 65ט לפקודת השותפויות מפנה להוראות אלו רק לגבי שותפות מוגבלת ציבורית, הרי שעל שותפות מוגבלת פרטית, שאינה עונה להגדרת "ציבורית", לא חלה חובה למנות דירקטורים חיצוניים. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)', 'הטעות הנפוצה היא להחיל את כלל חובת מינוי הדירקטורים החיצוניים על כל סוגי השותפויות המוגבלות, מבלי להבחין בין שותפות ציבורית לפרטית, או להתעלם מההפניה הספציפית בפקודת השותפויות.',
      '["שותפות מוגבלת ציבורית", "שותפות מוגבלת פרטית", "דירקטורים חיצוניים", "פקודת השותפויות", "חוק החברות", "סעיף 65ט לפקודת השותפויות", "סעיף 239(א) לחוק החברות"]'::jsonb, '**וריאציה 1 — חובת דח"צ בשותפות:** על איזה סוג שותפות חלה חובת מינוי דח"צ? ← רק על שותפות מוגבלת ציבורית. סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975

**וריאציה 2 — מקור החובה:** מהו מקור החובה למינוי דח"צ בשותפות ציבורית? ← סעיף 65ט לפקודת השותפויות המפנה לסעיף 239(א) לחוק החברות. סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975
**וריאציה 3 — שותפות פרטית:** האם שותפות מוגבלת פרטית חייבת למנות דח"צ? ← לא, החובה אינה חלה עליה. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)', 'חובת דח"צ ← רק על שותפות מוגבלת ציבורית (ס'' 65ט לפקודת השותפויות) ← מכוח הפניה לס'' 239(א) לחוק החברות ← לא חלה על שותפות פרטית.', '["פקודת השותפויות [נוסח חדש], תשל\"ה-1975, סעיף 65ט", "חוק החברות, התשנ\"ט-1999, סעיף 239(א)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (20.01.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שכל שותפות מוגבלת, ללא קשר לסיווגה כפרטית או ציבורית, חייבת למנות דירקטורים חיצוניים.', false, 'טענה זו שגויה, שכן חובת מינוי דירקטורים חיצוניים חלה רק על שותפויות מוגבלות ציבוריות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חובת מינוי דירקטורים חיצוניים חלה רק על שותפויות מוגבלות ציבוריות, מכוח סעיף 65ט לפקודת השותפויות המפנה לסעיף 239(א) לחוק החברות.', true, 'תשובה זו נכונה, שכן סעיף 65ט לפקודת השותפויות מחיל את הוראות חוק החברות בדבר דירקטורים חיצוניים רק על שותפויות מוגבלות ציבוריות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם מחזור ההכנסות השנתי של השותפות עולה על סכום מסוים הקבוע בתקנות.', false, 'טענה זו שגויה, שכן דרישת מחזור הכנסות רלוונטית לחברות ציבוריות מסוימות, אך אינה התנאי המכריע לשותפויות פרטיות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן השותפות בחרה לאמץ את הוראות חוק החברות בעניין זה בתקנון שלה.', false, 'טענה זו שגויה, שכן חובת מינוי דח"צ אינה עניין לבחירה של שותפות פרטית, אלא חובה חוקית החלה על שותפויות ציבוריות בלבד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q29';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תכלית מינוי דירקטורים חיצוניים', 2,
      'מהי התכלית העיקרית העומדת בבסיס הדרישה למינוי דירקטורים חיצוניים בחברות ציבוריות ובשותפויות מוגבלות ציבוריות?', 'שאלה זו עוסקת בתכלית העומדת בבסיס הדרישה למינוי דירקטורים חיצוניים בחברות ציבוריות ובשותפויות מוגבלות ציבוריות. היא מדגישה את חשיבותם של הדירקטורים החיצוניים כמנגנון הגנה על ענייני הציבור ובעלי מניות המיעוט, וככלי לשיפור הממשל התאגידי.', 'הדרישה למינוי דירקטורים חיצוניים בחברות ציבוריות (ומכוח סעיף 65ט לפקודת השותפויות, גם בשותפויות מוגבלות ציבוריות) נועדה להבטיח ממשל תאגידי תקין ולהגן על ענייני הציבור ובעלי מניות המיעוט. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020) תפקידם של הדירקטורים החיצוניים הוא לספק ביקורת בלתי תלויה על פעילות הדירקטוריון וההנהלה, למנוע ניגודי עניינים, ולוודא שהחלטות החברה מתקבלות לטובת כלל בעלי המניות. רע"פ 9818/01 שמעון ביטון נ'' ציון סולטן (31.03.2005) הם מהווים "שומרי סף" שמטרתם להבטיח את תקינות פעילות התאגיד ואת האיזון בין בעלי העניין השונים. ת"א (מחוזי ת"א) 27470-07-19 בית יורב 1997 בע"מ נ'' טובה כהן (21.06.2022)', 'הטעות הנפוצה היא לבלבל בין תפקידם של דירקטורים חיצוניים לבין תפקידם של דירקטורים רגילים, או לחשוב שתפקידם הוא לשרת את האינטרסים של בעלי השליטה.',
      '["דירקטורים חיצוניים", "ממשל תאגידי", "הגנת בעלי מניות מיעוט", "ביקורת בלתי תלויה", "חוק החברות", "פקודת השותפויות"]'::jsonb, '**וריאציה 1 — תכלית עיקרית:** מהי התכלית העיקרית של דח"צ? ← הגנה על הציבור ובעלי מניות המיעוט. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)
**וריאציה 2 — תפקיד ביקורתי:** איזה תפקיד ממלאים הדח"צ? ← ביקורת בלתי תלויה על הדירקטוריון וההנהלה. רע"פ 9818/01 שמעון ביטון נ'' ציון סולטן (31.03.2005)
**וריאציה 3 — שומרי סף:** כיצד נתפסים הדח"צ? ← כ"שומרי סף" להבטחת תקינות פעילות התאגיד. ת"א (מחוזי ת"א) 27470-07-19 בית יורב 1997 בע"מ נ'' טובה כהן (21.06.2022)', 'תכלית דח"צ ← הגנה על הציבור ומיעוט ← ממשל תאגידי תקין ← ביקורת בלתי תלויה ← "שומרי סף".', '["פקודת השותפויות [נוסח חדש], תשל\"ה-1975, סעיף 65ט", "חוק החברות, התשנ\"ט-1999, סעיף 239(א)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (20.01.2020)", "רע\"פ 9818/01 שמעון ביטון נ'' ציון סולטן (31.03.2005)", "ת\"א (מחוזי ת\"א) 27470-07-19 בית יורב 1997 בע\"מ נ'' טובה כהן (21.06.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לייצג את האינטרסים של בעלי השליטה בחברה ולסייע להם בקבלת החלטות אסטרטגיות.', false, 'טענה זו שגויה, שכן תפקידם של הדירקטורים החיצוניים הוא להגן על בעלי מניות המיעוט והציבור, ולא על בעלי השליטה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'להגן על ענייני הציבור ובעלי מניות המיעוט, להבטיח ממשל תאגידי תקין, ולספק ביקורת בלתי תלויה על פעילות הדירקטוריון וההנהלה.', true, 'תשובה זו נכונה, שכן היא משקפת את התכליות העיקריות של מינוי דירקטורים חיצוניים כפי שנקבעו בחוק ובפסיקה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לספק מומחיות מקצועית בתחומי פעילות החברה ולשפר את ביצועיה העסקיים.', false, 'טענה זו שגויה, שכן מומחיות מקצועית היא תכונה רצויה לכל דירקטור, אך אינה התכלית הייחודית והעיקרית של דירקטור חיצוני.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לשמש כבוררים בסכסוכים פנימיים בין חברי הדירקטוריון.', false, 'טענה זו שגויה, שכן תפקיד הדח"צ אינו לבורר בסכסוכים, אלא לפקח ולבקר את פעילות הדירקטוריון וההנהלה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q29';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'מספר מינימלי של דח"צ', 3,
      'שותפות מוגבלת ציבורית התאגדה בשנת 2010 ומינתה דירקטוריון שכלל דירקטור חיצוני אחד בלבד. האם מינוי זה עומד בדרישות החוק?', 'שאלה זו בוחנת את הדרישה למספר המינימלי של דירקטורים חיצוניים בשותפות מוגבלת ציבורית. היא מדגישה את ההפניה מסעיף 65ט לפקודת השותפויות לסעיף 239(א) לחוק החברות, הקובע כי בחברה ציבורית (ובמקרה זה, בשותפות מוגבלת ציבורית) יכהנו לפחות שני דירקטורים חיצוניים.', 'סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975, קובע כי הוראות סעיפים 239(א) ו-240 לחוק החברות, התשנ"ט-1999, יחולו, בשינויים המחויבים, על שותפות מוגבלת ציבורית. סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975 סעיף 239(א) לחוק החברות קובע במפורש כי "בחברה ציבורית יכהנו לפחות שני דירקטורים חיצוניים". סעיף 239(א) לחוק החברות, התשנ"ט-1999 לפיכך, שותפות מוגבלת ציבורית חייבת למנות לפחות שני דירקטורים חיצוניים. מינוי של דירקטור חיצוני אחד בלבד אינו עומד בדרישות החוק. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)', 'הטעות הנפוצה היא לחשוב שדי במינוי דירקטור חיצוני אחד, או להתעלם מהדרישה המפורשת למספר מינימלי של שני דירקטורים חיצוניים בחברות ציבוריות ובשותפויות מוגבלות ציבוריות.',
      '["דירקטורים חיצוניים", "מספר מינימלי", "שותפות מוגבלת ציבורית", "חוק החברות", "פקודת השותפויות", "סעיף 239(א) לחוק החברות", "סעיף 65ט לפקודת השותפויות"]'::jsonb, '**וריאציה 1 — דרישת חוק החברות:** כמה דח"צ נדרשים בחברה ציבורית? ← לפחות שניים (סעיף 239(א) לחוק החברות). סעיף 239(א) לחוק החברות, התשנ"ט-1999
**וריאציה 2 — תחולה על שותפות:** האם דרישה זו חלה על שותפות ציבורית? ← כן, מכוח סעיף 65ט לפקודת השותפויות. סעיף 65ט לפקודת השותפויות [נוסח חדש], תשל"ה-1975
**וריאציה 3 — מינוי חסר:** האם מינוי דח"צ אחד עומד בדרישה? ← לא, נדרשים לפחות שניים. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)', 'שותפות ציבורית ← חייבת לפחות 2 דח"צ (ס'' 65ט לפקודת השותפויות + ס'' 239(א) לחוק החברות) ← מינוי 1 אינו חוקי.', '["פקודת השותפויות [נוסח חדש], תשל\"ה-1975, סעיף 65ט", "חוק החברות, התשנ\"ט-1999, סעיף 239(א)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (20.01.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהחוק דורש לפחות דירקטור חיצוני אחד, ודרישה זו התקיימה.', false, 'טענה זו שגויה, שכן החוק דורש לפחות שני דירקטורים חיצוניים בשותפות מוגבלת ציבורית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שותפות מוגבלת ציבורית חייבת למנות לפחות שני דירקטורים חיצוניים, מכוח סעיף 65ט לפקודת השותפויות המפנה לסעיף 239(א) לחוק החברות.', true, 'תשובה זו נכונה, שכן סעיף 239(א) לחוק החברות, החל על שותפויות מוגבלות ציבוריות, קובע חובה למינוי לפחות שני דירקטורים חיצוניים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם הדירקטור החיצוני היחיד הוא בעל מומחיות מיוחדת וניסיון רב.', false, 'טענה זו שגויה, שכן כישורים מיוחדים אינם פוטרים מחובת מינוי המספר המינימלי של דירקטורים חיצוניים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן השותפות קיבלה פטור מיוחד מבית המשפט ממינוי דירקטור חיצוני נוסף.', false, 'טענה זו שגויה, שכן אין בחוק הוראה המאפשרת פטור ממינוי המספר המינימלי של דירקטורים חיצוניים בשותפות מוגבלת ציבורית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q29';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות בית המשפט להתערב בהאצלת סמכויות', 4,
      'דירקטוריון של שותפות מוגבלת ציבורית העניק לדירקטור יחיד זכות הכרעה בלעדית בעניינים פיננסיים מהותיים, בניגוד להוראות החוק. בעלי מניות מיעוט מעוניינים לבטל החלטה זו. מהו ההליך המשפטי המתאים ביותר לנקוט בו?', 'שאלה זו עוסקת בסמכות בית המשפט להתערב בהחלטות דירקטוריון של שותפות מוגבלת ציבורית, ובפרט בהאצלת סמכויות בניגוד לחוק. היא בוחנת את ההליכים המשפטיים העומדים לרשות בעלי מניות מיעוט במקרים של הפרת הוראות חוק החברות החלות על השותפות.', 'סעיף 106 לחוק החברות, התשנ"ט-1999, קובע סמכויות מסוימות שאינן ניתנות להאצלה על ידי הדירקטוריון. סעיף 106(ב) לחוק החברות, התשנ"ט-1999 הענקת זכות הכרעה בלעדית לדירקטור יחיד בעניינים פיננסיים מהותיים מנוגדת לעקרון הניהול הקולקטיבי של הדירקטוריון ומהווה האצלת סמכות פסולה. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020) במקרה כזה, בעלי מניות מיעוט יכולים לפנות לבית המשפט בבקשה לסעד הצהרתי או צו עשה לביטול ההחלטה, בטענה שהיא מנוגדת לחוק. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020) תביעה נגזרת מתאימה יותר כאשר נגרם נזק לחברה ובעלי המניות מבקשים לתבוע בשם החברה פיצויים, אך במקרה זה הסעד העיקרי המבוקש הוא ביטול ההחלטה הפסולה. רע"פ 9818/01 שמעון ביטון נ'' ציון סולטן (31.03.2005)', 'הטעות הנפוצה היא לבלבל בין סעדים שונים העומדים לרשות בעלי מניות, או לחשוב שהחלטה בלתי חוקית של דירקטוריון ניתנת לריפוי בדרכים פנים-תאגידיות ללא התערבות שיפוטית.',
      '["האצלת סמכויות", "סעיף 106 לחוק החברות", "שותפות מוגבלת ציבורית", "סעד הצהרתי", "צו עשה", "תביעה נגזרת", "התערבות שיפוטית"]'::jsonb, '**וריאציה 1 — סמכויות לא ניתנות להאצלה:** האם ניתן להאציל סמכויות ליבה פיננסיות לדירקטור יחיד? ← לא, סעיף 106 לחוק החברות קובע סמכויות שאינן ניתנות להאצלה. סעיף 106(ב) לחוק החברות, התשנ"ט-1999
**וריאציה 2 — עקרון הניהול הקולקטיבי:** מה נפגע מהאצלה כזו? ← עקרון הניהול הקולקטיבי של הדירקטוריון. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)
**וריאציה 3 — סעד לבעלי מניות:** מהו הסעד המתאים לביטול החלטה כזו? ← תביעה לסעד הצהרתי או צו עשה לביטול ההאצלה. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (20.01.2020)', 'האצלת סמכויות ליבה ← אסורה (ס'' 106 לחוק החברות) ← פוגעת בניהול קולקטיבי ← סעד: תביעה לסעד הצהרתי/צו עשה לביטול.', '["חוק החברות, התשנ\"ט-1999, סעיף 106", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (20.01.2020)", "רע\"פ 9818/01 שמעון ביטון נ'' ציון סולטן (31.03.2005)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הגשת תביעה לבית המשפט בטענה להפרת חובת הדירקטוריון לפי סעיף 106 לחוק החברות, בצירוף בקשה לסעד הצהרתי או צו עשה לביטול ההאצלה.', true, 'תשובה זו נכונה, שכן סעיף 106 לחוק החברות קובע סמכויות שאינן ניתנות להאצלה, ובית המשפט מוסמך להתערב בהחלטות דירקטוריון המנוגדות לחוק.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פנייה לרשות ניירות ערך בבקשה שתתערב ותורה על ביטול ההאצלה.', false, 'טענה זו שגויה, שכן למרות שלרשות ניירות ערך סמכויות פיקוח, הסעד המבוקש הוא ביטול החלטה, וזהו סעד שיפוטי מובהק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הגשת תביעה נגזרת נגד הדירקטורים שהצביעו בעד ההאצלה, בטענה להפרת חובת אמונים.', false, 'טענה זו שגויה, שכן תביעה נגזרת מתאימה יותר לפיצוי על נזק שנגרם לחברה, בעוד שהסעד המבוקש הוא ביטול ההחלטה עצמה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הגשת בקשה לכינוס אסיפה כללית מיוחדת של בעלי המניות כדי להצביע על ביטול ההאצלה.', false, 'טענה זו שגויה, שכן החלטה המנוגדת לחוק אינה ניתנת לריפוי בהצבעת אסיפה כללית, ונדרשת התערבות שיפוטית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q29';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 29, '2024-W-S-Q29';
END
$$;

-- ============================================================
-- Q30 — angles backfill for 2024-W-S-Q30 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q30';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q30';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תוקף הסכם מייסדים שלא אומץ', 1,
      'בין מספר יזמי נדל"ן נכרת הסכם מייסדים בשנת 2019 בקשר עם חברת נדל"ן שתוקם. בהסכם נכלל סעיף אנטי דילול. בשנת 2020 התאגדה החברה, אך היא לא אישרה ולא כללה את הסכם המייסדים בתקנונה. כעת, החברה מבקשת לבצע גיוס הון שיפגע בסעיף האנטי דילול. מה הדין?', 'שאלה זו בוחנת את מעמדו המשפטי של הסכם מייסדים שלא אומץ על ידי החברה לאחר התאגדותה. היא מדגישה את העיקרון לפיו חברה אינה כפופה אוטומטית להסכמים שנכרתו טרם הקמתה, אלא אם כן אימצה אותם במפורש או במשתמע.', 'הסכם מייסדים הוא הסכם שנכרת בין יזמים טרם הקמת החברה. ככלל, חברה אינה צד להסכם שנכרת לפני הקמתה, ולכן אינה מחויבת לו אוטומטית. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996) כדי שהסכם כזה יחייב את החברה, עליה לאמץ אותו במפורש או במשתמע לאחר התאגדותה. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017) במקרה הנדון, החברה לא אישרה ולא כללה את הסכם המייסדים בתקנונה, ולכן היא אינה מחויבת לסעיף האנטי דילול. ההסכם ימשיך לחייב את היזמים שחתמו עליו בינם לבין עצמם. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'הטעות הנפוצה היא להניח שהסכם מייסדים מחייב את החברה באופן אוטומטי, מבלי להבין את הצורך במעשה אימוץ מצידה לאחר התאגדותה.',
      '["הסכם מייסדים", "אימוץ הסכם טרום התאגדות", "חברה", "תוקף חוזי", "חוק החברות", "אישיות משפטית נפרדת"]'::jsonb, '**וריאציה 1 — חברה והסכם טרום התאגדות:** האם חברה מחויבת אוטומטית להסכם טרום התאגדות? ← לא, אלא אם אימצה אותו. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)
**וריאציה 2 — אימוץ הסכם:** כיצד חברה מאמצת הסכם טרום התאגדות? ← במפורש או במשתמע. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)
**וריאציה 3 — הסכם שלא אומץ:** מה תוקפו של הסכם מייסדים שלא אומץ? ← מחייב רק את היזמים שחתמו עליו. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'הסכם מייסדים שלא אומץ ← לא מחייב את החברה ← מחייב רק את היזמים שחתמו עליו ← נדרש אימוץ מפורש/משתמע.', '["חוק החברות, התשנ\"ט-1999, סעיף 12", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (20.03.2017)", "בג\"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'החברה אינה מחויבת לסעיף האנטי דילול, שכן היא לא אימצה את הסכם המייסדים, וההסכם מחייב רק את היזמים שחתמו עליו.', true, 'תשובה זו נכונה, שכן חברה אינה מחויבת אוטומטית להסכם שנכרת טרם התאגדותה, אלא אם אימצה אותו במפורש או במשתמע.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'החברה מחויבת לסעיף האנטי דילול, מכיוון שהיא הוקמה על בסיס הסכם המייסדים, ואין צורך באישור פורמלי.', false, 'טענה זו שגויה, שכן נדרש מעשה אימוץ מצד החברה כדי שהסכם טרום התאגדות יחייב אותה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'החברה מחויבת לסעיף האנטי דילול, אך רק אם המשקיעים החיצוניים היו מודעים לקיומו של ההסכם.', false, 'טענה זו שגויה, שכן מודעות המשקיעים אינה הופכת את ההסכם למחייב את החברה אם היא לא אימצה אותו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'החברה אינה מחויבת לסעיף האנטי דילול, אך היזמים שחתמו על ההסכם עשויים להיות חשופים לתביעה בגין הפרת חוזה.', false, 'טענה זו נכונה חלקית, אך אינה התשובה המלאה לשאלה האם החברה מחויבת. החברה אינה מחויבת, והיזמים עשויים להיות חשופים לתביעה, אך השאלה מתמקדת בחבות החברה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q30';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחן אימוץ הסכם טרום התאגדות', 2,
      'מהם הדרכים שבהן חברה יכולה לאמץ הסכם מייסדים שנכרת טרם התאגדותה, ובכך להפוך אותו למחייב כלפיה?', 'שאלה זו מתמקדת במבחנים ובדרכים שבהן חברה יכולה לאמץ הסכם מייסדים שנכרת טרם התאגדותה. היא מדגישה את ההבחנה בין אימוץ מפורש לאימוץ במשתמע, ואת המשמעות המשפטית של כל אחת מהדרכים הללו.', 'חברה, בהיותה אישיות משפטית נפרדת, אינה מחויבת אוטומטית להסכמים שנכרתו טרם הקמתה. כדי שהסכם מייסדים יחייב את החברה, עליה לאמץ אותו לאחר התאגדותה. אימוץ זה יכול להיעשות בשתי דרכים עיקריות: אימוץ מפורש או אימוץ במשתמע. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996) אימוץ מפורש יכול להתבטא בהחלטת דירקטוריון או אסיפה כללית המאשרת את ההסכם, או בהכללת הוראות ההסכם בתקנון החברה. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017) אימוץ במשתמע מתרחש כאשר החברה מבצעת פעולות המעידות על כוונתה לקבל על עצמה את ההסכם, כגון קבלת תמורה על פיו או נקיטת פעולות בהתאם להוראותיו. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'הטעות הנפוצה היא לחשוב שאימוץ חייב להיות מפורש ופורמלי, או להתעלם מהאפשרות של אימוץ במשתמע באמצעות התנהגות החברה.',
      '["הסכם מייסדים", "אימוץ מפורש", "אימוץ במשתמע", "תקנון חברה", "החלטת דירקטוריון", "החלטת אסיפה כללית", "חוק החברות"]'::jsonb, '**וריאציה 1 — דרכי אימוץ:** באילו דרכים חברה יכולה לאמץ הסכם מייסדים? ← אימוץ מפורש או במשתמע. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)
**וריאציה 2 — אימוץ מפורש:** דוגמאות לאימוץ מפורש? ← החלטת דירקטוריון/אסיפה כללית, הכללה בתקנון. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)
**וריאציה 3 — אימוץ במשתמע:** דוגמאות לאימוץ במשתמע? ← קבלת תמורה, נקיטת פעולות לפי ההסכם. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'אימוץ הסכם מייסדים ← מפורש (החלטה/תקנון) או במשתמע (התנהגות) ← הופך את ההסכם למחייב את החברה.', '["חוק החברות, התשנ\"ט-1999, סעיף 12", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (20.03.2017)", "בג\"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק באמצעות החלטה מפורשת של האסיפה הכללית של בעלי המניות, המאשרת את ההסכם.', false, 'טענה זו שגויה, שכן אימוץ יכול להיעשות גם במשתמע, ולא רק בהחלטה מפורשת של האסיפה הכללית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'באמצעות אימוץ מפורש (כגון החלטת דירקטוריון או אסיפה כללית) או אימוץ במשתמע (כגון פעולות המעידות על כוונת החברה לקבל על עצמה את ההסכם).', true, 'תשובה זו נכונה, שכן הפסיקה מכירה בשתי דרכים לאימוץ הסכם טרום התאגדות: מפורש או במשתמע.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק באמצעות הכללת הוראות ההסכם בתקנון החברה, ואין די באישור חיצוני לתקנון.', false, 'טענה זו שגויה, שכן הכללת ההסכם בתקנון היא דרך לאימוץ מפורש, אך אינה הדרך היחידה, ואימוץ יכול להיעשות גם ללא הכללה בתקנון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'החברה אינה יכולה לאמץ הסכם טרום התאגדות, אלא עליה לכרות הסכם חדש עם היזמים לאחר הקמתה.', false, 'טענה זו שגויה, שכן הפסיקה מכירה באפשרות של אימוץ הסכם טרום התאגדות על ידי החברה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q30';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'הסכם מייסדים מחוץ לתקנון', 3,
      'חברה אימצה הסכם מייסדים שכלל סעיף אנטי דילול, אך לא כללה אותו בתקנונה. כעת, החברה שינתה את תקנונה באופן שפוגע בסעיף האנטי דילול. מה הדין לגבי תוקף השינוי בתקנון והאם החברה חשופה לתביעה?', 'שאלה זו עוסקת במקרה של סתירה בין תקנון חברה לבין הסכם מייסדים שאומץ על ידי החברה אך לא נכלל בתקנון. היא בוחנת את עקרון העליונות של התקנון על הסכמים חיצוניים, לצד חבותה החוזית של החברה בגין הפרת הסכם המייסדים.', 'תקנון החברה הוא המסמך המחייב של החברה וקובע את יחסיה עם בעלי מניותיה. סעיף 15 לחוק החברות, התשנ"ט-1999 במקרה של סתירה בין הוראות התקנון לבין הסכם חיצוני, הוראות התקנון גוברות. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017) לכן, שינוי התקנון יהיה תקף. עם זאת, העובדה שהחברה אימצה את הסכם המייסדים הופכת אותו למחייב אותה חוזית. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996) לפיכך, אם החברה פועלת בניגוד להוראות הסכם המייסדים שאומץ, היא חשופה לתביעה בגין הפרת חוזה מצד היזמים. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'הטעות הנפוצה היא לבלבל בין תוקפו של שינוי בתקנון לבין חבותה החוזית של החברה. התקנון גובר, אך החברה עדיין יכולה להפר חוזה.',
      '["תקנון חברה", "הסכם מייסדים", "עליונות התקנון", "הפרת חוזה", "חוק החברות", "סעיף 15 לחוק החברות"]'::jsonb, '**וריאציה 1 — סתירה תקנון/הסכם:** מה גובר במקרה של סתירה בין תקנון להסכם חיצוני? ← התקנון גובר. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)
**וריאציה 2 — חבות חוזית:** האם החברה עדיין מחויבת חוזית להסכם שאומץ? ← כן, גם אם לא נכלל בתקנון. בג"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)
**וריאציה 3 — תוצאת הפרה:** מהי התוצאה אם החברה פועלת בניגוד להסכם שאומץ? ← חשופה לתביעה בגין הפרת חוזה. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017)', 'הסכם מייסדים מחוץ לתקנון ← תקנון גובר על הסכם חיצוני ← אך החברה עדיין מחויבת חוזית להסכם שאומץ ← הפרה תוביל לתביעה.', '["חוק החברות, התשנ\"ט-1999, סעיף 15", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (20.03.2017)", "בג\"ץ 4295/95 קמחי נ'' בית-הדין הארצי לעבודה בירושלים (25.03.1996)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'שינוי התקנון תקף, והחברה אינה חשופה לתביעה, מכיוון שהתקנון גובר על הסכם חיצוני.', false, 'טענה זו שגויה, שכן למרות שהתקנון גובר, החברה עדיין חשופה לתביעה בגין הפרת הסכם המייסדים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'שינוי התקנון תקף, מכיוון שהתקנון הוא המסמך המחייב של החברה, אך החברה חשופה לתביעה בגין הפרת הסכם המייסדים.', true, 'תשובה זו נכונה, שכן התקנון גובר על הסכם חיצוני במקרה של סתירה, אך החברה עדיין מחויבת חוזית להסכם המייסדים שאימצה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שינוי התקנון אינו תקף, מכיוון שהוא מנוגד להסכם המייסדים שאומץ על ידי החברה.', false, 'טענה זו שגויה, שכן במקרה של סתירה בין התקנון להסכם חיצוני, התקנון גובר, גם אם החברה אימצה את ההסכם.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'החברה אינה חשופה לתביעה, מכיוון שהסכם המייסדים לא נכלל בתקנון, ולכן אין לו תוקף מחייב כלפי החברה.', false, 'טענה זו שגויה, שכן החברה אימצה את הסכם המייסדים, ולכן הוא מחייב אותה חוזית, גם אם לא נכלל בתקנון.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q30';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סעדים בגין הפרת הסכם מייסדים', 4,
      'חברה אימצה הסכם מייסדים שכלל סעיף אנטי דילול וכללה אותו בתקנונה. כעת, החברה מבצעת גיוס הון בניגוד לסעיף זה, ובעלי המניות המייסדים מעוניינים לתבוע. מהם הסעדים העיקריים העומדים לרשותם?', 'שאלה זו עוסקת בסעדים העומדים לרשות בעלי מניות מייסדים במקרה של הפרת הסכם מייסדים שאומץ על ידי החברה. היא בוחנת את מגוון הסעדים החוזיים, כגון אכיפה, פיצויים וצווי מניעה, ומדגישה את הרלוונטיות שלהם בהקשר התאגידי.', 'כאשר חברה מאמצת הסכם מייסדים, הוא הופך למחייב אותה חוזית. הפרת הסכם זה על ידי החברה מקנה לצד הנפגע את הסעדים הכלליים הקבועים בחוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (20.03.2017) הסעדים העיקריים כוללים: אכיפת ההסכם (למשל, באמצעות צו עשה המורה לחברה להקצות מניות נוספות למייסדים כדי לשמר את שיעור אחזקותיהם), פיצויים בגין הנזק שנגרם כתוצאה מהדילול (הפסד ערך המניות, אובדן רווחים וכדומה), או צו מניעה זמני או קבוע לעצירת גיוס ההון הפוגע. חוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970, סעיפים 2, 3, 10 סעד של פירוק חברה הוא סעד קיצוני שיינתן רק במקרים חריגים ביותר, כאשר אין דרך אחרת להגן על זכויות בעלי המניות. סעיף 257 לחוק החברות, התשנ"ט-1999', 'הטעות הנפוצה היא לחשוב שסעדים חוזיים אינם רלוונטיים בהקשר התאגידי, או לבלבל בין סעדים חוזיים רגילים לבין סעדים קיצוניים כמו פירוק חברה.',
      '["הסכם מייסדים", "הפרת חוזה", "אכיפה", "פיצויים", "צו מניעה", "חוק החוזים (תרופות)", "חוק החברות"]'::jsonb, '**וריאציה 1 — סעדים חוזיים:** מהם הסעדים העיקריים להפרת הסכם מייסדים? ← אכיפה, פיצויים, צו מניעה. חוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970, סעיפים 2, 3, 10
**וריאציה 2 — אכיפה ספציפית:** כיצד ניתן לאכוף סעיף אנטי דילול? ← צו עשה להקצאת מניות נוספות. חוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970, סעיף 3
**וריאציה 3 — פירוק חברה:** האם הפרת הסכם מייסדים היא עילה לפירוק? ← לא, זהו סעד קיצוני שיינתן רק במקרים חריגים. סעיף 257 לחוק החברות, התשנ"ט-1999', 'הפרת הסכם מייסדים שאומץ ← סעדים: אכיפה, פיצויים, צו מניעה ← לא פירוק חברה (סעד קיצוני) ← חוק החוזים (תרופות).', '["חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 2", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 3", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 10", "חוק החברות, התשנ\"ט-1999, סעיף 257", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (20.03.2017)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק פיצויים כספיים בגין הנזק שנגרם להם כתוצאה מהדילול.', false, 'טענה זו שגויה, שכן בנוסף לפיצויים, ניתן לדרוש גם אכיפה או צו מניעה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'אכיפת ההסכם (למשל, באמצעות צו עשה המורה לחברה להקצות מניות נוספות), פיצויים בגין הנזק שנגרם, או צו מניעה לעצירת גיוס ההון הפוגע.', true, 'תשובה זו נכונה, שכן אלו הם הסעדים העיקריים בגין הפרת חוזה, והם רלוונטיים גם להפרת הסכם מייסדים שאומץ על ידי החברה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'ביטול החברה ופירוקה, מכיוון שהפרת הסכם מייסדים מהווה עילה לפירוק.', false, 'טענה זו שגויה, שכן הפרת הסכם מייסדים אינה עילה אוטומטית לפירוק חברה, וזהו סעד קיצוני שיינתן רק במקרים חריגים ביותר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הגשת תלונה לרשות ניירות ערך, שתטיל קנסות על החברה.', false, 'טענה זו שגויה, שכן תלונה לרשות ניירות ערך היא הליך מנהלי, ואינה מספקת סעד ישיר לבעלי המניות המייסדים בגין הפרת ההסכם.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q30';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 30, '2024-W-S-Q30';
END
$$;

-- ============================================================
-- Q31 — angles backfill for 2024-W-S-Q31 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q31';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q31';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'היקף חובת הגילוי במכירת דירה יד שנייה', 1,
      'ראובן מכר לשמעון דירת מגורים יד שנייה. במהלך המשא ומתן, ראובן לא גילה לשמעון מיוזמתו כי קיים פגם קל במערכת האינסטלציה, אשר ניתן היה לגלותו בבדיקה סבירה. שמעון לא ביצע בדיקה כזו. האם ראובן הפר את חובת הגילוי כלפי שמעון?', 'שאלה זו בוחנת את היקף חובת הגילוי במשא ומתן במכירת דירה יד שנייה, תוך השוואה לחובת הגילוי המוגברת החלה על קבלן במכירת דירה ''על הנייר''. היא מדגישה את ההבדל בנטל הבדיקה המוטל על הקונה ואת פערי המידע והכוחות בין הצדדים בסוגי עסקאות שונים.', 'פסק הדין בעניין *מור נ'' אלעד ישראל מגורים* (ע"א 2274/21) קבע כי חובת גילוי מוגברת חלה על קבלן המוכר דירה ''על הנייר'', וזאת בשל פערי המידע והכוחות המשמעותיים בין הקבלן לרוכש, וחוסר יכולתו של הרוכש לבחון את הנכס פיזית. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) במכירת דירה יד שנייה, לעומת זאת, פערי המידע קטנים יותר, ועל הקונה מוטל נטל רב יותר לבדוק את הנכס בעצמו. אם הפגם ניתן לגילוי בבדיקה סבירה, והקונה לא ביצע בדיקה כזו, קשה יהיה לטעון שהמוכר הפר את חובת הגילוי, אלא אם מדובר בפגם נסתר או שהמוכר הטעה במכוון. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'הטעות הנפוצה היא להחיל את חובת הגילוי המוגברת של קבלן על כל מוכר דירה, מבלי להבחין בין סוגי העסקאות השונים ומידת יכולתו של הקונה לבדוק את הנכס.',
      '["חובת גילוי", "דירה ''על הנייר''", "דירה יד שנייה", "פערי מידע", "נטל בדיקה", "תום לב במשא ומתן"]'::jsonb, '**וריאציה 1 — חובת גילוי לקבלן:** מהי חובת הגילוי של קבלן במכירת דירה ''על הנייר''? ← מוגברת, בשל פערי מידע וכוח. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 2 — חובת גילוי למוכר יד שנייה:** מהי חובת הגילוי של מוכר דירה יד שנייה? ← פחותה, ועל הקונה מוטל נטל בדיקה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 3 — פגם גלוי:** האם אי-גילוי פגם גלוי בבדיקה סבירה מהווה הפרה? ← לא, אם הקונה לא ביצע בדיקה סבירה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'חובת גילוי קבלן ''על הנייר'' ← מוגברת. חובת גילוי מוכר יד שנייה ← פחותה, נטל בדיקה על הקונה. פגם גלוי בבדיקה סבירה ← אי-גילוי אינו הפרה אם הקונה לא בדק.', '["ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(א)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שחובת הגילוי חלה על כל מוכר, ללא קשר לסוג הנכס.', false, 'טענה זו שגויה, שכן היקף חובת הגילוי משתנה בהתאם לנסיבות, ובמכירת דירה יד שנייה נטל הבדיקה על הקונה גדול יותר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שבמכירת דירה יד שנייה, חובת הגילוי של המוכר פחותה, ועל הקונה מוטל נטל בדיקה עצמאית.', true, 'תשובה זו נכונה, שכן במכירת דירה יד שנייה, בניגוד לדירה ''על הנייר'', הקונה יכול לבדוק את הנכס, ולכן חובת הגילוי היזומה של המוכר פחותה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם ראובן ידע בפועל על הפגם ולא רק היה עליו לדעת.', false, 'טענה זו שגויה, שכן גם ידיעה קונסטרוקטיבית (היה עליו לדעת) יכולה להקים חובת גילוי במקרים מסוימים, אך במקרה זה נטל הבדיקה על הקונה הוא העיקר.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם הפגם היה נסתר ולא ניתן היה לגלותו בבדיקה סבירה.', false, 'טענה זו שגויה, שכן אם הפגם היה נסתר, חובת הגילוי של המוכר הייתה גוברת, אך השאלה מתייחסת לפגם שניתן לגלותו בבדיקה סבירה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q31';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחן חובת הגילוי המוגברת לקבלן', 2,
      'מהם השיקולים המרכזיים שבית המשפט יבחן בקביעת היקפה של חובת הגילוי המוגברת המוטלת על קבלן המוכר דירה ''על הנייר''?', 'שאלה זו מתמקדת במבחנים לקביעת היקפה של חובת הגילוי המוגברת המוטלת על קבלן המוכר דירה ''על הנייר''. היא מדגישה את השיקולים המרכזיים שנקבעו בפסיקה, כגון פערי מידע וכוחות, חוסר יכולת בדיקה פיזית ומהותיות המידע, הנגזרים מעקרון תום הלב במשא ומתן.', 'בית המשפט העליון בעניין *מור נ'' אלעד ישראל מגורים* (ע"א 2274/21) קבע כי חובת גילוי מוגברת חלה על קבלן המוכר דירה ''על הנייר''. שיקולים מרכזיים בקביעת היקף חובה זו כוללים את פערי המידע והכוחות המשמעותיים בין הקבלן לרוכש, את חוסר יכולתו של הרוכש לבחון את הנכס פיזית בשלב הטרום-חוזי, ואת מהותיות המידע שלא נמסר. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) תכליתה של חובה זו היא להבטיח שהסכמת הרוכש תהיה מודעת ומבוססת על כל הפרטים החשובים בנוגע לדירה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'הטעות הנפוצה היא להתמקד בכוונת הקבלן (תום לב סובייקטיבי) במקום בנסיבות האובייקטיביות של העסקה (פערי מידע וכוח) בקביעת חובת הגילוי.',
      '["חובת גילוי מוגברת", "דירה ''על הנייר''", "פערי מידע", "פערי כוחות", "תום לב במשא ומתן", "מהותיות המידע"]'::jsonb, '**וריאציה 1 — פערי מידע:** מהם השיקולים לחובת גילוי מוגברת? ← פערי מידע וכוח בין הצדדים. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 2 — יכולת בדיקה:** האם חוסר יכולת לבחון את הנכס משפיע? ← כן, רוכש ''על הנייר'' אינו יכול להתרשם פיזית. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)

**וריאציה 3 — תכלית החובה:** מהי תכלית חובת הגילוי המוגברת? ← להבטיח הסכמה מודעת של הרוכש. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'מבחן חובת גילוי מוגברת לקבלן ← פערי מידע וכוח + חוסר יכולת בדיקה פיזית + מהותיות המידע ← תכלית: הסכמה מודעת.', '["ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(א)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק את מידת ידיעתו בפועל של הקבלן על המידע הרלוונטי.', false, 'טענה זו שגויה, שכן חובת הגילוי המוגברת אינה תלויה רק בידיעה בפועל, אלא גם בפערי מידע וכוח.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פערי המידע והכוחות בין הקבלן לרוכש, חוסר יכולתו של הרוכש לבחון את הנכס פיזית, ומהותיות המידע שלא נמסר.', true, 'תשובה זו נכונה, שכן אלו הם השיקולים המרכזיים שנקבעו בפסיקה להטלת חובת גילוי מוגברת על קבלן.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק את מידת תום ליבו הסובייקטיבי של הקבלן.', false, 'טענה זו שגויה, שכן חובת תום הלב במשא ומתן היא אובייקטיבית, ואינה תלויה רק בתום ליבו הסובייקטיבי של הקבלן.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'רק את מידת רשלנותו של הקונה באי-בדיקת המידע.', false, 'טענה זו שגויה, שכן רשלנות הקונה עשויה להשפיע על גובה הפיצויים (אשם תורם), אך אינה פוטרת את הקבלן מחובת הגילוי המוגברת.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q31';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'אשם תורם של רוכש דירה', 3,
      'קבלן הפר את חובת הגילוי המוגברת כלפי רוכש דירה ''על הנייר'' בכך שלא גילה לו על חסימת נוף. עם זאת, הרוכש לא שאל שאלות כלל ולא ביצע כל בירור, למרות שחשש מבעיית חסימה. האם התנהלות הרוכש תפטור את הקבלן מאחריות?', 'שאלה זו עוסקת בדוקטרינת האשם התורם בהקשר של הפרת חובת גילוי במשא ומתן, ובפרט במכירת דירה ''על הנייר''. היא בוחנת את השפעת רשלנותו של הרוכש על אחריות הקבלן, ומדגישה כי אשם תורם אינו פוטר את הקבלן מאחריות, אלא עשוי להפחית את הפיצויים.', 'פסק הדין בעניין *מור נ'' אלעד ישראל מגורים* (ע"א 2274/21) דן באשם תורם של רוכש דירה ''על הנייר''. נקבע כי למרות שעל רוכש דירה מוטל נטל לבדוק ולשאול שאלות, מחדל זה אינו פוטר את הקבלן מאחריותו בגין הפרת חובת הגילוי המוגברת. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) עם זאת, התנהלות הרוכש עשויה להיזקף לחובתו כאשם תורם, אשר יפחית את שיעור הפיצויים להם הוא זכאי. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) בפסק הדין, דעת הרוב אף קבעה כי במקרים של הפרת חובת גילוי הנגזרת מחובת תום הלב הכללית (סעיף 12(א) לחוק החוזים), אין מקום להפחית את אחריות המפר בגין אשם תורם של הנפגע. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'הטעות הנפוצה היא לחשוב שרשלנות הקונה פוטרת את הקבלן מאחריות לחלוטין, או להתעלם מההבחנה בין אשם תורם לבין פטור מאחריות.',
      '["אשם תורם", "חובת גילוי מוגברת", "דירה ''על הנייר''", "הפרת חובת תום לב", "פיצויים", "חוק החוזים (חלק כללי), סעיף 12"]'::jsonb, '**וריאציה 1 — אשם תורם והפרת גילוי:** האם אשם תורם של רוכש פוטר קבלן מאחריות? ← לא, אך עשוי להפחית פיצויים. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 2 — דעת הרוב במור:** מהי עמדת דעת הרוב בעניין מור לגבי אשם תורם? ← אין להפחית פיצויים בגין אשם תורם במקרה של הפרת חובת גילוי כללית. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 3 — נטל בדיקה:** האם על רוכש דירה ''על הנייר'' מוטל נטל בדיקה? ← כן, אך הוא אינו פוטר את הקבלן מחובת הגילוי המוגברת. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)', 'אשם תורם רוכש דירה ''על הנייר'' ← אינו פוטר קבלן מאחריות ← עשוי להפחית פיצויים (בדעת מיעוט במור) ← דעת הרוב במור: אין להפחית.', '["ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(א)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שעל רוכש דירה, ובפרט דירת יוקרה, מוטל נטל בדיקה משמעותי.', false, 'טענה זו שגויה, שכן נטל הבדיקה אינו פוטר את הקבלן מאחריות במקרה של הפרת חובת גילוי מוגברת, אלא עשוי להוביל לאשם תורם.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, אך התנהלות הרוכש עשויה להיזקף לחובתו כאשם תורם ולהפחית את שיעור הפיצויים להם הוא זכאי.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי אשם תורם של הרוכש אינו פוטר את הקבלן מאחריות, אך עשוי להפחית את הפיצויים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם הקבלן פעל בתום לב סובייקטיבי ולא התכוון להטעות.', false, 'טענה זו שגויה, שכן חובת תום הלב במשא ומתן היא אובייקטיבית, ואינה תלויה בתום ליבו הסובייקטיבי של הקבלן.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, מכיוון שחובת הגילוי המוגברת של הקבלן היא מוחלטת ואינה מושפעת מהתנהלות הרוכש.', false, 'טענה זו שגויה, שכן חובת הגילוי אינה מוחלטת, והתנהלות הרוכש יכולה להשפיע על גובה הפיצויים באמצעות אשם תורם.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q31';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סעדים נוספים בגין הפרת חובת גילוי', 4,
      'קבלן הפר את חובת הגילוי המוגברת כלפי רוכש דירה ''על הנייר'' בכך שלא גילה לו על חסימת נוף. הרוכש אינו מעוניין לבטל את החוזה, אך מבקש סעד שיעמיד אותו במצב בו היה עומד אילו כרת חוזה תוך ידיעת העובדות כהווייתן. איזה סעד עשוי בית המשפט להעניק לו?', 'שאלה זו עוסקת בסעדים הניתנים בגין הפרת חובת גילוי במשא ומתן, במיוחד כאשר החוזה קוים והנפגע אינו מעוניין לבטלו. היא מתמקדת בסעד של ''שיחזור שקילות התמורות'' או ''פיצוי שיעמיד את הנפגע במקום בו היה עומד אילו כרת חוזה תוך ידיעת העובדות כהווייתן'', כפי שנקבע בפסק הדין *מור נ'' אלעד ישראל מגורים*.', 'פסק הדין בעניין *מור נ'' אלעד ישראל מגורים* (ע"א 2274/21) דן במצב שבו נפגע ממצג שווא טרום חוזי גילה על המצג רק לאחר שהחוזה נכרת, ואינו מעוניין לבטל את החוזה. במקרה כזה, הנפגע זכאי לתבוע פיצוי שיעמיד אותו במקום בו היה עומד אילו כרת חוזה תוך ידיעת העובדות כהווייתן. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) פיצוי זה יחושב על ידי קביעת ההפרש היחסי (בשברים או באחוזים) בין שווי השוק של הנכס בהתאם למצג השווא לבין שווי השוק של הנכס בהתאם לעובדות כהווייתן, נכון למועד כריתת החוזה, ולאחר מכן הפחתת ההפרש היחסי מהתמורה החוזית ששולמה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) סעד זה מכונה לעיתים ''שיחזור שקילות התמורות'' והוא נועד להביא את הנפגע למצב שבו היה אילו המשא ומתן נוהל בתום לב והוא היה מודע לכל העובדות. אביאל פלינט, חגי ויניצקי תובענות ייצוגיות (2017) | פרק ו עילות התביעה השונות', 'הטעות הנפוצה היא לחשוב שבהיעדר ביטול חוזה, הסעד היחיד הוא פיצויי הסתמכות בגין הוצאות, מבלי להכיר את הסעד הספציפי של ''שיחזור שקילות התמורות'' במקרים אלו.',
      '["סעדים", "הפרת חובת גילוי", "פיצויים", "שיחזור שקילות התמורות", "דירה ''על הנייר''", "חוק החוזים (חלק כללי), סעיף 12(ב)"]'::jsonb, '**וריאציה 1 — סעד ללא ביטול:** מהו סעד לנפגע שלא מבטל חוזה? ← פיצוי שיעמיד אותו במקום בו היה אילו כרת חוזה בידיעת העובדות. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 2 — חישוב הפיצוי:** כיצד מחושב פיצוי זה? ← הפחתת המחיר החוזי בשיעור היחס בין שווי הדירה עם/בלי הפגם. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 3 — מטרת הסעד:** מה מטרת סעד זה? ← שיחזור שקילות התמורות. אביאל פלינט, חגי ויניצקי תובענות ייצוגיות (2017) | פרק ו עילות התביעה השונות', 'הפרת גילוי, חוזה קוים ← סעד: פיצוי שיעמיד במצב של ידיעת העובדות ← חישוב יחסי של הפחתת מחיר ← שיחזור שקילות התמורות.', '["ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(ב)", "אביאל פלינט, חגי ויניצקי, תובענות ייצוגיות (2017), פרק ו עילות התביעה השונות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'פיצויי קיום מלאים, שיעמידו אותו במצב כאילו החוזה קוים במלואו ללא פגם.', false, 'טענה זו שגויה, שכן פיצויי קיום ניתנים בדרך כלל להפרת חוזה, ולא להפרת חובת גילוי טרום חוזית, אלא במקרים חריגים ביותר.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'פיצוי שיחושב על ידי הפחתת המחיר החוזי ששולם עבור הדירה, בשיעור היחס שבין שווי הדירה עם החסימה לבין שווי דירה דומה ללא חסימה, במועד כריתת החוזה.', true, 'תשובה זו נכונה, שכן זהו הסעד שנקבע בפסק הדין בעניין מור כ''שיחזור שקילות התמורות'' במקרים בהם החוזה קוים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'רק פיצויי הסתמכות בגין הוצאות שהוצאו במשא ומתן.', false, 'טענה זו שגויה, שכן במקרים של הפרת חובת גילוי, ניתן לקבל סעדים רחבים יותר מפיצויי הסתמכות בלבד, במיוחד אם החוזה קוים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'צו עשה המורה לקבלן להסיר את המבנה החוסם את הנוף.', false, 'טענה זו שגויה, שכן צו עשה כזה אינו סביר או אפשרי במקרים רבים, והוא אינו הסעד העיקרי במקרה של הפרת חובת גילוי טרום חוזית כאשר החוזה קוים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q31';
