  RAISE NOTICE 'Q% angles backfilled: external_id %', 31, '2024-W-S-Q31';
END
$$;

-- ============================================================
-- Q32 — angles backfill for 2024-W-S-Q32 (2 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q32';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q32';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תוקף חיסיון בייצוג משותף מול צד שלישי', 1,
      'עו"ד בירון ייצג במשותף את חברת "אקסילון" וחברת "קשנית" בעריכת הסכם שירותים. כעת, צד שלישי, חברת "גלובל", הגישה תביעה נגד שתי החברות ומבקשת לזמן את עו"ד בירון לעדות בקשר להסכם. חברת אקסילון מסכימה לויתור על החיסיון, אך חברת קשנית מתנגדת. האם עו"ד בירון רשאי ליתן עדות?', 'שאלה זו בוחנת את היקף חיסיון עורך דין-לקוח במקרה של ייצוג משותף, כאשר צד שלישי מבקש לחשוף מידע. היא מדגישה את ההבחנה בין ויתור על חיסיון בין הלקוחות לבין ויתור על חיסיון כלפי צד שלישי, ומבהירה כי כלפי צד שלישי נדרשת הסכמת כל הלקוחות.', 'כאשר עורך דין מייצג שני לקוחות במשותף, המידע שהוחלף ביניהם לגבי העניין המשותף אינו חסוי בפני הלקוח האחר. ע"א 442/81 אונה (רוחמה) גרומט נ'' יוסף סרוסי (03.10.1982) אולם, כלפי צד שלישי, החיסיון נשמר, ונדרשת הסכמתם של כל הלקוחות שיוצגו במשותף כדי לוותר עליו. יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון? זאת, מכיוון שהחיסיון הוא זכותו של הלקוח, וכל לקוח זכאי להגנה מפני חשיפת מידע שנמסר לעורך דינו. במקרה זה, מכיוון שחברת קשנית מתנגדת לויתור על החיסיון, עו"ד בירון אינו רשאי ליתן עדות כלפי צד שלישי, גם אם חברת אקסילון מסכימה. רע"א (מחוזי ב"ש) 72664-11-21 קיסיה אכרם נ'' וליד חמוד (27.01.2022)', 'הטעות הנפוצה היא לבלבל בין הכלל החל על יחסים פנימיים בין לקוחות משותפים לבין הכלל החל על יחסים חיצוניים מול צד שלישי, ולהניח שדי בהסכמת לקוח אחד לויתור על החיסיון גם כלפי צד שלישי.',
      '["חיסיון עורך דין-לקוח", "ייצוג משותף", "ויתור על חיסיון", "צד שלישי", "פקודת הראיות", "חוק לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — חיסיון בייצוג משותף מול צד שלישי:** האם נדרשת הסכמת כל הלקוחות לויתור על חיסיון כלפי צד שלישי? ← כן, כלפי צד שלישי נדרשת הסכמת כולם. יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון?
**וריאציה 2 — הבחנה בין יחסים:** מה ההבדל בין חיסיון בין לקוחות משותפים לחיסיון מול צד שלישי? ← בין לקוחות אין חיסיון, מול צד שלישי יש חיסיון הדורש הסכמת כולם. רע"א (מחוזי ב"ש) 72664-11-21 קיסיה אכרם נ'' וליד חמוד (27.01.2022)
**וריאציה 3 — זכות הלקוח:** מי בעל הזכות לחיסיון? ← הלקוח, ורק הוא רשאי לוותר עליו. יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון?', 'ייצוג משותף מול צד שלישי ← חיסיון חל ← דורש ויתור של כל הלקוחות. אין לבלבל עם יחסים פנימיים בין הלקוחות.', '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "ע\"א 442/81 אונה (רוחמה) גרומט נ'' יוסף סרוסי (03.10.1982)", "רע\"א (מחוזי ב\"ש) 72664-11-21 קיסיה אכרם נ'' וליד חמוד (27.01.2022)", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, ג. מיהו בעל החיסיון?"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שדי בהסכמת אחד הלקוחות לויתור על החיסיון.', false, 'טענה זו שגויה, שכן הכלל לפיו די בהסכמת אחד הלקוחות חל רק ביחסים שבין הלקוחות המשותפים, ולא כלפי צד שלישי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שנדרשת הסכמת שני הלקוחות לויתור על החיסיון כלפי צד שלישי.', true, 'תשובה זו נכונה, שכן כלפי צד שלישי, חיסיון עורך דין-לקוח נשמר, ונדרשת הסכמת כל הלקוחות שיוצגו במשותף כדי לוותר עליו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, מכיוון שהחיסיון אינו חל על עניינים שיוצגו במשותף.', false, 'טענה זו שגויה, שכן העובדה שהחיסיון אינו חל בין הלקוחות המשותפים אינה אומרת שהוא אינו חל כלפי צד שלישי.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, מכיוון שהחיסיון חל באופן מוחלט ואינו ניתן להסרה על ידי אף אחד מהלקוחות.', false, 'טענה זו שגויה, שכן הלקוח רשאי לוותר על החיסיון, אך במקרה של ייצוג משותף מול צד שלישי, נדרשת הסכמת כל הלקוחות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q32';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאי תחולת חיסיון עו"ד-לקוח', 2,
      'מהם התנאים המצטברים לקיומו של חיסיון עורך דין-לקוח, כפי שנקבעו בסעיף 48 לפקודת הראיות?', 'שאלה זו מתמקדת בתנאים המהותיים לקיומו של חיסיון עורך דין-לקוח, כפי שהם מעוגנים בסעיף 48 לפקודת הראיות. היא מפרטת את שני התנאים המצטברים: חילופי דברים ומסמכים בין עורך דין ללקוחו, וקשר ענייני לשירות המקצועי שניתן.', 'סעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע את חיסיון עורך דין-לקוח. על פי הוראה זו, קיימים שני תנאים מצטברים לקיומו של החיסיון: הראשון, כי יהיה מדובר ב"דברים ומסמכים שהוחלפו בין עורך דין לבין לקוחו או לבין אדם אחר מטעם הלקוח"; השני, כי לדברים ומסמכים הללו "יש [...] קשר עניני לשירות המקצועי שניתן על ידי עורך הדין ללקוח". סעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971 החיסיון חל על כל סוגי התקשורת, בכתב ובעל פה, ואינו מוגבל למקום מסוים. יניב ואקי דיני ראיות כרך ג (2021) | א. חיסיון על השירות המקצועי שנתן עורך דין ללקוח', 'הטעות הנפוצה היא להוסיף תנאים שאינם קבועים בחוק, כגון סוג המידע (משפטי בלבד), צורת התקשורת (בעל פה בלבד) או מקום התקשורת (במשרד עורך הדין בלבד).',
      '["חיסיון עורך דין-לקוח", "פקודת הראיות", "שירות מקצועי", "דברים ומסמכים", "קשר ענייני"]'::jsonb, '**וריאציה 1 — תנאים מצטברים:** מהם התנאים המצטברים לחיסיון עו"ד-לקוח? ← (1) חילופי דברים/מסמכים בין עו"ד ללקוח; (2) קשר ענייני לשירות המקצועי. סעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971
**וריאציה 2 — סוג תקשורת:** האם החיסיון חל רק על תקשורת כתובה? ← לא, חל על כל סוגי התקשורת (כתובה ובעל פה). יניב ואקי דיני ראיות כרך ג (2021) | א. חיסיון על השירות המקצועי שנתן עורך דין ללקוח
**וריאציה 3 — היקף שירות מקצועי:** מה כולל "שירות מקצועי"? ← ייצוג, עריכת מסמכים, ייעוץ משפטי. יניב ואקי דיני ראיות כרך ג (2021) | א. חיסיון על השירות המקצועי שנתן עורך דין ללקוח', 'חיסיון עו"ד-לקוח ← 2 תנאים מצטברים (ס'' 48 פקודת הראיות): חילופי דברים/מסמכים בין עו"ד ללקוח + קשר ענייני לשירות המקצועי (בכתב/בעל פה).', '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48(א)", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, א. חיסיון על השירות המקצועי שנתן עורך דין ללקוח"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'המידע הוחלף בין עורך דין ללקוחו, והוא נוגע לעניינים משפטיים בלבד.', false, 'טענה זו שגויה, שכן התנאי הוא ''קשר ענייני לשירות המקצועי'', שהוא רחב יותר מ''עניינים משפטיים בלבד''.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'המידע הוחלף בין עורך דין ללקוחו (או אדם מטעמו), וקיים קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח.', true, 'תשובה זו נכונה, שכן אלו הם שני התנאים המצטברים המפורטים בסעיף 48 לפקודת הראיות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המידע הוחלף בין עורך דין ללקוחו, והוא נמסר בעל פה בלבד.', false, 'טענה זו שגויה, שכן החיסיון חל על כל סוגי התקשורת, הן בכתב והן בעל פה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'המידע הוחלף בין עורך דין ללקוחו, והוא נמסר במשרד עורך הדין בלבד.', false, 'טענה זו שגויה, שכן החיסיון חל ללא קשר למקום בו הוחלף המידע, כל עוד הוא עומד בתנאים המהותיים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q32';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 32, '2024-W-S-Q32';
END
$$;

