  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q33';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q33';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הגבלת היורש הראשון ב"יורש אחר יורש"', 1,
      'מצווה קבע בצוואתו הסדר של ''יורש אחר יורש'', לפיו בנו יירש אותו, ולאחר מות הבן, נכדו יירש את הנותר. הבן, היורש הראשון, מכר את הנכס שירש מהמצווה במהלך חייו. האם הנכד, היורש השני, יוכל לטעון לזכות בנכס זה לאחר מות הבן?', 'שאלה זו בוחנת את היקף זכויותיו של היורש הראשון בהסדר של ''יורש אחר יורש'' ואת המגבלות המוטלות עליו. היא מתמקדת בעקרון ''כבתוך שלו'' המעוגן בסעיף 42(ב) לחוק הירושה, המאפשר ליורש הראשון לעשות דיספוזיציה בנכס במהלך חייו, אך לא באמצעות צוואה.', 'בהסדר של ''יורש אחר יורש'', היורש הראשון זוכה בנכסים עם מות המצווה, והוא רשאי לעשות בהם ''כבתוך שלו''. סעיף 42(ב) לחוק הירושה, תשכ"ה-1965 משמעות הדבר היא שהיורש הראשון יכול להשתמש בנכס, לכלותו, למכור אותו או להעבירו במתנה במהלך חייו. מרדכי ראבילו חוק המתנה (1997) | 11. יורש אחר יורש ומתנה היורש השני יזכה רק במה ש''שייר'' היורש הראשון, כלומר, במה שנותר מהנכסים שירש. ע"א 1182/90 דורית שחם נ'' מרים רוטמן (02.08.1992) המגבלה היחידה המוטלת על היורש הראשון מכוח החוק היא שאינו יכול לגרוע מזכותו של היורש השני על ידי צוואה משלו. סעיף 42(ב) לחוק הירושה, תשכ"ה-1965 לפיכך, אם הבן מכר את הנכס במהלך חייו, הנכד לא יוכל לטעון לזכות בו, שכן הבן פעל במסגרת סמכותו כיורש ראשון. בע"מ 1857/24 פלונית נ'' פלונית (02.12.2024)', 'הטעות הנפוצה היא לחשוב שהיורש הראשון מוגבל לחלוטין מלעשות דיספוזיציה בנכס, או לבלבל בין הגבלה על ידי צוואה לבין הגבלה על ידי פעולות בחייו.',
      '["יורש אחר יורש", "סעיף 42(ב) לחוק הירושה", "כבתוך שלו", "זכות שיורית", "דיספוזיציה בנכס", "צוואה"]'::jsonb, '**וריאציה 1 — זכות היורש הראשון:** האם היורש הראשון ב''יורש אחר יורש'' יכול למכור את הנכס? ← כן, הוא רשאי לעשות בו ''כבתוך שלו''. סעיף 42(ב) לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — זכות היורש השני:** מה יקבל היורש השני? ← רק את מה ששייר היורש הראשון. סעיף 42(ב) לחוק הירושה, תשכ"ה-1965
**וריאציה 3 — מגבלת צוואה:** האם היורש הראשון יכול לגרוע מזכות היורש השני בצוואה? ← לא, זו המגבלה היחידה בחוק. סעיף 42(ב) לחוק הירושה, תשכ"ה-1965', 'יורש אחר יורש ← יורש ראשון רשאי לעשות בנכס ''כבתוך שלו'' (למכור/לתת) ← יורש שני יזכה רק במה ששייר ← היורש הראשון אינו יכול לגרוע בצוואה.', '["חוק הירושה, תשכ\"ה-1965, סעיף 42(ב)", "ע\"א 1182/90 דורית שחם נ'' מרים רוטמן (02.08.1992)", "בע\"מ 1857/24 פלונית נ'' פלונית (02.12.2024)", "מרדכי ראבילו, חוק המתנה (1997), 11. יורש אחר יורש ומתנה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שהיורש הראשון אינו רשאי לגרוע מזכותו של היורש השני.', false, 'טענה זו שגויה, שכן היורש הראשון רשאי לעשות בנכס ''כבתוך שלו'' במהלך חייו, למעט גריעה באמצעות צוואה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שהיורש הראשון רשאי לעשות במה שקיבל ''כבתוך שלו'', והיורש השני יזכה רק במה ששייר הראשון.', true, 'תשובה זו נכונה, שכן סעיף 42(ב) לחוק הירושה קובע כי היורש הראשון רשאי לעשות בנכס כבתוך שלו, והיורש השני יזכה רק במה ששייר הראשון.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם המצווה קבע במפורש בצוואה שהיורש הראשון אינו רשאי למכור את הנכס.', false, 'טענה זו נכונה עקרונית, אך השאלה מתייחסת למצב בו לא נקבעה הגבלה מפורשת בצוואה, אלא להוראת החוק הכללית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הנכד יוכיח שהמכירה נעשתה בחוסר תום לב על ידי הבן.', false, 'טענה זו שגויה, שכן עקרון תום הלב עשוי להטיל חובה מוסרית, אך אינו מבטל את זכותו של היורש הראשון לעשות בנכס כבתוך שלו, אלא במקרים חריגים ביותר.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q33';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'ההבחנה בין "יורש אחר יורש" ל"יורש במקום יורש"', 2,
      'מהו ההבדל המהותי בין הסדר של ''יורש אחר יורש'' (סעיף 42 לחוק הירושה) לבין הסדר של ''יורש במקום יורש'' (סעיף 41 לחוק הירושה)?', 'שאלה זו עוסקת בהבחנה המהותית בין שני הסדרי הורשה מרכזיים בחוק הירושה: ''יורש אחר יורש'' (סעיף 42) ו''יורש במקום יורש'' (סעיף 41). היא מדגישה את ההבדל במועד הזכייה של היורש השני ואת קיומה או אי-קיומה של ''תקופת ביניים'' בה היורש הראשון הוא הבעלים.', 'ההבדל המהותי בין הסדר של ''יורש אחר יורש'' (סעיף 42 לחוק הירושה) לבין הסדר של ''יורש במקום יורש'' (סעיף 41 לחוק הירושה) טמון במועד הזכייה של היורש השני. ע"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)
ב''יורש אחר יורש'', המצווה קובע שהיורש הראשון יירש אותו, ולאחר מות היורש הראשון (או בהתקיים תנאי אחר), היורש השני יירש את מה ששייר הראשון. סעיף 42(א) לחוק הירושה, תשכ"ה-1965 ישנה ''תקופת ביניים'' בה היורש הראשון הוא הבעלים של הרכוש. ע"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)
לעומת זאת, ב''יורש במקום יורש'', המצווה קובע שהיורש הראשון יירש אותו, אך אם היורש הראשון לא יזכה (למשל, אם ימות לפני המצווה, יימצא פסול לרשת או יסתלק מהירושה), אזי היורש השני יבוא במקומו. סעיף 41(א) לחוק הירושה, תשכ"ה-1965 במקרה זה, אין ''תקופת ביניים'' שכן היורש השני זוכה רק אם היורש הראשון לא זכה כלל. אם היורש הראשון זוכה, ההסדר מוצה והיורש השני אינו מקבל דבר. ע"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)', 'הטעות הנפוצה היא לבלבל בין שני ההסדרים, במיוחד בכל הנוגע למועד הזכייה של היורש השני וליכולת היורש הראשון לעשות דיספוזיציה בנכסים.',
      '["יורש אחר יורש", "יורש במקום יורש", "סעיף 41 לחוק הירושה", "סעיף 42 לחוק הירושה", "תקופת ביניים", "זכייה בירושה"]'::jsonb, '**וריאציה 1 — מועד זכייה:** מתי זוכה היורש השני ב''יורש אחר יורש'' לעומת ''יורש במקום יורש''? ← ב''יורש אחר יורש'' – לאחר שהראשון זכה ונפטר; ב''יורש במקום יורש'' – רק אם הראשון לא זכה כלל. ע"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)
**וריאציה 2 — תקופת ביניים:** האם קיימת ''תקופת ביניים'' בשני ההסדרים? ← רק ב''יורש אחר יורש'' היורש הראשון הוא הבעלים בתקופת ביניים. ע"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)
**וריאציה 3 — מספר יורשים:** האם יש הגבלה על מספר היורשים בשני ההסדרים? ← ב''יורש אחר יורש'' מוגבל לשניים (למעט חריג); ב''יורש במקום יורש'' אין הגבלה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965 סעיף 41(ג) לחוק הירושה, תשכ"ה-1965', 'יורש אחר יורש ← הראשון זוכה, השני אחריו, תקופת ביניים, מוגבל לשניים. יורש במקום יורש ← השני זוכה אם הראשון לא זכה, אין תקופת ביניים, אין הגבלה במספר.', '["חוק הירושה, תשכ\"ה-1965, סעיף 41", "חוק הירושה, תשכ\"ה-1965, סעיף 42", "ע\"א 4402/98 יצחק מלמד נ'' אשכנזי סולומון (17.11.1999)", "בע\"מ 10807/03 אליקום זמיר נ'' רות גמליאל (04.02.2007)", "ת\"ע (משפחה תל אביב-יפו) 8339-02-19 מ.ד נ'' מ.א (16.07.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'ב''יורש אחר יורש'' היורש הראשון אינו זוכה כלל, ואילו ב''יורש במקום יורש'' היורש הראשון זוכה בנכסים.', false, 'טענה זו שגויה, שכן ב''יורש אחר יורש'' היורש הראשון דווקא זוכה בנכסים, ואילו ב''יורש במקום יורש'' היורש השני זוכה רק אם הראשון לא זכה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'ב''יורש אחר יורש'' היורש השני זוכה לאחר שהיורש הראשון זכה ונפטר, ואילו ב''יורש במקום יורש'' היורש השני זוכה רק אם היורש הראשון לא זכה כלל.', true, 'תשובה זו נכונה, שכן זהו ההבדל המהותי בין שני ההסדרים: ב''יורש אחר יורש'' יש תקופת ביניים בה היורש הראשון הוא הבעלים, ואילו ב''יורש במקום יורש'' אין תקופת ביניים כזו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'ב''יורש אחר יורש'' אין הגבלה על מספר היורשים, ואילו ב''יורש במקום יורש'' יש הגבלה לשני יורשים בלבד.', false, 'טענה זו שגויה, שכן ההגבלה לשני יורשים חלה על ''יורש אחר יורש'' (למעט חריגים), ואילו ב''יורש במקום יורש'' אין הגבלה כזו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'ב''יורש אחר יורש'' היורש הראשון אינו יכול לעשות דיספוזיציה בנכסים, ואילו ב''יורש במקום יורש'' הוא יכול לעשות כרצונו.', false, 'טענה זו שגויה, שכן ב''יורש אחר יורש'' היורש הראשון רשאי לעשות דיספוזיציה בנכסים במהלך חייו (למעט בצוואה), ואילו ב''יורש במקום יורש'' אם היורש הראשון זוכה, ההסדר מוצה והוא יכול לעשות בנכס כרצונו ללא הגבלה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q33';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריג למגבלת שני יורשים ב"יורש אחר יורש"', 3,
      'אריה, המצווה, קבע בצוואתו הסדר של ''יורש אחר יורש'' כדלקמן: בנו יירש אותו, לאחר מות הבן יירש נכדו הבכור, ולאחר מות הנכד הבכור תירש נכדתו. בעת עריכת הצוואה, בנו, נכדו הבכור ונכדתו היו כולם בחיים. האם הוראה זו כשרה?', 'שאלה זו בוחנת את החריג לכלל המגביל את הסדר ''יורש אחר יורש'' לשני יורשים בלבד, כפי שנקבע בסעיף 42(ד) לחוק הירושה. היא מדגישה את חשיבות העובדה שכל היורשים הנוספים היו בחיים בעת עריכת הצוואה כתנאי לתוקף שרשרת יורשים ארוכה יותר.', 'הכלל הקבוע בסעיף 42(ד) לחוק הירושה, תשכ"ה-1965, קובע כי הוראת צוואה על דרך ''יורש אחר יורש'' ליותר משני יורשים – בטלה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965 מגבלה זו נועדה להגביל את ''שלטון המת על החי'' ולאפשר דינמיות בהעברת נכסים. רע"א 3130/05 יורשי המנוחה א. ר. ז"ל נ'' האפוטרופוס הכללי כמנהל עזבון המנוחה מ. ר. ז"ל (14.09.2006)
עם זאת, סעיף 42(ד) קובע חריג לכלל זה: הוראה כזו תהיה כשרה אם היא לטובתו של מי שהיה בחיים בשעת עשיית הצוואה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965 במקרה הנדון, מכיוון שהבן, הנכד הבכור והנכדה היו כולם בחיים בעת עריכת הצוואה, החריג חל, והוראת הצוואה כשרה למרות שהיא קובעת שרשרת של שלושה יורשים. נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | יורש אחר יורש', 'הטעות הנפוצה היא להתעלם מהחריג הקבוע בסעיף 42(ד) לחוק הירושה, ולחשוב שההגבלה לשני יורשים היא מוחלטת בכל מקרה.',
      '["יורש אחר יורש", "סעיף 42(ד) לחוק הירושה", "שלטון המת על החי", "חריג לכלל", "כשרות צוואה", "מועד עריכת צוואה"]'::jsonb, '**וריאציה 1 — מגבלת יורש אחר יורש:** כמה יורשים ניתן לקבוע ב''יורש אחר יורש''? ← שניים, אלא אם חל החריג. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — תנאי לחריג:** מהו התנאי לחריג המאפשר יותר משני יורשים? ← שכל היורשים הנוספים היו בחיים בעת עשיית הצוואה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965
**וריאציה 3 — תכלית המגבלה:** מהי תכלית המגבלה על מספר היורשים? ← להגביל את ''שלטון המת על החי''. רע"א 3130/05 יורשי המנוחה א. ר. ז"ל נ'' האפוטרופוס הכללי כמנהל עזבון המנוחה מ. ר. ז"ל (14.09.2006)', 'יורש אחר יורש מוגבל לשניים ← חריג: אם כל היורשים הנוספים היו בחיים בעת עשיית הצוואה ← אז כשרה. (ס'' 42(ד) לחוק הירושה).', '["חוק הירושה, תשכ\"ה-1965, סעיף 42(ד)", "רע\"א 3130/05 יורשי המנוחה א. ר. ז\"ל נ'' האפוטרופוס הכללי כמנהל עזבון המנוחה מ. ר. ז\"ל (14.09.2006)", "נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026), יורש אחר יורש", "שמואל שילה, פירוש לחוק הירושה כרך א (1995), סעיף 42: יורש אחר יורש, ז. הורשה לשלישי או יותר"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לא, מכיוון שהסדר ''יורש אחר יורש'' מוגבל לשני יורשים בלבד, ללא יוצא מן הכלל.', false, 'טענה זו שגויה, שכן קיים חריג לכלל המגביל את מספר היורשים לשניים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'כן, מכיוון שההגבלה לשני יורשים אינה חלה אם כל היורשים הנוספים היו בחיים בשעת עשיית הצוואה.', true, 'תשובה זו נכונה, שכן סעיף 42(ד) לחוק הירושה קובע חריג לכלל המגביל את מספר היורשים לשניים, והוא חל כאשר כל היורשים הנוספים היו בחיים בעת עשיית הצוואה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, מכיוון שהנכדים אינם יורשים ישירים של המצווה, אלא של הבן.', false, 'טענה זו שגויה, שכן ב''יורש אחר יורש'' היורש השני (והלאה, בחריג) נחשב כיורש ישיר של המוריש המקורי, ולא של היורש הראשון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אך רק אם המצווה קבע זאת במפורש בצוואתו כהוראה קוגנטית.', false, 'טענה זו שגויה, שכן החריג קבוע בחוק ואינו דורש קביעה קוגנטית נוספת בצוואה, והוראת סעיף 42(ד) עצמה היא קוגנטית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q33';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'עקיפת מגבלת "יורש אחר יורש" באמצעות תאגיד', 4,
      'אריה, המצווה, מעוניין להבטיח שרכושו יועבר לבנו, לאחר מכן לנכדו, ולאחר מכן לנינו, גם אם הנכד והנין טרם נולדו בעת עריכת הצוואה. איזו דרך פעולה עשויה לאפשר לו להגשים את רצונו מבלי שהוראת הצוואה תיפסל לפי סעיף 42(ד) לחוק הירושה?', 'שאלה זו בוחנת דרכים יצירתיות לעקיפת מגבלות חוק הירושה, ובפרט את מגבלת שני היורשים בהסדר ''יורש אחר יורש''. היא מתמקדת באפשרות של הורשה לתאגיד, אשר נחשב כיורש אחד, ובכך מאפשר למצווה לשלוט על גורל רכושו למשך דורות רבים באמצעות הוראות בתקנון התאגיד.', 'סעיף 42(ד) לחוק הירושה, תשכ"ה-1965, מגביל את הסדר ''יורש אחר יורש'' לשני יורשים בלבד, אלא אם כן היורשים הנוספים היו בחיים בעת עשיית הצוואה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965 מגבלה זו נועדה למנוע ''שלטון מתים'' ממושך על נכסים. בר"ע 108/75 גד גרייבר נ'' נעמי, רחל חוה, ראם ו-הרן גרייבר, קטינים (13.07.1975)
דרך אחת לעקוף מגבלה זו, כפי שנדונה בפסיקה ובספרות, היא באמצעות הורשה לתאגיד. כאשר המצווה מוריש את רכושו לתאגיד (כגון חברה או עמותה), התאגיד נחשב כיורש אחד בלבד. שמואל שילה פירוש לחוק הירושה כרך א (1995) | 1. הורשה לתאגיד המצווה יכול לקבוע בתקנון התאגיד הוראות מפורטות לגבי אופן ניהול הרכוש והעברתו לדורות הבאים, ובכך להגשים את רצונו לשלוט על גורל רכושו למשך זמן ארוך יותר, מבלי שהוראת הצוואה תיפסל. שמואל שילה פירוש לחוק הירושה כרך א (1995) | 1. הורשה לתאגיד', 'הטעות הנפוצה היא לחשוב שאין כל דרך חוקית לעקוף את מגבלת שני היורשים ב''יורש אחר יורש'', או לבלבל בין הורשה לאנשים פרטיים לבין הורשה לישות משפטית נפרדת.',
      '["יורש אחר יורש", "סעיף 42(ד) לחוק הירושה", "הורשה לתאגיד", "שלטון המת על החי", "תקנון תאגיד", "עקיפת חוק"]'::jsonb, '**וריאציה 1 — מגבלת יורש אחר יורש:** האם ניתן לצוות ליותר משני יורשים ב''יורש אחר יורש'' אם הם לא בחיים? ← לא, הוראה כזו בטלה. סעיף 42(ד) לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — הורשה לתאגיד:** האם הורשה לתאגיד כפופה למגבלת סעיף 42(ד)? ← לא, התאגיד נחשב כיורש אחד. שמואל שילה פירוש לחוק הירושה כרך א (1995) | 1. הורשה לתאגיד
**וריאציה 3 — תכלית העקיפה:** מה מאפשרת עקיפה זו? ← שליטה על הרכוש למשך דורות רבים באמצעות הוראות התאגיד. שמואל שילה פירוש לחוק הירושה כרך א (1995) | 1. הורשה לתאגיד', 'עקיפת מגבלת ''יורש אחר יורש'' ← הורשה לתאגיד ← התאגיד יורש אחד ← הוראות בתקנון התאגיד שולטות על העברת הרכוש לדורות הבאים.', '["חוק הירושה, תשכ\"ה-1965, סעיף 42(ד)", "שמואל שילה, פירוש לחוק הירושה כרך א (1995), סעיף 42: יורש אחר יורש, 1. הורשה לתאגיד", "בר\"ע 108/75 גד גרייבר נ'' נעמי, רחל חוה, ראם ו-הרן גרייבר, קטינים (13.07.1975)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לצוות את הרכוש לבנו, ולכלול בצוואה הוראה מפורשת שהבן חייב להוריש את הרכוש לנכד, ולאחר מכן הנין.', false, 'טענה זו שגויה, שכן הוראה כזו תהווה ניסיון להגביל את היורש הראשון באמצעות צוואה, דבר שאסור לפי סעיף 42(ב) לחוק הירושה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'להקים תאגיד (כגון חברה או עמותה) ולצוות את כל רכושו לתאגיד זה, תוך קביעת הוראות בתקנון התאגיד לגבי אופן ניהול הרכוש והעברתו לדורות הבאים.', true, 'תשובה זו נכונה, שכן הורשה לתאגיד נחשבת כיורש אחד, והוראות התאגיד לגבי העברת הנכסים אינן כפופות למגבלות סעיף 42 לחוק הירושה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לצוות את הרכוש לבנו, ולכלול בצוואה תנאי מפסיק לפיו אם הבן לא יוריש את הרכוש לנכד, יבוטל חלקו בירושה.', false, 'טענה זו שגויה, שכן תנאי כזה עשוי להיחשב כהגבלה בלתי לגיטימית על חופש הציווי של היורש הראשון, או כניסיון לעקוף את סעיף 42(ב).', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לצוות את הרכוש לבנו, ולכלול בצוואה הוראה לפיה הנכד והנין יירשו את הרכוש כ''יורש במקום יורש'' זה אחר זה.', false, 'טענה זו שגויה, שכן ''יורש במקום יורש'' חל רק אם היורש הקודם לא זכה כלל, ולא במקרה של העברה מדור לדור לאחר זכייה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q33';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 33, '2024-W-S-Q33';
END
$$;

