  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q34';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q34';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'השעיית חיוב בחיובים מותנים', 1,
      'ראובן, צבעי, התחייב לצבוע את מכוניתו של שמעון. בהסכם נקבע כי שמעון יספק את הצבעים לראובן ביום 1.6.2024, וראובן יצבע את המכונית ביום 5.6.2024. שמעון לא סיפק את הצבעים במועד. האם ראובן חייב לצבוע את המכונית ביום 5.6.2024?', 'שאלה זו עוסקת בסיווג חיובים חוזיים כ''חיובים מותנים'' ובנפקות סיווג זה. היא בוחנת את הכלל הקבוע בסעיף 43(א)(2) לחוק החוזים (חלק כללי), לפיו כאשר קיום חיובו של צד אחד מותנה בקיום חיובו של הצד השני תחילה, מועד קיום החיוב המותנה נדחה עד לקיום התנאי.', 'חיובים מותנים הם חיובים נגדיים שנקבעו למועדים עוקבים שונים, כך שקיום חיוב אחד מותנה בכך שיקויים תחילה החיוב הנגדי. ת"א (שלום חי'') 13110-06-19 יותם גור נ'' אברהם ברקוביץ (18.04.2022) סעיף 43(א)(2) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי במצב כזה, המועד לקיומו של החיוב המותנה נדחה עד שקויים החיוב המהווה תנאי. סעיף 43(א)(2) לחוק החוזים (חלק כללי), תשל"ג-1973 במקרה הנדון, חיובו של ראובן לצבוע את המכונית מותנה בכך ששמעון יספק לו תחילה את הצבעים. מכיוון ששמעון לא קיים את חיובו המוקדם, חיובו של ראובן נדחה, והוא אינו חייב לצבוע את המכונית במועד שנקבע. ע"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)', 'הטעות הנפוצה היא לבלבל בין חיובים מותנים לחיובים עצמאיים, ולחשוב שאי-קיום חיוב מוקדם אינו משפיע על חובת הקיום של החיוב המאוחר.',
      '["חיובים מותנים", "דחיית קיום", "סעיף 43(א)(2) לחוק החוזים", "תנאי מוקדם", "הפרת חוזה"]'::jsonb, '**וריאציה 1 — הגדרת חיוב מותנה:** מהו חיוב מותנה? ← חיוב שקיומו תלוי בקיום חיוב קודם של הצד השני. ע"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)
**וריאציה 2 — נפקות אי-קיום תנאי:** מה קורה אם התנאי המוקדם לא מתקיים? ← החיוב המותנה נדחה. סעיף 43(א)(2) לחוק החוזים (חלק כללי), תשל"ג-1973
**וריאציה 3 — דוגמה לחיוב מותנה:** חיוב קבלן לעלות על הקרקע? ← מותנה בהעמדת הקרקע לרשותו על ידי המזמין. ע"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)', 'חיוב מותנה ← קיומו נדחה אם התנאי המוקדם לא קוים (ס'' 43(א)(2) לחוק החוזים).', '["חוק החuזים (חלק כללי), תשל\"ג-1973, סעיף 43(א)(2)", "ע\"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)", "ע\"א 765/82 משה אלתר נ'' יחזקאל אלעני (21.06.1984)", "ת\"א (שלום חי'') 13110-06-19 יותם גור נ'' אברהם ברקוביץ (18.04.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שחיובו של ראובן הוא עצמאי ואינו תלוי בחיובו של שמעון.', false, 'טענה זו שגויה, שכן חיובו של ראובן לצבוע את המכונית מותנה בקיום חיובו של שמעון לספק את הצבעים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שחיובו של ראובן מותנה בכך ששמעון יקיים תחילה את חיובו לספק את הצבעים, ולכן מועד קיום חיובו של ראובן נדחה.', true, 'תשובה זו נכונה, שכן זהו המאפיין של חיובים מותנים, כפי שקבוע בסעיף 43(א)(2) לחוק החוזים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך ראובן זכאי לפיצויים משמעון בגין האיחור באספקת הצבעים.', false, 'טענה זו שגויה, שכן ראובן אינו חייב לקיים את חיובו כלל כל עוד התנאי המוקדם לא קוים, וזכאות לפיצויים היא סעד נפרד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אך ראובן חייב להודיע לשמעון על דחיית הקיום זמן סביר מראש.', false, 'טענה זו שגויה, שכן דחיית הקיום בחיובים מותנים היא אוטומטית ואינה דורשת הודעה מוקדמת.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q34';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחני סיווג חיובים חוזיים', 2,
      'מהו המבחן העיקרי לסיווג חיובים חוזיים כעצמאיים, מותנים או שלובים?', 'שאלה זו מתמקדת במבחנים המשפטיים לסיווג חיובים חוזיים. היא מדגישה כי סיווג זה הוא שאלה פרשנית, הנעשית על פי כללי הפרשנות המקובלים של חוזים, תוך בחינת לשון החוזה ותכליתו, וכי יש לנקוט זהירות כאשר לשון החוזה אינה תומכת במפורש בסיווג מסוים.', 'השאלה האם חיובים חוזיים מסוימים הם בגדר חיובים עצמאיים, מותנים או שלובים היא שאלה פרשנית, הטעונה הכרעה על פי כללי הפרשנות הרגילים. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024) נקודת המוצא לפרשנות היא לשון החוזה בכללותו, על הוראותיו השונות וההסדרים הקבועים בו. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024) הפסיקה קבעה כי יש לנקוט משנה זהירות כאשר לשון החוזה אינה תומכת בפרשנות לפיה חיוב מסוים הוא חיוב מותנה או שלוב. סעיף 43 לחוק החוזים (חלק כללי), תשל"ג-1973 ע"א 1258/14 מ. מגן אינטרנשיונל יזמות והשקעות בע"מ נ'' עירית רמת גן (03.09.2015)', 'הטעות הנפוצה היא להניח סיווג מסוים של חיובים מבלי לבחון לעומק את לשון החוזה ותכליתו, או לבלבל בין ברירת המחדל החוקית (כמו סעיף 23 לחוק המכר) לבין האפשרות להתנות עליה.',
      '["פרשנות חוזה", "לשון החוזה", "תכלית החוזה", "חיובים עצמאיים", "חיובים מותנים", "חיובים שלובים"]'::jsonb, '**וריאציה 1 — כללי פרשנות:** כיצד מסווגים חיובים חוזיים? ← על פי כללי פרשנות החוזה, לשונו ותכליתו. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024)
**וריאציה 2 — זהירות בסיווג:** מתי יש לנקוט זהירות בסיווג חיובים כמותנים/שלובים? ← כשלשון החוזה אינה תומכת בכך במפורש. ע"א 1258/14 מ. מגן אינטרנשיונל יזמות והשקעות בע"מ נ'' עירית רמת גן (03.09.2015)
**וריאציה 3 — נקודת מוצא לפרשנות:** מהי נקודת המוצא לפרשנות? ← לשון החוזה בכללותו. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024)', 'סיווג חיובים חוזיים ← פרשנות לשון ותכלית החוזה ← זהירות בהיעדר תמיכה מפורשת בלשון.', '["ע\"א 8316/21 אדלטק אחזקות (2006) בע\"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע\"מ (14.08.2024)", "ע\"א 1258/14 מ. מגן אינטרנשיונל יזמות והשקעות בע\"מ נ'' עירית רמת גן (03.09.2015)", "ע\"א 765/82 משה אלתר נ'' יחזקאל אלעני (21.06.1984)", "גבריאלה שלו ואפי צמח, דיני חוזים (2019), פרק 18 חיובים בחוזה הדדי"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הסיווג נקבע באופן אובייקטיבי על פי סוג החוזה (לדוגמה, חוזה מכר תמיד יכלול חיובים שלובים).', false, 'טענה זו שגויה, שכן הסיווג הוא פרשני ואינו נקבע באופן אוטומטי לפי סוג החוזה, אלא לפי אומד דעת הצדדים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הסיווג נקבע על פי כללי פרשנות החוזה, תוך בחינת לשונו ותכליתו, ובזהירות כאשר לשון החוזה אינה תומכת במפורש בסיווג מסוים.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי סיווג החיובים הוא שאלה פרשנית של החוזה, תוך דגש על לשונו ותכליתו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הסיווג נקבע על פי ברירת המחדל הקבועה בסעיף 43 לחוק החוזים, ללא אפשרות להתנות עליה.', false, 'טענה זו שגויה, שכן סעיף 43 קובע את דין דחיית הקיום, אך הסיווג עצמו הוא פרשני, וניתן להתנות על ברירות המחדל.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הסיווג נקבע על פי מידת הנזק שייגרם לצד הנפגע אם החיוב לא יקוים.', false, 'טענה זו שגויה, שכן מידת הנזק רלוונטית לסעדים, אך לא לסיווג הראשוני של החיובים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q34';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'נכונות לקיים חיוב שלוב', 3,
      'יאיר ודורון קבעו בהסכם כי מסירת הרכב ותשלום יתרת התמורה הם חיובים שלובים. יאיר לא מסר את הרכב במועד. דורון, מצידו, הודיע ליאיר בכתב כי הוא ''מוכן ומזומן'' לשלם את יתרת התמורה, אך לא הפקיד את הכסף בחשבון נאמנות או הראה יכולת ממשית לתשלום. האם הודעתו של דורון מספיקה כדי להיחשב כ''נכונות לקיים'' את חיובו?', 'שאלה זו בוחנת את דרישת ''הנכונות לקיים'' חיוב שלוב, כפי שנקבעה בפסיקה. היא מדגישה כי נכונות זו אינה מסתכמת בהצהרה בעלמא, אלא דורשת ביטויים חיצוניים המעידים על רצון ויכולת בפועל לקיים את החיוב, וזאת על מנת למנוע ''מעגל שוטה'' בחיובים הדדיים.', 'בחיובים שלובים, כאשר לא ניתן לקיים את החיובים בד בבד, די בכך שצד לחוזה הראה נכונות חד משמעית לקיים את החיוב על מנת שיוכל לתבוע את קיום החוזה על ידי הצד שכנגד. ע"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011) הנכונות לקיומו של חיוב שלוב נבחנת לפי ביטויים חיצוניים, כאשר נדרשים רצון ויכולת בפועל לקיום החיוב. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024) אמירות בעלמא אינן מספיקות, ונדרשת נכונות מעשית, כגון הפקדת כספים בקופת בית המשפט. ת"א (שלום ירושלים) 20359/97 עוזי יושיע נ'' דוד שורקה (21.08.2002) במקרה זה, הודעתו של דורון כי הוא ''מוכן ומזומן'' לשלם, ללא ביטוי חיצוני של יכולת ממשית, אינה מספיקה כדי להיחשב כ''נכונות לקיים'' את חיובו. דניאל פרידמן, נילי כהן חוזים - כרך ג (2003) | הקדמה', 'הטעות הנפוצה היא לחשוב שהצהרה בעלמא על נכונות לקיים חיוב שלוב מספיקה, מבלי להבין את הדרישה לביטויים חיצוניים וליכולת ממשית לקיום.',
      '["חיובים שלובים", "נכונות לקיים", "סעיף 43(א)(3) לחוק החוזים", "מעגל שוטה", "ביטויים חיצוניים", "הפקדת כספים"]'::jsonb, '**וריאציה 1 — נכונות מעשית:** מהי נכונות לקיים חיוב שלוב? ← ביטויים חיצוניים, רצון ויכולת בפועל. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024)
**וריאציה 2 — אמירה בעלמא:** האם אמירה ''מוכן ומזומן'' מספיקה? ← לא, נדרשת נכונות מעשית, כגון הפקדת כספים. ת"א (שלום ירושלים) 20359/97 עוזי יושיע נ'' דוד שורקה (21.08.2002)
**וריאציה 3 — מטרת הדרישה:** מדוע נדרשת נכונות מעשית? ← למנוע ''מעגל שוטה'' בחיובים הדדיים. דניאל פרידמן, נילי כהן חוזים - כרך ג (2003) | הקדמה', 'נכונות לקיים חיוב שלוב ← ביטויים חיצוניים + רצון ויכולת בפועל (לא רק אמירה) ← למנוע מעגל שוטה.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 43(א)(3)", "ע\"א 8316/21 אדלטק אחזקות (2006) בע\"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע\"מ (14.08.2024)", "ע\"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)", "ת\"א (שלום ירושלים) 20359/97 עוזי יושיע נ'' דוד שורקה (21.08.2002)", "דניאל פרידמן, נילי כהן, חוזים - כרך ג (2003), הקדמה"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, די בהודעה בכתב המעידה על רצון לקיים את החיוב.', false, 'טענה זו שגויה, שכן נכונות לקיים חיוב שלוב דורשת ביטויים חיצוניים המעידים על רצון ויכולת בפועל, ולא רק אמירה בעלמא.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, נכונות לקיים חיוב שלוב דורשת ביטויים חיצוניים המעידים על רצון ויכולת בפועל לקיום החיוב, ולא רק אמירה בעלמא.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי נכונות לקיים חיוב שלוב צריכה להיות מעשית ומוכחת, ולא רק הצהרתית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אלא אם יאיר יוכיח שדורון לא היה מסוגל לשלם בפועל.', false, 'טענה זו שגויה, שכן הנטל להראות נכונות לקיים מוטל על דורון, והיא כוללת גם את היכולת בפועל.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן דורון היה מודע לכך שיאיר לא ימסור את הרכב.', false, 'טענה זו שגויה, שכן נכונות לקיים אינה תלויה בידיעה על הפרה צפויה, אלא ביכולת ורצון לקיים את החיוב הנגדי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q34';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סעדים במקרה של הפרת חיוב שלוב', 4,
      'יאיר ודורון קבעו בהסכם כי מסירת הרכב ותשלום יתרת התמורה הם חיובים שלובים. יאיר לא מסר את הרכב במועד. דורון, שמוכן לקיים את חיובו, מעוניין לתבוע את יאיר. אילו סעדים עומדים לרשות דורון?', 'שאלה זו עוסקת בסעדים העומדים לרשות צד לחוזה שהופר חיוב שלוב כלפיו. היא מדגישה כי דחיית קיום (השעיית חיוב) היא סעד עצמי המונע מהצד הנפגע להיחשב כמפר, אך אינה שוללת את זכותו לתבוע את מגוון הסעדים הקבועים בחוק החוזים (תרופות בשל הפרת חוזה), כגון אכיפה, ביטול ופיצויים.', 'הפרה של חיוב שלוב אינה מביאה לביטולו או לפקיעתו של החיוב שכנגד. היא מקנה בידי הצד הנפגע את התרופות הנתונות לכל נפגע מהפרת חוזה כגון ביטול, אכיפה ופיצויים. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024) בנוסף לסעדים אלו, עומד לרשות הצד הנפגע גם הסעד העצמי של דחיית קיום חיובו שלו, כל עוד הצד שכנגד אינו מוכן לקיים את החיוב המוטל עליו, וזאת מכוח סעיף 43(א)(3) לחוק החוזים. סעיף 43(א)(3) לחוק החוזים (חלק כללי), תשל"ג-1973 סעד זה נועד למנוע מצב של ''מעגל שוטה'' ולאפשר לצד הנפגע להגן על עצמו מבלי להיחשב כמפר. ע"א 7938/08 היאלי מונסנגו נ'' מוריס מכביאן (11.08.2011)', 'הטעות הנפוצה היא לחשוב שדחיית קיום היא הסעד היחיד במקרה של הפרת חיוב שלוב, או שהיא מבטלת את החוזה באופן אוטומטי.',
      '["הפרת חוזה", "חיובים שלובים", "סעדים", "אכיפה", "ביטול חוזה", "פיצויים", "דחיית קיום", "סעד עצמי"]'::jsonb, '**וריאציה 1 — סעדים להפרת חיוב שלוב:** אילו סעדים עומדים לנפגע מהפרת חיוב שלוב? ← אכיפה, ביטול ופיצויים. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024)
**וריאציה 2 — דחיית קיום:** האם דחיית קיום היא סעד נוסף? ← כן, סעד עצמי המונע מהנפגע להיחשב כמפר. סעיף 43(א)(3) לחוק החוזים (חלק כללי), תשל"ג-1973
**וריאציה 3 — ביטול חלקי:** האם ניתן לבטל חוזה באופן חלקי במקרה של הפרת חיוב שלוב? ← רק אם החוזה ניתן להפרדה לחלקים ועילת הביטול מתייחסת רק לאחד מהם. ע"א 8316/21 אדלטק אחזקות (2006) בע"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע"מ (14.08.2024)', 'הפרת חיוב שלוב ← סעדים: אכיפה, ביטול, פיצויים + דחיית קיום (סעד עצמי). ביטול חלקי רק אם החוזה ניתן להפרדה.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 43", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 7", "ע\"א 8316/21 אדלטק אחזקות (2006) בע\"מ נ'' קבוצת עמוס לוזון יזמות ואנרגיה בע\"מ (14.08.2024)", "ע\"א 765/82 משה אלתר נ'' יחזקאל אלעני (21.06.1984)", "ד\"נ 20/82 אדרס חמרי בנין בע\"מ נ'' הרלו אנד גונ''ס ג.מ.ב.ה. (11.02.1988)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'דורון רשאי רק לדחות את תשלום יתרת התמורה, ואינו יכול לתבוע סעדים נוספים כל עוד החוזה לא בוטל.', false, 'טענה זו שגויה, שכן דחיית קיום היא סעד עצמי, אך אינה שוללת את הזכות לתבוע סעדים נוספים בגין הפרת חוזה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'דורון רשאי לתבוע אכיפה, ביטול ופיצויים, בנוסף לזכותו לדחות את קיום חיובו שלו.', true, 'תשובה זו נכונה, שכן הפרת חיוב שלוב מקנה לנפגע את כל התרופות הקבועות בחוק החוזים (תרופות), בנוסף לזכות לדחות את קיום חיובו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'דורון רשאי לתבוע רק פיצויים בגין הנזק שנגרם לו עקב האיחור במסירה, אך אינו יכול לדרוש אכיפה או ביטול.', false, 'טענה זו שגויה, שכן פיצויים הם רק אחד מהסעדים, ודורון זכאי גם לאכיפה או ביטול, בהתאם לנסיבות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'דורון רשאי לבטל את החוזה באופן חלקי, ולדרוש השבה של המקדמה ששילם.', false, 'טענה זו שגויה, שכן ביטול חלקי אפשרי רק אם החוזה ניתן להפרדה לחלקים, ודורון זכאי להשבה מלאה של המקדמה במקרה של ביטול מלא.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q34';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 34, '2024-W-S-Q34';
END
$$;

-- ============================================================
-- Q35 — angles backfill for 2024-W-S-Q35 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q35';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q35';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הוצאות עבר ועתיד בתשלום תכוף', 1,
      'יהודית, שנפגעה בתאונת דרכים, נשאה בהוצאות רפואיות רבות מיד לאחר התאונה, וכעת היא זקוקה לטיפולי פיזיותרפיה שוטפים ולעזרת מטפלת. אילו מבין ההוצאות הללו יכולות להיכלל בבקשה לתשלום תכוף?', 'שאלה זו בוחנת את סוגי ההוצאות והצרכים המכוסים במסגרת תשלום תכוף, כפי שקבוע בסעיף 5(ב) לחוק פיצויים לנפגעי תאונות דרכים. היא מדגישה את ההבחנה בין הוצאות ריפוי שהוצאו בעבר לבין תשלומים חודשיים לצרכי ריפוי, סיעוד ומחיה עתידיים.', 'סעיף 5(ב) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975, מפרט את סוגי ההוצאות והצרכים המכוסים במסגרת תשלום תכוף. סעיף 5(ב)(1) קובע כי התשלום התכוף יכלול "הוצאות שהוציא הנפגע לצרכי ריפויו, לרבות הוצאות אשפוז בבית חולים". סעיף 5(ב)(1) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 כלומר, הוצאות רפואיות שהוצאו בעבר על ידי הנפגע נכללות בתשלום התכוף. סעיף 5(ב)(2) קובע כי התשלום התכוף יכלול גם "תשלומים חודשיים שיהיה בהם כדי לספק, עד להחלטה הסופית בעניין הפיצויים, את צרכי ריפויו של הנפגע וסיעודו ואת צרכי מחייתו". סעיף 5(ב)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 מכאן, שגם צרכים עתידיים כגון טיפולי פיזיותרפיה (ריפוי) ועזרת מטפלת (סיעוד) נכללים בתשלום התכוף. ת"א (שלום י-ם) 54847-11-13 יצחק נחום נ'' כלל חברה לביטוח בע"מ (29.06.2015)', 'הטעות הנפוצה היא לחשוב שתשלום תכוף מכסה רק הוצאות עבר או רק הוצאות עתיד, ולא להבין שהוא מיועד לספק את שני סוגי הצרכים הדחופים.',
      '["תשלום תכוף", "חוק פיצויים לנפגעי תאונות דרכים", "צרכי ריפוי", "צרכי סיעוד", "הוצאות עבר", "הוצאות עתיד"]'::jsonb, '**וריאציה 1 — הוצאות ריפוי עבר:** האם תשלום תכוף מכסה הוצאות רפואיות שכבר שולמו? ← כן, סעיף 5(ב)(1) לחוק. סעיף 5(ב)(1) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975

**וריאציה 2 — צרכים עתידיים:** האם תשלום תכוף מכסה צרכי סיעוד ומחיה עתידיים? ← כן, סעיף 5(ב)(2) לחוק. סעיף 5(ב)(2) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 3 — מטרת התשלום:** מהי מטרת התשלום התכוף? ← להקל על הנפגע ולספק צרכים חיוניים שאינם יכולים לחכות. ת"א (שלום י-ם) 54847-11-13 יצחק נחום נ'' כלל חברה לביטוח בע"מ (29.06.2015)', 'תשלום תכוף (ס'' 5(ב) לחוק הפלת"ד) ← מכסה הוצאות ריפוי עבר (ס'' 5(ב)(1)) + תשלומים חודשיים לצרכי ריפוי, סיעוד ומחיה עתידיים (ס'' 5(ב)(2)).', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 5(ב)", "ת\"א (שלום י-ם) 54847-11-13 יצחק נחום נ'' כלל חברה לביטוח בע\"מ (29.06.2015)", "תקנות פיצויים לנפגעי תאונות דרכים (תשלומים תכופים), תשמ\"ט-1989, תקנה 4"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'רק הוצאות רפואיות שהוציאה בעבר, שכן תשלום תכוף נועד לכסות הוצאות שכבר נגרמו.', false, 'טענה זו שגויה, שכן תשלום תכוף נועד לכסות גם צרכים עתידיים, כגון צרכי ריפוי, סיעוד ומחיה.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'רק הוצאות עתידיות לטיפולי פיזיותרפיה ולעזרת מטפלת, שכן תשלום תכוף נועד לספק צרכים חיוניים שאינם סובלים דיחוי.', false, 'טענה זו שגויה, שכן תשלום תכוף מכסה גם הוצאות רפואיות שהוצאו בעבר, כפי שמפורט בסעיף 5(ב)(1) לחוק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הוצאות רפואיות שהוציאה בעבר, וכן תשלומים חודשיים עבור טיפולי פיזיותרפיה ועזרת מטפלת.', true, 'תשובה זו נכונה, שכן סעיף 5(ב)(1) לחוק פיצויים לנפגעי תאונות דרכים מתייחס להוצאות ריפוי שהוצאו בעבר, וסעיף 5(ב)(2) מתייחס לתשלומים חודשיים לצרכי ריפוי, סיעוד ומחיה עתידיים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'אף אחת מההוצאות, שכן תשלום תכוף אינו מיועד לכיסוי הוצאות רפואיות או סיעודיות.', false, 'טענה זו שגויה לחלוטין, שכן צרכי ריפוי וסיעוד הם מטרות מרכזיות של התשלום התכוף.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q35';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'רמת הראיות הנדרשת לתשלום תכוף', 2,
      'יהודית הגישה בקשה לתשלום תכוף לבית המשפט. חברת הביטוח טוענת כי אין קשר סיבתי בין התאונה לבין הצורך בסיעוד, וכי מצבה הרפואי של יהודית אינו מצדיק את הסכומים הנדרשים. מהי רמת הראיות הנדרשת מיהודית בשלב זה של הדיון?', 'שאלה זו עוסקת ברמת הראיות הנדרשת מנפגע המבקש תשלום תכוף. היא מדגישה את אופיו הדחוף של התשלום התכוף, המצדיק בחינה לכאורית בלבד של הזכאות והנזק, מבלי להיכנס לעומק המחלוקות העובדתיות והרפואיות, אשר שמורות להליך העיקרי.', 'תכליתו של התשלום התכוף היא מתן סיוע ראשוני, מהיר וזמני לנפגע, עד למתן פסק הדין הסופי בתביעת הפיצויים. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018) בשל דחיפות זו, בית המשפט אינו נכנס לעומקן של המחלוקות ולפרטי העובדות בשלב זה, אלא בוחן את הזכאות לכאורה על יסוד ראיות לכאורה בלבד. בת"ת (שלום נצרת) 52513-06-25 פלוני נ'' התאגיד המנהל של המאגר לביטוח רכב חובה ("הפול") (09.12.2025) רק בהתקיים ספק של ממש בעצם זכאותו של הנפגע, יידחה או יסוכל התשלום התכוף. בת"ת (שלום בת ים) 25640-05-24 פלוני נ'' הפניקס חברה לביטוח בע"מ (07.07.2024)', 'הטעות הנפוצה היא לייחס להליך התשלום התכוף את אותה רמת הוכחה הנדרשת בהליך העיקרי, ובכך לפספס את אופיו הייחודי כסעד דחוף המבוסס על ראיות לכאורה.',
      '["תשלום תכוף", "ראיות לכאורה", "סעד דחוף", "חוק פיצויים לנפגעי תאונות דרכים", "נטל הוכחה", "קשר סיבתי"]'::jsonb, '**וריאציה 1 — רמת הוכחה:** מהי רמת ההוכחה הנדרשת לתשלום תכוף? ← ראיות לכאורה בלבד. בת"ת (שלום נצרת) 52513-06-25 פלוני נ'' התאגיד המנהל של המאגר לביטוח רכב חובה ("הפול") (09.12.2025)
**וריאציה 2 — עומק הבדיקה:** האם בית המשפט נכנס לעומק המחלוקות? ← לא, אלא אם קיים ספק של ממש בעצם הזכאות. בת"ת (שלום בת ים) 25640-05-24 פלוני נ'' הפניקס חברה לביטוח בע"מ (07.07.2024)
**וריאציה 3 — מטרת ההליך:** מהי מטרת הליך התשלום התכוף? ← סיוע ראשוני, מהיר וזמני לנפגע. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018)', 'תשלום תכוף ← סעד דחוף ← ראיות לכאורה בלבד ← בית המשפט לא נכנס לעומק המחלוקת, אלא אם ספק של ממש בזכאות.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 5", "ת\"א (שלום י-ם) 54847-11-13 יצחק נחום נ'' כלל חברה לביטוח בע\"מ (29.06.2015)", "ת\"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע\"מ (24.07.2018)", "בת\"ת (שלום נצרת) 52513-06-25 פלוני נ'' התאגיד המנהל של המאגר לביטוח רכב חובה (\"הפול\") (09.12.2025)", "בת\"ת (שלום בת ים) 25640-05-24 פלוני נ'' הפניקס חברה לביטוח בע\"מ (07.07.2024)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'יהודית נדרשת להוכיח את טענותיה במלואן, לרבות קשר סיבתי והיקף הנזק, בדומה להליך העיקרי.', false, 'טענה זו שגויה, שכן בשלב התשלום התכוף בית המשפט אינו נכנס לעומקן של המחלוקות, ובירור ממצה שמור להליך העיקרי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'יהודית נדרשת להציג ראיות לכאורה בלבד, ובית המשפט אינו נכנס לעומק המחלוקות אלא אם קיים ספק של ממש בעצם זכאותה.', true, 'תשובה זו נכונה, שכן תכלית התשלום התכוף היא מתן סעד דחוף, ולכן הבחינה השיפוטית היא לכאורית בלבד.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'יהודית פטורה מהצגת ראיות כלשהן, שכן מדובר בסעד סוציאלי שנועד להקל על נפגעים.', false, 'טענה זו שגויה, שכן על המבקש מוטל נטל הוכחה להציג תשתית ראייתית, גם אם היא לכאורית בלבד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'יהודית נדרשת להציג חוות דעת מומחה רפואי שתאשר את הקשר הסיבתי והיקף הנזק.', false, 'טענה זו שגויה, שכן מינוי מומחים רפואיים ובחינת חוות דעתם נעשים בדרך כלל בשלב התביעה העיקרית, ולא בשלב התשלום התכוף.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q35';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'שיהוי בהגשת בקשה לתשלום תכוף', 3,
      'יהודית נפגעה בתאונת דרכים לפני 14 חודשים. רק כעת, לאחר שנקלעה לקשיים כלכליים חמורים, היא פונה לחברת הביטוח בדרישה לתשלום תכוף. חברת הביטוח טוענת כי השיהוי בהגשת הדרישה מעיד על היעדר דחיפות ועל כן יש לדחות את בקשתה. מהי עמדת בית המשפט במקרה כזה?', 'שאלה זו בוחנת את השפעת שיהוי בהגשת דרישה או בקשה לתשלום תכוף. היא מדגישה כי למרות שתשלום תכוף נועד לספק צרכים מיידיים ודחופים, שיהוי בהגשה אינו מוביל בהכרח לדחיית הבקשה על הסף, ובית המשפט יבחן את נסיבות המקרה לגופן.', 'תכליתו של התשלום התכוף היא להושיט סיוע ראשוני, מהיר וזמני לנפגע, לענות על צרכיו המידיים ולמנוע ממנו סבל מיותר. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018) הגשת דרישה או בקשה לתשלום תכוף בשלב מאוחר, כגון 14 חודשים לאחר התאונה, אינה עולה בקנה אחד עם מטרת ההליך לענות על צרכים מידיים ודחופים. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018) עם זאת, הפסיקה קובעת כי למרות השיהוי, בית המשפט לא ידחה את הבקשה על הסף, אלא יבחן את הבקשה לגופה, במיוחד לאור אופי הפגיעה והצרכים הנטענים. ת"א (שלום חי'') 29075-12-18 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (14.01.2020)', 'הטעות הנפוצה היא לחשוב ששיהוי בהגשת בקשה לתשלום תכוף מוביל לדחייה אוטומטית, מבלי להבין שבית המשפט יבחן את נסיבות המקרה ואת הצורך הדחוף של הנפגע.',
      '["תשלום תכוף", "שיהוי", "דחיפות", "חוק פיצויים לנפגעי תאונות דרכים", "בחינה לגופו של עניין", "סעד דחוף"]'::jsonb, '**וריאציה 1 — השפעת שיהוי:** האם שיהוי בהגשת בקשה לתשלום תכוף מוביל לדחייה? ← לא בהכרח, בית המשפט יבחן לגופה. ת"א (שלום חי'') 29075-12-18 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונות דרכים (14.01.2020)
**וריאציה 2 — אינדיקציה לשיהוי:** מה יכול שיהוי להעיד? ← לכאורה, על היעדר צורך דחוף. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018)
**וריאציה 3 — תכלית התשלום:** מהי תכלית התשלום התכוף? ← סיוע ראשוני, מהיר וזמני. ת"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע"מ (24.07.2018)', 'שיהוי בהגשת בקשה לתשלום תכוף ← עשוי להעיד על היעדר דחיפות ← אך בית המשפט יבחן לגופה ולא ידחה על הסף.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 5", "ת\"א (שלום חי'') 67238-03-18 פלוני נ'' כלל חברה לביטוח בע\"מ (24.07.2018)", "ת\"א (שלום חי'') 29075-12-18 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונות דרכים (14.01.2020)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הבקשה תידחה על הסף, שכן שיהוי כה ארוך סותר את תכלית התשלום התכוף כסעד דחוף.', false, 'טענה זו שגויה, שכן למרות השיהוי, בית המשפט יבחן את הבקשה לגופה, במיוחד אם מדובר בצרכים חיוניים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'השיהוי עשוי להעיד לכאורה על היעדר צורך דחוף, אך בית המשפט יבחן את הבקשה לגופה, במיוחד לאור אופי הפגיעה והצרכים הנטענים.', true, 'תשובה זו נכונה, שכן הפסיקה קובעת כי למרות השיהוי, בית המשפט לא ידחה את הבקשה על הסף ויבחן את נסיבות המקרה לגופן.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'השיהוי אינו רלוונטי כלל, שכן אין הגבלת זמן להגשת דרישה לתשלום תכוף.', false, 'טענה זו שגויה, שכן השיהוי רלוונטי לבחינת הדחיפות, גם אם אינו מהווה עילה אוטומטית לדחייה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הבקשה תידחה, אלא אם יהודית תוכיח שהשיהוי נבע מסיבות רפואיות שמנעו ממנה לפעול קודם לכן.', false, 'טענה זו שגויה, שכן למרות שסיבות רפואיות יכולות להסביר שיהוי, בית המשפט יבחן את הבקשה לגופה גם ללא הוכחה כזו, אם קיימים צרכים דחופים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q35';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'הליך הגשת בקשה לתשלום תכוף לבית המשפט', 4,
      'יהודית הגישה דרישה לתשלום תכוף לחברת הביטוח, אך חלפו 45 ימים וחברת הביטוח לא השיבה לדרישתה. יהודית מעוניינת כעת להגיש בקשה לתשלום תכוף לבית המשפט. האם היא רשאית לעשות זאת?', 'שאלה זו מתמקדת בהליך הפרוצדורלי להגשת בקשה לתשלום תכוף לבית המשפט, לאחר הגשת דרישה לחברת הביטוח. היא בוחנת את דרישת תקופת ההמתנה הקבועה בחוק, ואת חשיבותה של דרישה זו כתנאי סף להגשת הבקשה לבית המשפט.', 'הליך הגשת בקשה לתשלום תכוף הוא הליך דו-שלבי. השלב הראשון הוא הגשת דרישה בכתב לחברת הביטוח (החייב בפיצויים) בהתאם לסעיף 5(ב) לחוק פיצויים לנפגעי תאונות דרכים. סעיף 5(ב) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 השלב השני, הגשת בקשה לבית המשפט, אפשרי רק לאחר שחלפו 60 ימים מיום שהוגשה הדרישה לחייב והדורש לא קיבל את התשלום. בש"א (שלום ירושלים) 3818/03 אמזלג דוד נ'' מנורה חברה לביטוח בע"מ (08.08.2003) דרישה זו מהווה תנאי מוקדם מהותי להגשת הבקשה לבית המשפט. ת"א (שלום תל אביב-יפו) 168786/02 ליברמן יהודה נ'' סלומון חיות (11.06.2002) במקרה הנדון, מכיוון שחלפו רק 45 ימים, יהודית אינה רשאית עדיין להגיש את הבקשה לבית המשפט ועליה להמתין את מלוא תקופת 60 הימים. בש"א (שלום רמלה) 1408/04 רונן אליזבט נ'' מגדל חב'' לביטוח בע"מ (09.06.2004)', 'הטעות הנפוצה היא לחשוב שאי-מענה של חברת הביטוח או סירוב מוקדם מקצרים את תקופת ההמתנה של 60 הימים, או שניתן לפנות לבית המשפט מיד לאחר הגשת הדרישה.',
      '["תשלום תכוף", "דרישה לתשלום תכוף", "בקשה לתשלום תכוף", "חוק פיצויים לנפגעי תאונות דרכים", "תקופת המתנה", "תנאי סף"]'::jsonb, '**וריאציה 1 — תקופת המתנה:** כמה זמן יש להמתין לאחר דרישה לחברת הביטוח? ← 60 ימים. סעיף 5(ב) לחוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975
**וריאציה 2 — תנאי סף:** האם הגשת דרישה היא תנאי סף לבקשה לבית המשפט? ← כן. ת"א (שלום תל אביב-יפו) 168786/02 ליברמן יהודה נ'' סלומון חיות (11.06.2002)
**וריאציה 3 — אי-מענה:** מה קורה אם חברת הביטוח לא משיבה? ← עדיין יש להמתין 60 ימים. בש"א (שלום רמלה) 1408/04 רונן אליזבט נ'' מגדל חב'' לביטוח בע"מ (09.06.2004)', 'הליך תשלום תכוף ← דרישה לחברת הביטוח ← המתנה 60 ימים ← רק אז בקשה לבית המשפט (ס'' 5(ב) לחוק הפלת"ד).', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 5(ב)", "חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 5א(א)", "תקנות פיצויים לנפגעי תאונות דרכים (תשלומים תכופים), תשמ\"ט-1989, תקנה 2(א)", "בש\"א (שלום רמלה) 1408/04 רונן אליזבט נ'' מגדל חב'' לביטוח בע\"מ (09.06.2004)", "בש\"א (שלום ירושלים) 3818/03 אמזלג דוד נ'' מנורה חברה לביטוח בע\"מ (08.08.2003)", "ת\"א (שלום תל אביב-יפו) 168786/02 ליברמן יהודה נ'' סלומון חיות (11.06.2002)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, מכיוון שחלפו 30 ימים ממועד הגשת הדרישה, וזהו פרק זמן סביר.', false, 'טענה זו שגויה, שכן חוק פיצויים לנפגעי תאונות דרכים קובע תקופת המתנה של 60 ימים, ולא 30 ימים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, מכיוון שעליה להמתין 60 ימים מיום הגשת הדרישה לחברת הביטוח, ורק אז תוכל להגיש בקשה לבית המשפט.', true, 'תשובה זו נכונה, שכן סעיף 5א(א) לחוק פיצויים לנפגעי תאונות דרכים קובע כי יש להמתין 60 ימים מיום הגשת הדרישה לחייב בטרם הגשת בקשה לבית המשפט.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, מכיוון שחברת הביטוח לא השיבה לדרישתה, והדבר מהווה סירוב המאפשר פנייה מיידית לבית המשפט.', false, 'טענה זו שגויה, שכן גם במקרה של אי-מענה, יש להמתין את מלוא תקופת 60 הימים הקבועה בחוק.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן חברת הביטוח הודיעה במפורש על סירובה לשלם את התשלום התכוף.', false, 'טענה זו שגויה, שכן תקופת ההמתנה של 60 ימים חלה גם במקרה של סירוב מפורש, וגם במקרה של אי-מענה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q35';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 35, '2024-W-S-Q35';
END
$$;

-- ============================================================
-- Q36 — angles backfill for 2024-W-S-Q36 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q36';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q36';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'חישוב הוצאות ברכוש משותף עם תקנון מוסכם', 1,
      'נציגות בית משותף מעוניינת בזיפות הגג המשותף. בבית המשותף 6 דירות. בתקנון המוסכם של הבית נקבע כי הוצאות החזקה וניהול הרכוש המשותף יחולקו באופן שווה בין כל הדירות. כיצד יחולק התשלום עבור הזיפות בין בעלי הדירות?', 'שאלה זו בוחנת את היחס בין ברירת המחדל החוקית לחלוקת הוצאות רכוש משותף (סעיף 58(א) לחוק המקרקעין) לבין קביעה שונה בתקנון מוסכם. היא מדגישה את עדיפותו של התקנון המוסכם, משנרשם, על פני הוראות החוק הדיספוזיטיביות.', 'סעיף 58(א) לחוק המקרקעין, תשכ"ט-1969, קובע כי בעל דירה חייב להשתתף בהוצאות החזקה וניהול הרכוש המשותף "לפי יחס שטח רצפת דירתו אל שטח הרצפה של כל הדירות שבבית המשותף, זולת אם נקבע בתקנון שיעור השתתפות אחר". סעיף 58(א) לחוק המקרקעין, תשכ"ט-1969 כלומר, הוראת החוק היא דיספוזיטיבית, וניתן להתנות עליה בתקנון הבית המשותף. תקנון מוסכם שנרשם בפנקס הבתים המשותפים מחייב את כל בעלי הדירות, לרבות אלה שנעשו בעלי דירות לאחר מכן. המפקח על המקרקעין פתח תקוה 722/20 נציגות הבית המשותף ברח'' תל חי 40 כפר סבא נ'' חב'' כהן יצחק בית מסחר לכלי בית בע"מ (23.03.2022) במקרה זה, התקנון המוסכם קובע חלוקה שווה של הוצאות ההחזקה בין כל הדירות. קביעה זו גוברת על ברירת המחדל החוקית, ולכן כל בעל דירה ישלם 1/6 מהתשלום. המפקח על המקרקעין פתח תקוה 264/20 נציגות הבית המשותף ברחוב סוקולוב 3 הוד השרון נ'' עזרא ליאור (04.08.2021)', 'הטעות הנפוצה היא להתעלם מקיומו של תקנון מוסכם וליישם באופן אוטומטי את ברירת המחדל החוקית, או לחשוב שתקנון מוסכם אינו מחייב רוכשים חדשים.',
      '["חוק המקרקעין", "סעיף 58(א)", "תקנון מוסכם", "הוצאות רכוש משותף", "עדיפות תקנון", "חיובים בבית משותף"]'::jsonb, '**וריאציה 1 — עדיפות תקנון:** מה קובע סעיף 58(א) לגבי תקנון? ← התקנון גובר על ברירת המחדל של שטח רצפה. סעיף 58(א) לחוק המקרקעין, תשכ"ט-1969
**וריאציה 2 — תוקף תקנון מוסכם:** האם תקנון מוסכם מחייב גם רוכשים חדשים? ← כן, משנרשם, כוחו יפה לכל בעלי הדירות. המפקח על המקרקעין פתח תקוה 722/20 נציגות הבית המשותף ברח'' תל חי 40 כפר סבא נ'' חב'' כהן יצחק בית מסחר לכלי בית בע"מ (23.03.2022)
**וריאציה 3 — חלוקה שווה:** אם התקנון קובע חלוקה שווה, מה המשמעות? ← כל דירה משלמת חלק שווה מההוצאה. המפקח על המקרקעין פתח תקוה 290/24 וינשטין יצחק נ'' נציגות הבית המשותף ברח'' העמק 16 כפר סבא (20.07.2025)', 'תקנון מוסכם גובר על ברירת המחדל החוקית (ס'' 58(א) לחוק המקרקעין) ← אם קובע חלוקה שווה, זו החלוקה המחייבת.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 58(א)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 62(ג)", "(המפקח על המקרקעין פתח תקוה) 213/19 נציגות הבית המשותף ברחוב התע\"ש 26 כפר סבא נ'' ספאמדן בע\"מ (30.09.2020)", "(המפקח על המקרקעין פתח תקוה) 722/20 נציגות הבית המשותף ברח'' תל חי 40 כפר סבא נ'' חב'' כהן יצחק בית מסחר לכלי בית בע\"מ (23.03.2022)", "(המפקח על המקרקעין פתח תקוה) 264/20 נציגות הבית המשותף ברחוב סוקולוב 3 הוד השרון נ'' עזרא ליאור (04.08.2021)", "(המפקח על המקרקעין פתח תקוה) 290/24 וינשטין יצחק נ'' נציגות הבית המשותף ברח'' העמק 16 כפר סבא (20.07.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כל בעלי דירה ישלם 1/6 מהתשלום.', true, 'תשובה זו נכונה, שכן תקנון מוסכם גובר על ברירת המחדל החוקית, וקובע חלוקה שווה בין כל הדירות.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'התשלום יחולק לפי יחס שטח רצפת הדירה לשטח הרצפה של כל הדירות, שכן זו ברירת המחדל החוקית.', false, 'טענה זו שגויה, שכן ברירת המחדל החוקית חלה רק בהיעדר קביעה אחרת בתקנון, ואילו כאן קיים תקנון מוסכם הקובע חלוקה שונה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'התשלום יחולק לפי יחס שטח רצפת הדירה לשטח הרצפה של כל הדירות, אלא אם כן כל בעלי הדירות יסכימו פה אחד לחלוקה שווה.', false, 'טענה זו שגויה, שכן התקנון המוסכם כבר קובע חלוקה שווה, והוא גובר על ברירת המחדל החוקית ללא צורך בהסכמה נוספת.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'התשלום יחולק לפי יחס שטח רצפת הדירה לשטח הרצפה של כל הדירות, אך ללא חישוב שטחי הצמדות.', false, 'טענה זו שגויה, שכן התקנון המוסכם קובע חלוקה שווה, והיא גוברת על כלל החישוב לפי שטח רצפה, בין אם כולל הצמדות ובין אם לאו.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q36';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'הגדרת "החזקה תקינה" ושינויי זמן', 2,
      'נציגות בית משותף החליטה לבצע שיפוץ מקיף בחזית הבניין, הכולל חידוש ציפוי הקירות החיצוניים והתקנת תאורת לד חסכונית, שלא הייתה קיימת בעת גמר הבנייה. דייר אחד מתנגד לתשלום, בטענה כי מדובר ב''השבחה'' ולא ב''החזקה תקינה''. האם טענתו תתקבל?', 'שאלה זו עוסקת בפרשנות המונח "החזקה תקינה" בסעיף 58(א) לחוק המקרקעין, ובאופן שבו הפסיקה הרחיבה את משמעותו מעבר לשמירה על המצב הקיים בלבד. היא בוחנת את ההכרה בשיפורים ושדרוגים כחלק מ''החזקה תקינה'' בהתאם לתנאי הזמן והמקום.', 'סעיף 58(א) לחוק המקרקעין, תשכ"ט-1969, מגדיר "החזקה תקינה" כ"שמירה על מצבו של הרכוש המשותף כפי שהיה בעת גמר הבניה, לרבות שיפורים שבוצעו בו לאחר מכן בהסכמת בעלי הדירות". סעיף 58(א) לחוק המקרקעין, תשכ"ט-1969 הפסיקה הרחיבה את פרשנות המונח "החזקה תקינה" וקבעה כי הוא אינו כובל את בעלי הדירות למצב המקורי של הבניין, אלא בוחן את המונח בתנאי הזמן והמקום. המפקח על המקרקעין חולון 28/22 נציגות הבית המשותף מרחוב שדרות העצמאות 32 בת ים נ'' אלוש משה לורן (20.02.2023) כך, שיפוצים הכוללים שיפורים והתאמות לסטנדרטים מודרניים, כמו התקנת תאורת לד, יכולים להיחשב כחלק מ''החזקה תקינה'' אם הם מיועדים לשמור על תפקודו התקין, חזותו וערכו הכלכלי של הבית, וכן על בריאות ובטיחות הדיירים. המפקח על המקרקעין פתח תקוה 55/21 נציגות הבית המשותף - רח'' מנחם בגין 62, פ"ת נ'' נחום יוסף (18.08.2022) במקרה זה, חידוש ציפוי הקירות והתקנת תאורת לד, גם אם לא היו קיימים במקור, יכולים להיחשב כ''החזקה תקינה'' בהתאם לפרשנות המרחיבה של הפסיקה, ובלבד שהתקבלו בהסכמת בעלי הדירות (בדרך כלל ברוב רגיל). המפקח על המקרקעין נתניה 280/20 נציגות הבית המשותף ברח'' טשרניחובסקי 21, נתניה נ'' ונגר בלה יפה (23.03.2022)', 'הטעות הנפוצה היא לדבוק בפרשנות מצמצמת של ''החזקה תקינה'' כפי שהייתה בעבר, מבלי להכיר בהתפתחות הפסיקתית המרחיבה את המונח.',
      '["החזקה תקינה", "סעיף 58(א) לחוק המקרקעין", "פרשנות חוק", "שיפוץ רכוש משותף", "השבחה", "תנאי הזמן והמקום"]'::jsonb, '**וריאציה 1 — פרשנות "החזקה תקינה":** האם "החזקה תקינה" כוללת רק שמירה על המצב הקיים? ← לא, הפסיקה מרחיבה לשיפורים ושדרוגים בהתאם לזמן ומקום. המפקח על המקרקעין חולון 28/22 נציגות הבית המשותף מרחוב שדרות העצמאות 32 בת ים נ'' אלוש משה לורן (20.02.2023)
**וריאציה 2 — תכלית השיפוץ:** מהי תכלית השיפוץ הנחשב כהחזקה תקינה? ← שמירה על תפקוד, חזות, ערך כלכלי, בריאות ובטיחות. המפקח על המקרקעין פתח תקוה 55/21 נציגות הבית המשותף - רח'' מנחם בגין 62, פ"ת נ'' נחום יוסף (18.08.2022)
**וריאציה 3 — דוגמאות לשיפורים:** האם תוספת מתקנים שלא היו במקור יכולה להיכלל? ← כן, אם מתאימים לסטנדרט חדש יותר. המפקח על המקרקעין נתניה 280/20 נציגות הבית המשותף ברח'' טשרניחובסקי 21, נתניה נ'' ונגר בלה יפה (23.03.2022)', 'החזקה תקינה (ס'' 58(א) לחוק המקרקעין) ← פרשנות מרחיבה בפסיקה ← כוללת שיפורים ושדרוגים ← בהתאם לתנאי הזמן והמקום.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 58(א)", "רע\"א 7112/93 צודלר נ'' יוסף, פ\"ד מח(5) 550 (1994)", "(המפקח על המקרקעין חולון) 28/22 נציגות הבית המשותף מרחוב שדרות העצמאות 32 בת ים נ'' אלוש משה לורן (20.02.2023)", "(המפקח על המקרקעין פתח תקוה) 55/21 נציגות הבית המשותף - רח'' מנחם בגין 62, פ\"ת נ'' נחום יוסף (18.08.2022)", "(המפקח על המקרקעין נתניה) 280/20 נציגות הבית המשותף ברח'' טשרניחובסקי 21, נתניה נ'' ונגר בלה יפה (23.03.2022)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, שכן ''החזקה תקינה'' מוגדרת כשמירה על מצבו של הרכוש המשותף כפי שהיה בעת גמר הבנייה, ואינה כוללת שיפורים או שדרוגים.', false, 'טענה זו שגויה, שכן הפסיקה הרחיבה את פרשנות המונח ''החזקה תקינה'' כך שתכלול גם שיפורים ושדרוגים בהתאם לתנאי הזמן והמקום.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן הפסיקה מרחיבה את פרשנות המונח ''החזקה תקינה'' כך שתכלול גם שיפורים ושדרוגים המתאימים לתנאי הזמן והמקום, ובלבד שהתקבלו בהסכמת בעלי הדירות.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי ''החזקה תקינה'' אינה כובלת למצב המקורי של הבניין, אלא מתפתחת עם הזמן והצרכים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אלא אם כן השיפוץ נדרש עקב צו של רשות מוסמכת, כמו עירייה.', false, 'טענה זו שגויה, שכן גם ללא צו רשות, שיפורים יכולים להיחשב כ''החזקה תקינה'' אם הם מתאימים לתנאי הזמן והמקום והתקבלו בהסכמה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אך רק אם כל בעלי הדירות הסכימו פה אחד לשיפוץ, שכן מדובר בהשבחה.', false, 'טענה זו שגויה, שכן שיפוץ הנחשב כ''החזקה תקינה'' (גם אם כולל שיפורים) דורש בדרך כלל רוב רגיל באסיפה הכללית, ולא הסכמה פה אחד.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q36';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'קיזוז חובות דמי ועד בית', 3,
      'דייר בבית משותף מסרב לשלם את חלקו בהוצאות החזקה השוטפות, בטענה כי נגרמו לו נזקי רטיבות בדירתו עקב ליקויים ברכוש המשותף שהנציגות לא תיקנה, וכי הוא זכאי לקזז את עלות תיקון הנזקים מחובו לנציגות. האם טענת הקיזוז תתקבל?', 'שאלה זו עוסקת באופייה המוחלט של חובת בעל דירה לשלם את חלקו בהוצאות החזקה וניהול הרכוש המשותף, ובמגבלה על זכות הקיזוז כנגד חובה זו. היא מדגישה את עקרון שמירת הקופה המשותפת ואת הצורך להפריד בין חובת התשלום לבין טענות נגד הנציגות.', 'החובה החלה על בעל דירה להשתתף בהוצאות החזקה וניהול הרכוש המשותף, המעוגנת בסעיף 58(א) לחוק המקרקעין, היא חובה מוחלטת ובלתי תלויה. המפקח על המקרקעין נתניה 201/20 נציגות הבית המשותף ברח'' בן יהודה 34, הרצליה נ'' פרסיקו ינון (04.09.2023) תכליתה של חובה זו היא להבטיח שלא תיפגע הקופה המשותפת, ובתוך כך בעלי הדירות האחרים המשלמים את חלקם. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021) הפסיקה קבעה באופן עקבי כי בעל דירה אינו רשאי לקזז חיובים כספיים, שלשיטתו הוא זכאי להיפרע מנציגות הבית המשותף (כגון בגין נזקי רטיבות), מחלקו בהוצאות החזקה. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021) טענותיו של בעל הדירה כנגד הנציגות, גם אם הן מוצדקות, צריכות להתברר בהליך נפרד, ואינן פוטרות אותו מחובתו לשלם את דמי ועד הבית במועד וכסדרו. המפקח על המקרקעין פתח תקוה 557/18 נציגות הבית המשותף ברחוב החלוצים 21 בני ברק נ'' גבאי יהונתן (31.01.2021)', 'הטעות הנפוצה היא לחשוב שניתן להשתמש בזכות הקיזוז כדי להימנע מתשלום דמי ועד בית, מבלי להבין את האופי המוחלט של חובה זו ואת ההפרדה הנדרשת בין חובות הדייר לנציגות לבין טענותיו כלפיה.',
      '["חובת תשלום הוצאות החזקה", "סעיף 58(א) לחוק המקרקעין", "זכות קיזוז", "נציגות בית משותף", "קופה משותפת", "חובה מוחלטת"]'::jsonb, '**וריאציה 1 — אופי החובה:** האם חובת תשלום דמי ועד בית היא מוחלטת? ← כן, חובה מוחלטת ובלתי תלויה. המפקח על המקרקעין נתניה 201/20 נציגות הבית המשותף ברח'' בן יהודה 34, הרצליה נ'' פרסיקו ינון (04.09.2023)
**וריאציה 2 — זכות קיזוז:** האם ניתן לקזז חובות נטענים נגד דמי ועד בית? ← לא, בעל דירה אינו רשאי לקזז. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021)
**וריאציה 3 — תכלית האיסור:** מדוע אסור לקזז? ← כדי להבטיח את תפקודה התקין של הקופה המשותפת. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021)', 'חובת תשלום דמי ועד בית (ס'' 58(א) לחוק המקרקעין) ← חובה מוחלטת ובלתי תלויה ← לא ניתן לקזז חובות נטענים כנגדה.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 58(א)", "(המפקח על המקרקעין תל אביב-יפו) 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע\"מ (14.04.2021)", "(המפקח על המקרקעין פתח תקוה) 557/18 נציגות הבית המשותף ברחוב החלוצים 21 בני ברק נ'' גבאי יהונתן (31.01.2021)", "(המפקח על המקרקעין פתח תקוה) 452/19 נציגות הבית המשותף ברחוב עמק איילון 5 בכפר סבא נ'' נווה יהודה נסים (05.08.2021)", "(המפקח על המקרקעין נתניה) 201/20 נציגות הבית המשותף ברח'' בן יהודה 34, הרצליה נ'' פרסיקו ינון (04.09.2023)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, אם יוכיח כי נגרמו לו נזקים והנציגות סירבה לתקנם, שכן זכות הקיזוז היא זכות יסוד בדיני חוזים.', false, 'טענה זו שגויה, שכן חובת התשלום לנציגות היא מוחלטת ואינה ניתנת לקיזוז בגין טענות נגד הנציגות, אלא יש להגיש תביעה נפרדת.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן החובה לשלם את חלקו בהוצאות החזקה היא חובה מוחלטת ובלתי תלויה, ובעל דירה אינו רשאי לקזז חובות כספיים מחובתו זו.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה באופן עקבי כי לא ניתן לקזז חובות נטענים נגד חובת התשלום לנציגות, כדי להבטיח את תפקודה התקין של הקופה המשותפת.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הנזקים נגרמו כתוצאה מרשלנות חמורה של הנציגות.', false, 'טענה זו שגויה, שכן גם במקרה של רשלנות, לא ניתן לקזז את החוב, אלא יש לתבוע את הנציגות בנפרד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן הנציגות הסכימה במפורש לקיזוז.', false, 'טענה זו שגויה, שכן גם אם הנציגות הסכימה, הסכמה כזו עשויה לחרוג מסמכותה, שכן היא אינה רשאית לפטור בעל דירה מחובתו.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q36';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות המפקח על המקרקעין בתביעות נזיקין', 4,
      'דייר בבית משותף מעוניין לתבוע דייר אחר בגין נזקים שנגרמו לדירתו כתוצאה מנזילת מים מדירת הדייר השני. האם המפקח על רישום המקרקעין מוסמך לדון בתביעה זו?', 'שאלה זו בוחנת את היקף הסמכות העניינית של המפקח על רישום המקרקעין, ובפרט את גבולות סמכותו לדון בתביעות נזיקין. היא מדגישה כי סמכות המפקח פורשה בפסיקה באופן דווקני ואינה כוללת תביעות נזיקין כלליות, למעט חריגים מוגדרים.', 'סמכותו של המפקח על רישום המקרקעין לדון בסכסוכים קבועה בסעיף 72 לחוק המקרקעין. סמכות זו פורשה בפסיקה באופן דווקני ונקבע כי אין להרחיב את גדריה. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021) המפקח על רישום המקרקעין אינו מוסמך להכריע בתביעה שעילתה בפקודת הנזיקין, למעט בעוולה של הסגת גבול. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021) תביעה בגין נזקי רטיבות מדירה לדירה אחרת היא תביעת נזיקין כללית, שאינה נכללת בסמכותו הייחודית של המפקח. המפקח על המקרקעין תל אביב-יפו 1140/24 נציגות הבית המשותף ברחוב מעפילי אגוז 82, תל אביב נ'' גרויסמן ברטה (15.01.2025) לפיכך, הסמכות לדון בתביעה זו נתונה לבית המשפט השלום. יצוין כי המפקח מוסמך לדון בתביעה לשיפוי בגין הוצאות שהוצאו לתיקון ליקוי ברכוש המשותף, אך לא בנזקים שנגרמו לדירה פרטית. המפקח על המקרקעין תל אביב-יפו 637/20 אברהמי רבקה נ'' אורן טל (11.03.2021)', 'הטעות הנפוצה היא להניח שכל סכסוך בין דיירים בבית משותף נכנס אוטומטית לסמכות המפקח על רישום המקרקעין, מבלי להבחין בין סוגי הסכסוכים השונים.',
      '["סמכות עניינית", "מפקח על רישום מקרקעין", "חוק המקרקעין", "פקודת הנזיקין", "הסגת גבול", "נזקי רטיבות"]'::jsonb, '**וריאציה 1 — סמכות המפקח:** האם המפקח מוסמך לדון בתביעות נזיקין? ← לא, למעט עוולת הסגת גבול. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021)
**וריאציה 2 — תביעה לשיפוי:** האם המפקח מוסמך לדון בתביעה לשיפוי בגין תיקון רכוש משותף? ← כן, אך לא בנזקים לדירה פרטית. המפקח על המקרקעין תל אביב-יפו 637/20 אברהמי רבקה נ'' אורן טל (11.03.2021)
**וריאציה 3 — פרשנות סמכות:** כיצד פורשה סמכות המפקח? ← באופן דווקני, אין להרחיב גדריה. המפקח על המקרקעין תל אביב-יפו 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע"מ (14.04.2021)', 'סמכות המפקח על המקרקעין ← דווקנית ← לא כוללת תביעות נזיקין כלליות (למעט הסגת גבול) ← נזקי רטיבות לדירה פרטית בסמכות בית משפט שלום.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 72", "(המפקח על המקרקעין תל אביב-יפו) 451/20 נציגות הבית המשותף ברחוב חברה חדשה 5 תל אביב נ'' ז. צסוואן השקעות בע\"מ (14.04.2021)", "(המפקח על המקרקעין תל אביב-יפו) 637/20 אברהמי רבקה נ'' אורן טל (11.03.2021)", "(המפקח על המקרקעין תל אביב-יפו) 1140/24 נציגות הבית המשותף ברחוב מעפילי אגוז 82, תל אביב נ'' גרויסמן ברטה (15.01.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, המפקח מוסמך לדון בכל סכסוך בין בעלי דירות בבית משותף, לרבות תביעות נזיקין.', false, 'טענה זו שגויה, שכן סמכות המפקח מוגבלת לעניינים ספציפיים המנויים בחוק, ותביעות נזיקין אינן נכללות בהן, למעט חריגים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, המפקח אינו מוסמך לדון בתביעות נזיקין, למעט עוולת הסגת גבול, ולכן הסמכות נתונה לבית המשפט השלום.', true, 'תשובה זו נכונה, שכן סמכות המפקח פורשה בפסיקה באופן דווקני, והיא אינה כוללת תביעות נזיקין כלליות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אם הנזילה מקורה ברכוש המשותף, אך לא אם מקורה בדירה הפרטית.', false, 'טענה זו שגויה, שכן גם אם הנזילה מהרכוש המשותף, תביעה נזיקית בגין נזקים לדירה פרטית אינה בסמכות המפקח, אלא תביעה לשיפוי בגין תיקון הרכוש המשותף.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן התביעה מוגשת על ידי נציגות הבית המשותף.', false, 'טענה זו שגויה, שכן זהות התובע אינה משנה את מהות הסכסוך הנזיקי, שאינו בסמכות המפקח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q36';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 36, '2024-W-S-Q36';
END
$$;

-- ============================================================
-- Q37 — angles backfill for 2024-W-S-Q37 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q37';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q37';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'היקף חובת הסודיות האתית', 1,
      'עורך דין קיבל מלקוחו מידע שאינו קשור ישירות לשירות המקצועי שניתן לו, אלא לפרט אישי אחר. האם מידע זה חוסה תחת חובת הסודיות האתית של עורך הדין?', 'שאלה זו עוסקת בהיקף חובת הסודיות האתית של עורך דין, כפי שנקבעה בכלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית). היא מדגישה את ההבחנה בין חובת הסודיות הרחבה, החלה על כל מידע שהגיע לעורך הדין מלקוחו, לבין חיסיון עורך דין-לקוח, המוגבל למידע בעל קשר ענייני לשירות המקצועי.', 'כלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע כי "עורך דין ישמור בסוד כל דבר שיובא לידיעתו בידי לקוח או מטעמו, תוך כדי מילוי תפקידיו, זולת אם הסכים הלקוח במפורש אחרת". כלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986 היקפה של חובת הסודיות רחב יותר מהיקפו של חיסיון עורך דין-לקוח (המעוגן בסעיף 90 לחוק לשכת עורכי הדין וסעיף 48 לפקודת הראיות). יניב ואקי דיני ראיות כרך ג (2021) | מבוא חובת הסודיות חלה על כל מידע שהגיע לעורך הדין מהלקוח או מטעמו, גם אם אין לו קשר ענייני לשירות המקצועי. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שמירת סודיות לעומת זאת, החיסיון חל רק על מידע שיש לו קשר ענייני לשירות המקצועי. יניב ואקי דיני ראיות כרך ג (2021) | מבוא', 'הטעות הנפוצה היא לבלבל בין היקף חובת הסודיות האתית לבין היקף חיסיון עורך דין-לקוח, ולחשוב ששניהם חלים רק על מידע בעל קשר ענייני לשירות המקצועי.',
      '["חובת סודיות אתית", "חיסיון עורך דין-לקוח", "כלל 19 לכללי האתיקה", "סעיף 90 לחוק לשכת עורכי הדין", "סעיף 48 לפקודת הראיות", "קשר ענייני לשירות המקצועי"]'::jsonb, '**וריאציה 1 — היקף חובת הסודיות:** על איזה מידע חלה חובת הסודיות האתית? ← כל דבר שיובא לידיעת עורך הדין מלקוחו. כלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986
**וריאציה 2 — הבחנה מחיסיון:** מה ההבדל בין חובת סודיות לחיסיון? ← חובת הסודיות רחבה יותר ואינה דורשת קשר ענייני לשירות המקצועי. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שמירת סודיות
**וריאציה 3 — ויתור על סודיות:** מתי עורך דין רשאי לגלות מידע סודי? ← רק אם הלקוח הסכים במפורש. כלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986', 'חובת סודיות אתית (כלל 19) ← רחבה מחיסיון ← חלה על כל מידע מלקוח ← אלא אם הלקוח הסכים במפורש.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 19", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, מבוא", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026), שמירת סודיות"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, חובת הסודיות האתית חלה על כל מידע שהגיע לעורך הדין מהלקוח או מטעמו, גם אם אין לו קשר ענייני לשירות המקצועי.', true, 'תשובה זו נכונה, שכן כלל 19 לכללי האתיקה קובע חובת סודיות רחבה יותר מהחיסיון, החלה על כל דבר שיובא לידיעת עורך הדין מלקוחו.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חובת הסודיות האתית, בדומה לחיסיון עורך דין-לקוח, חלה רק על מידע שיש לו קשר ענייני לשירות המקצועי.', false, 'טענה זו שגויה, שכן חובת הסודיות האתית רחבה יותר מהחיסיון ואינה מוגבלת למידע בעל קשר ענייני לשירות המקצועי.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הלקוח ביקש במפורש שעורך הדין ישמור על סודיות המידע הספציפי הזה.', false, 'טענה זו שגויה, שכן חובת הסודיות חלה באופן אוטומטי על כל מידע שהגיע לעורך הדין מלקוחו, אלא אם הלקוח הסכים במפורש אחרת.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן גילוי המידע עלול לפגוע בלקוח באופן ממשי.', false, 'טענה זו שגויה, שכן חובת הסודיות אינה תלויה במידת הפגיעה הפוטנציאלית, אלא בעצם קבלת המידע מהלקוח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q37';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאי תחולת חיסיון עורך דין-לקוח', 2,
      'מהם התנאים המצטברים לתחולת חיסיון עורך דין-לקוח על מידע מסוים?', 'שאלה זו בוחנת את התנאים המהותיים לתחולת חיסיון עורך דין-לקוח, כפי שהם מוגדרים בסעיף 48 לפקודת הראיות ובסעיף 90 לחוק לשכת עורכי הדין. היא מדגישה את הדרישה לקשר ענייני בין המידע לשירות המקצועי שניתן על ידי עורך הדין ללקוח.', 'חיסיון עורך דין-לקוח קבוע בסעיף 48 לפקודת הראיות [נוסח חדש], תשל"א-1971, ובסעיף 90 לחוק לשכת עורכי הדין, תשכ"א-1961. יניב ואקי דיני ראיות כרך ג (2021) | מבוא שני הסעיפים קובעים כי החיסיון חל על "דברים ומסמכים שהוחלפו בין עורך דין לבין לקוחו או לבין אדם אחר מטעם הלקוח ויש להם קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח". בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008) מכאן, התנאים המצטברים לתחולת החיסיון הם: 1. קיומם של יחסי עורך דין-לקוח (או אדם אחר מטעם הלקוח). 2. המידע הוא "דברים ומסמכים שהוחלפו" בין הצדדים. 3. קיים "קשר ענייני לשירות המקצועי" שניתן על ידי עורך הדין ללקוח. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008) החיסיון הוא של הלקוח, והוא יכול לוותר עליו. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)', 'הטעות הנפוצה היא להניח שכל תקשורת בין עורך דין ללקוחו חסויה, מבלי לבחון את דרישת הקשר הענייני לשירות המקצועי.',
      '["חיסיון עורך דין-לקוח", "פקודת הראיות סעיף 48", "חוק לשכת עורכי הדין סעיף 90", "קשר ענייני לשירות המקצועי", "ויתור על חיסיון", "יחסי עורך דין-לקוח"]'::jsonb, '**וריאציה 1 — תנאי החיסיון:** מהם התנאים לתחולת חיסיון עורך דין-לקוח? ← הוחלפו דברים/מסמכים בין עו"ד ללקוח, וקשר ענייני לשירות המקצועי. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)
**וריאציה 2 — חיסיון מוחלט:** האם החיסיון מוחלט? ← כן, אין לבית המשפט סמכות להסירו, אלא אם הלקוח ויתר. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון עורך דין-לקוח, מהו?
**וריאציה 3 — מי הבעלים של החיסיון:** למי שייך החיסיון? ← ללקוח, לא לעורך הדין. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)', 'חיסיון עו"ד-לקוח (ס'' 48 פקודת הראיות, ס'' 90 חוק לשכת עו"ד) ← דברים/מסמכים שהוחלפו + קשר ענייני לשירות מקצועי ← חיסיון מוחלט של הלקוח.', '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "בש\"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, מבוא", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, א. חיסיון עורך דין-לקוח, מהו?"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'המידע הוחלף בין עורך דין ללקוחו, ויש לו קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח.', true, 'תשובה זו נכונה, שכן אלו הם התנאים המפורשים הקבועים בסעיף 48 לפקודת הראיות ובסעיף 90 לחוק לשכת עורכי הדין.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'המידע הוחלף בין עורך דין ללקוחו, והלקוח ביקש במפורש לשמור על סודיותו.', false, 'טענה זו שגויה, שכן בקשה מפורשת של הלקוח לשמור על סודיות אינה תנאי לתחולת החיסיון, אלא תנאי לויתור עליו.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'המידע הוחלף בין עורך דין ללקוחו, וגילויו עלול לפגוע באינטרסים לגיטימיים של הלקוח.', false, 'טענה זו שגויה, שכן מידת הפגיעה באינטרסי הלקוח אינה תנאי לתחולת החיסיון, אלא שיקול באיזון במקרים חריגים של הסרת חיסיון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'המידע הוחלף בין עורך דין ללקוחו, והוא נוגע להליך משפטי תלוי ועומד.', false, 'טענה זו שגויה, שכן החיסיון חל גם על ייעוץ משפטי שאינו קשור להליך משפטי תלוי ועומד, ובלבד שיש לו קשר ענייני לשירות המקצועי.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q37';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'חריגים לחיסיון עורך דין-לקוח', 3,
      'עורך דין נאשם בעבירה פלילית יחד עם לקוחו, והמידע החסוי חיוני להגנתו של עורך הדין. האם החיסיון יחול במקרה זה?', 'שאלה זו עוסקת בחריגים לתחולת חיסיון עורך דין-לקוח, ובפרט במקרים בהם עורך הדין עצמו מעורב בעבירה או נתבע. היא מדגישה כי החיסיון אינו מגן על מעשי עבירה, וכי במקרים חריגים עשויה זכותו של עורך הדין להתגונן לגבור על החיסיון.', 'חיסיון עורך דין-לקוח חל רק על נושאים "שיש להם קשר ענייני לשירות המקצועי שניתן על-ידי עורך הדין ללקוח". בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008) מעשי עבירה שהלקוח ועורך הדין נאשמים בהם אינם חלק מן השירות המקצועי, ולכן החיסיון אינו חל עליהם מלכתחילה. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008) בנוסף, הפסיקה הכירה באפשרות, במקרים נדירים וחריגים, שזכותו של עורך הדין להתגונן מפני תביעות המוגשות נגדו תגבר על החיסיון. ח"ד (שלום תל אביב-יפו) 12/05 JXC JOREIGN ECONOMIC ASSOCIATION TECHNOSTROYEXPORT נ'' INTERNATIONAL DEVELOPMENT + TRADE SERVICES. INC. (03.07.2005) תנאי סף לכך הוא שהמידע יהיה רלוונטי ונחוץ להגנתו של עורך הדין. ח"ד (שלום תל אביב-יפו) 12/05 JXC JOREIGN ECONOMIC ASSOCIATION TECHNOSTROYEXPORT נ'' INTERNATIONAL DEVELOPMENT + TRADE SERVICES. INC. (03.07.2005)', 'הטעות הנפוצה היא לחשוב שהחיסיון מגן על עורך הדין גם כאשר הוא מעורב בעבירה עם לקוחו, או שאין כלל חריגים לחיסיון.',
      '["חיסיון עורך דין-לקוח", "חריגים לחיסיון", "מעשי עבירה", "זכות התגוננות", "קשר ענייני לשירות המקצועי", "איזון אינטרסים"]'::jsonb, '**וריאציה 1 — מעשי עבירה:** האם חיסיון חל על מעשי עבירה משותפים? ← לא, אינם חלק מהשירות המקצועי. בש"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)
**וריאציה 2 — הגנת עורך הדין:** מתי חיסיון עשוי לסגת לצורך הגנת עורך הדין? ← במקרים נדירים וחריגים, כשהמידע חיוני להגנתו. ח"ד (שלום תל אביב-יפו) 12/05 JXC JOREIGN ECONOMIC ASSOCIATION TECHNOSTROYEXPORT נ'' INTERNATIONAL DEVELOPMENT + TRADE SERVICES. INC. (03.07.2005)
**וריאציה 3 — פנייה לוועדת האתיקה:** מה מומלץ לעורך דין במקרה של ספק? ← לפנות לוועדת האתיקה לקבלת עמדתה. ח"ד (שלום תל אביב-יפו) 12/05 JXC JOREIGN ECONOMIC ASSOCIATION TECHNOSTROYEXPORT נ'' INTERNATIONAL DEVELOPMENT + TRADE SERVICES. INC. (03.07.2005)', 'חיסיון עו"ד-לקוח ← אינו חל על מעשי עבירה משותפים ← עשוי לסגת במקרים חריגים להגנת עו"ד ← מומלץ לפנות לוועדת האתיקה.', '["בש\"פ 10937/07 ליאורה ברקו נ'' מדינת ישראל (10.01.2008)", "ח\"ד (שלום תל אביב-יפו) 12/05 JXC JOREIGN ECONOMIC ASSOCIATION TECHNOSTROYEXPORT נ'' INTERNATIONAL DEVELOPMENT + TRADE SERVICES. INC. (03.07.2005)", "יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, א. חיסיון עורך דין-לקוח, מהו?"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, החיסיון הוא מוחלט ואינו נסוג גם במקרה של מעורבות עורך הדין בעבירה.', false, 'טענה זו שגויה, שכן החיסיון אינו חל על מעשי עבירה שהלקוח ועורך הדין נאשמים בהם, שכן אלה אינם חלק מהשירות המקצועי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, החיסיון אינו חל על מעשי עבירה שהלקוח ועורך הדין נאשמים בהם, וכן עשוי לסגת במקרים חריגים כאשר המידע חיוני להגנת עורך הדין מפני תביעה נגדו.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי מעשי עבירה אינם חלק מהשירות המקצועי, וכן הכירה באפשרות חשיפת מידע חסוי במקרים חריגים לצורך הגנת עורך הדין.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'לא, אך רק אם בית המשפט יורה על הסרת החיסיון לאחר איזון אינטרסים.', false, 'טענה זו שגויה, שכן החיסיון הוא מוחלט ובית המשפט אינו מוסמך להסירו, אלא אם הוא אינו חל מלכתחילה (כמו במעשי עבירה) או במקרים חריגים מאוד של הגנת עורך הדין.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'כן, אלא אם כן הלקוח ויתר על החיסיון במפורש.', false, 'טענה זו שגויה, שכן במקרה של מעורבות עורך הדין בעבירה, החיסיון אינו חל מלכתחילה, ללא קשר לויתור הלקוח.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q37';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'חובת סודיות על זהות הלקוח', 4,
      'עורך דין נדרש לחשוף את זהותו של לקוח שפנה אליו לייעוץ משפטי בעניין רגיש. האם חיסיון עורך דין-לקוח חל על זהותו של הלקוח?', 'שאלה זו עוסקת בסוגיה מורכבת בתחום חיסיון עורך דין-לקוח: האם החיסיון חל גם על זהותו של הלקוח. היא בוחנת את הכלל לפיו זהות הלקוח אינה חסויה ככלל, ואת החריגים לכלל זה, בהם חשיפת הזהות עלולה לפגוע בליבת החיסיון.', 'ככלל, חיסיון עורך דין-לקוח אינו חל על זהותו של הלקוח, על סוג השירות ועל מהות הטיפול, שכן אלה נחשבים לפרטים הקשורים ל"מעטפת ההתקשרות" ולא ל"ליבת החיסיון". יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח עם זאת, הפסיקה נסוגה מהקביעה הגורפת והביעה דעה כי כלל זה "אינו הרמטי". יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח במקרים חריגים, כאשר חשיפת זהותו של הלקוח עלולה לחשוף את תוכן ההתקשרות בין עורך הדין ללקוחו ולפגוע "בלב החיסיון", ניתן יהיה להרחיב את החיסיון ולהחילו גם על זהות הלקוח. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח דוגמאות לכך כוללות מצבים בהם חשיפת הזהות תקשר את הלקוח לעניין שלשמו התבקש הייעוץ המשפטי (כגון ייצוג בני חבורה המזוהה כארגון פשע), או כאשר לקוח מבקש להסגיר את עצמו ולהתוודות על פשע. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח', 'הטעות הנפוצה היא להניח שזהות הלקוח תמיד חסויה או תמיד גלויה, מבלי להבין את הניואנסים והחריגים שנקבעו בפסיקה.',
      '["חיסיון עורך דין-לקוח", "זהות הלקוח", "ליבת החיסיון", "חריגים לחיסיון", "מעטפת הייצוג", "איזון אינטרסים"]'::jsonb, '**וריאציה 1 — הכלל:** האם חיסיון חל על זהות הלקוח ככלל? ← לא, ככלל אינו חל. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח
**וריאציה 2 — החריג:** מתי חיסיון עשוי לחול על זהות הלקוח? ← כאשר חשיפת הזהות פוגעת בליבת החיסיון. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח
**וריאציה 3 — דוגמה לחריג:** דוגמה למקרה בו זהות הלקוח חסויה? ← לקוח המבקש להסגיר עצמו ולהתוודות על פשע. יניב ואקי דיני ראיות כרך ג (2021) | חיסיון על זהות הלקוח', 'חיסיון על זהות הלקוח ← ככלל לא חל ← חריג: אם חשיפת הזהות פוגעת בליבת החיסיון (למשל, חשיפת פשע).', '["יניב ואקי, דיני ראיות כרך ג (2021), פרק 54 חיסיון עורך דין-לקוח, ב. חיסיון על זהות הלקוח"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, חיסיון עורך דין-לקוח חל תמיד על זהות הלקוח, שכן היא חלק בלתי נפרד מההתקשרות המקצועית.', false, 'טענה זו שגויה, שכן ככלל, החיסיון אינו חל על זהות הלקוח, אלא אם מתקיימים חריגים ספציפיים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, ככלל החיסיון אינו חל על זהות הלקוח, אלא אם חשיפת הזהות עלולה לחשוף את תוכן ההתקשרות המקצועית ולפגוע בליבת החיסיון.', true, 'תשובה זו נכונה, שכן הפסיקה קבעה כי זהות הלקוח אינה חסויה ככלל, אך הכירה בחריגים בהם חשיפת הזהות פוגעת בליבת החיסיון.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הלקוח הוא אדם מפורסם וגילוי זהותו עלול לגרום לו נזק תדמיתי.', false, 'טענה זו שגויה, שכן מעמד הלקוח או נזק תדמיתי אינם קריטריונים לתחולת החיסיון על זהותו, אלא הקשר לתוכן ההתקשרות המקצועית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, חיסיון עורך דין-לקוח חל רק על תוכן הייעוץ המשפטי, ולא על פרטים טכניים כמו זהות הלקוח.', false, 'טענה זו שגויה, שכן למרות שהחיסיון מתמקד בתוכן הייעוץ, ישנם מקרים בהם זהות הלקוח קשורה באופן הדוק לתוכן הייעוץ ולליבת החיסיון.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q37';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 37, '2024-W-S-Q37';
END
$$;

-- ============================================================
-- Q38 — angles backfill for 2024-W-S-Q38 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q38';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q38';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'תרומה ללא צידוק עסקי', 1,
      'חברת "ירקות לכול" מעוניינת לתרום 5,000 מארזי ירקות טריים לעמותה הפועלת למען ילדים נזקקים, מתוך רצון טהור לתרום לקהילה, ללא כל ציפייה לתועלת עסקית או פרסום. האם החברה רשאית לבצע תרומה זו?', 'שאלה זו בוחנת את החריג בסעיף 11(א) לחוק החברות, המאפשר לחברה לתרום סכום סביר למטרה ראויה, אף אם התרומה אינה במסגרת שיקולים עסקיים, ובלבד שנקבעה לכך הוראה בתקנון. היא מדגישה את ההבחנה בין תרומה משיקולים עסקיים לבין תרומה פילנתרופית טהורה.', 'סעיף 11(א) לחוק החברות, תשנ"ט-1999, קובע כי תכלית חברה היא לפעול על פי שיקולים עסקיים להשאת רווחיה. סעיף 11(א) לחוק החברות, תשנ"ט-1999 עם זאת, הסעיף מוסיף וקובע כי "כמו כן רשאית חברה לתרום סכום סביר למטרה ראויה, אף אם התרומה אינה במסגרת שיקולים עסקיים כאמור, אם נקבעה לכך הוראה בתקנון". סעיף 11(א) לחוק החברות, תשנ"ט-1999 כלומר, החוק מאפשר לחברה לבצע תרומות שאינן נובעות משיקולים עסקיים, בתנאי שהן עומדות בשלושה קריטריונים מצטברים: 1. התרומה היא בסכום סביר. 2. התרומה היא למטרה ראויה. 3. נקבעה לכך הוראה בתקנון החברה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה במקרה זה, מדובר בתרומה מתוך רצון טהור לתרום לקהילה, ללא ציפייה לתועלת עסקית. לכן, על מנת שהתרומה תהיה כדין, נדרשת הוראה מתאימה בתקנון החברה. יוסף גרוס דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018) | פרק ב: תכלית החברה כמצפן לפעילות הדירקטוריון', 'הטעות הנפוצה היא לחשוב שכל תרומה, ללא קשר למניעיה, דורשת הוראה בתקנון, או לחילופין, שכל תרומה מותרת ללא כל הגבלה.',
      '["תכלית החברה", "סעיף 11(א) לחוק החברות", "תרומה ללא שיקולים עסקיים", "סכום סביר", "מטרה ראויה", "הוראה בתקנון"]'::jsonb, '**וריאציה 1 — תרומה פילנתרופית:** האם חברה יכולה לתרום ללא צידוק עסקי? ← כן, אם התרומה בסכום סביר למטרה ראויה ונקבעה לכך הוראה בתקנון. סעיף 11(א) לחוק החברות, תשנ"ט-1999
**וריאציה 2 — תרומה עסקית:** האם תרומה משיקולים עסקיים דורשת הוראה בתקנון? ← לא, היא נכללת במסגרת שיקולים עסקיים להשאת רווחים. סעיף 11(א) לחוק החברות, תשנ"ט-1999
**וריאציה 3 — מונחי שסתום:** מהם "סכום סביר" ו"מטרה ראויה"? ← מונחי שסתום שיש לפרשם בהתאם לנסיבות, רצוי לקבוע בתקנון. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה', 'תרומה ללא צידוק עסקי (ס'' 11(א) לחוק החברות) ← מותרת אם סכום סביר + מטרה ראויה + הוראה בתקנון.', '["חוק החברות, תשנ\"ט-1999, סעיף 11(א)", "יוסף גרוס, חוק החברות (מהדורה חמישית, 2016), פרק ו: תכלית החברה, עמ'' 12", "יוסף גרוס, דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018), פרק ב: תכלית החברה כמצפן לפעילות הדירקטוריון, עמ'' 9"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, החברה רשאית לתרום סכום סביר למטרה ראויה, גם אם התרומה אינה במסגרת שיקולים עסקיים, ובלבד שנקבעה לכך הוראה בתקנון.', true, 'תשובה זו נכונה, שכן סעיף 11(א) לחוק החברות מאפשר תרומה שאינה במסגרת שיקולים עסקיים, בתנאי שהיא בסכום סביר למטרה ראויה ונקבעה לכך הוראה בתקנון.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, החברה אינה רשאית לתרום ללא צידוק עסקי, שכן תכליתה העיקרית היא השאת רווחים לבעלי מניותיה.', false, 'טענה זו שגויה, שכן סעיף 11(א) לחוק החברות מאפשר תרומה שאינה במסגרת שיקולים עסקיים, בכפוף לתנאים מסוימים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, החברה רשאית לתרום ללא הגבלה, שכן תרומה לקהילה היא חלק מהאחריות החברתית של תאגידים מודרניים.', false, 'טענה זו שגויה, שכן החוק מגביל את האפשרות לתרום ללא צידוק עסקי בכך שהתרומה צריכה להיות בסכום סביר למטרה ראויה ודורשת הוראה בתקנון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן כל בעלי המניות הסכימו פה אחד לתרומה, שכן היא פוגעת ברווחי החברה.', false, 'טענה זו שגויה, שכן החוק קובע מנגנון ספציפי לתרומות שאינן עסקיות (הוראה בתקנון), ואינו דורש הסכמה פה אחד של בעלי המניות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q38';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'מבחני סבירות התרומה', 2,
      'חברה בתחום ההייטק מעוניינת לתרום סכום משמעותי של 500,000 ש"ח לעמותה המקדמת חינוך טכנולוגי בפריפריה, מתוך אמונה שזה יתרום לפיתוח עובדים פוטנציאליים בעתיד. בתקנון החברה קיימת הוראה כללית המאפשרת תרומות למטרות ראויות. מהם השיקולים שעל הדירקטוריון לבחון כדי לוודא שהתרומה עומדת במבחן ה"סכום הסביר" ו"מטרה ראויה"?', 'שאלה זו מתמקדת בפרשנות מונחי השסתום "סכום סביר" ו"מטרה ראויה" בהקשר של תרומות חברה, כפי שמופיעים בסעיף 11(א) לחוק החברות. היא בוחנת את השיקולים שעל הדירקטוריון להפעיל בעת קבלת החלטה על תרומה, תוך התייחסות למצבה הפיננסי של החברה ולקשר בין פעילותה למטרת התרומה.', 'סעיף 11(א) לחוק החברות מאפשר לחברה לתרום "סכום סביר למטרה ראויה". סעיף 11(א) לחוק החברות, תשנ"ט-1999 מונחים אלו הם "מונחי שסתום" שיש לפרשם בהתאם לנסיבות. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה על הדירקטוריון, שהוא האורגן המוסמך לקבוע מדיניות, לבחון מספר שיקולים: 1. מצבה הפיננסי של החברה: הסכומים חייבים להיות מותאמים למצבה הפיננסי של החברה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה 2. היקף התרומה: התרומה צריכה להיות בסכום סביר, כלומר, לא תפגע בבעלי המניות באופן ניכר. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה 3. קשר למטרות החברה: רצוי שיהיה קשר מסוים בין פעילות החברה לתרומה, ולא תהא רחוקה ממטרות החברה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה אין צורך להוכיח תועלת מיידית לחברה, אך המניע לתרומה רצוי שיהיה קשור למטרותיה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה', 'הטעות הנפוצה היא להתייחס ל"סכום סביר" ו"מטרה ראויה" כאל קריטריונים אובייקטיביים ומוחלטים, מבלי להבין שהם דורשים הפעלת שיקול דעת בהתאם לנסיבות הספציפיות של החברה והתרומה.',
      '["סעיף 11(א) לחוק החברות", "סכום סביר", "מטרה ראויה", "שיקול דעת דירקטוריון", "מצב פיננסי של החברה", "קשר לפעילות החברה"]'::jsonb, '**וריאציה 1 — סבירות הסכום:** מהם השיקולים לקביעת "סכום סביר"? ← מצב פיננסי של החברה והיקף התרומה ביחס לרווחיה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה
**וריאציה 2 — מטרה ראויה:** מהם השיקולים לקביעת "מטרה ראויה"? ← קשר בין פעילות החברה למטרת התרומה, גם ללא תועלת מיידית. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה
**וריאציה 3 — אורגן מוסמך:** מי האורגן המוסמך להחליט על תרומה? ← הדירקטוריון, כקובע מדיניות. יוסף גרוס דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018) | פרק ב: תכלית החברה כמצפן לפעילות הדירקטוריון', 'סבירות תרומה (ס'' 11(א) לחוק החברות) ← תלויה במצב פיננסי, היקף, וקשר למטרות החברה ← הדירקטוריון מחליט.', '["חוק החברות, תשנ\"ט-1999, סעיף 11(א)", "יוסף גרוס, חוק החברות (מהדורה חמישית, 2016), פרק ו: תכלית החברה, עמ'' 12", "יוסף גרוס, דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018), פרק ב: תכלית החברה כמצפן לפעילות הדירקטוריון, עמ'' 9"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הדירקטוריון צריך לבחון את מצבה הפיננסי של החברה, את היקף התרומה ביחס לרווחיה ונכסיה, ואת הקשר בין פעילות החברה למטרת התרומה.', true, 'תשובה זו נכונה, שכן אלו הם השיקולים המרכזיים הנגזרים ממונחי השסתום "סכום סביר" ו"מטרה ראויה", כפי שפורשו בספרות המשפטית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הדירקטוריון צריך לבחון רק את מצבה הפיננסי של החברה, שכן גובה התרומה הוא השיקול היחיד לקביעת סבירותה.', false, 'טענה זו שגויה, שכן בנוסף למצב הפיננסי, יש לבחון גם את הקשר בין התרומה לפעילות החברה ואת אופייה של המטרה הנתרמת.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הדירקטוריון צריך לבחון רק את מידת התועלת המיידית שתצמח לחברה מהתרומה, שכן תרומה חייבת להיות בעלת צידוק עסקי מובהק.', false, 'טענה זו שגויה, שכן תרומה יכולה להיות למטרה ראויה גם ללא תועלת עסקית מיידית, ובלבד שנקבעה לכך הוראה בתקנון.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הדירקטוריון צריך לבחון רק את אישור האסיפה הכללית, שכן הסכמת בעלי המניות פוטרת מכל בדיקה נוספת.', false, 'טענה זו שגויה, שכן גם אם האסיפה הכללית אישרה, הדירקטוריון עדיין חייב לפעול בשיקול דעת סביר ולבחון את עמידת התרומה בתנאי החוק.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q38';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'תכלית חברה לתועלת הציבור', 3,
      'חברת "אור ירוק" היא חברה לתועלת הציבור, אשר מטרתה העיקרית היא קידום הבטיחות בדרכים. החברה מעוניינת להשקיע את עודפיה הכספיים בפיתוח טכנולוגיות חדשניות להפחתת תאונות דרכים, גם אם הדבר לא יניב רווחים כלכליים בטווח הקצר. האם פעולה זו עולה בקנה אחד עם תכליתה של חברה לתועלת הציבור?', 'שאלה זו עוסקת בתכליתה הייחודית של חברה לתועלת הציבור, כפי שנקבעה בסעיף 11(ב) לחוק החברות. היא מדגישה את ההבדל המהותי בין חברה עסקית, שתכליתה השאת רווחים, לבין חברה לתועלת הציבור, שתכליתה קידום מטרות ציבוריות, ופטורה מחובת השאת רווחים.', 'סעיף 11(א) לחוק החברות קובע כי תכלית חברה היא לפעול על פי שיקולים עסקיים להשאת רווחיה. סעיף 11(א) לחוק החברות, תשנ"ט-1999 אולם, סעיף 11(ב) לחוק החברות קובע חריג מפורש: "הוראת סעיף קטן (א) לא תחול על חברה לתועלת הציבור". סעיף 11(ב) לחוק החברות, תשנ"ט-1999 משמעות הדבר היא שתכליתה של חברה לתועלת הציבור אינה השאת רווחים, אלא קידום מטרות ציבוריות. זוהר גושן אסף אקשטיין דיני חברות (2023) | פרק יב תכלית החברה חברה כזו מוקמת להשגת מטרות ציבוריות בלבד, ותקנונה אוסר חלוקת רווחים לבעלי מניותיה. אירית חביב-סגל דיני חברות - כרך ב (2007) | פרק ג: ניגודי אינטרסים בין המשקיעים ותכלית החברה לפיכך, השקעה בפיתוח טכנולוגיות חדשניות להפחתת תאונות דרכים, גם אם אינה מניבה רווחים כלכליים בטווח הקצר, עולה בקנה אחד עם תכליתה של חברת "אור ירוק" כחברה לתועלת הציבור, שכן היא משרתת את מטרתה הציבורית. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)', 'הטעות הנפוצה היא להחיל את תכלית השאת הרווחים על כל סוגי החברות, מבלי להבחין בחריג המפורש של חברה לתועלת הציבור.',
      '["חברה לתועלת הציבור", "סעיף 11(ב) לחוק החברות", "תכלית החברה", "מטרות ציבוריות", "השאת רווחים", "חלוקת רווחים"]'::jsonb, '**וריאציה 1 — תכלית חלופית:** מהי תכלית חברה לתועלת הציבור? ← קידום מטרות ציבוריות, לא השאת רווחים. סעיף 11(ב) לחוק החברות, תשנ"ט-1999
**וריאציה 2 — איסור חלוקת רווחים:** מהו תנאי מהותי לחברה לתועלת הציבור? ← תקנונה אוסר חלוקת רווחים לבעלי מניותיה. אירית חביב-סגל דיני חברות - כרך ב (2007) | פרק ג: ניגודי אינטרסים בין המשקיעים ותכלית החברה
**וריאציה 3 — השוואה לאגודה שיתופית:** האם אגודה שיתופית דומה לחברה לתועלת הציבור? ← לא, אגודה שיתופית נועדה לשפר מצב כלכלי של חבריה, אך לא מצטמצמת לאינטרס כלכלי צר. ת"א (מחוזי מרכז) 35157-04-14 אהרון אינדיך נ'' אגד אגודה שיתופית לתחבורה לישראל בע"מ (26.02.2024)', 'חברה לתועלת הציבור (ס'' 11(ב) לחוק החברות) ← תכליתה קידום מטרות ציבוריות ← פטורה מחובת השאת רווחים.', '["חוק החברות, תשנ\"ט-1999, סעיף 11(ב)", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק יב תכלית החברה, עמ'' 3", "אירית חביב-סגל, דיני חברות - כרך ב (2007), פרק ג: ניגודי אינטרסים בין המשקיעים ותכלית החברה, עמ'' 12", "רע\"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית\"ר בע\"מ (09.11.2025)", "ת\"א (מחוזי מרכז) 35157-04-14 אהרון אינדיך נ'' אגד אגודה שיתופית לתחבורה לישראל בע\"מ (26.02.2024)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, שכן תכליתה של חברה לתועלת הציבור אינה השאת רווחים, אלא קידום מטרות ציבוריות.', true, 'תשובה זו נכונה, שכן סעיף 11(ב) לחוק החברות קובע במפורש כי הוראת סעיף קטן (א) (השאת רווחים) לא תחול על חברה לתועלת הציבור.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, שכן גם חברה לתועלת הציבור חייבת לפעול על פי שיקולים עסקיים להשאת רווחיה, אלא אם כן נקבע אחרת בתקנון.', false, 'טענה זו שגויה, שכן סעיף 11(ב) לחוק החברות פוטר במפורש חברה לתועלת הציבור מחובת השאת רווחים.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם פיתוח הטכנולוגיות יניב רווחים בטווח הארוך, שכן גם חברה לתועלת הציבור צריכה להיות בת קיימא כלכלית.', false, 'טענה זו שגויה, שכן תכליתה של חברה לתועלת הציבור אינה השאת רווחים, ואין חובה שהשקעותיה יניבו רווחים כלכליים, אלא שיקדמו את מטרותיה הציבוריות.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, שכן חברה לתועלת הציבור אינה רשאית להשקיע את עודפיה הכספיים בפיתוח טכנולוגיות, אלא רק בפעילות ישירה לקידום מטרותיה.', false, 'טענה זו שגויה, שכן השקעה בפיתוח טכנולוגיות יכולה להיות דרך לקידום מטרותיה הציבוריות של החברה, ואין הגבלה על אופן השימוש בעודפים כל עוד הוא משרת את התכלית.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q38';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'השאת רווחים מול אינטרסים אחרים', 4,
      'האם סעיף 11(א) לחוק החברות מאפשר לחברה להביא בחשבון את ענייניהם של נושיה, עובדיה והציבור, גם כאשר הדבר מתנגש עם המטרה של השאת רווחיה?', 'שאלה זו עוסקת בפרשנות סעיף 11(א) לחוק החברות, ובמתח שבין תכלית השאת רווחי החברה לבין האפשרות להביא בחשבון את ענייניהם של נושיה, עובדיה והציבור. היא בוחנת את הגישה המקובלת בפסיקה ובספרות, לפיה קיימת היררכיה ברורה, ותכלית השאת הרווחים היא העיקרית.', 'סעיף 11(א) לחוק החברות קובע כי "תכלית חברה היא לפעול על פי שיקולים עסקיים להשאת רווחיה, וניתן להביא בחשבון במסגרת שיקולים אלה, בין השאר, את עניניהם של נושיה, עובדיה ואת ענינו של הציבור". סעיף 11(א) לחוק החברות, תשנ"ט-1999 הפסיקה והספרות מפרשות סעיף זה כיוצר היררכיה מפורשת, כאשר השאת רווחים מוגדרת כתכלית העסקית הראשית. ע"א 8416/19 עו"ד שלמה נס ורו"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע"מ נ'' מדינת ישראל (22.12.2021) שיקולים עסקיים הם אלה המנחים את פעילותה של חברה, וניתן "להביא בחשבון" מעגל זיקות נוסף (נושים, עובדים, ציבור) רק במסגרת שיקולים אלה. ע"פ 6790/18 משה טטרו נ'' מדינת ישראל (29.07.2020) כלומר, ההתחשבות באינטרסים אלו עשויה להשפיע על רווחי החברה, אך לא כאשר היא מתנגשת עם המטרה של השאת רווחי החברה. יוסף גרוס חוק החברות (2016) | פרק ו: תכלית החברה', 'הטעות הנפוצה היא לפרש את סעיף 11(א) כמאפשר איזון שווה בין השאת רווחים לבין אינטרסים אחרים, מבלי להבין את ההיררכיה שנקבעה בחוק ובפסיקה.',
      '["תכלית החברה", "סעיף 11(א) לחוק החברות", "השאת רווחים", "אינטרסים של נושים", "אינטרסים של עובדים", "אינטרסים של הציבור", "היררכיה"]'::jsonb, '**וריאציה 1 — תכלית ראשית:** מהי התכלית הראשית של חברה? ← השאת רווחים. סעיף 11(א) לחוק החברות, תשנ"ט-1999
**וריאציה 2 — מעגל זיקות נוסף:** מתי ניתן להביא בחשבון אינטרסים של נושים/עובדים/ציבור? ← במסגרת שיקולים עסקיים התומכים בהשאת רווחים. ע"א 8416/19 עו"ד שלמה נס ורו"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע"מ נ'' מדינת ישראל (22.12.2021)
**וריאציה 3 — חברות ממשלתיות:** האם לחברות ממשלתיות תכלית שונה? ← כן, הממשלה יכולה לקבוע להן "שיקולי פעולה אחרים". בג"ץ 5474/23 חברת דואר ישראל בע"מ נ'' שר התקשורת (07.03.2024)', 'סעיף 11(א) לחוק החברות ← תכלית ראשית: השאת רווחים ← אינטרסים אחרים נשקלים רק במסגרת שיקולים עסקיים התומכים ברווחים.', '["חוק החברות, תשנ\"ט-1999, סעיף 11(א)", "ע\"א 8416/19 עו\"ד שלמה נס ורו\"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע\"מ נ'' מדינת ישראל (22.12.2021)", "ע\"פ 6790/18 משה טטרו נ'' מדינת ישראל (29.07.2020)", "יוסף גרוס, חוק החברות (מהדורה חמישית, 2016), פרק ו: תכלית החברה, עמ'' 3", "בג\"ץ 5474/23 חברת דואר ישראל בע\"מ נ'' שר התקשורת (07.03.2024)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, סעיף 11(א) יוצר דואליות המאפשרת איזון בין השאת רווחים לבין אינטרסים חברתיים וציבוריים, גם במחיר פגיעה ברווחים.', false, 'טענה זו שגויה, שכן למרות הדואליות, תכלית השאת הרווחים נותרה העיקרית, ואינטרסים אחרים נשקלים במסגרת שיקולים עסקיים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, תכלית החברה היא השאת רווחיה, וניתן להביא בחשבון אינטרסים של נושים, עובדים וציבור רק במסגרת שיקולים עסקיים התומכים בהשאת רווחים, ולא כאשר הם מתנגשים עמה.', true, 'תשובה זו נכונה, שכן הפסיקה והספרות מפרשות את סעיף 11(א) כיוצר היררכיה ברורה, בה השאת רווחים היא התכלית העיקרית.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הדבר נקבע במפורש בתקנון החברה, שכן תקנון יכול לשנות את תכלית החברה.', false, 'טענה זו שגויה, שכן סעיף 11(א) הוא הוראה קוגנטית לגבי תכלית השאת הרווחים, ואין אפשרות לשנותה בתקנון, למעט חברה לתועלת הציבור.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן מדובר בחברה ממשלתית, שלגביה נקבעו שיקולי פעולה אחרים.', false, 'טענה זו שגויה, שכן למרות שלחברות ממשלתיות יש שיקולי פעולה אחרים, הכלל לגבי חברות פרטיות נשאר שתכליתן היא השאת רווחים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q38';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 38, '2024-W-S-Q38';
END
$$;

-- ============================================================
-- Q39 — angles backfill for 2024-W-S-Q39 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q39';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q39';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'זיקת הנאה מכוח שנים', 1,
      'ירון משתמש בשביל העובר בחלקה של מיכל במשך 35 שנה, ללא הסכם בכתב וללא התנגדות מצד מיכל. כעת, מיכל דורשת מירון להפסיק לעבור בשבילה. מה הדין?', 'שאלה זו עוסקת ברכישת זיקת הנאה מכוח שנים, כפי שקבוע בסעיף 94 לחוק המקרקעין. היא בוחנת את התנאים המצטברים הנדרשים לרכישת זכות זו, ובפרט את משמעות השימוש הרצוף והיעדר התנגדות מצד בעל המקרקעין הכפופים.', 'סעיף 94(א) לחוק המקרקעין, תשכ"ט-1969, קובע כי "מי שהשתמש בזכות הראויה להוות זיקת הנאה במשך תקופה של שלושים שנים רצופות רכש את הזיקה והוא זכאי לדרוש רישומה". ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019) סעיף 94(ב) מוסיף כי "הודעה בכתב של בעל המקרקעין למי שמשתמש בזכות כאמור, לרבות הודעה לציבור, שהוא מתנגד לשימוש בזכות, מפסיקה את התקופה האמורה בסעיף קטן (א)". ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019) במקרה זה, ירון השתמש בשביל במשך 35 שנה, שהיא תקופה העולה על 30 השנים הנדרשות, ומיכל מעולם לא התנגדה לשימוש. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019) לפיכך, ירון רכש זיקת הנאה מכוח שנים והוא זכאי לדרוש את רישומה. יעקב שקד פינוי מקרקעין – הליכים והלכות (2024) | פרק שניים-עשר התיישנות במקרקעין', 'הטעות הנפוצה היא לבלבל בין רשות שימוש הדירה לבין זיקת הנאה מכוח שנים, או לחשוב שנדרשת הסכמה מפורשת של בעל המקרקעין כדי לרכוש זיקת הנאה מכוח שנים.',
      '["זיקת הנאה מכוח שנים", "חוק המקרקעין סעיף 94", "שימוש רצוף", "התנגדות בכתב", "זכות קניינית", "רישום זיקת הנאה"]'::jsonb, '**וריאציה 1 — תנאי הרכישה:** מהם התנאים לרכישת זיקת הנאה מכוח שנים? ← שימוש בזכות הראויה לזיקת הנאה במשך 30 שנה רצופות. ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)
**וריאציה 2 — הפסקת המרוץ:** מה מפסיק את מרוץ 30 השנים? ← הודעה בכתב של בעל המקרקעין על התנגדות לשימוש. ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)
**וריאציה 3 — מהות הזכות:** האם זיקת הנאה מכוח שנים היא זכות קניינית? ← כן, היא זכות קניינית הניתנת לרישום. יעקב שקד פינוי מקרקעין – הליכים והלכות (2024) | פרק שניים-עשר התיישנות במקרקעין', 'זיקת הנאה מכוח שנים (ס'' 94 לחוק המקרקעין) ← נרכשת בשימוש רצוף 30 שנה ← ללא התנגדות בכתב ← מקנה זכות קניינית לרישום.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 94", "ת\"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)", "ת\"א (מחוזי ת\"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)", "יעקב שקד, פינוי מקרקעין – הליכים והלכות (2024), פרק שניים-עשר התיישנות במקרקעין, עמ'' 29"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'ירון רכש זיקת הנאה מכוח שנים, והוא זכאי לדרוש את רישומה.', true, 'תשובה זו נכונה, שכן שימוש בזכות הראויה להוות זיקת הנאה במשך 30 שנה רצופות, ללא התנגדות בעל המקרקעין, מקנה זכות לרישום זיקת הנאה מכוח שנים, לפי סעיף 94(א) לחוק המקרקעין.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'ירון אינו יכול לרכוש זיקת הנאה ללא הסכם בכתב ורישום אצל רשם המקרקעין.', false, 'טענה זו שגויה, שכן סעיף 94 לחוק המקרקעין מאפשר רכישת זיקת הנאה מכוח שנים גם ללא הסכם ורישום מוקדם.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'מיכל רשאית למנוע מירון את המעבר, שכן שתיקתה אינה מהווה הסכמה קניינית.', false, 'טענה זו שגויה, שכן שתיקה במשך 30 שנה, בהיעדר התנגדות בכתב, מאפשרת רכישת זיקת הנאה מכוח שנים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'ירון רכש רשות שימוש במקרקעין, אך מיכל רשאית לבטלה בכל עת.', false, 'טענה זו שגויה, שכן שימוש רצוף במשך 35 שנה, ללא התנגדות, עולה כדי זיקת הנאה מכוח שנים, שהיא זכות קניינית, ולא רשות שימוש הדירה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q39';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאי השימוש הנוגד בזיקת הנאה מכוח שנים', 2,
      'מהם התנאים המצטברים לשימוש שמאפשר רכישת זיקת הנאה מכוח שנים, כפי שנקבע בפסיקה?', 'שאלה זו מתמקדת באופיו ותכונותיו של השימוש הנדרש לרכישת זיקת הנאה מכוח שנים, כפי שפורש בפסיקה, ובפרט בעניין אסטרחאן. היא מדגישה את הדרישה ל"שימוש נוגד" ואת ההבחנה בינו לבין שימוש שנעשה בהסכמה.', 'הפסיקה, ובראשה עניין אסטרחאן, קבעה שלושה תנאים מצטברים לרכישת זיקת הנאה מכוח שנים, כאשר התנאי השני נוגע לאופיו ותכונותיו של השימוש. ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019) תכונותיו היסודיות של שימוש המאפשר רכישת זיקת הנאה מכוח שנים הן: 1. שימוש נוגד לזכות הבעלים של המקרקעין הכפופים: השימוש חייב להוות הפרה של זכויות הבעלים, ולא לנבוע מהסכמה (מפורשת או מכללא) של הבעלים. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019) 2. שימוש גלוי וחשוף לעין כל: דרישה זו מאפשרת לבעל המקרקעין לדעת על השימוש ולהפעיל את זכותו להתנגד. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019) 3. שימוש הנמצא בידיעתו הקונסטרוקטיבית של בעל המקרקעין הכפופים: די בכך שיכול היה להיות מודע לשימוש, ואין ידיעתו בפועל מעלה או מורידה. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019) 4. שמקורו אינו בזכות חוזית או בזכות אחרת שהוענקה על ידי בעל המקרקעין הכפופים למשתמש: שימוש מכוח הסכם אינו יכול להבשיל לזיקת הנאה מכוח שנים. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)', 'הטעות הנפוצה היא להתעלם מדרישת ה"שימוש הנוגד" ולחשוב שכל שימוש רצוף, גם אם בהסכמה, יכול להקנות זיקת הנאה מכוח שנים.',
      '["זיקת הנאה מכוח שנים", "שימוש נוגד", "גלוי וחשוף", "ידיעה קונסטרוקטיבית", "הסכמה מכללא", "עניין אסטרחאן"]'::jsonb, '**וריאציה 1 — שימוש נוגד:** מהו שימוש נוגד? ← שימוש המהווה הפרה של זכויות הבעלים, ולא נובע מהסכמה. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)
**וריאציה 2 — גלוי וחשוף:** מדוע השימוש צריך להיות גלוי? ← כדי לאפשר לבעל המקרקעין להתנגד לשימוש. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)
**וריאציה 3 — הסכמה שוללת:** האם הסכמה (גם משתמעת) שוללת שימוש נוגד? ← כן, שימוש בהסכמה אינו יכול להבשיל לזיקת הנאה מכוח שנים. ת"א (מחוזי ת"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)', 'שימוש נוגד (זיקת הנאה מכוח שנים) ← גלוי, בידיעה קונסטרוקטיבית, לא מכוח הסכמה ← מהווה הפרה של זכויות הבעלים.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 94", "ת\"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)", "ת\"א (מחוזי ת\"א) 24235-06-15 גרשון דושניצקי נ'' אלון בן דרור (29.12.2019)", "יעקב שקד, פינוי מקרקעין – הליכים והלכות (2024), פרק שניים-עשר התיישנות במקרקעין, עמ'' 29"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'שימוש נוגד לזכות הבעלים של המקרקעין הכפופים, גלוי וחשוף לעין כל, בידיעה קונסטרוקטיבית של הבעלים, ושאינו נובע מזכות חוזית או אחרת שהוענקה על ידי הבעלים.', true, 'תשובה זו נכונה, שכן אלו הם התנאים המצטברים שנקבעו בפסיקה (עניין אסטרחאן) לשימוש המאפשר רכישת זיקת הנאה מכוח שנים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'שימוש שנעשה בתום לב, גלוי וחשוף לעין כל, ובידיעה בפועל של בעל המקרקעין הכפופים.', false, 'טענה זו שגויה, שכן השימוש אינו חייב להיות בתום לב, ונדרשת ידיעה קונסטרוקטיבית ולאו דווקא בפועל.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שימוש שנעשה בהסכמת בעל המקרקעין הכפופים, ובלבד שההסכמה לא ניתנה בכתב.', false, 'טענה זו שגויה, שכן שימוש בהסכמה (גם משתמעת) אינו יכול להבשיל לזיקת הנאה מכוח שנים, שכן הוא אינו "שימוש נוגד".', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'שימוש שאינו פוגע בערך המקרקעין הכפופים, ובלבד שבעל המקרקעין לא התנגד לו בכתב.', false, 'טענה זו שגויה, שכן אי פגיעה בערך אינה תנאי, והדרישה המרכזית היא לשימוש נוגד, ולא רק היעדר התנגדות.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q39';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'ביטול זיקת הנאה עקב שינוי נסיבות', 3,
      'למיכל יש זיקת הנאה רשומה למעבר דרך חלקה של ירון. כעת ירון מעוניין לבנות על חלק מהחלקה, והמעבר מפריע לו באופן משמעותי. למיכל קיימת דרך חלופית נוחה למעבר. האם בית המשפט יבטל את זיקת ההנאה של מיכל?', 'שאלה זו עוסקת בסמכות בית המשפט לבטל או לשנות זיקת הנאה, כפי שקבוע בסעיף 96 לחוק המקרקעין. היא בוחנת את העילות לביטול (שינוי בנסיבות השימוש או במצב המקרקעין) ואת שיקולי האיזון שעל בית המשפט להפעיל, לרבות פסיקת פיצויים.', 'סעיף 96 לחוק המקרקעין, תשכ"ט-1969, קובע כי "זיקת הנאה היא לתקופה בלתי מוגבלת, זולת אם נקבעה לה תקופה בתנאי הזיקה; אולם בית המשפט רשאי, על פי בקשת צד מעונין או היועץ המשפטי לממשלה, לבטל את הזיקה או לשנות תנאיה, אם ראה לעשות כן בגלל אי הפעלת הזיקה או בגלל שינוי בנסיבות השימוש בה או במצב המקרקעין הזכאים או הכפופים; ורשאי בית המשפט לפסוק פיצוי למי שנגרם לו נזק על ידי הביטול או השינוי". סעיף 96 לחוק המקרקעין, תשכ"ט-1969 מטרת סעיף 96 היא למנוע היווצרות זכויות העלולות להכביד או לשתק את ההתפתחות הכלכלית במקרקעין המשועבדים לזיקת הנאה. אבי וינרוט דיני קניין - פרקי יסוד (2024) | פרק ח זיקת הנאה ((Easement בית המשפט יבחן האם השעבוד מסכל את פיתוח הקרקע, האם ביטול הזיקה יגרום להפסד תועלת העולה על הרווח הצפוי מפיתוח הקרקע, והאם הביטול יגרום נזק לבעלים. אבי וינרוט דיני קניין - פרקי יסוד (2024) | פרק ח זיקת הנאה ((Easement במקרה זה, רצונו של ירון לבנות על חלק מהחלקה, וקיומה של דרך חלופית למיכל, מהווים שינוי נסיבות המצדיק הפעלת סמכות בית המשפט. ת"א (שלום פ"ת) 55046-09-14 מרדכי ביסטרה נ'' עיריית יהוד מונוסון (11.06.2019) בית המשפט יאזן בין האינטרסים ויפסוק פיצוי למיכל אם ייגרם לה נזק. ת"א (שלום פ"ת) 55046-09-14 מרדכי ביסטרה נ'' עיריית יהוד מונוסון (11.06.2019)', 'הטעות הנפוצה היא לחשוב שזיקת הנאה, בהיותה זכות קניינית, אינה ניתנת לביטול או שינוי, או להתעלם מהצורך באיזון אינטרסים ופסיקת פיצויים.',
      '["סעיף 96 לחוק המקרקעין", "ביטול זיקת הנאה", "שינוי נסיבות", "איזון אינטרסים", "פיצויים", "מקרקעין כפופים"]'::jsonb, '**וריאציה 1 — סמכות בית המשפט:** מתי בית המשפט רשאי לבטל זיקת הנאה? ← בגלל אי הפעלת הזיקה, או שינוי בנסיבות השימוש/מצב המקרקעין. סעיף 96 לחוק המקרקעין, תשכ"ט-1969
**וריאציה 2 — מטרת הסעיף:** מהי מטרת סעיף 96? ← למנוע הכבדה או שיתוק של התפתחות כלכלית במקרקעין. אבי וינרוט דיני קניין - פרקי יסוד (2024) | פרק ח זיקת הנאה ((Easement
**וריאציה 3 — פיצויים:** האם ניתן לפסוק פיצויים בגין ביטול זיקה? ← כן, למי שנגרם לו נזק. סעיף 96 לחוק המקרקעין, תשכ"ט-1969', 'ביטול זיקת הנאה (ס'' 96 לחוק המקרקעין) ← עקב שינוי נסיבות/אי הפעלה ← ביהמ"ש יאזן אינטרסים ← ויכול לפסוק פיצויים.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 96", "ת\"א (שלום פ\"ת) 55046-09-14 מרדכי ביסטרה נ'' עיריית יהוד מונוסון (11.06.2019)", "ת\"א (שלום ביש\"א) 51033-07-17 תמר אזואלוס נ'' פרוספר דהן (10.08.2019)", "אבי וינרוט, דיני קניין - פרקי יסוד (2024), פרק ח זיקת הנאה ((Easement, עמ'' 115, 117"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, בית המשפט רשאי לבטל את הזיקה, תוך איזון בין האינטרסים של הצדדים ומתן פיצוי למיכל בגין הנזק שייגרם לה.', true, 'תשובה זו נכונה, שכן סעיף 96 לחוק המקרקעין מקנה לבית המשפט סמכות לבטל זיקת הנאה עקב שינוי נסיבות, תוך איזון אינטרסים ופסיקת פיצויים.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, זיקת הנאה רשומה היא זכות קניינית מוחלטת שאינה ניתנת לביטול על ידי בית המשפט.', false, 'טענה זו שגויה, שכן סעיף 96 לחוק המקרקעין קובע במפורש את סמכות בית המשפט לבטל או לשנות זיקת הנאה, גם אם היא רשומה.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם ירון יוכיח כי המעבר מונע ממנו שימוש סביר במקרקעין, ואין למיכל כל דרך חלופית.', false, 'טענה זו שגויה, שכן קיומה של דרך חלופית הוא שיקול חשוב, אך לא תנאי בלעדי לביטול, ובית המשפט בוחן מכלול שיקולים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן מיכל תסכים לביטול הזיקה בתמורה לפיצוי הולם.', false, 'טענה זו שגויה, שכן בית המשפט מוסמך לבטל את הזיקה גם ללא הסכמת בעל הזיקה, תוך פסיקת פיצויים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ג', '2024-W-S-Q39';
  END IF;

  -- Angle ד
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ד';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ד', 'סמכות עניינית בתביעות זיקת הנאה', 4,
      'ירון מעוניין להגיש תביעה לבית המשפט להצהיר על קיומה של זיקת הנאה מכוח שנים בחלקה של מיכל. לאיזה בית משפט הסמכות העניינית לדון בתביעה זו?', 'שאלה זו עוסקת בסמכות העניינית של בתי המשפט לדון בתביעות הנוגעות לזיקת הנאה. היא מדגישה את ההבחנה המהותית בין תביעה לסעד הצהרתי בדבר עצם קיומה של זיקת הנאה (הנתונה לסמכות בית המשפט המחוזי) לבין תביעה לאכיפת שימוש בזיקת הנאה קיימת (הנתונה לסמכות בית משפט השלום).', 'הסמכות העניינית בתחום האזרחי נקבעת על פי מבחן הסעד המבוקש. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019) תביעה לסעד הצהרתי בדבר עצם קיומה של זיקת הנאה, שהיא זכות קניינית במקרקעין, נתונה לסמכותו העניינית של בית המשפט המחוזי. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019) זאת, מכיוון שתביעה כזו נחשבת ל"תביעה אחרת הנוגעת למקרקעין" ולא לתביעה ל"שימוש במקרקעין" כמשמעותה בסעיף 51(א)(3) לחוק בתי המשפט. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019) לעומת זאת, תביעה לאכיפת שימוש בזיקת הנאה קיימת, שאינה כוללת סעד הצהרתי על עצם קיומה, נתונה לסמכות בית משפט השלום. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019) במקרה זה, ירון מבקש להצהיר על קיומה של זיקת הנאה מכוח שנים, ולכן הסמכות נתונה לבית המשפט המחוזי. ת"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)', 'הטעות הנפוצה היא לבלבל בין סוגי הסעדים השונים בתביעות זיקת הנאה, ולהחיל את סמכות בית משפט השלום (החזקה ושימוש) גם על תביעות הצהרתיות בדבר עצם קיום הזכות הקניינית.',
      '["סמכות עניינית", "זיקת הנאה", "סעד הצהרתי", "זכות קניינית", "בית משפט מחוזי", "בית משפט שלום"]'::jsonb, '**וריאציה 1 — סעד הצהרתי:** לאיזה בית משפט סמכות לדון בסעד הצהרתי על קיום זיקת הנאה? ← בית המשפט המחוזי. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019)
**וריאציה 2 — אכיפת שימוש:** לאיזה בית משפט סמכות לדון בתביעה לאכיפת שימוש בזיקת הנאה קיימת? ← בית משפט השלום. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019)
**וריאציה 3 — מבחן הסעד:** מהו המבחן לקביעת סמכות עניינית? ← מבחן הסעד המבוקש. ת"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019)', 'סמכות עניינית (זיקת הנאה) ← סעד הצהרתי על קיום זיקה: מחוזי ← אכיפת שימוש בזיקה קיימת: שלום.', '["ת\"א (מחוזי חי'') 52575-07-18 דנקר בירגר בע\"מ נ'' גולן יוסף ו-557 נוספי (11.06.2019)", "ת\"א (מחוזי מרכז) 5791-06-16 שירן רחל נ'' גבריאל מנטין (15.08.2019)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'לבית המשפט המחוזי, שכן מדובר בסעד הצהרתי בדבר עצם קיומה של זכות קניינית במקרקעין.', true, 'תשובה זו נכונה, שכן תביעה לסעד הצהרתי בדבר קיומה של זיקת הנאה, שהיא זכות קניינית, נתונה לסמכותו העניינית של בית המשפט המחוזי.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לבית משפט השלום, שכן מדובר בתביעה הנוגעת לשימוש במקרקעין, הנמצאת בסמכותו.', false, 'טענה זו שגויה, שכן ההבחנה היא בין תביעה להצהיר על קיום זיקה (מחוזי) לבין תביעה לאכיפת שימוש בזיקה קיימת (שלום).', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'למפקח על רישום המקרקעין, שכן הוא הגורם המוסמך לדון בסכסוכים בין בעלי מקרקעין.', false, 'טענה זו שגויה, שכן סמכות המפקח מוגבלת לסכסוכים בבתים משותפים, ואינה כוללת תביעות להצהרה על קיום זיקת הנאה.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לבית הדין לחוזים אחידים, שכן מדובר בסכסוך הנובע מהסכם בין הצדדים.', false, 'טענה זו שגויה, שכן בית הדין לחוזים אחידים עוסק בחוזים אחידים, ולא בסכסוכי מקרקעין בין פרטים.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q39';
  END IF;

  RAISE NOTICE 'Q% angles backfilled: external_id %', 39, '2024-W-S-Q39';
END
$$;

-- ============================================================
-- Q40 — angles backfill for 2024-W-S-Q40 (4 angles)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid;
  v_ang_id uuid;
BEGIN
  SELECT id INTO v_sq_id FROM public.source_questions WHERE external_id = '2024-W-S-Q40';
  IF v_sq_id IS NULL THEN
    RAISE NOTICE 'parent source % not found, skipping angles', '2024-W-S-Q40';
    RETURN;
  END IF;

  -- Angle א
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'א';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'א', 'הגבלת חופש העיסוק לאזרח ישראלי', 1,
      'אבי, אזרח ישראלי, עבד כנהג אוטובוס. רישיונו נשלל לשנה עקב עבירות תנועה חמורות שביצע. אבי טוען כי שלילת הרישיון פוגעת באופן בלתי חוקתי בחופש העיסוק שלו. מה הדין?', 'שאלה זו בוחנת את היקף חופש העיסוק של אזרח ישראלי ואת האפשרות להגבילו. היא מתמקדת ביישום פסקת ההגבלה שבחוק יסוד: חופש העיסוק על מקרה של שלילת רישיון מקצועי, תוך בחינת התנאים המצטברים לפגיעה חוקתית בזכות יסוד.', 'חופש העיסוק הוא זכות יסוד חוקתית המעוגנת בחוק יסוד: חופש העיסוק. חוק יסוד: חופש העיסוק, סעיף 3 עם זאת, זכות זו אינה מוחלטת וניתן להגבילה באמצעות פסקת ההגבלה שבסעיף 4 לחוק היסוד. חוק יסוד: חופש העיסוק, סעיף 4 שלילת רישיון נהיגה ציבורי, המהווה מקור פרנסה, אכן פוגעת בחופש העיסוק. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) אולם, פגיעה זו עשויה להיות חוקתית אם היא עומדת בתנאי פסקת ההגבלה: היא נעשית בחוק (פקודת התעבורה), לתכלית ראויה (בטיחות הציבור והגנה על חיי אדם), והיא מידתית (שלילה זמנית עקב עבירות חמורות). רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)', 'הטעות הנפוצה היא לראות בחופש העיסוק זכות מוחלטת שאינה ניתנת להגבלה, או להתעלם מהצורך לבחון את עמידת ההגבלה בתנאי פסקת ההגבלה.',
      '["חופש העיסוק", "חוק יסוד: חופש העיסוק", "פסקת ההגבלה", "תכלית ראויה", "מידתיות", "פקודת התעבורה"]'::jsonb, '**וריאציה 1 — פגיעה בזכות:** האם שלילת רישיון נהיגה ציבורי פוגעת בחופש העיסוק? ← כן, אם הנהיגה היא מקור פרנסה. חוק יסוד: חופש העיסוק, סעיף 3
**וריאציה 2 — חוקתיות הפגיעה:** מתי פגיעה בחופש העיסוק היא חוקתית? ← אם היא עומדת בתנאי פסקת ההגבלה (בחוק, הולם, תכלית ראויה, מידתי). חוק יסוד: חופש העיסוק, סעיף 4
**וריאציה 3 — תכלית ראויה:** מהי התכלית הראויה בשלילת רישיון נהיגה? ← בטיחות הציבור והגנה על חיי אדם. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)', 'חופש העיסוק (אזרח) ← זכות יסוד חוקתית ← ניתן להגבילה בחוק העומד בפסקת ההגבלה (בחוק, הולם, תכלית ראויה, מידתי).', '["חוק יסוד: חופש העיסוק, סעיפים 3, 4", "רע\"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית\"ר בע\"מ (09.11.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'שלילת הרישיון פוגעת בחופש העיסוק של אבי, אך הפגיעה חוקתית שכן היא עומדת בתנאי פסקת ההגבלה.', true, 'תשובה זו נכונה, שכן שלילת רישיון נהיגה ציבורי עקב עבירות תנועה חמורות היא הגבלה בחוק (פקודת התעבורה), לתכלית ראויה (בטיחות הציבור), והיא מידתית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'שלילת הרישיון פוגעת בחופש העיסוק של אבי, והיא אינה חוקתית שכן אין חוק יסוד המאפשר פגיעה כזו.', false, 'טענה זו שגויה, שכן פקודת התעבורה היא חוק המאפשר פגיעה כזו, והיא עשויה לעמוד בתנאי פסקת ההגבלה שבחוק יסוד: חופש העיסוק.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'שלילת הרישיון אינה פוגעת בחופש העיסוק, שכן חופש העיסוק אינו כולל את הזכות לעסוק במקצוע מסוכן לציבור.', false, 'טענה זו שגויה, שכן שלילת רישיון אכן פוגעת בחופש העיסוק, אך הפגיעה עשויה להיות מוצדקת וחוקתית.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'שלילת הרישיון חוקתית רק אם היא נעשתה באישור בית המשפט העליון.', false, 'טענה זו שגויה, שכן שלילת רישיון נעשית על פי פקודת התעבורה, ואין צורך באישור מוקדם של בית המשפט העליון.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'א', '2024-W-S-Q40';
  END IF;

  -- Angle ב
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ב';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ב', 'תנאי פסקת ההגבלה', 2,
      'מהם התנאים המצטברים שבהם ניתן לפגוע בזכות יסוד המעוגנת בחוק יסוד, על פי פסקת ההגבלה?', 'שאלה זו עוסקת בליבת המשפט החוקתי בישראל – פסקת ההגבלה. היא בוחנת את ארבעת התנאים המצטברים שנקבעו בחוקי היסוד (חוק יסוד: כבוד האדם וחירותו וחוק יסוד: חופש העיסוק) המאפשרים פגיעה בזכויות יסוד, ובכך מבטיחים את אופיין החוקתי של זכויות אלו.', 'פסקת ההגבלה קבועה בסעיף 8 לחוק יסוד: כבוד האדם וחירותו ובסעיף 4 לחוק יסוד: חופש העיסוק. חוק יסוד: חופש העיסוק, סעיף 4 היא קובעת ארבעה תנאים מצטברים לפגיעה בזכות יסוד: 1. בחוק או מכוח הסמכה מפורשת בו: הפגיעה חייבת להיות מעוגנת בחקיקה ראשית או בתקנות שהוסמכו במפורש בחוק. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) 2. הולם את ערכיה של מדינת ישראל: החוק הפוגע צריך להלום את ערכיה של מדינת ישראל כמדינה יהודית ודמוקרטית. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) 3. לתכלית ראויה: הפגיעה צריכה לשרת מטרה חברתית חשובה וראויה. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) 4. במידה שאינה עולה על הנדרש (מידתיות): הפגיעה בזכות צריכה להיות מידתית, כלומר, לא חמורה יותר מהנדרש להשגת התכלית הראויה. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)', 'הטעות הנפוצה היא לשכוח אחד מהתנאים המצטברים של פסקת ההגבלה, או לבלבל בין התנאים השונים.',
      '["פסקת ההגבלה", "חוק יסוד: כבוד האדם וחירותו", "חוק יסוד: חופש העיסוק", "בחוק", "הולם את ערכי המדינה", "תכלית ראויה", "מידתיות"]'::jsonb, '**וריאציה 1 — תנאים מצטברים:** כמה תנאים יש בפסקת ההגבלה? ← ארבעה תנאים מצטברים. חוק יסוד: חופש העיסוק, סעיף 4
**וריאציה 2 — תנאי המידתיות:** מה בוחן תנאי המידתיות? ← האם הפגיעה בזכות אינה עולה על הנדרש להשגת התכלית הראויה. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)
**וריאציה 3 — חוק יסוד:** באילו חוקי יסוד קיימת פסקת הגבלה? ← חוק יסוד: כבוד האדם וחירותו וחוק יסוד: חופש העיסוק. חוק יסוד: חופש העיסוק, סעיף 4', 'פסקת ההגבלה ← 4 תנאים מצטברים: בחוק, הולם ערכי המדינה, תכלית ראויה, מידתיות.', '["חוק יסוד: חופש העיסוק, סעיף 4", "חוק יסוד: כבוד האדם וחירותו, סעיף 8", "רע\"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית\"ר בע\"מ (09.11.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'הפגיעה נעשית בחוק או מכוח הסמכה מפורשת בו, החוק הולם את ערכיה של מדינת ישראל, נועד לתכלית ראויה, ובמידה שאינה עולה על הנדרש.', true, 'תשובה זו נכונה, שכן אלו הם ארבעת התנאים המצטברים הקבועים בפסקת ההגבלה שבחוקי היסוד.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'הפגיעה נעשית בחוק, נועדה לתכלית ראויה, ובלבד שהיא אינה פוגעת בליבת הזכות.', false, 'טענה זו שגויה, שכן חסרים תנאים נוספים (הולם את ערכי המדינה, מידתיות) ואין דרישה מפורשת לאי פגיעה בליבת הזכות, אלא למידתיות.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'הפגיעה נעשית בחוק, הולמת את ערכיה של מדינת ישראל, ובלבד שהיא אושרה על ידי בית המשפט העליון.', false, 'טענה זו שגויה, שכן אישור בית המשפט העליון אינו תנאי מוקדם לפגיעה, אלא חלק מהביקורת השיפוטית בדיעבד.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'הפגיעה נעשית בחוק, נועדה לתכלית ראויה, ובלבד שהיא אינה מפלה.', false, 'טענה זו שגויה, שכן איסור אפליה הוא עקרון כללי, אך אינו אחד מארבעת התנאים המפורשים של פסקת ההגבלה.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ב', '2024-W-S-Q40';
  END IF;

  -- Angle ג
  SELECT id INTO v_ang_id FROM public.angle_questions WHERE source_question_id = v_sq_id AND angle_letter = 'ג';
  IF v_ang_id IS NULL THEN
    INSERT INTO public.angle_questions (
      source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
    ) VALUES (
      v_sq_id, 'ג', 'פגיעה בחופש התנועה של קטין', 3,
      'הורים גרושים מסוכסכים על מקום מגוריו של בנם הקטין. האם בית המשפט רשאי להגביל את חופש התנועה של הקטין, למשל על ידי איסור יציאה מהארץ, גם אם הדבר פוגע בזכותו החוקתית לחופש תנועה?', 'שאלה זו בוחנת את היחס בין זכויות יסוד חוקתיות, כגון חופש התנועה (המעוגן בסעיף 6 לחוק יסוד: כבוד האדם וחירותו), לבין עקרון טובת הקטין. היא מדגישה כי זכויות קטינים אינן מוחלטות, וכי בית המשפט מוסמך להגבילן כאשר הדבר נדרש לשמירה על טובתם, גם במחיר פגיעה בזכות חוקתית.', 'חופש התנועה, ובכלל זה הזכות לצאת מישראל ולהיכנס אליה, מעוגן בסעיף 6 לחוק יסוד: כבוד האדם וחירותו. חוק יסוד: כבוד האדם וחירותו, סעיף 6 עם זאת, זכויות קטינים אינן מוחלטות, ועקרון טובת הקטין הוא עיקרון על בדיני משפחה, המנחה את בית המשפט בהחלטותיו. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) בית המשפט מוסמך להגביל את חופש התנועה של קטין, לרבות איסור יציאה מהארץ, אם הדבר נדרש לשמירה על טובתו, למשל במקרים של חשש לחטיפה, ניתוק קשר עם הורה, או פגיעה ברווחתו. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) פגיעה זו בזכות חוקתית נחשבת לגיטימית כאשר היא נעשית מכוח חוק (כגון חוק הכשרות המשפטית והאפוטרופסות) ולשם הגנה על טובת הקטין, העומדת בתנאי פסקת ההגבלה. זוהר גושן אסף אקשטיין דיני חברות (2023) | פרק יב תכלית החברה', 'הטעות הנפוצה היא להחיל את הכללים הנוגעים להגבלת זכויות יסוד של בגירים באופן זהה על קטינים, מבלי להתחשב בעקרון טובת הקטין.',
      '["חופש התנועה", "חוק יסוד: כבוד האדם וחירותו", "טובת הקטין", "איסור יציאה מהארץ", "חוק הכשרות המשפטית והאפוטרופסות", "פסקת ההגבלה"]'::jsonb, '**וריאציה 1 — טובת הקטין:** האם טובת הקטין גוברת על חופש התנועה שלו? ← כן, טובת הקטין היא עיקרון על. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)
**וריאציה 2 — סמכות בית המשפט:** האם בית המשפט רשאי לאסור יציאת קטין מהארץ? ← כן, אם הדבר נדרש לשמירה על טובתו. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025)
**וריאציה 3 — בסיס חוקי:** מהו הבסיס החוקי להגבלת חופש התנועה של קטין? ← חוק הכשרות המשפטית והאפוטרופסות, העומד בפסקת ההגבלה. זוהר גושן אסף אקשטיין דיני חברות (2023) | פרק יב תכלית החברה', 'חופש תנועה של קטין ← אינו מוחלט ← בית המשפט יגביל לטובת הקטין (חוק הכשרות המשפטית והאפוטרופסות).', '["חוק יסוד: כבוד האדם וחירותו, סעיף 6", "חוק הכשרות המשפטית והאפוטרופסות, תשכ\"ב-1962", "רע\"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית\"ר בע\"מ (09.11.2025)", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק יב תכלית החברה, עמ'' 3"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, בית המשפט רשאי להגביל את חופש התנועה של קטין, שכן טובת הקטין גוברת על זכותו החוקתית לחופש תנועה.', true, 'תשובה זו נכונה, שכן טובת הקטין היא עיקרון על בדיני משפחה, ובית המשפט מוסמך להגביל את חופש התנועה של קטין אם הדבר נדרש לשמירה על טובתו, גם במחיר פגיעה בזכות חוקתית.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, חופש התנועה היא זכות יסוד מוחלטת, ואין להגבילה גם במקרה של קטינים.', false, 'טענה זו שגויה, שכן זכויות יסוד אינן מוחלטות, ובמיוחד אצל קטינים הן נסוגות מפני עקרון טובת הילד.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הקטין עצמו מסכים להגבלה, שכן יש לכבד את רצונו.', false, 'טענה זו שגויה, שכן רצון הקטין הוא שיקול, אך אינו מכריע, ובית המשפט יפסוק לפי טובתו גם בניגוד לרצונו.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן ההגבלה נועדה למנוע ביצוע עבירה פלילית על ידי הקטין.', false, 'טענה זו שגויה, שכן הגבלת חופש התנועה של קטין יכולה להיעשות גם למטרות אחרות, כגון שמירה על קשר עם הורה או מניעת חטיפה.', 4);
