    ) VALUES (
      v_sq_id, 'ד', 'סמכות מניעת כניסה לישראל', 4,
      'אדם שאינו אזרח ישראל הגיע לגבול המדינה ומבקש להיכנס. האם רשויות המדינה רשאיות למנוע את כניסתו, ומהו הבסיס החוקי לכך?', 'שאלה זו עוסקת בסמכות רשויות המדינה למנוע כניסה לישראל של מי שאינו אזרח, ובבסיס החוקי לסמכות זו. היא מדגישה את ההבחנה בין זכות הכניסה של אזרחים (זכות יסוד) לבין מעמדם של מי שאינם אזרחים, אשר כניסתם כפופה לדיני ההגירה ולשיקול דעת הרשויות על פי חוק הכניסה לישראל.', 'הזכות להיכנס לישראל מוקנית לאזרחים ותושבים של המדינה, כפי שקבוע בסעיף 6 לחוק יסוד: כבוד האדם וחירותו. חוק יסוד: כבוד האדם וחירותו, סעיף 6 לעומת זאת, מי שאינו אזרח או תושב של המדינה, אין לו זכות קנויה להיכנס לישראל. רע"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית"ר בע"מ (09.11.2025) סמכות רשויות המדינה למנוע כניסה של מי שאינו אזרח מעוגנת בחוק הכניסה לישראל, תשי"ב-1952. חוק הכניסה לישראל, תשי"ב-1952, סעיף 1 חוק זה מקנה לשר הפנים סמכות רחבה למנוע כניסה, בין היתר, אם קיים חשש שהאדם עלול לסכן את ביטחון המדינה, שלום הציבור, או בריאות הציבור, או אם הוא מגיע למטרות עבודה ללא היתר. חוק הכניסה לישראל, תשי"ב-1952, סעיף 2', 'הטעות הנפוצה היא לבלבל בין זכות הכניסה של אזרחים לבין מעמדם של מי שאינם אזרחים, ולחשוב שלכל אדם יש זכות להיכנס לישראל.',
      '["חוק הכניסה לישראל", "אזרח", "תושב", "מי שאינו אזרח", "זכות כניסה", "סמכות שר הפנים"]'::jsonb, '**וריאציה 1 — זכות כניסה לאזרח:** למי יש זכות קנויה להיכנס לישראל? ← לאזרח ותושב המדינה. חוק יסוד: כבוד האדם וחירותו, סעיף 6
**וריאציה 2 — זכות כניסה לזר:** האם למי שאינו אזרח יש זכות קנויה להיכנס לישראל? ← לא, כניסתו כפופה לחוק הכניסה לישראל. חוק הכניסה לישראל, תשי"ב-1952, סעיף 1
**וריאציה 3 — סמכות מניעה:** מי מוסמך למנוע כניסה של מי שאינו אזרח? ← שר הפנים, על פי שיקול דעתו ובכפוף לחוק הכניסה לישראל. חוק הכניסה לישראל, תשי"ב-1952, סעיף 2', 'כניסה לישראל ← אזרח/תושב: זכות יסוד (ס'' 6 חוק יסוד: כבוד האדם וחירותו) ← מי שאינו אזרח: כפוף לחוק הכניסה לישראל ולשיקול דעת שר הפנים.', '["חוק יסוד: כבוד האדם וחירותו, סעיף 6", "חוק הכניסה לישראל, תשי\"ב-1952, סעיפים 1, 2", "רע\"א 41402-12-24 יוסף גרנות נ'' רמת רזיאל כפר שתופי של תנועת חירות בית\"ר בע\"מ (09.11.2025)"]'::jsonb
    ) RETURNING id INTO v_ang_id;
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'א', 'כן, רשויות המדינה רשאיות למנוע את כניסתו על פי חוק הכניסה לישראל, ואין לו זכות קנויה להיכנס למדינה.', true, 'תשובה זו נכונה, שכן חוק הכניסה לישראל מקנה לרשויות סמכות רחבה למנוע כניסת מי שאינו אזרח, ואין לאדם כזה זכות קנויה להיכנס לישראל.', 1);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ב', 'לא, כל אדם זכאי להיכנס לישראל, אלא אם כן הוכח כי הוא מהווה סכנה ביטחונית מיידית.', false, 'טענה זו שגויה, שכן הזכות להיכנס לישראל מוקנית לאזרחים ותושבים בלבד, ולא לכל אדם.', 2);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ג', 'כן, אך רק אם הוא מוגדר כ''מסתנן'' על פי חוק למניעת הסתננות.', false, 'טענה זו שגויה, שכן חוק הכניסה לישראל מקנה סמכות רחבה יותר למנוע כניסה, שאינה מוגבלת רק למסתננים.', 3);
    INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_id, 'ד', 'לא, אלא אם כן יש לו דרכון מזויף או שאין לו אשרת כניסה תקפה.', false, 'טענה זו שגויה, שכן גם אם יש לו דרכון ואשרה, רשויות המדינה עדיין יכולות למנוע כניסה מסיבות אחרות המפורטות בחוק הכניסה לישראל.', 4);
  ELSE
    RAISE NOTICE 'angle % already exists for %, skipping', 'ד', '2024-W-S-Q40';
